// ── ADMIN USERS ───────────────────────────────────────────────
const ADMIN_USERNAMES = ['chukwunonso'];
function isAdminUser(user) {
  if (!user) return false;
  return ADMIN_USERNAMES.includes((user.username||'').toLowerCase()) ||
         ADMIN_USERNAMES.includes((user.email||'').split('@')[0].toLowerCase());
}

