// ── Appearance: theme + font ─────────────────────────────────
function applyTheme(t) {
  // 'default' (and anything unknown) = Cloud, the new default for everyone.
  // 'classic' = the original Black & Gold, 'skyline' = Sky & Sage.
  const name = (t==='skyline' || t==='classic') ? t : 'cloud';
  document.body.dataset.theme = (name==='classic') ? '' : name;
  localStorage.setItem('bd_theme', t||'default');
  document.documentElement.style.background = name==='skyline' ? '#f4f8f7' : name==='classic' ? '#0f1117' : '#f4f7fc';
  const themeColor = name==='skyline' ? '#1466d6' : name==='classic' ? '#d4af37' : '#f4f7fc';
  document.querySelectorAll('meta[name="theme-color"],meta[name="msapplication-TileColor"]')
    .forEach(m=>m.setAttribute('content', themeColor));
  try { if (typeof bdThemeChanged === 'function') bdThemeChanged(); } catch(e) {}
}
// Chart colours: the dark theme's bright hexes are swapped for light-theme
// equivalents (canvas can't read CSS variables).
function bdIsCloud() { return document.body && document.body.dataset.theme === 'cloud'; }
function bdChartHex(h) {
  if (!bdIsCloud()) return h;
  return ({'#4ade80':'#13795b','#f87171':'#b3261e','#60a5fa':'#4f7bd9','#fbbf24':'#d99a1e','#a78bfa':'#8c52ff','#d4af37':'#6b34d9','#f97316':'#d9661a'})[String(h).toLowerCase()] || h;
}
function bdChartRgba(rgba) {
  if (!bdIsCloud()) return rgba;
  return String(rgba).replace('74,222,128','19,121,91').replace('248,113,113','179,38,30');
}
function applyFont(f) {
  const font = f && f!=='default' ? f : 'Segoe UI';
  document.body.style.fontFamily = "'"+font+"',Arial,sans-serif";
  localStorage.setItem('bd_font', f||'default');
}
try { applyTheme(localStorage.getItem('bd_theme')||'default'); applyFont(localStorage.getItem('bd_font')||'default'); } catch(e){}

