function togglePw(id, el) {
  const inp = document.getElementById(id);
  if (!inp) return;
  inp.type = inp.type === 'password' ? 'text' : 'password';
  el.innerHTML = inp.type === 'password' ? PW_EYE_SVG : PW_MONKEY_SVG;
}

function suPwStrength(pw) {
  const segs = document.querySelectorAll('#suPwBar .pwseg');
  const label = document.getElementById('suPwLabel');
  let score = 0;
  if (pw.length >= 6) score++;
  if (pw.length >= 10) score++;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
  if (/\d/.test(pw) || /[^A-Za-z0-9]/.test(pw)) score++;
  const names = ['','Weak','Fair','Good','Strong'];
  segs.forEach((s,i)=>{ s.style.background = i < score ? 'var(--gold)' : 'var(--border2)'; });
  if (label) { label.textContent = names[score]; label.style.color = score>=4?'var(--gold)':'var(--muted)'; }
}

async function riRegister() {
  const err = document.getElementById('riErr');
  const first = document.getElementById('ri_first')?.value?.trim();
  const last  = document.getElementById('ri_last')?.value?.trim();
  if (!first || !last) { if(err) err.textContent='First and last name are required.'; return; }
  const dobDay   = document.getElementById('ri_dob_day')?.value;
  const dobMonth = document.getElementById('ri_dob_month')?.value;
  const dobYear  = document.getElementById('ri_dob_year')?.value;
  let dateOfBirth = null;
  if (dobDay && dobMonth && dobYear) {
    // Round-trip check catches impossible combinations (e.g. day 30 for
    // February) — JS silently rolls those over into the next month
    // rather than erroring, so comparing back against what was picked
    // is what actually catches it.
    const d = new Date(parseInt(dobYear,10), parseInt(dobMonth,10)-1, parseInt(dobDay,10));
    if (d.getMonth() !== parseInt(dobMonth,10)-1 || d.getDate() !== parseInt(dobDay,10)) {
      if (err) { err.textContent = "That's not a real date — check the day for that month."; err.style.color='var(--red)'; }
      return;
    }
    dateOfBirth = dobYear + '-' + String(dobMonth).padStart(2,'0') + '-' + String(dobDay).padStart(2,'0');
  }
  if (err) { err.textContent='Saving…'; err.style.color='var(--muted)'; }
  try {
    const originCode = document.getElementById('ri_origin_country')?.value||'NG';
    const originCountryList = (typeof BD_COUNTRIES !== 'undefined' && BD_COUNTRIES.length) ? BD_COUNTRIES : [{code:'NG',name:'Nigeria'}];
    const originCountryName = originCountryList.find(c=>c.code===originCode)?.name || 'Nigeria';
    profileData = {
      first_name:first,
      last_name:last,
      full_name:first+' '+last,
      date_of_birth:dateOfBirth,
      gender:document.getElementById('ri_gender')?.value||'',
      phone:document.getElementById('ri_phone')?.value?.trim()||'',
      country:originCountryName,
      state:document.getElementById('ri_state')?.value||'',
      lga:document.getElementById('ri_lga')?.value?.trim()||'',
      town:document.getElementById('ri_town')?.value?.trim()||'',
      email:bkUser?.email||'',
    };
    await bkDb.from('profiles').upsert({ id:bkUser.id, username:(bkUser?.email||'').split('@')[0]||'user', ...Object.fromEntries(Object.entries(profileData).filter(([k])=>k!=='email')), updated_at:new Date().toISOString() }, {onConflict:'id'});
    staffDisplayName = profileData.full_name;
    showAuthScreen('success');
  } catch(e) { if(err){ err.textContent='Error: '+(e.message||'could not save'); err.style.color='var(--red)'; } }
}



// ══ PERSONAL ACCOUNTING MODULE ═══════════════════════════════
let personalProfile = null;
let personalDebts = [];
let personalItems = [];
let personalTxns = [];

async function loadPersonalData() {
  if (!bkUser) return;
  try {
    const [p, d, it, tx] = await Promise.all([
      bkDb.from('personal_profiles').select('*').eq('user_id',bkUser.id).maybeSingle(),
      bkDb.from('personal_debts').select('*').eq('user_id',bkUser.id).order('created_at'),
      bkDb.from('personal_items').select('*').eq('user_id',bkUser.id).order('created_at'),
      bkDb.from('personal_transactions').select('*').eq('user_id',bkUser.id).order('txn_date',{ascending:false}).limit(50),
    ]);
    personalProfile = p.data || null;
    personalDebts   = d.data || [];
    personalItems   = it.data || [];
    personalTxns    = tx.data || [];
  } catch(e) {}
}

