function showModeChoice() {
  hideAuthScreen();
  staffHideChrome();
  bdSaveRoute('mode-choice');
  const hour = new Date().getHours();
  const greeting = hour<12?'GOOD MORNING':hour<17?'GOOD AFTERNOON':'GOOD EVENING';
  const fname = profileData?.first_name || staffDisplayName?.split(' ')[0] || '';
  document.getElementById('bkContent').innerHTML = `
    <div style="text-align:center;padding:34px 20px 8px;">
      <div style="display:inline-flex;align-items:center;gap:8px;margin-bottom:26px;">
        ${bfiMark(32)}
        <span style="font-weight:800;font-size:0.85rem;">Butterfi</span>
      </div>
      <div style="font-size:0.68rem;letter-spacing:0.16em;color:var(--muted);font-weight:700;">${greeting}</div>
      <div style="font-size:1.7rem;font-weight:900;color:var(--white);margin:4px 0;">${escH(fname)} 👋</div>
      <div style="font-size:0.85rem;color:var(--muted);">Let’s get started.</div>
    </div>
    <div class="mode-cards">
      <div onclick="startBusinessMode()" style="background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:22px;cursor:pointer;">
        <div style="width:44px;height:44px;border-radius:12px;background:var(--gold-t014);display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:14px;">🏢</div>
        <div style="font-size:1.05rem;font-weight:900;color:var(--white);margin-bottom:6px;">Business Accounting</div>
        <div style="font-size:0.8rem;color:var(--muted);line-height:1.5;">Register and manage one or more businesses. Track revenue, expenses, invoices, and team performance.</div>
        <div style="color:var(--gold);font-size:0.78rem;font-weight:800;margin-top:12px;">Get started →</div>
      </div>
      <div onclick="showSearchBusinessPage()" style="background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:22px;cursor:pointer;">
        <div style="width:44px;height:44px;border-radius:12px;background:var(--gold-t014);display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:14px;">🔍</div>
        <div style="font-size:1.05rem;font-weight:900;color:var(--white);margin-bottom:6px;">Join a Business</div>
        <div style="font-size:0.8rem;color:var(--muted);line-height:1.5;">Joining a business that is already on the platform? Type its Business ID and the owner will approve you.</div>
        <div style="color:var(--gold);font-size:0.78rem;font-weight:800;margin-top:12px;">Join →</div>
      </div>
    </div>
    <div style="text-align:center;font-size:0.72rem;color:var(--muted);padding:16px;">Register a new business, or join one already on the platform.</div>`;
}


// ══ SEARCH FOR BUSINESS (onboarding) ═════════════════════════
let _sfbResults=[], _sfbSelected=null, _sfbSearched=false;
function showSearchBusinessPage() { return showJoinBusiness(); }
function showSearchBusinessPageOld() {
  staffHideChrome();
  bdSaveRoute('search-business');
  localStorage.setItem('bd_mode','business');
  document.getElementById('bkContent').innerHTML = `
    <div style="max-width:560px;margin:0 auto;padding:28px 16px;">
      <div style="font-size:1.35rem;font-weight:900;color:var(--white);">Search for your Business</div>
      <div style="font-size:0.78rem;color:var(--muted);margin:4px 0 18px;">Find the business you own or work for, state your position, and continue.</div>
      <div style="display:flex;gap:8px;">
        <input class="bk-login-input" id="sfb_q" style="flex:1;margin:0;" placeholder="Business name…" onkeydown="if(event.key==='Enter')sfbSearch()"/>
        <button onclick="sfbSearch()" style="background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:0 18px;border-radius:8px;cursor:pointer;">Search</button>
      </div>
      <div id="sfbResults" style="margin-top:12px;"></div>
      <div id="sfbJoin" style="margin-top:12px;"></div>
      <div class="bk-auth-btnrow" style="margin-top:20px;">
        <button class="bk-login-back" onclick="showModeChoice()">← Back</button>
      </div>
    </div>`;
  setTimeout(()=>document.getElementById('sfb_q')?.focus(),50);
}
async function sfbSearch() {
  const q = document.getElementById('sfb_q')?.value?.trim();
  if (!q) return;
  try {
    const {data,error} = await bkDb.from('businesses').select('id,name,industry,icon,logo_url,owner_user_id').ilike('name','%'+q+'%').limit(10);
    if (error) throw error;
    _sfbResults = data||[]; _sfbSelected=null; _sfbSearched=true;
    sfbRender();
  } catch(e){ alert('Search failed: '+(e.message||'')); }
}
function sfbRender() {
  const box = document.getElementById('sfbResults');
  if (!box) return;
  box.innerHTML = _sfbResults.length ? _sfbResults.map(b=>`
    <div onclick="sfbSelect('${b.id}')" style="display:flex;align-items:center;gap:10px;padding:11px;border:1px solid ${_sfbSelected?.id===b.id?'var(--gold)':'var(--border2)'};border-radius:10px;margin-bottom:8px;cursor:pointer;background:var(--surface);">
      <div style="width:34px;height:34px;border-radius:8px;background:var(--gold-t012);display:flex;align-items:center;justify-content:center;overflow:hidden;">${b.logo_url?`<img src="${b.logo_url}" style="width:100%;height:100%;object-fit:cover;"/>`:(b.icon||'🏢')}</div>
      <div style="flex:1;"><div style="font-weight:800;font-size:0.84rem;color:var(--white);">${escH(b.name)}${b.owner_user_id===bkUser?.id?' <span style="font-size:0.6rem;color:var(--muted);">(you own this)</span>':''}</div>
      <div style="font-size:0.68rem;color:var(--muted);">${escH(b.industry||'')}</div></div>
      ${_sfbSelected?.id===b.id?'<span style="color:var(--gold);font-weight:900;">✓</span>':''}
    </div>`).join('')
  : (_sfbSearched ? '<div style="font-size:0.75rem;color:var(--muted);">No businesses found. Check the spelling, or go back and register it.</div>' : '');
  const join = document.getElementById('sfbJoin');
  if (join) join.innerHTML = _sfbSelected ? `
    <label class="su-label">YOUR POSITION IN THE BUSINESS *</label>
    <input class="bk-login-input" id="sfb_pos" placeholder="e.g. Owner, Manager, Cashier, Accountant"/>
    <button class="bk-login-btn" style="width:100%;background:var(--gold);color:var(--accent-ink);margin-top:8px;" onclick="sfbSave()">Save &amp; Continue →</button>` : '';
}
function sfbSelect(id){ _sfbSelected=_sfbResults.find(b=>b.id===id)||null; sfbRender(); }
async function sfbSave() {
  if (!_sfbSelected) return;
  const position = document.getElementById('sfb_pos')?.value?.trim();
  if (!position) { alert('Please enter your position in the business.'); return; }
  try {
    if (_sfbSelected.owner_user_id === bkUser?.id) { alert('You own "'+_sfbSelected.name+'" — it is already in your account.'); return; }
    const role = /owner/i.test(position) ? 'employee' : 'employee';
    const {error} = await bkDb.from('user_businesses').upsert(
      {user_id:bkUser.id, business_id:_sfbSelected.id, role, position},{onConflict:'user_id,business_id'});
    if (error) throw error;
    await loadUserBusinesses();
    showAllBusinessesDashboard();
  } catch(e){ alert('Could not save: '+(e.message||'')); }
}
function startBusinessMode() {
  localStorage.setItem('bd_mode','business');
  if (userBusinesses.length) { showAllBusinessesDashboard(); }
  else showRegisterBusinessPage();
}

function startPersonalMode() {
  localStorage.setItem('bd_mode','personal');
  if (personalProfile) { showPersonalHome(); }
  else showPersonalSetup();
}

function hideAuthScreen() {
  try { closeBkMenu(); } catch(e) {}
  document.getElementById('bkAuthScreen')?.classList.add('hidden');
  try { bfiInit(); } catch(e) {}
  try {
    reqRefreshBell();
    if (!window._bkBellPoll) window._bkBellPoll = setInterval(() => { try { reqRefreshBell(); } catch(e) {} }, 60000);
  } catch(e) {}
}

