  document.addEventListener('touchend', cancel, { passive: true, capture: true });
  document.addEventListener('touchcancel', cancel, { passive: true, capture: true });
  document.addEventListener('contextmenu', e => { if (learningOn && Date.now() - _learnSwallow < 900 && learnResolve(e.target)) e.preventDefault(); }, true);
  // A press-and-hold that opened help must not also trigger the button underneath.
