// ══ BUTTERFI — the floating AI chat widget, present on every page ══
// Mounted once (idempotent) as a fixed-position overlay appended to
// <body>, independent of whatever #bkContent currently shows, so page
// navigation never remounts or loses it. Talks to /api/butterfi/chat,
// which has live read access (via the Worker's service-role key) to
// this business's real account balances and recent ledger entries —
// not a generic/offline tutor.
let bfiOpen = false;
let bfiSending = false;
let bfiMessages = []; // {role:'user'|'assistant', content:string}

function bfiInit() {
  if (document.getElementById('bfiRoot')) return; // already mounted
  if (!document.getElementById('bfiStyles')) {
    const style = document.createElement('style');
    style.id = 'bfiStyles';
    style.textContent = `
      #bfi-bubble-btn{position:fixed;right:18px;bottom:84px;width:58px;height:58px;border-radius:50%;
        background:linear-gradient(145deg,var(--gold),var(--gold));box-shadow:0 8px 20px var(--gold-dim);
        display:flex;align-items:center;justify-content:center;font-size:1.5rem;cursor:pointer;z-index:10050;
        border:none;padding:0;-webkit-tap-highlight-color:transparent;}
      #bfi-bubble-btn{touch-action:none;-webkit-user-select:none;user-select:none;}
      #bfi-bubble-btn.bfi-dragging{cursor:grabbing;transform:scale(1.08);box-shadow:0 14px 30px rgba(0,0,0,0.3);transition:none;}
      #bfi-bubble-btn.bfi-docking{transition:transform .22s ease,opacity .22s ease;transform:scale(.2);opacity:0;}
      #bkMenuBtn.bfi-hot{transform:scale(1.22);box-shadow:0 0 0 3px var(--gold),0 6px 18px rgba(0,0,0,0.25) !important;transition:transform .12s ease;}
      #bkMenuBfi{position:absolute;right:14px;bottom:9px;width:34px;height:34px;border-radius:50%;border:none;padding:0;
        background:var(--gold);color:#fff;font-size:1.05rem;display:none;align-items:center;justify-content:center;cursor:pointer;
        box-shadow:0 3px 10px var(--gold-dim);-webkit-tap-highlight-color:transparent;}
      #bkMenuBfi.bfi-pop{animation:bfiPop .28s ease;}
      @keyframes bfiPop{0%{transform:scale(.2)}70%{transform:scale(1.18)}100%{transform:scale(1)}}
      #bfi-bubble-dot{position:absolute;top:-1px;right:-1px;width:12px;height:12px;border-radius:50%;
        background:#34d399;border:2px solid var(--bg);}
      #bfi-greeting{position:fixed;right:16px;bottom:150px;width:236px;max-width:68vw;background:var(--surface);
        border:1px solid var(--gold);border-radius:14px 14px 2px 14px;padding:13px;
        box-shadow:0 10px 28px rgba(0,0,0,0.35);z-index:10050;font-size:0.78rem;color:var(--white);line-height:1.5;}
      #bfi-greeting .bfi-close{float:right;color:var(--muted);cursor:pointer;font-size:0.72rem;margin-left:8px;}
      #bfi-panel{position:fixed;z-index:10060;background:var(--surface);display:flex;flex-direction:column;
        box-shadow:0 10px 40px rgba(0,0,0,0.5);}
      @media(min-width:560px){ #bfi-panel{right:18px;bottom:18px;width:380px;height:580px;border-radius:16px;border:1px solid var(--border);} }
      @media(max-width:559px){ #bfi-panel{inset:0;width:100%;height:100%;} }
      #bfi-header{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--border);background:var(--surface2);flex:0 0 auto;}
      #bfi-header .bfi-avatar{width:36px;height:36px;border-radius:50%;background:var(--gold);display:flex;align-items:center;justify-content:center;font-size:1.05rem;flex:0 0 auto;}
      #bfi-msgs{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:10px;}
      .bfi-row{display:flex;gap:7px;max-width:88%;}
      .bfi-row.bfi-user{align-self:flex-end;max-width:84%;}
      .bfi-avatar-sm{width:24px;height:24px;border-radius:50%;background:var(--surface2);display:flex;align-items:center;justify-content:center;font-size:0.72rem;flex:0 0 auto;}
      .bfi-bubble{border-radius:4px 14px 14px 14px;padding:9px 12px;font-size:0.8rem;line-height:1.5;background:var(--surface2);border:1px solid var(--border);color:var(--white);white-space:pre-wrap;}
      .bfi-row.bfi-user .bfi-bubble{background:var(--gold);color:#1a1304;border:none;border-radius:14px 4px 14px 14px;font-weight:600;}
      #bfi-chips{display:flex;gap:7px;padding:0 14px 10px;overflow-x:auto;flex:0 0 auto;}
      .bfi-chip{flex:0 0 auto;background:var(--surface2);border:1px solid var(--border);border-radius:20px;padding:7px 12px;font-size:0.7rem;color:var(--off);white-space:nowrap;cursor:pointer;}
      #bfi-inputbar{display:flex;align-items:center;gap:8px;padding:11px 13px;border-top:1px solid var(--border);background:var(--surface2);flex:0 0 auto;}
      #bfi-input{flex:1;background:var(--surface);border:1px solid var(--border2);border-radius:22px;padding:10px 15px;font-size:0.8rem;color:var(--white);outline:none;font-family:inherit;}
      #bfi-send{width:38px;height:38px;border-radius:50%;background:var(--gold);border:none;display:flex;align-items:center;justify-content:center;font-size:1rem;color:#1a1304;flex:0 0 auto;cursor:pointer;}
      #bfi-send:disabled{opacity:0.5;cursor:default;}
      /* ── Butterfi chat: refreshed look ── */
      #bfi-panel{background:var(--bg);overflow:hidden;box-shadow:0 18px 60px rgba(10,20,40,0.35);}
      @media(min-width:560px){ #bfi-panel{width:392px;height:600px;border-radius:20px;border:1px solid var(--border);} }
      #bfi-header{gap:11px;padding:14px 14px 13px 16px;background:var(--surface);border-bottom:1px solid var(--border);}
      #bfi-header .bfi-avatar{width:42px;height:42px;background:var(--surface2);border:1px solid var(--border);box-shadow:0 2px 8px var(--gold-dim);}
      .bfi-title{font-size:1rem;font-weight:800;letter-spacing:0.06em;color:var(--white);line-height:1.1;}
      .bfi-sub{font-size:0.64rem;color:var(--muted);font-weight:600;display:flex;align-items:center;gap:5px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
      .bfi-sub i{width:7px;height:7px;border-radius:50%;background:#34d399;flex:none;box-shadow:0 0 0 3px rgba(52,211,153,0.2);}
      .bfi-hbtn{border:1px solid var(--border2);background:var(--surface);color:var(--off);border-radius:18px;padding:6px 11px;font-size:0.66rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:5px;font-family:inherit;line-height:1;}
      .bfi-hbtn.on{background:var(--gold);color:var(--accent-ink,#fff);border-color:var(--gold);}
      .bfi-hbtn.x{border:none;background:transparent;padding:6px 8px;font-size:0.95rem;color:var(--muted);}
      #bfi-msgs{padding:16px 14px;gap:12px;background:var(--bg);}
      .bfi-hero{text-align:center;padding:14px 10px 6px;}
      .bfi-hero .bfi-papilio{margin:0 auto 10px;display:block;}
      .bfi-hero h3{margin:0 0 6px;font-size:1.02rem;font-weight:800;color:var(--white);}
      .bfi-hero p{margin:0 auto;font-size:0.76rem;line-height:1.55;color:var(--muted);max-width:290px;}
      .bfi-row{gap:8px;align-items:flex-end;}
      .bfi-avatar-sm{width:26px;height:26px;background:var(--surface);border:1px solid var(--border);}
      .bfi-bubble{background:var(--surface);border:1px solid var(--border);border-radius:16px 16px 16px 4px;padding:10px 13px;box-shadow:0 1px 2px rgba(10,20,40,0.05);}
      .bfi-row.bfi-user .bfi-bubble{background:var(--gold);color:var(--accent-ink,#fff);border-radius:16px 16px 4px 16px;box-shadow:0 3px 10px var(--gold-dim);}
      .bfi-bubble.bfi-err{background:var(--surface2);border-style:dashed;color:var(--off);}
      .bfi-dots{display:inline-flex;gap:4px;padding:3px 2px;}
      .bfi-dots i{width:6px;height:6px;border-radius:50%;background:var(--muted);opacity:.4;animation:bfiDot 1.1s infinite ease-in-out;}
      .bfi-dots i:nth-child(2){animation-delay:.18s}.bfi-dots i:nth-child(3){animation-delay:.36s}
      @keyframes bfiDot{0%,80%,100%{opacity:.25;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}
      #bfi-chips{flex-wrap:wrap;overflow:visible;padding:0 14px 12px;background:var(--bg);}
      .bfi-chip{background:var(--surface);border:1px solid var(--border2);color:var(--off);font-weight:600;box-shadow:0 1px 2px rgba(10,20,40,0.05);}
      .bfi-chip:hover{border-color:var(--gold);color:var(--gold);}
      #bfi-inputbar{background:var(--surface);padding:11px 12px 13px;}
      #bfi-input{background:var(--bg);border-radius:24px;padding:11px 16px;}
      #bfi-input:focus{border-color:var(--gold);box-shadow:0 0 0 3px var(--gold-dim);}
      #bfi-send{background:var(--gold);color:var(--accent-ink,#fff);width:40px;height:40px;box-shadow:0 3px 10px var(--gold-dim);}
      #bfi-bubble-btn .bfi-ico{width:80%;height:80%;}
    `;
    document.head.appendChild(style);
  }
  const root = document.createElement('div');
  root.id = 'bfiRoot';
  document.body.appendChild(root);
  bfiInitDrag();
  bfiRender();
  bfiApplyDockState();
  try { learnInit(); } catch (e) {}
  if (!sessionStorage.getItem('bfi_greeted') && !bfiIsDocked()) {
    setTimeout(() => { if (!bfiOpen) bfiShowGreeting(); }, 1400);
  }
}

// ── Move the bubble anywhere; drop it on the ☰ menu button to tuck it away ──
function bfiIsDocked() { try { return localStorage.getItem('bd_bfi_docked') === '1'; } catch(e) { return false; } }
function bfiSavedPos() { try { const p = JSON.parse(localStorage.getItem('bk_bfi_pos')||'null'); return (p && isFinite(p.x) && isFinite(p.y)) ? p : null; } catch(e) { return null; } }
function bfiClampPos(x, y) {
  const sz = 58, m = 4;
  return { x: Math.max(m, Math.min(x, window.innerWidth - sz - m)), y: Math.max(m, Math.min(y, window.innerHeight - sz - m)) };
}
function bfiApplyPos() {
  const b = document.getElementById('bfi-bubble-btn'); if (!b) return;
  const p = bfiSavedPos(); if (!p) return;
  const c = bfiClampPos(p.x, p.y);
  b.style.left = c.x + 'px'; b.style.top = c.y + 'px'; b.style.right = 'auto'; b.style.bottom = 'auto';
}
let _bfiJustDragged = false;
function bfiBubbleClick() { if (_bfiJustDragged) return; bfiToggle(); }
function bfiOverMenuBtn(cx, cy) {
  const m = document.getElementById('bkMenuBtn'); if (!m) return false;
  const r = m.getBoundingClientRect(), pad = 18;
  return cx >= r.left - pad && cx <= r.right + pad && cy >= r.top - pad && cy <= r.bottom + pad;
}
function bfiApplyDockState(animate) {
  const docked = bfiIsDocked();
  const mb = document.getElementById('bkMenuBfi');
  if (mb) { mb.style.display = docked ? 'flex' : 'none'; if (docked && animate) { mb.classList.remove('bfi-pop'); void mb.offsetWidth; mb.classList.add('bfi-pop'); } }
  if (docked) { document.getElementById('bfi-greeting')?.remove(); if (!bfiOpen) { const r = document.getElementById('bfiRoot'); if (r) r.innerHTML = ''; } }
  else if (!bfiOpen) bfiRender();
}
function bfiDock() {
  try { localStorage.setItem('bd_bfi_docked', '1'); } catch(e) {}
  document.getElementById('bkMenuBtn')?.classList.remove('bfi-hot');
  const b = document.getElementById('bfi-bubble-btn');
  const finish = () => { bfiApplyDockState(true); try { bdToast('Butterfi is tucked into the menu — open the menu and tap the Butterfi button to bring it back'); } catch(e) {} };
  if (b) { b.classList.add('bfi-docking'); setTimeout(() => { const r = document.getElementById('bfiRoot'); if (r && !bfiOpen) r.innerHTML = ''; finish(); }, 230); }
  else finish();
}
function bfiUndock() {
  try { localStorage.setItem('bd_bfi_docked', '0'); localStorage.removeItem('bk_bfi_pos'); } catch(e) {}
  try { closeBkMenu(); } catch(e) {}
  bfiApplyDockState();
  if (!bfiOpen) bfiRender();
}
function bfiInitDrag() {
  const root = document.getElementById('bfiRoot'); if (!root || root._bfiDrag) return;
  root._bfiDrag = true;
  let d = null;
  root.addEventListener('pointerdown', e => {
    const b = e.target.closest('#bfi-bubble-btn'); if (!b) return;
    if (e.button !== undefined && e.button > 0) return;
    const r = b.getBoundingClientRect();
    d = { b, ox: e.clientX - r.left, oy: e.clientY - r.top, sx: e.clientX, sy: e.clientY, moved: false, pid: e.pointerId };
  });
  window.addEventListener('pointermove', e => {
    if (!d) return;
    if (!d.moved) {
      if (Math.hypot(e.clientX - d.sx, e.clientY - d.sy) < 6) return;
      d.moved = true; d.b.classList.add('bfi-dragging');
      document.getElementById('bfi-greeting')?.remove(); try { sessionStorage.setItem('bfi_greeted','1'); } catch(_) {}
      try { d.b.setPointerCapture(d.pid); } catch(_) {}
    }
    e.preventDefault();
    const c = bfiClampPos(e.clientX - d.ox, e.clientY - d.oy);
    d.b.style.left = c.x + 'px'; d.b.style.top = c.y + 'px'; d.b.style.right = 'auto'; d.b.style.bottom = 'auto';
    d.hot = bfiOverMenuBtn(c.x + 29, c.y + 29);
    document.getElementById('bkMenuBtn')?.classList.toggle('bfi-hot', d.hot);
  }, { passive:false });
  const end = () => {
    if (!d) return;
    const x = d; d = null;
    x.b.classList.remove('bfi-dragging');
    document.getElementById('bkMenuBtn')?.classList.remove('bfi-hot');
    if (!x.moved) return;
    _bfiJustDragged = true; setTimeout(() => { _bfiJustDragged = false; }, 60);
    if (x.hot) { bfiDock(); return; }
    const r = x.b.getBoundingClientRect();
    try { localStorage.setItem('bk_bfi_pos', JSON.stringify({ x: Math.round(r.left), y: Math.round(r.top) })); } catch(_) {}
  };
  window.addEventListener('pointerup', end);
  window.addEventListener('pointercancel', end);
  window.addEventListener('resize', () => bfiApplyPos());
}

function bfiShowGreeting() {
  if (document.getElementById('bfi-greeting') || bfiOpen || bfiIsDocked() || bfiSavedPos()) return;
  const el = document.createElement('div');
  el.id = 'bfi-greeting';
  el.innerHTML = `<span class="bfi-close" onclick="bfiDismissGreeting()">✕</span>`
    + `<b>${bfiMark(16)} Hi, I'm Butterfi!</b><br/>Ask me anything about your books — recording a sale, VAT, your reports, you name it.`;
  el.onclick = (e) => { if (e.target === el || e.target.tagName !== 'SPAN') bfiToggle(); };
  document.body.appendChild(el);
}
function bfiDismissGreeting() {
  sessionStorage.setItem('bfi_greeted', '1');
  document.getElementById('bfi-greeting')?.remove();
}

function bfiToggle() {
  bfiDismissGreeting();
  bfiOpen = !bfiOpen;
  bfiRender();
}

function bfiRender() {
  const root = document.getElementById('bfiRoot');
  if (!root) return;
  if (!bfiOpen) {
    if (bfiIsDocked()) { root.innerHTML = ''; bfiApplyDockState(true); return; }
    root.innerHTML = `<button id="bfi-bubble-btn" onclick="bfiBubbleClick()" aria-label="Open Butterfi chat — drag to move"><span class="bfi-ico"></span><span id="bfi-bubble-dot"></span></button>`;
    bfiApplyPos();
    return;
  }
  const bizName = (activeBusiness && activeBusiness.name) || businessDisplayName || 'your business';
  const chipsHtml = bfiMessages.length ? '' : `
    <div id="bfi-chips">
      <div class="bfi-chip" onclick="bfiQuickAsk('How is my cash doing this week?')">How's my cash doing?</div>
      <div class="bfi-chip" onclick="bfiQuickAsk('What is VAT and do I need to charge it?')">What's VAT?</div>
      <div class="bfi-chip" onclick="bfiQuickAsk('Walk me through reconciling my bank account.')">Reconcile my bank</div>
    </div>`;
  root.innerHTML = `
    <div id="bfi-panel">
      <div id="bfi-header">
        <div class="bfi-avatar">${bfiMark(30)}</div>
        <div style="flex:1;min-width:0;">
          <div class="bfi-title">BUTTERFi</div>
          <div class="bfi-sub"><i></i>Online · ${escH(bizName)}</div>
        </div>
        <button class="bfi-hbtn ${learningOn?'on':''}" id="bfiLearnBtn" onclick="learnToggle()" title="Learning mode: plain-English help across the app">${learnIco(13)} Learn</button>
        <button class="bfi-hbtn x" onclick="bfiToggle()" aria-label="Close">✕</button>
      </div>
      <div id="bfi-msgs"></div>
      ${chipsHtml}
      <div id="bfi-inputbar">
        <input id="bfi-input" type="text" placeholder="Ask Butterfi anything…" onkeydown="if(event.key==='Enter')bfiSendFromInput()"/>
        <button id="bfi-send" onclick="bfiSendFromInput()" ${bfiSending?'disabled':''}>➤</button>
      </div>
    </div>`;
  bfiRenderMessages();
  setTimeout(() => document.getElementById('bfi-input')?.focus(), 50);
}

function bfiRenderMessages() {
  const el = document.getElementById('bfi-msgs');
  if (!el) return;
  const rows = bfiMessages.map(m => m.role === 'user'
    ? `<div class="bfi-row bfi-user"><div class="bfi-bubble">${escH(m.content)}</div></div>`
    : `<div class="bfi-row"><div class="bfi-avatar-sm">${bfiMark(16)}</div><div class="bfi-bubble${m.err?' bfi-err':''}">${escH(m.content)}</div></div>`
  ).join('');
  const intro = bfiMessages.length ? '' : `<div class="bfi-hero">${bfiMark(60)}<h3>Hi, I'm Butterfi</h3><p>I can see your business's real balances and recent entries. Ask me things like "why did my cash drop this week?" or "explain this report."</p></div>`;
  const typing = bfiSending ? `<div class="bfi-row"><div class="bfi-avatar-sm">${bfiMark(16)}</div><div class="bfi-bubble"><span class="bfi-dots"><i></i><i></i><i></i></span></div></div>` : '';
  el.innerHTML = intro + rows + typing;
  el.scrollTop = el.scrollHeight;
  // The chips row is only built into the initial bfiRender() markup;
  // once a real conversation starts, hide it here too rather than
  // requiring a full panel re-render (which would drop input focus).
  const chips = document.getElementById('bfi-chips');
  if (chips) chips.style.display = bfiMessages.length ? 'none' : '';
}

function bfiQuickAsk(text) { bfiSend(text); }

function bfiSendFromInput() {
  const input = document.getElementById('bfi-input');
  if (!input) return;
  const text = input.value;
  input.value = '';
  bfiSend(text);
}

async function bfiSend(text) {
  text = (text || '').trim();
  if (!text || bfiSending) return;
  const priorHistory = bfiMessages.slice();
  bfiMessages.push({ role: 'user', content: text });
  bfiSending = true;
  bfiRenderMessages();
  const sendBtn = document.getElementById('bfi-send');
  if (sendBtn) sendBtn.disabled = true;

  try {
    const res = await fetch('/api/butterfi/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        user_id: bkUser?.id,
        business_id: (activeBusiness && activeBusiness.id) || null,
        business_name: (activeBusiness && activeBusiness.name) || businessDisplayName || '',
        message: text,
        history: priorHistory,
      }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.error) throw new Error(data.error || 'Something went wrong.');
    bfiMessages.push({ role: 'assistant', content: data.reply || "Sorry, I didn't catch that." });
  } catch (e) {
    try { console.warn('[Butterfi]', e && e.message); } catch (x) {}
    bfiMessages.push({ role: 'assistant', err: true, content: "I can't answer right now. Something on our side needs attention, and it isn't anything you did. Please try again in a little while." });
  } finally {
    bfiSending = false;
    bfiRenderMessages();
    const sendBtn2 = document.getElementById('bfi-send');
    if (sendBtn2) sendBtn2.disabled = false;
  }
}

async function doSignUp() {
  const email = document.getElementById('suEmail')?.value.trim();
  const pw    = document.getElementById('suPW')?.value;
  const pw2   = document.getElementById('suPW2')?.value;
  const err   = document.getElementById('suAuthErr');
  if (!email || !pw) { if(err) err.textContent='Please enter your email and a password.'; return; }
  if (pw.length < 6)  { if(err) err.textContent='Password must be at least 6 characters.'; return; }
  if (pw !== pw2)     { if(err) err.textContent='Passwords do not match.'; return; }
  if (err) { err.textContent='Creating account…'; err.style.color='var(--muted)'; }

  const { data, error } = await bkDb.auth.signUp({ email, password: pw });
  if (error) {
    if (err) { err.textContent = error.message; err.style.color='var(--red)'; }
    return;
  }

  // The presence of a session (not just data.user, which Supabase
  // returns either way) is what actually indicates whether email
  // confirmation is required — signUp() always returns a user object
  // even when the account still needs verifying.
  if (data.session) {
    bkUser = data.user;
    showAuthScreen('personal-info');
    return;
  }

  bkPendingSignupEmail = email;
  showAuthScreen('verify-email');
}

// ── EMAIL VERIFICATION (OTP) ────────────────────────────────
function bkClearOtpBoxes() {
  document.querySelectorAll('.bk-otp-box').forEach(b => { b.value = ''; b.classList.remove('error'); });
}
function bkFocusFirstOtpBox() {
  document.querySelector('.bk-otp-box[data-idx="0"]')?.focus();
}
function bkGetOtpValue() {
  return Array.from(document.querySelectorAll('.bk-otp-box')).map(b => b.value).join('');
}
function bkMarkOtpBoxesError() {
  document.querySelectorAll('.bk-otp-box').forEach(b => b.classList.add('error'));
}
function bkOnOtpInput(el) {
  el.value = el.value.replace(/[^0-9]/g, '').slice(0, 1);
  el.classList.remove('error');
  document.getElementById('bkEOtp')?.classList.remove('show');
  const idx = parseInt(el.dataset.idx, 10);
  if (el.value && idx < 5) document.querySelector(`.bk-otp-box[data-idx="${idx + 1}"]`)?.focus();
  if (bkGetOtpValue().length === 6) bkVerifyEmailCode();
}
function bkOnOtpKeydown(e, el) {
  const idx = parseInt(el.dataset.idx, 10);
  if (e.key === 'Backspace' && !el.value && idx > 0) {
    const prev = document.querySelector(`.bk-otp-box[data-idx="${idx - 1}"]`);
    if (prev) { prev.focus(); prev.value = ''; }
  }
}
function bkOnOtpPaste(e) {
  e.preventDefault();
  const text = (e.clipboardData || window.clipboardData).getData('text').replace(/[^0-9]/g, '').slice(0, 6);
  const boxes = document.querySelectorAll('.bk-otp-box');
  text.split('').forEach((ch, i) => { if (boxes[i]) boxes[i].value = ch; });
  if (text.length === 6) bkVerifyEmailCode();
  else boxes[text.length]?.focus();
}
function bkStartResendCooldown(seconds) {
  clearInterval(_bkResendCooldownInterval);
  let remaining = seconds;
  const el = document.getElementById('bkResendText');
  function tick() {
    if (!el) return;
    if (remaining <= 0) {
      clearInterval(_bkResendCooldownInterval);
      el.innerHTML = `<span style="color:var(--gold);font-weight:700;cursor:pointer;" onclick="bkResendVerificationCode()">Resend code</span>`;
      return;
    }
    const m = Math.floor(remaining / 60), s = String(remaining % 60).padStart(2, '0');
    el.textContent = `Resend code in ${m}:${s}`;
    remaining--;
  }
  tick();
  _bkResendCooldownInterval = setInterval(tick, 1000);
}
async function bkVerifyEmailCode() {
  const code  = bkGetOtpValue();
  const email = bkPendingSignupEmail;
  const errEl = document.getElementById('bkEOtp');
  const btn   = document.getElementById('bkVerifyBtn');
  if (code.length !== 6) {
    if (errEl) { errEl.textContent = 'Enter all 6 digits'; errEl.classList.add('show'); }
    return;
  }
  if (btn) { btn.textContent = 'Verifying…'; btn.disabled = true; }
  if (errEl) errEl.classList.remove('show');

  const { data, error } = await bkDb.auth.verifyOtp({ email, token: code, type: 'signup' });

  if (btn) { btn.textContent = 'Verify →'; btn.disabled = false; }
  if (error) {
    if (errEl) { errEl.textContent = "That code's not right. Try again."; errEl.classList.add('show'); }
    bkMarkOtpBoxesError();
    return;
  }
  clearInterval(_bkResendCooldownInterval);
  bkUser = data?.session?.user || data?.user;
  showAuthScreen('personal-info');
}
async function bkResendVerificationCode() {
  const email = bkPendingSignupEmail;
  const { error } = await bkDb.auth.resend({ type: 'signup', email });
  if (!error) bkStartResendCooldown(60);
}
function bkBackToSignupFromVerify() {
  clearInterval(_bkResendCooldownInterval);
  showAuthScreen('signup');
}

async function doLogin() {
  const email = document.getElementById('loginEmail')?.value.trim();
  const pw    = document.getElementById('loginPW')?.value;
  const err   = document.getElementById('loginErr');
  if (!email||!pw) { if(err) { err.textContent='Please enter email and password.'; err.style.color='var(--red)'; } return; }
  if (err) { err.textContent='Logging in…'; err.style.color='var(--gold)'; }

  const { data:{ session }, error } = await bkDb.auth.signInWithPassword({ email, password:pw });
  if (error||!session) {
    if (err) { err.textContent = error?.message||'Login failed. Please try again.'; err.style.color='var(--red)'; }
    return;
  }
  if (!(await bkMfaGate())) { if (err) { err.textContent = 'Sign-in was cancelled.'; err.style.color='var(--red)'; } return; }
  bkUser = session.user;
  hideAuthScreen();
  await continueInit();
}

// ── SIGNUP WIZARD ─────────────────────────────────────────────
function renderSuStep() {
  const c = document.getElementById('bkAuthContent');
  const pct = Math.round((suStep/SU_TOTAL)*100);
  let html = `
    <div style="margin-bottom:20px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <span style="font-size:0.65rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:var(--muted);">Step ${suStep} of ${SU_TOTAL}</span>
        ${suStep>1?`<button class="su-back-btn" onclick="suBack()">← Back</button>`:''}
      </div>
      <div class="su-progress"><div class="su-progress-bar" style="width:${pct}%"></div></div>
    </div>`;

  if (suStep===1) html += `
    <div class="su-heading">What type of account do you want to set up?</div>
    <div class="su-options">
      <div class="su-option sel" onclick="suData.accountType='business';renderSuStep()">
        <div class="su-option-icon">🏢</div>
        <div class="su-option-title">Business Account</div>
        <div class="su-option-desc">For sole traders, companies, partnerships and organisations</div>
      </div>
    </div>
    <button class="su-next-btn" onclick="suNext()">Continue →</button>
    <div style="text-align:center;margin-top:16px;"><button class="su-back-btn" onclick="showAuthScreen('landing')">← Back to start</button></div>`;

  else if (suStep===2) html += `
    <div class="su-heading">Who are you?</div>
    <div class="su-options">
      <div class="su-option ${suData.whoAreYou==='owner'?'sel':''}" onclick="suData.whoAreYou='owner';renderSuStep()">
        <div class="su-option-icon">👔</div>
        <div class="su-option-title">Business Owner</div>
        <div class="su-option-desc">I own or co-own this business</div>
      </div>
      <div class="su-option ${suData.whoAreYou==='manager'?'sel':''}" onclick="suData.whoAreYou='manager';renderSuStep()">
        <div class="su-option-icon">🗂️</div>
        <div class="su-option-title">Manager</div>
        <div class="su-option-desc">I manage this business</div>
      </div>
      <div class="su-option ${suData.whoAreYou==='employee'?'sel':''}" onclick="suData.whoAreYou='employee';renderSuStep()">
        <div class="su-option-icon">👷</div>
        <div class="su-option-title">Employee / Staff</div>
        <div class="su-option-desc">I work here and record transactions</div>
      </div>
    </div>
    <button class="su-next-btn" onclick="suNext()">Continue →</button>`;

  else if (suStep===3) {
    const types=[
      {val:'sole_proprietorship',icon:'👤',label:'Sole Proprietorship',desc:'One owner, personally liable'},
      {val:'company',icon:'🏢',label:'Limited Company',desc:'Separate legal entity'},
      {val:'partnership',icon:'🤝',label:'Partnership',desc:'Two or more owners'},
      {val:'plc',icon:'📈',label:'Public Limited Company',desc:'Publicly traded shares'},
      {val:'joint_venture',icon:'🔗',label:'Joint Venture',desc:'Two entities collaborating'},
      {val:'government',icon:'🏛️',label:'Government Account',desc:'Public sector entity'},
    ];
    html += `<div class="su-heading">What type of business?</div>
    <div class="su-options" style="grid-template-columns:repeat(2,1fr);gap:10px;">
      ${types.map(t=>`
      <div class="su-option ${suData.businessType===t.val?'sel':''}"
        onclick="suData.businessType='${t.val}';renderSuStep()">
        <div class="su-option-icon">${t.icon}</div>
        <div class="su-option-title">${t.label}</div>
        <div class="su-option-desc">${t.desc}</div>
      </div>`).join('')}
    </div>
    <button class="su-next-btn" onclick="suNext()">Continue →</button>`;
  }

  else if (suStep===4) html += `
    <div class="su-heading">Is your business registered?</div>
    <div class="su-options">
      <div class="su-option ${suData.isRegistered===true?'sel':''}"
        onclick="suData.isRegistered=true;renderSuStep()">
        <div class="su-option-icon">✅</div>
        <div class="su-option-title">Yes, it is registered</div>
        <div class="su-option-desc">RC number / CAC / FIRS registered</div>
      </div>
      <div class="su-option ${suData.isRegistered===false?'sel':''}"
        onclick="suData.isRegistered=false;renderSuStep()">
        <div class="su-option-icon">⏳</div>
        <div class="su-option-title">Not yet registered</div>
        <div class="su-option-desc">Operating informally for now</div>
      </div>
    </div>
    <button class="su-next-btn" onclick="suNext()">Continue →</button>`;

  else if (suStep===5) {
    const industries = Object.keys(INDUSTRY_BUSINESS_TYPES);
    const query = (suData._indSearch||'').toLowerCase();
    const filtered = query ? industries.filter(i=>i.toLowerCase().includes(query)) : industries;
    const selectedIndustry = suData.industry;
    const bizTypes = selectedIndustry ? (INDUSTRY_BUSINESS_TYPES[selectedIndustry]||[]) : [];
    const selectedBizTypes = suData.bizTypes || [];

    html += `
      <div class="su-heading">What industry are you in?</div>
      <input class="su-search" type="text" placeholder="Search industry…"
        id="suIndSearch" value="${suData._indSearch||''}"
        oninput="suFilterIndustries(this.value)"/>
      <div class="su-industry-grid" id="suIndGrid" style="max-height:180px;overflow-y:auto;margin-bottom:16px;">
        ${filtered.map((ind,ii)=>`
        <div class="su-industry-item ${suData.industry===ind?'sel':''}"
          data-ii="${ii}" onclick="suSelectIndustryByIndex(this)">
          ${ind}
        </div>`).join('')}
      </div>
      ${selectedIndustry?`
        <div style="font-size:0.75rem;font-weight:700;color:var(--gold);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.08em;">
          Select your business type(s) — up to 5
        </div>
        <div class="su-selected-count">
          <span id="suBizCount">${selectedBizTypes.length}</span>/5 selected
        </div>
        <div class="su-biz-type-grid" id="suBizTypeGrid">
          ${bizTypes.map((bt,bi)=>{
            const isSel = selectedBizTypes.includes(bt);
            const isMaxed = !isSel && selectedBizTypes.length >= 5;
            return `<div class="su-biz-type-item ${isSel?'sel':''} ${isMaxed?'disabled-max':''}"
              data-bi="${bi}" onclick="suToggleBizTypeByIndex(this,${bi})">
              ${isSel?'✓ ':''}${bt}
            </div>`;
          }).join('')}
        </div>
        <div style="display:flex;gap:8px;margin-top:12px;">
          <input class="su-search" type="text" id="customBizTypeInput"
            placeholder="Not listed? Type your business type here…"
            style="margin-bottom:0;flex:1;" />
          <button class="su-next-btn" style="padding:10px 16px;white-space:nowrap;"
            onclick="suAddCustomBizType()">Add</button>
        </div>
        <button class="su-next-btn" id="suNextBtn5" style="width:100%;margin-top:12px;" onclick="suNext()"
          ${selectedBizTypes.length===0?'disabled style="opacity:0.4;width:100%;margin-top:12px;"':''}>
          Continue with ${selectedBizTypes.length} business type${selectedBizTypes.length!==1?'s':''} →
        </button>
      `:''} `;
  }

  else if (suStep===6) html += `
    <div class="su-heading">Where is your business located?</div>
    <div class="su-row">
      <div class="su-field">
        <label class="su-label">Country *</label>
        <input class="su-input" type="text" id="su_country" value="${suData.country}" placeholder="e.g. Nigeria"
          list="su_countries" oninput="suData.country=this.value;suRefreshState()"/>
        <datalist id="su_countries">${ALL_COUNTRIES.map(c=>`<option value="${c}">`).join('')}</datalist>
      </div>
      <div class="su-field">
        <label class="su-label">State / Province</label>
        <input class="su-input" type="text" id="su_state" value="${suData.state}" placeholder="e.g. Lagos"
          list="su_states" oninput="suData.state=this.value;suRefreshLga()"/>
        <datalist id="su_states"></datalist>
      </div>
    </div>
    <div class="su-row">
      <div class="su-field">
        <label class="su-label">Local Government Area</label>
        <input class="su-input" type="text" id="su_lga" value="${suData.lga}" placeholder="e.g. Ikeja"
          list="su_lgas" oninput="suData.lga=this.value"/>
        <datalist id="su_lgas"></datalist>
      </div>
      <div class="su-field">
        <label class="su-label">Town</label>
        <input class="su-input" type="text" id="su_town" value="${suData.town}" placeholder="Town name"/>
      </div>
    </div>
    <div class="su-row">
      <div class="su-field">
        <label class="su-label">Village (if applicable)</label>
        <input class="su-input" type="text" id="su_village" value="${suData.village}" placeholder="Village name"/>
      </div>
      <div class="su-field">
        <label class="su-label">Street / Address</label>
        <input class="su-input" type="text" id="su_street" value="${suData.street}" placeholder="Street address"/>
      </div>
    </div>
    <button class="su-next-btn" style="margin-top:16px;" onclick="suSaveLocation()">Continue →</button>`;

  else if (suStep===7) html += `
    <div class="su-heading">What is the name of your business?</div>
    <div class="su-field">
      <label class="su-label">Business Name *</label>
      <input class="su-input" type="text" id="su_bizname" value="${suData.businessName}"
        placeholder="Enter your business name" style="font-size:1rem;padding:13px;"/>
    </div>
    <button class="su-next-btn" style="margin-top:8px;" onclick="suSaveName()">Continue →</button>`;

  else if (suStep===8) {
    // Products spreadsheet
    const sym = CURRENCIES[suData.prodCurrency]?.symbol || '₦';
    const rows = suData.products;

    html += `
      <div class="su-heading">Register the products & services you offer</div>
      <div style="display:flex;gap:10px;margin-bottom:14px;">
        <div class="su-option ${suData.offerType==='products'?'sel':''}"
          style="flex:1;padding:12px 8px;" onclick="suData.offerType='products';renderSuStep()">
          <div style="font-size:1rem;margin-bottom:4px;">📦</div>
          <div style="font-size:0.78rem;font-weight:700;color:var(--white);">Products</div>
        </div>
        <div class="su-option ${suData.offerType==='services'?'sel':''}"
          style="flex:1;padding:12px 8px;" onclick="suData.offerType='services';renderSuStep()">
          <div style="font-size:1rem;margin-bottom:4px;">🛠️</div>
          <div style="font-size:0.78rem;font-weight:700;color:var(--white);">Services</div>
        </div>
        <div class="su-option ${suData.offerType==='both'?'sel':''}"
          style="flex:1;padding:12px 8px;" onclick="suData.offerType='both';renderSuStep()">
          <div style="font-size:1rem;margin-bottom:4px;">⚡</div>
          <div style="font-size:0.78rem;font-weight:700;color:var(--white);">Both</div>
        </div>
      </div>
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;">
        <table class="su-prod-table" style="min-width:520px;">
          <thead><tr>
            <th style="width:36px;">S/N</th>
            <th style="width:90px;">Offering</th>
            <th>Type</th>
            <th style="width:150px;">
              Unit Price
              <select class="su-curr-select" onchange="suData.prodCurrency=this.value;renderSuStep()">
                ${Object.entries(CURRENCIES).map(([k,v])=>`<option value="${k}" ${suData.prodCurrency===k?'selected':''}>${v.symbol} ${k}</option>`).join('')}
              </select>
            </th>
            <th style="width:32px;"></th>
            <th style="width:28px;"></th>
          </tr></thead>
          <tbody id="suProdBody">
            ${rows.map((r,i)=>`
            <tr>
              <td class="su-prod-sn">${i+1}</td>
              <td>
                <select class="su-prod-cell" style="font-size:0.75rem;padding:4px 4px;"
                  onchange="suData.products[${i}].offering=this.value">
                  <option value="service" ${(r.offering||'service')==='service'?'selected':''}>Service</option>
                  <option value="product" ${(r.offering||'service')==='product'?'selected':''}>Product</option>
                </select>
              </td>
              <td><input class="su-prod-cell" type="text" value="${escH(r.name)}"
                placeholder="Enter type…"
                oninput="suData.products[${i}].name=this.value"/></td>
              <td>
                <div style="display:flex;align-items:center;padding:0 4px;gap:3px;">
                  <span style="color:var(--gold);font-size:0.78rem;flex-shrink:0;">${CURRENCIES[suData.prodCurrency]?.symbol||'₦'}</span>
                  <input class="su-prod-cell" type="text" inputmode="decimal"
                    style="text-align:right;padding:4px 2px;"
                    value="${r.price>0?r.price.toLocaleString('en-NG'):''}"
                    placeholder="0"
                    oninput="suPriceInput(this,${i})"
                    onfocus="this.select()"/>
                </div>
              </td>
              <td class="su-prod-del"><button class="su-prod-del-btn" onclick="suDelProd(${i})">✕</button></td>
              <td><button class="su-prod-save-btn" onclick="suSaveProdRow(${i})" title="Save row">›</button></td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>
      <button class="su-add-row-btn" onclick="suAddProdRow()">+ Add row</button>
      <button class="su-done-btn" onclick="suDone()">Done — Go to My Dashboard →</button>`;
  }

  // ── Step 9: Employee personal details + company selection ──
  else if (suStep===9) {
    // Fetch registered companies asynchronously and inject into the dropdown
    html += `
    <div class="su-heading">Your Details</div>
    <div style="display:flex;flex-direction:column;gap:12px;max-width:420px;margin:0 auto;">
      <div class="acct-field"><label class="acct-label">First Name *</label>
        <input class="acct-input" type="text" id="su_fname" value="${escH(suData.firstName||'')}"
          oninput="suData.firstName=this.value" placeholder="First name"/></div>
      <div class="acct-field"><label class="acct-label">Middle Name</label>
        <input class="acct-input" type="text" id="su_mname" value="${escH(suData.middleName||'')}"
          oninput="suData.middleName=this.value" placeholder="Middle name (optional)"/></div>
      <div class="acct-field"><label class="acct-label">Last Name *</label>
        <input class="acct-input" type="text" id="su_lname" value="${escH(suData.lastName||'')}"
          oninput="suData.lastName=this.value" placeholder="Last name"/></div>
      <div class="acct-field"><label class="acct-label">Date of Birth</label>
        <input class="acct-input" type="date" id="su_dob" value="${suData.dob||''}"
          onchange="suData.dob=this.value"/></div>
      <div class="acct-field"><label class="acct-label">Position / Job Title *</label>
        <input class="acct-input" type="text" id="su_position" value="${escH(suData.position||'')}"
          oninput="suData.position=this.value" placeholder="e.g. Barber, Laundry Attendant, Cashier"/></div>
      <div class="acct-field">
        <label class="acct-label">Company / Business *</label>
        <input class="acct-input" type="text" id="su_coSearch" placeholder="Search for your company…"
          oninput="suFilterCompanies(this.value)" autocomplete="off"
          value="${escH(suData.companySearch||'')}"/>
        <select class="acct-input" id="su_company" style="margin-top:6px;"
          onchange="suSelectCompany(this.value)">
          <option value="">— Select company —</option>
          <option value="__testing__">🧪 No company yet — just testing the platform</option>
          <option value="__loading__" disabled>Loading registered companies…</option>
        </select>
        <div id="su_company_note" style="font-size:0.7rem;color:var(--muted);margin-top:4px;">
          ${suData.companyName ? '✓ Selected: <strong style="color:var(--gold)">'+escH(suData.companyName)+'</strong>' : 'Companies register on this platform and appear in this list.'}
        </div>
      </div>
    </div>
    <button class="su-next-btn" style="margin-top:20px;" onclick="suEmployeeDone()">Continue →</button>
    <div style="text-align:center;margin-top:12px;">
      <button class="su-back-btn" onclick="suStep=2;renderSuStep()">← Back</button>
    </div>`;
    // Load companies in background
    setTimeout(suLoadCompanies, 100);
  }

  c.innerHTML = html;

  // After render, init datalists for step 6
  if (suStep===6) {
    suRefreshState();
  }
}

function suNext() {
  if (suStep===1 && !suData.accountType) return;
  // Employee flow: after step 2 (Who are you?), go straight to employee details step
  if (suStep===2 && suData.whoAreYou==='employee') { suStep=9; renderSuStep(); return; }
  if (suStep===9) { suDone(); return; } // employee done after their details
  if (suStep===3 && !suData.businessType) return;
  if (suStep===4 && suData.isRegistered===null) return;
  if (suStep===5 && suData.bizTypes.length===0) return;
  if (suStep===8) { suDone(); return; }
  // When entering step 8, pre-populate products from selected business types
  if (suStep===7) {
    suData.products = [];
    suData.bizTypes.forEach(bt=>{
      const prods = BIZ_TYPE_PRODUCTS[bt] || BIZ_TYPE_PRODUCTS['default'];
      prods.forEach(p=>suData.products.push({
        name: p.n,
        price: p.p,
        currency: suData.prodCurrency,
        bizType: bt,
        offering: p.svc ? 'service' : 'product',
      }));
    });
  }
  suStep++;
  renderSuStep();
}

function suBack() {
  if (suStep<=1) { showAuthScreen('landing'); return; }
  suStep--;
  renderSuStep();
}

function suToggleBizType(bt) {
  const idx = suData.bizTypes.indexOf(bt);
  if (idx>=0) suData.bizTypes.splice(idx,1);
  else if (suData.bizTypes.length<5) suData.bizTypes.push(bt);
}

// ── No-re-render business type toggle ─────────────────────────
// Uses index into the current industry's bizTypes array — no string escaping
function suToggleBizTypeByIndex(el, idx) {
  const industry  = suData.industry;
  const bizTypes  = INDUSTRY_BUSINESS_TYPES[industry] || [];
  const bt        = bizTypes[idx];
  if (!bt) return;

  const alreadySel = suData.bizTypes.includes(bt);
  if (!alreadySel && suData.bizTypes.length >= 5) { suBizTypeMaxed(); return; }

  suToggleBizType(bt);
  const isSel = suData.bizTypes.includes(bt);
  el.classList.toggle('sel', isSel);
  el.textContent = (isSel ? '✓ ' : '') + bt;

  // Update count
  const countEl = document.getElementById('suBizCount');
  if (countEl) countEl.textContent = suData.bizTypes.length;

  // Update disabled state on all non-selected items
  const maxed = suData.bizTypes.length >= 5;
  document.querySelectorAll('#suBizTypeGrid .su-biz-type-item').forEach(item => {
    if (!item.classList.contains('sel')) {
      item.classList.toggle('disabled-max', maxed);
    }
  });

  // Update continue button
  const btn = document.getElementById('suNextBtn5');
  if (btn) {
    const n = suData.bizTypes.length;
    btn.disabled = n === 0;
    btn.style.opacity = n === 0 ? '0.4' : '1';
    btn.textContent = `Continue with ${n} business type${n!==1?'s':''} →`;
  }
}

function suToggleBizTypeUI(el, bt) { /* kept for compatibility */ suToggleBizType(bt); }

function suBizTypeMaxed() {
  const countEl = document.getElementById('suBizCount');
  if (countEl) {
    countEl.style.color = 'var(--red)';
    setTimeout(()=>{ countEl.style.color=''; }, 1000);
  }
}

// ── Industry search — targeted grid update (no full re-render) ─
function suFilterIndustries(val) {
  suData._indSearch = val;
  const industries = Object.keys(INDUSTRY_BUSINESS_TYPES);
  const q = val.toLowerCase();
  const filtered = q ? industries.filter(i=>i.toLowerCase().includes(q)) : industries;
  const grid = document.getElementById('suIndGrid');
  if (!grid) return;
  grid.innerHTML = filtered.map((ind,ii)=>`
    <div class="su-industry-item ${suData.industry===ind?'sel':''}"
      data-ii="${ii}" onclick="suSelectIndustryByIndex(this)">
      ${ind}
    </div>`).join('');
  if (!filtered.length) {
    grid.innerHTML = `<div style="color:var(--muted);font-size:0.8rem;padding:8px;grid-column:1/-1;">
      No match — <button onclick="suData.industry=document.getElementById('suIndSearch').value;suData.bizTypes=[];renderSuStep()"
        style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:0.8rem;">Use "${val}" as custom industry →</button>
    </div>`;
  }
}

function suSelectIndustry(ind) {
  suData.industry = ind;
  suData.bizTypes = [];
  renderSuStep(); // Full re-render here is OK — user deliberately chose an industry
}

// Index-based selector — avoids all string-escaping issues in onclick attributes
function suSelectIndustryByIndex(el) {
  const industries = Object.keys(INDUSTRY_BUSINESS_TYPES);
  const q          = (suData._indSearch || '').toLowerCase();
  const filtered   = q ? industries.filter(i => i.toLowerCase().includes(q)) : industries;
  const idx        = parseInt(el.dataset.ii);
  const ind        = filtered[idx];
  if (ind) suSelectIndustry(ind);
}

// ── Ledger sub-account switcher ────────────────────────────────
async function switchLedgerAccount(accountId) {
  const acct = (accounts[activeType]||[]).find(a=>String(a.id)===String(accountId));
  if (acct) await openAccount(activeType, acct);
}

// ── COA: sub-account links to its ledger ──────────────────────
function coaOpenRecord(id, type) {
  const acct = (accounts[type]||[]).find(a=>a.id===id);
  if (acct) { openAccount(type, acct); closeBkMenu(); }
}

// ── Save signup products to bk_products (if logged in) ────────
async function saveSignupProducts() {
  if (!bkUser || !suData.products || suData.products.length === 0) return;
  const inserts = suData.products
    .filter(p => p.name && p.name.trim())
    .map(p => ({
      user_id:      bkUser.id,
      product_name: p.name.trim(),
      price:        p.price || 0,
      cost_price:   0,
      qty_in_stock: 0,
      unit:         'unit',
      is_service:   p.offering === 'service',
      is_active:    true,
    }));
  if (inserts.length > 0) {
    inserts.forEach(x=>x.business_id=activeBusiness?.id||null);
    await bkDb.from('bk_products').insert(inserts);
  }
}

// ── Save role + business profile for real ──────────────────────
// Routing at every future login depends on this — must persist even
// though the products spreadsheet above stays test-run for now.
async function saveSignupProfile() {
  if (!bkUser) return;
  await bkDb.from('bk_business_profiles').upsert({
    user_id:            bkUser.id,
    business_name:      suData.businessName || null,
    industry:           suData.industry || null,
    business_type:      (suData.bizTypes||[]).join(', ') || suData.position || null,
    country:            suData.country || null,
    state_province:     suData.state || null,
    lga:                suData.lga || null,
    role:               suData.whoAreYou || 'owner',
    staff_display_name: suData.staffName || null,
    updated_at:         new Date().toISOString(),
  }, { onConflict:'user_id' });
}

function suAddCustomBizType() {
  const input = document.getElementById('customBizTypeInput');
  if (!input) return;
  const val = input.value.trim();
  if (!val) { input.style.borderColor='var(--red)'; return; }
  if (suData.bizTypes.length >= 5) {
    input.style.borderColor='var(--red)';
    input.placeholder = 'Maximum 5 business types selected';
    return;
  }
  if (!suData.bizTypes.includes(val)) {
    suData.bizTypes.push(val);
    // Also add to the industry list so it appears selected
    if (!INDUSTRY_BUSINESS_TYPES[suData.industry]) INDUSTRY_BUSINESS_TYPES[suData.industry]=[];
    if (!INDUSTRY_BUSINESS_TYPES[suData.industry].includes(val)) {
      INDUSTRY_BUSINESS_TYPES[suData.industry].push(val);
    }
  }
  input.value = '';
  renderSuStep();
  setTimeout(()=>{ document.getElementById('customBizTypeInput')?.focus(); }, 30);
}

function suPriceInput(el, i) {
  // Strip non-numeric, format with commas
  const raw = el.value.replace(/[^0-9.]/g, '');
  const num = parseFloat(raw) || 0;
  suData.products[i].price = num;
  // Format display with commas
  const parts = raw.split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const pos = el.selectionStart;
  el.value = parts.join('.');
  // Restore cursor position approximately
  try { el.setSelectionRange(pos, pos); } catch(e) {}
}

function suRefreshState() {
  const country = document.getElementById('su_country')?.value||suData.country;
  const states  = COUNTRY_STATES[country]||[];
  const dl = document.getElementById('su_states');
  if (dl) dl.innerHTML = states.map(s=>`<option value="${s}">`).join('');
  suRefreshLga();
}

function suRefreshLga() {
  const state = document.getElementById('su_state')?.value||suData.state;
  const lgas  = NIGERIA_LGAS[state]||[];
  const dl = document.getElementById('su_lgas');
  if (dl) dl.innerHTML = lgas.map(l=>`<option value="${l}">`).join('');
}

function suSaveLocation() {
  suData.country = document.getElementById('su_country')?.value.trim()||suData.country;
  suData.state   = document.getElementById('su_state')?.value.trim()||suData.state;
  suData.lga     = document.getElementById('su_lga')?.value.trim()||suData.lga;
  suData.town    = document.getElementById('su_town')?.value.trim();
  suData.village = document.getElementById('su_village')?.value.trim();
  suData.street  = document.getElementById('su_street')?.value.trim();
  suNext();
}

function suSaveName() {
  const name = document.getElementById('su_bizname')?.value.trim();
  if (!name) { document.getElementById('su_bizname').style.borderColor='var(--red)'; return; }
  suData.businessName = name;
  suNext();
}

function suAddProdRow() {
  suData.products.push({name:'', price:0, currency:suData.prodCurrency});
  renderSuStep();
  setTimeout(()=>{
    const rows = document.querySelectorAll('#suProdBody tr');
    const last = rows[rows.length-1];
    last?.querySelector('input')?.focus();
  }, 30);
}

function suDelProd(i) {
  suData.products.splice(i,1);
  renderSuStep();
}

function suSaveProdRow(i) {
  const btn = document.querySelectorAll('#suProdBody tr')[i]?.querySelector('.su-prod-save-btn');
  if (btn) { btn.textContent='✓'; btn.style.color='var(--green)'; setTimeout(()=>{btn.textContent='›';btn.style.color='';},1200); }
}

// ── Employee signup helpers ────────────────────────────────────

let _allCompanies = []; // cached list of registered businesses

async function suLoadCompanies() {
  try {
    const { data } = await bkDb.from('bk_business_profiles')
      .select('business_name')
      .not('business_name', 'is', null)
      .in('role', ['owner', 'manager'])
      .order('business_name');

    // Unique business names only
    const seen = {};
    _allCompanies = (data||[])
      .map(r => r.business_name)
      .filter(n => n && !seen[n] && (seen[n]=1));

    suPopulateCompanyDropdown(_allCompanies, document.getElementById('su_coSearch')?.value||'');
  } catch(e) {
    _allCompanies = [];
  }
}

function suPopulateCompanyDropdown(companies, filter) {
  const sel = document.getElementById('su_company');
  if (!sel) return;
  const q = (filter||'').toLowerCase().trim();
  const filtered = q ? companies.filter(n => n.toLowerCase().includes(q)) : companies;

  sel.innerHTML = '<option value="">— Select company —</option>'
    + '<option value="__testing__">🧪 No company yet — just testing the platform</option>'
    + filtered.map(n => `<option value="${escH(n)}" ${suData.companyName===n?'selected':''}>${escH(n)}</option>`).join('');
}

function suFilterCompanies(q) {
  suData.companySearch = q;
  suPopulateCompanyDropdown(_allCompanies, q);
}

function suSelectCompany(val) {
  if (val === '__testing__') {
    suData.businessName = 'Testing Platform';
    suData.companyName  = 'Testing Platform';
  } else if (val && val !== '__loading__') {
    suData.businessName = val;
    suData.companyName  = val;
  }
  const note = document.getElementById('su_company_note');
  if (note && val && val !== '__loading__') {
    note.innerHTML = val === '__testing__'
      ? 'You\u2019ll be in test mode — you can switch to a real company later.'
      : '\u2713 Selected: <strong style="color:var(--gold)">'+escH(suData.companyName)+'</strong>';
  }
}

function suEmployeeDone() {
  const fname = document.getElementById('su_fname')?.value.trim();
  const lname = document.getElementById('su_lname')?.value.trim();
  const pos   = document.getElementById('su_position')?.value.trim();
  const comp  = document.getElementById('su_company')?.value;
  if (!fname || !lname) { alert('Please enter your first and last name.'); return; }
  if (!pos)   { alert('Please enter your position / job title.'); return; }
  if (!comp || comp === '__loading__') { alert('Please select your company, or choose "No company yet".'); return; }

  suData.firstName  = fname;
  suData.lastName   = lname;
  suData.middleName = document.getElementById('su_mname')?.value.trim()||'';
  suData.dob        = document.getElementById('su_dob')?.value||'';
  suData.position   = pos;

  // staff_display_name = "First [Middle] Last"
  const parts = [fname, suData.middleName, lname].filter(Boolean);
  suData.staffName = parts.join(' ');

  suDone();
}

async function suDone() {
  await saveSignupProducts();
  await saveSignupProfile();
  // Hide the auth wizard and fully initialise the new user's app
  hideAuthScreen();
  await continueInit();
}

function suShowTestDashboard() {
  hideAuthScreen();
  businessDisplayName = suData.businessName || '';
  document.getElementById('bkUserName').textContent = suData.businessName || 'User';
  showDashboard();
}

// Employees/staff land directly in the Staff Pages area — no main app chrome
function suShowStaffEntry() {
  hideAuthScreen();
  staffHideChrome();
  staffDisplayName = suData.staffName || suData.name || (bkUser?.email?.split('@')[0]) || 'Staff';
  businessDisplayName = suData.businessName || '';
  document.getElementById('bkUserName').textContent = suData.businessName || 'Test User';
  showStaffPage();
}

