// The Worker (/api/*) no longer trusts a user_id sent in the request body — it
// verifies the signed-in user's Supabase access token. Every same-origin
// /api/ call (Butterfi, bank feeds, scan-a-sale, journal upload, templates —
// including calls made by bankfeed-module.js) gets that token attached here,
// in one place. Provider webhooks are server-to-server and never pass through
// the browser, so they are not affected.
(function(){
  const _origFetch = window.fetch.bind(window);
  window.fetch = async function(input, init){
    try {
      const url = typeof input === 'string' ? input : (input && input.url) || '';
      if (url.startsWith('/api/')) {
        const { data } = await bkDb.auth.getSession();   // refreshes an expired token automatically
        const token = data && data.session && data.session.access_token;
        if (token) {
          const headers = new Headers((init && init.headers) || (typeof input !== 'string' && input.headers) || {});
          if (!headers.has('Authorization')) headers.set('Authorization', 'Bearer ' + token);
          init = Object.assign({}, init || {}, { headers });
        }
      }
    } catch (e) { /* fall through: the Worker will answer 401 and the feature shows its normal error */ }
    return _origFetch(input, init);
  };
})();


// ═══ MULTI-DEVICE SYNC ═════════════════════════════════════════
// Everything below keeps every device you're signed in on in step:
//  1. SETTINGS (theme, font, column layouts, chart-of-account numbers & groups,
//     labels…) are mirrored to the cloud (table bk_user_prefs) and applied on
//     your other devices within a second or two.
//  2. DATA (journal, transactions, accounts, currency/decimal settings): when a
//     device saves, it pings your other devices (Supabase Realtime broadcast),
//     and database change events cover anything written by the server. A device
//     refreshes quietly — never while you are typing or have unsaved rows.
const BD_PREF_PREFIXES = ['bd_theme','bd_font','bd_coa_','bd_jrn_labels','bd_jrn_datefmt','bd_jrn_arrange','bd_led_','bd_cols_','bd_hidden_','bd_collabels_','bd_colmeta_','bd_ps_customvals','bd_bfi_docked'];
const BD_LIVE_TABLES   = ['bk_journal','bk_transactions','bk_accounts','bk_settings'];
function bdIsPrefKey(k) { return typeof k === 'string' && BD_PREF_PREFIXES.some(p => k.indexOf(p) === 0); }

const _bdLsSet = Storage.prototype.setItem, _bdLsRem = Storage.prototype.removeItem;
let _bdPrefsApplying = false, _bdPrefsDisabled = false, _bdPrefTimer = null;
const _bdDirty = new Set();
function _bdTsRead() { try { return JSON.parse(localStorage.getItem('bd_sync_ts') || '{}'); } catch (e) { return {}; } }
function _bdTsWrite(o) { try { _bdLsSet.call(localStorage, 'bd_sync_ts', JSON.stringify(o)); } catch (e) {} }
Storage.prototype.setItem = function (k, v) {
  _bdLsSet.call(this, k, v);
  if (this === localStorage && !_bdPrefsApplying && bdIsPrefKey(k)) bdPrefDirty(k);
};
Storage.prototype.removeItem = function (k) {
  _bdLsRem.call(this, k);
  if (this === localStorage && !_bdPrefsApplying && bdIsPrefKey(k)) bdPrefDirty(k);
};
function bdPrefDirty(k) {
  const ts = _bdTsRead(); ts[k] = Date.now(); _bdTsWrite(ts);
  _bdDirty.add(k);
  clearTimeout(_bdPrefTimer);
  _bdPrefTimer = setTimeout(bdPrefsPush, 700);
}
async function bdPrefsPush() {
  if (_bdPrefsDisabled || !bkUser || !_bdDirty.size) return;
  if (!navigator.onLine) { _bdPrefTimer = setTimeout(bdPrefsPush, 15000); return; }
  const keys = Array.from(_bdDirty); _bdDirty.clear();
  try {
    const { data, error: e0 } = await bkDb.from('bk_user_prefs').select('prefs').eq('user_id', bkUser.id).maybeSingle();
    if (e0) throw e0;
    const merged = (data && data.prefs) || {};
    const ts = _bdTsRead();
    keys.forEach(k => { merged[k] = { v: localStorage.getItem(k), t: ts[k] || Date.now() }; });
    const { error } = await bkDb.from('bk_user_prefs').upsert({ user_id: bkUser.id, prefs: merged, updated_at: new Date().toISOString() });
    if (error) throw error;
    bdBroadcast('user', 'prefs');
  } catch (e) {
    if (e && /bk_user_prefs|relation|does not exist|schema cache/i.test(e.message || '')) { _bdPrefsDisabled = true; console.warn('[sync] bk_user_prefs table not found — run the sync SQL once in Supabase.'); return; }
    keys.forEach(k => _bdDirty.add(k));
    _bdPrefTimer = setTimeout(bdPrefsPush, 15000);
  }
}
// Pull the cloud copy of the settings; newer-wins per key. `initial` also
// uploads settings this device has that the cloud has never seen.
async function bdPrefsPull(initial) {
  if (_bdPrefsDisabled || !bkUser || !navigator.onLine) return [];
  try {
    const { data, error } = await bkDb.from('bk_user_prefs').select('prefs').eq('user_id', bkUser.id).maybeSingle();
    if (error) throw error;
    const remote = (data && data.prefs) || {};
    const ts = _bdTsRead(), changed = [];
    _bdPrefsApplying = true;
    try {
      Object.keys(remote).forEach(k => {
        if (!bdIsPrefKey(k)) return;
        const r = remote[k] || {};
        if ((r.t || 0) > (ts[k] || 0)) {
          if (r.v === null || r.v === undefined) _bdLsRem.call(localStorage, k); else _bdLsSet.call(localStorage, k, r.v);
          ts[k] = r.t; changed.push(k);
        }
      });
      _bdTsWrite(ts);
      if (changed.indexOf('bd_bfi_docked') >= 0) { try { bfiApplyDockState(); } catch (e) {} }
      if (changed.indexOf('bd_theme') >= 0) { try { applyTheme(localStorage.getItem('bd_theme') || 'default'); } catch (e) {} }
      if (changed.indexOf('bd_font') >= 0)  { try { applyFont(localStorage.getItem('bd_font') || 'default'); } catch (e) {} }
    } finally { _bdPrefsApplying = false; }
    if (initial) {
      Object.keys(localStorage).forEach(k => { if (bdIsPrefKey(k) && !remote[k]) { const t2 = _bdTsRead(); if (!t2[k]) { t2[k] = Date.now(); _bdTsWrite(t2); } _bdDirty.add(k); } });
      if (_bdDirty.size) { clearTimeout(_bdPrefTimer); _bdPrefTimer = setTimeout(bdPrefsPush, 400); }
    }
    return changed;
  } catch (e) {
    if (e && /bk_user_prefs|relation|does not exist|schema cache/i.test(e.message || '')) { _bdPrefsDisabled = true; console.warn('[sync] bk_user_prefs table not found — run the sync SQL once in Supabase.'); }
    return [];
  }
}

// ── Realtime channels ─────────────────────────────────────────
const _bdDeviceId = Math.random().toString(36).slice(2);
let _bdChans = {}, _bdChanScope = '', _bdLastLocalWrite = 0, _bdPending = false, _bdRefreshTimer = null, _bdHiddenAt = 0, _bdBcastTimer = null, _bdPgChans = [];
function _bdScopes() {
  return { user: 'u-' + bkUser.id, data: (activeBusiness && activeBusiness.id) ? 'b-' + activeBusiness.id : 'u-' + bkUser.id };
}
function bdBroadcast(which, event) {
  try {
    const ch = _bdChans[which];
    if (ch) ch.send({ type: 'broadcast', event: event, payload: { from: _bdDeviceId, t: Date.now() } });
  } catch (e) {}
}
function bdSyncEnsure() {
  if (!bkUser) return;
  const sc = _bdScopes(), key = sc.user + '|' + sc.data;
  if (key === _bdChanScope) return;
  bdSyncStop();
  _bdChanScope = key;
  try {
    _bdChans.user = bkDb.channel('bdsync-' + sc.user + '-p', { config: { broadcast: { self: false } } })
      .on('broadcast', { event: 'prefs' }, () => { bdPrefsPull(false).then(ch => { if (ch.length) bdScheduleRefresh('prefs'); }); })
      .subscribe();
    _bdChans.data = bkDb.channel('bdsync-' + sc.data + '-d', { config: { broadcast: { self: false } } })
      .on('broadcast', { event: 'data' }, () => bdScheduleRefresh('remote'))
      .subscribe();
    // Server-side / other-writer changes (own echoes are ignored for a few seconds).
    const filt = (activeBusiness && activeBusiness.id) ? 'business_id=eq.' + activeBusiness.id : 'user_id=eq.' + bkUser.id;
    const pg = (name, table, filter, cb) => {
      try { _bdPgChans.push(bkDb.channel(name).on('postgres_changes', { event: '*', schema: 'public', table: table, filter: filter }, cb).subscribe()); } catch (e) {}
    };
    const onData = () => { if (Date.now() - _bdLastLocalWrite > 6000) bdScheduleRefresh('pg'); };
    ['bk_journal','bk_transactions','bk_accounts'].forEach(t => pg('bdpg-' + t + '-' + _bdDeviceId, t, filt, onData));
    pg('bdpg-settings-' + _bdDeviceId, 'bk_settings', 'user_id=eq.' + bkUser.id, onData);
    pg('bdpg-prefs-' + _bdDeviceId, 'bk_user_prefs', 'user_id=eq.' + bkUser.id, () => { bdPrefsPull(false).then(ch => { if (ch.length) bdScheduleRefresh('prefs'); }); });
  } catch (e) { console.warn('[sync] realtime unavailable', e); }
}
function bdSyncStop() {
  try { Object.keys(_bdChans).forEach(k => bkDb.removeChannel(_bdChans[k])); _bdPgChans.forEach(c => bkDb.removeChannel(c)); } catch (e) {}
  _bdChans = {}; _bdPgChans = []; _bdChanScope = '';
}
async function bdSyncStart() {
  if (!bkUser) return;
  try { await bdPrefsPull(true); } catch (e) {}
  bdSyncEnsure();
  if (!window._bdSyncTimerSet) {
    window._bdSyncTimerSet = true;
    setInterval(() => { try { if (bkUser) bdSyncEnsure(); else if (_bdChanScope) bdSyncStop(); } catch (e) {} }, 10000);
  }
}

// ── Notifying other devices after a local save ────────────────
// Wrap bkDb.from() so every successful insert/update/upsert/delete on the core
// tables pings the other devices (debounced), without touching each call site.
(function () {
  const origFrom = bkDb.from.bind(bkDb);
  function watch(q, table) {
    if (!q || typeof q.then !== 'function' || q.__bdw) return q;
    q.__bdw = true;
    const t = q.then.bind(q);
    q.then = function (res, rej) {
      return t(function (v) { try { if (v && !v.error) bdOnLocalWrite(table); } catch (e) {} return res ? res(v) : v; }, rej);
    };
    return q;
  }
  bkDb.from = function (table) {
    const b = origFrom(table);
    if (BD_LIVE_TABLES.indexOf(table) < 0) return b;
    ['insert','update','upsert','delete'].forEach(m => {
      const o = b[m]; if (typeof o !== 'function') return;
      b[m] = function () { return watch(o.apply(this, arguments), table); };
    });
    return b;
  };
})();
function bdOnLocalWrite() {
  _bdLastLocalWrite = Date.now();
  clearTimeout(_bdBcastTimer);
  _bdBcastTimer = setTimeout(() => bdBroadcast('data', 'data'), 500);
}

// ── Applying changes that came from another device ────────────
function bdScheduleRefresh() {
  _bdPending = true;
  clearTimeout(_bdRefreshTimer);
  _bdRefreshTimer = setTimeout(bdLiveRefresh, 1200);
}
function _bdBusy() {
  try {
    if (typeof jrnHasUnsaved === 'function' && jrnHasUnsaved()) return true;
    const ae = document.activeElement;
    if (ae && ae.closest && ae.closest('#bkContent') && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName || '')) return true;
    if (ae && ae.isContentEditable) return true;
    if (document.querySelector('#acctPickerPortal,#colMenuPortal,#coaTplOverlay,.bk-modal-overlay')) return true;
  } catch (e) {}
  return false;
}
const _BD_LIVE_ROUTES = /^(journal|dashboard|products|services|ap-vendors|ap-bills|ap-aging|coa|ledger:.*|report:.*)$/;
async function bdLiveRefresh() {
  if (!_bdPending || !bkUser || !navigator.onLine) return;
  if (document.visibilityState !== 'visible') return;             // picked up when the tab comes back
  if (_bdBusy()) { clearTimeout(_bdRefreshTimer); _bdRefreshTimer = setTimeout(bdLiveRefresh, 3000); return; }
  _bdPending = false;
  try {
    // currency / decimals / date format are stored in the cloud too
    const { data: st } = await bkDb.from('bk_settings').select('currency, decimal_places, date_format').eq('user_id', bkUser.id).maybeSingle();
    if (st) {
      if (st.currency && CURRENCIES[st.currency]) activeCurrency = st.currency;
      if (st.decimal_places != null) decimalPlaces = parseInt(st.decimal_places) || 0;
      if (st.date_format) dateFormat = st.date_format;
    }
  } catch (e) {}
  try { await jrnRefreshAccounts(); } catch (e) {}
  try { await refreshEquation(); } catch (e) {}
  if (_bdBusy()) { _bdPending = true; _bdRefreshTimer = setTimeout(bdLiveRefresh, 3000); return; }
  const route = currentPage || '';
  if (!_BD_LIVE_ROUTES.test(route)) return;
  const y = window.scrollY, c = document.getElementById('bkContent'), cy = c ? c.scrollTop : 0;
  try {
    if (route === 'coa') { await _coaLoadBalances(); renderCOA(); }
    else bdRestoreRoute();
  } catch (e) {}
  [150, 600, 1400].forEach(ms => setTimeout(() => { try { window.scrollTo(0, y); const c2 = document.getElementById('bkContent'); if (c2) c2.scrollTop = cy; } catch (e) {} }, ms));
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') { _bdHiddenAt = Date.now(); return; }
  if (!bkUser) return;
  // Phones suspend realtime in the background — catch up when the app returns.
  try { bdSyncEnsure(); } catch (e) {}
  if (_bdHiddenAt && Date.now() - _bdHiddenAt > 20000) {
    bdPrefsPull(false).then(ch => { if (ch.length) bdScheduleRefresh('prefs'); });
    bdScheduleRefresh('resume');
  }
});
window.addEventListener('online', () => { if (bkUser) { bdPrefsPull(false).then(() => {}); bdScheduleRefresh('online'); bdPrefsPush(); } });

// ── CURRENCIES ───────────────────────────────────────────────
const CURRENCIES = {
  NGN:{ symbol:'₦', name:'Nigerian Naira',       rate:1        },
  USD:{ symbol:'$', name:'US Dollar',            rate:0.000625 }, // ~₦1,600 per $1 (Jun 2026)
  GBP:{ symbol:'£', name:'British Pound',        rate:0.000496 }, // ~₦2,016 per £1
  EUR:{ symbol:'€', name:'Euro',                 rate:0.000575 }, // ~₦1,739 per €1
  GHS:{ symbol:'₵', name:'Ghana Cedi',           rate:0.00952  }, // ~₦105 per ₵1
  ZAR:{ symbol:'R', name:'South African Rand',   rate:0.01136  }, // ~₦88 per R1
};
let activeCurrency = 'NGN';

// ── FMT — format a number with current currency and decimal places ──
let decimalPlaces = 0;
function fmt(n) {
  const c = CURRENCIES[activeCurrency];
  const converted = n * c.rate;
  const abs = Math.abs(converted);
  const formatted = abs.toLocaleString('en-US', {
    minimumFractionDigits: decimalPlaces,
    maximumFractionDigits: decimalPlaces,
  });
  return (n < 0 ? '-' : '') + c.symbol + formatted;
}

// Exact amount for the Master Journal cards: never rounded to the global
// "decimal places" setting. Whole numbers show without decimals; anything with
// decimals shows them as entered (at least 2, up to 6), e.g. ₦1,250.75.
function fmtExact(n) {
  const c = CURRENCIES[activeCurrency];
  const v = (Number(n)||0) * c.rate;
  const abs = Math.abs(v);
  const rounded = Math.round(abs * 1e6) / 1e6;     // strips float noise only
  const hasFrac = Math.abs(rounded - Math.round(rounded)) > 1e-9;
  return (v < 0 ? '-' : '') + c.symbol + rounded.toLocaleString('en-US', {
    minimumFractionDigits: hasFrac ? 2 : 0,
    maximumFractionDigits: 6,
  });
}


function setCurrency(code) {
  activeCurrency = code;
  if (bkUser) {
    bkDb.from('bk_settings').upsert({ user_id:bkUser.id, currency:code, updated_at:new Date().toISOString() });
  }
  // Only refresh equation and re-render if we're on a page that shows them
  if (currentPage !== 'settings') {
    refreshEquation();
    if (activeAccount) renderLedger();
    else if (document.getElementById('journalTable')) renderJournal();
  }
}

