// ── HEAVY LIBRARIES: loaded when first needed, not on every page load ──────────
// PDF export, Excel reading, barcode scanning and statement OCR together are several
// megabytes. They used to download (one after another) before the app could start;
// now each group is fetched on demand — and the two export groups quietly in the
// background a few seconds after the first page is up, so they are usually ready by
// the time anyone clicks Export.
const BK_LIB_GROUPS = {
  pdfexport: [
    'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.5.28/jspdf.plugin.autotable.min.js',   // needs jsPDF first
  ],
  xlsx:   ['https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'],
  pdflib: ['https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js'],
  zxing:  ['https://cdn.jsdelivr.net/npm/@zxing/library@0.20.0/umd/index.min.js'],
  upload: ['@xlsx', '@pdflib', '@pdfjs', 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js', '/journal-ocr-extract.js?v=1'],
};
const _bkLibPromises = {};
function _bkLoadScriptTag(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src; s.async = false;
    s.onload = () => resolve();
    s.onerror = () => reject(new Error('Failed to load ' + src));
    document.head.appendChild(s);
  });
}
function bkEnsureLib(name) {
  if (_bkLibPromises[name]) return _bkLibPromises[name];
  const list = BK_LIB_GROUPS[name] || [];
  const p = (async () => {
    // pdf.js (self-hosted ES module) is attached to window the way the old inline module did it
    for (const item of list) {
      if (item === '@pdfjs') {
        if (!window.pdfjsLib) {
          const m = await import('/bk-docreader.js');
          window.pdfjsLib = m;
          m.GlobalWorkerOptions.workerSrc = '/bk-docreader-worker.js';
        }
      } else if (item.charAt(0) === '@') {
        await bkEnsureLib(item.slice(1));
      } else {
        await _bkLoadScriptTag(item);
      }
    }
  })();
  _bkLibPromises[name] = p;
  p.catch(() => { delete _bkLibPromises[name]; });     // allow a retry after a failed download
  return p;
}
function bkEnsureLibs(names) { return Promise.all((names || []).map(bkEnsureLib)); }
// Quiet background fetch of the export libraries once the first page is showing.
function bkWarmLibs() {
  const go = () => { bkEnsureLibs(['pdfexport', 'xlsx']).catch(() => {}); };
  if ('requestIdleCallback' in window) requestIdleCallback(go, { timeout: 8000 }); else setTimeout(go, 5000);
}

// ── LAZY SCRIPT LOADING ──────────────────────────────────────
// Sales module (customers, invoices, quotes, AR aging) only loads
// when someone actually opens it, not on every bookkeeping page load.
const _bkLoadedScripts = new Set();
function bkLoadScriptOnce(src) {
  if (!_bkLoadedScripts.has(src) && src.charAt(0) === '/') {
    // our own feature modules (sales, bills, documents…) may print PDFs / read spreadsheets
    return bkEnsureLibs(['pdfexport', 'xlsx']).catch(() => {}).then(() => _bkLoadScriptOnceRaw(src));
  }
  return _bkLoadScriptOnceRaw(src);
}
function _bkLoadScriptOnceRaw(src) {
  return new Promise((resolve, reject) => {
    if (_bkLoadedScripts.has(src)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = src;
    s.onload = () => { _bkLoadedScripts.add(src); resolve(); };
    s.onerror = () => reject(new Error('Failed to load ' + src));
    document.head.appendChild(s);
  });
}
