// ── NOTIFICATION BELL ─────────────────────────────────────────────
// Lives here (not in requisitions-module.js) so the unread dot shows up
// the moment someone logs in, without waiting for the Requisitions
// section to be opened. Generic (bk_notifications), so other features
// can post into the same bell later without any change here.
let _bkNotifCache = [];
let _bkBellOpen = false;

async function reqRefreshBell() {
  if (!bkUser) return;
  try {
    const { data } = await bkDb.from('bk_notifications').select('*').eq('user_id', bkUser.id)
      .order('created_at', { ascending: false }).limit(20);
    _bkNotifCache = data || [];
  } catch (e) { _bkNotifCache = []; }
  const unread = _bkNotifCache.filter(n => !n.is_read).length;
  const dot = document.getElementById('bkBellDot');
  if (dot) dot.style.display = unread ? 'block' : 'none';
  if (_bkBellOpen) renderBellDrop();

  // Requisitions menu badge — unread "new requisition" notifications are
  // the ones actually waiting on this person's decision, so that's what
  // the menu badge counts (not every unread notification type).
  const reqUnread = _bkNotifCache.filter(n => !n.is_read && n.type === 'requisition_new').length;
  const badge = document.getElementById('mnuReqBadge');
  if (badge) { badge.textContent = reqUnread; badge.style.display = reqUnread ? 'inline-block' : 'none'; }
}

function reqToggleBellDrop() { _bkBellOpen ? reqCloseBellDrop() : reqOpenBellDrop(); }
async function reqOpenBellDrop() {
  _bkBellOpen = true;
  document.getElementById('bkBellOverlay').style.display = 'block';
  document.getElementById('bkBellDrop').style.display = 'block';
  await reqRefreshBell();
}
function reqCloseBellDrop() {
  _bkBellOpen = false;
  const ov = document.getElementById('bkBellOverlay'); if (ov) ov.style.display = 'none';
  const dr = document.getElementById('bkBellDrop'); if (dr) dr.style.display = 'none';
}

const BK_NOTIF_ICONS = { requisition_new: '🛒', requisition_decided: '✅' };

function renderBellDrop() {
  const drop = document.getElementById('bkBellDrop');
  if (!drop) return;
  const rows = _bkNotifCache.length ? _bkNotifCache.map(n => `
    <div class="bk-notif-item ${n.is_read ? '' : 'unread'}" onclick="reqOpenNotification('${n.id}')">
      <div class="bk-notif-ic">${BK_NOTIF_ICONS[n.type] || '🔔'}</div>
      <div>
        <div class="bk-notif-t1">${escH(n.title)}</div>
        ${n.body ? `<div class="bk-notif-t2">${escH(n.body)}</div>` : ''}
        <div class="bk-notif-t3">${typeof fmtRelTime === 'function' ? fmtRelTime(n.created_at) : new Date(n.created_at).toLocaleDateString()}</div>
      </div>
    </div>`).join('') : `<div class="bk-notif-empty">No notifications yet.</div>`;
  drop.innerHTML = `<div class="hdr">Notifications</div>${rows}`;
}

async function reqOpenNotification(id) {
  const n = _bkNotifCache.find(x => x.id === id);
  if (!n) return;
  try { await bkDb.from('bk_notifications').update({ is_read: true }).eq('id', id); } catch (e) {}
  n.is_read = true;
  reqCloseBellDrop();
  await reqRefreshBell();
  if (n.link_type === 'requisition' && n.link_id) {
    await ensureRequisitionsModuleLoaded();
    try { closeBkMenu(); } catch (e) {}
    await reqOpenDetail(n.link_id);
  }
}
let accounts      = {};   // { capital:[{id,account_name,opening_balance},...], ... }
let activeType    = null;
let activeAccount = null; // { id, account_name, opening_balance, opening_date }
let rows          = [];
let isDirty       = false;
let addingForType = null;
let searchQuery   = '';
let searchTimer = null;
let ledColFilters = {};   // per-column search on the open ledger (key -> text)
let dateFrom      = '';
let dateTo        = '';
let charts        = {};

// Balance direction: which side increases the balance?
// Debit increases: asset, expenditure
// Credit increases: capital, liability, income
const DEBIT_NORMAL  = ['asset','expenditure'];
const CREDIT_NORMAL = ['capital','liability','income'];

// ── INIT ─────────────────────────────────────────────────────
(async () => {
  const { data:{ session } } = await bkDb.auth.getSession();
  if (!session) {
    // Only attempt a refresh if a session was actually ever stored —
    // otherwise (a brand-new visitor reaching the registration page,
    // or someone who just logged out) this was an unconditional,
    // pointless network round-trip attempting to refresh a token that
    // never existed, which is exactly what delayed the auth screen
    // from appearing.
    const hasStoredSession = Object.keys(localStorage).some(k => k.startsWith('sb-') && k.includes('auth-token'));
    if (hasStoredSession) {
      const { data:r } = await bkDb.auth.refreshSession();
      if (r?.session) {
        bkUser = r.session.user;
        hideAuthScreen();
        await continueInit();
        return;
      }
    }
    showAuthScreen('landing');
  } else {
    bkUser = session.user;
    hideAuthScreen();
    await continueInit();
  }
})();

let userRole = 'owner'; // 'owner' | 'manager' | 'employee' — determines which UI a logged-in user sees
let staffDisplayName = ''; // for employee role: their own name shown on Staff Pages
let businessDisplayName = ''; // shared: the business name, used in both UIs

async function continueInit() {
  // Everything below used to run one request after another (profile, then role,
  // then settings, then accounts, then the equation, then businesses, then the
  // cloud settings sync) — roughly eight network round trips in a row before the
  // first page could draw. These requests don't depend on each other, so they now
  // run side by side and the first page waits only for the slowest one.
  const syncP = (async () => { try { await bdSyncStart(); } catch(e) {} })();

  const nameP = (async () => {
    try {
      const { data:profile } = await bkDb.from('profiles')
        .select('username').eq('id', bkUser.id).maybeSingle();
      const name = profile?.username
        ? profile.username.charAt(0).toUpperCase() + profile.username.slice(1)
        : (bkUser.email?.split('@')[0] || 'there');
      const el = document.getElementById('bkUserName');
      if (el) el.textContent = name;
      staffDisplayName = name;
    } catch(e) {
      const el = document.getElementById('bkUserName');
      const fallback = bkUser.email?.split('@')[0] || 'there';
      if (el) el.textContent = fallback;
      staffDisplayName = fallback;
    }
  })();

  // ── Determine role + business name — decides which UI this user sees ──
  const roleP = (async () => {
    try {
      const { data:bizProfile } = await bkDb.from('bk_business_profiles')
        .select('role, business_name, staff_display_name').eq('user_id', bkUser.id).maybeSingle();
      userRole = bizProfile?.role || 'owner';
      businessDisplayName = bizProfile?.business_name || '';
      if (bizProfile?.staff_display_name) staffDisplayName = bizProfile.staff_display_name;
    } catch(e) {
      userRole = 'owner'; // safest default — never accidentally lock an owner out of the full app
      businessDisplayName = '';
    }
  })();

  const settingsP = (async () => {
    try {
      const { data:settings } = await bkDb.from('bk_settings')
        .select('currency, decimal_places, date_format').eq('user_id', bkUser.id).maybeSingle();
      if (settings?.currency)                setCurrency(settings.currency);
      if (settings?.date_format)             setDateFormat(settings.date_format);
      if (settings?.decimal_places != null)  decimalPlaces = parseInt(settings.decimal_places)||0;
    } catch(e) { /* use defaults */ }
  })();

  const acctP = (async () => { try { await loadAccounts(); } catch(e) { } })();

  await Promise.all([nameP, roleP, settingsP, acctP]);

  // The equation bar fills in by itself once settings + accounts are known; the
  // first page no longer waits for it.
  try { refreshEquation().catch(()=>{}); } catch(e) { }
  try { buildDropdowns(); } catch(e) { }

  applyRoleMenu(userRole);
  try { closeBkMenu(); } catch(e) {}

  // Load businesses BEFORE routing — this must be awaited, not
  // fire-and-forget. activeBusiness (set inside loadUserBusinesses)
  // is what every page's data queries filter by; rendering the
  // current page before this resolves was the root cause of pages
  // showing stale/wrong data and settings on refresh, only becoming
  // correct once you navigated away and back (by which point this
  // had quietly finished in the background).
  await Promise.all([
    loadUserBusinesses().catch(()=>{}),
    (userRole !== 'employee') ? loadProfileData().then(d=>{ profileData = d; }).catch(()=>{}) : Promise.resolve(),
  ]);
  // Staff access for the working business (owner = everything; others = their role)
  try {
    const wasOwner = userRole;
    await bdLoadAccess();
    if (activeBusiness && !activeBusiness._owned && !bizAccess.legacy) {
      try { localStorage.setItem('bd_staff_hint','1'); } catch(e) {}
      await loadAccounts().catch(()=>{});
      if (userRole !== 'employee') loadProfileData().then(d=>{ profileData = d; }).catch(()=>{});
    } else { try { localStorage.removeItem('bd_staff_hint'); } catch(e) {} }
    applyRoleMenu(userRole);
  } catch(e) { console.warn('access', e); }

  // Multi-device sync: the cloud copy of the settings has been downloading alongside
  // everything above; wait for it (it must be in before the first page draws).
  await syncP;

  // Paused staff see a short notice instead of the books
  if (activeBusiness && !activeBusiness._owned && bizAccess.status === 'paused') { bdPausedScreen(); return; }
  // Someone arrived through an invite link: take them to the join screen
  try { const jc = bdJoinLinkCode(); if (jc && !(userBusinesses||[]).some(b => b.business_code === jc)) { bdJoinLinkDone(); showJoinBusiness(jc); return; } bdJoinLinkDone(); } catch(e) {}
  // Route by role — employees go to Staff Pages, owners/managers go to Dashboard
  if (userRole === 'employee') {
    showStaffPage();
  } else {
    bdRestoreRoute();
  }
  bkWarmLibs();
}

// ── ACCOUNTS ─────────────────────────────────────────────────
let _laSeq = 0, _laChain = Promise.resolve();
// One load at a time: a second call waits for the first, so default accounts are never created twice.
function loadAccounts() { const r = _laChain.then(() => loadAccountsRun()); _laChain = r.catch(() => {}); return r; }
async function loadAccountsRun() {
  // Built in a private object and swapped in at the end: two loads overlapping (page start + business
  // switch, say) used to push into the same list and show every account twice.
  const mySeq = ++_laSeq;
  const acc = { capital:[], liability:[], asset:[], income:[], expenditure:[] };
  const seenIds = new Set();
  const addAcc = a => { if (!a || seenIds.has(a.id) || !acc[a.record_type]) return; seenIds.add(a.id); acc[a.record_type].push(a); };

  if (!navigator.onLine) {
    // No network — never attempt to create default accounts offline
    // (that would just fail, or duplicate once we're back online).
    const cached = bdCacheRead('accounts');
    window._bdShowingOfflineData = !!cached;
    const existing = cached ? cached.data : [];
    existing.forEach(addAcc);
    if (mySeq === _laSeq) accounts = acc;
    return;
  }
  window._bdShowingOfflineData = false;

  const { data } = await acctBizFilter(bkDb.from('bk_accounts').select('*')).order('created_at');
  const existing = data||[];
  existing.forEach(addAcc);

  // Staff of someone else's business never create a chart of accounts of their own
  let _skipDefaults = false;
  try { if (Object.keys(acc).some(t => acc[t].length === 0)) _skipDefaults = await bdIsLinkedStaff(); } catch(e) {}
  // Create default accounts if none exist for a type — scoped (stamped)
  // to the currently active business, so a brand-new business that has
  // no grandfathered legacy accounts to inherit gets its own default
  // chart of accounts rather than accidentally reusing another
  // business's.
  for (const type of Object.keys(DEFAULT_ACCOUNTS)) {
    if (acc[type].length === 0 && !_skipDefaults) {
      const inserts = DEFAULT_ACCOUNTS[type].map(name => ({
        user_id: bkUser.id,
        ...acctBizStamp(),
        record_type: type,
        account_name: name,
        opening_balance: 0,
        is_default: true,
      }));
      const { data:created } = await bkDb.from('bk_accounts').insert(inserts).select();
      if (created) acc[type] = created;
    }
  }

  // Cache the flattened list for offline viewing later
  if (mySeq !== _laSeq) return;      // a newer load has started; let it have the last word
  accounts = acc;
  const flat = [];
  Object.keys(accounts).forEach(t => accounts[t].forEach(a => flat.push(a)));
  bdCacheWrite('accounts', flat);
  try { await coaCloudPull(); } catch(e) { console.warn('chart layout sync', e); }
}

// ── Chart of Accounts layout (account numbers, sub-ledger groups, which group each account is in) ──
// These used to live only in this browser. They now follow the business: saved to the account a moment
// after every change, and loaded again on any device.
const COA_SYNC_KEYS = ['bd_coa_codes','bd_coa_group_codes','bd_coa_groups','bd_coa_memb','bd_coa_manual','bd_coa_tpl_tagged','bd_coa_deleted','bd_coa_glabels','bd_pay_methods','bd_sales_prod_assign','bd_unreg_products','bd_sales_excl_income','bd_sales_incl_income','bd_party_info','bd_own_accounts','bd_ac_units','bd_ac_unit_alias','bd_ac_datefmt','bd_sales_cell_cols'];
let _coaSyncBiz = null, _coaSyncMute = false, _coaSyncT = null;
const _coaLocalEdits = {};   // key -> time of the last change made on this device in this visit
// The time of every change is also kept on the device, so after a refresh a newer local change still beats an older copy in the account.
function _coaTsGet() { try { const o = JSON.parse(localStorage.getItem('bd_coa_ts') || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function _coaTsSet(o) { try { Storage.prototype.setItem.call(localStorage, 'bd_coa_ts', JSON.stringify(o)); } catch (e) {} }
(function () {
  const orig = Storage.prototype.setItem;
  Storage.prototype.setItem = function (k, v) {
    orig.call(this, k, v);
    if (this === window.localStorage && !_coaSyncMute && COA_SYNC_KEYS.indexOf(k) >= 0) {
      const now = Date.now(); _coaLocalEdits[k] = now;
      const ts = _coaTsGet(); ts[k] = now; _coaTsSet(ts);
      coaCloudPushSoon();
    }
  };
})();
function _coaSyncKey() { return (activeBusiness && activeBusiness.id) || 'u'; }
function coaCloudPushSoon() { clearTimeout(_coaSyncT); _coaSyncT = setTimeout(coaCloudPush, 1200); }
// Saves one settings blob for the user (or the active business). Tries the one-step upsert first;
// if the database has no matching unique rule for it, falls back to update-then-insert. Returns the error, if any.
async function bdSaveSetting(sheetKey, settings, perUser) {
  const bizId = perUser ? null : (activeBusiness?.id || null);
  const row = { user_id: bkUser.id, business_id: bizId, sheet_key: sheetKey, settings: settings, updated_at: new Date().toISOString() };
  const first = await bkDb.from('bk_sheet_settings').upsert(row, { onConflict: bizId ? 'business_id,sheet_key' : 'user_id,sheet_key' });
  if (!first.error) return null;
  try {
    let q = bkDb.from('bk_sheet_settings').select('id').eq('sheet_key', sheetKey);
    q = bizId ? q.eq('business_id', bizId) : q.is('business_id', null).eq('user_id', bkUser.id);
    const ex = await q.limit(1);
    if (ex.data && ex.data.length) {
      const up = await bkDb.from('bk_sheet_settings').update({ settings: settings, updated_at: row.updated_at }).eq('id', ex.data[0].id).select('id');
      if (!up.error && up.data && up.data.length) return null;
      return up.error || new Error('not allowed to update');
    }
    const ins = await bkDb.from('bk_sheet_settings').insert(row);
    return ins.error || null;
  } catch (e) { return e; }
}
let _coaToastAt = 0;
// Returns { ok, error }. Never throws.
async function coaCloudPush(quiet) {
  if (!bkUser) return { ok: false, error: 'not signed in' };
  if (!navigator.onLine) return { ok: false, error: 'you are offline' };
  if (_coaSyncBiz !== _coaSyncKey()) {
    // the first download never finished (for example a dropped connection): do it now instead of silently skipping the save
    try { await coaCloudPull(); } catch (e) {}
    if (_coaSyncBiz !== _coaSyncKey()) return { ok: false, error: "your saved settings couldn't be read from your account" };
  }
  const o = {};
  COA_SYNC_KEYS.forEach(k => { const v = localStorage.getItem(k); if (v != null) o[k] = v; });
  o.__ts = _coaTsGet();
  try {
    const error = await bdSaveSetting('coa_layout', o, false);
    if (error) throw error;
    return { ok: true };
  } catch (e) {
    console.warn('chart layout save failed', e);
    // Your numbers and groups are still kept on this device; only the copy in your account failed.
    if (!quiet && Date.now() - _coaToastAt > 300000) { _coaToastAt = Date.now(); bdToast("Chart numbers saved on this device, but couldn't be backed up to your account (" + String((e && e.message) || e).slice(0, 90) + ')', 'error'); }
    return { ok: false, error: String((e && (e.message || e.details)) || e) };
  }
}
// For choices the person has just made: save to the account now and say so if that did not work.
async function coaSyncNow(what) {
  clearTimeout(_coaSyncT);
  const r = await coaCloudPush(true);
  if (!r.ok) bdToast((what || 'This') + " is saved on this device, but couldn't be saved to your account (" + String(r.error || '').slice(0, 110) + '). Other devices won\'t see it yet.', 'error');
  return r;
}
async function coaCloudPull() {
  if (!bkUser || !navigator.onLine) return;
  const key = _coaSyncKey();
  if (_coaSyncBiz === key) return;
  const bizId = activeBusiness?.id || null;
  const t0 = Date.now();                        // anything you change after this moment is newer than what we are about to download
  let row = null;
  try {
    let q = bkDb.from('bk_sheet_settings').select('settings').eq('sheet_key', 'coa_layout');
    q = bizId ? q.eq('business_id', bizId) : q.is('business_id', null).eq('user_id', bkUser.id);
    const r = await q.maybeSingle(); if (r.error) throw r.error; row = r.data;
  } catch (e) { console.warn('chart layout read failed', e); return; }   // couldn't read: change nothing, try again next time
  let keptLocal = false;
  _coaSyncMute = true;
  try {
    if (row && row.settings && Object.keys(row.settings).length) {
      const ownerNow = localStorage.getItem('bd_coa_owner'), sameOwner = (ownerNow == null || ownerNow === key);   // no owner recorded yet = not known to belong to another business
      const rts = (row.settings.__ts && typeof row.settings.__ts === 'object') ? row.settings.__ts : {};
      let lts = _coaTsGet();
      if (!sameOwner) { const keep = {}; Object.keys(lts).forEach(k => { if ((_coaLocalEdits[k] || 0) >= t0) keep[k] = lts[k]; }); lts = keep; }
      COA_SYNC_KEYS.forEach(k => {
        const editedSince = (_coaLocalEdits[k] || 0) >= t0;
        const hasLocal = localStorage.getItem(k) != null;
        const localNewer = hasLocal && (lts[k] || 0) > (rts[k] || 0);   // changed here after the copy in the account was written
        if (row.settings[k] != null) {
          if (editedSince || localNewer) keptLocal = true;
          else { localStorage.setItem(k, row.settings[k]); if (rts[k]) lts[k] = rts[k]; }
        } else if (editedSince || (lts[k] || 0) > 0 || (sameOwner && hasLocal)) { if (hasLocal) keptLocal = true; }   // not in the account yet: keep it here and upload it
        else localStorage.removeItem(k);
      });
      _coaTsSet(lts);
      _jrnAcctPathMap = null;
    } else {
      const owner = localStorage.getItem('bd_coa_owner');
      if (owner && owner !== key) { COA_SYNC_KEYS.forEach(k => { if (!((_coaLocalEdits[k] || 0) >= t0)) localStorage.removeItem(k); }); _coaTsSet({}); }   // another business's leftovers
      _coaSyncBiz = key;
      localStorage.setItem('bd_coa_owner', key);
      _coaSyncMute = false; await coaCloudPush(true); return;
    }
    localStorage.setItem('bd_coa_owner', key);
  } finally { _coaSyncMute = false; }
  _coaSyncBiz = key;
  if (keptLocal) { try { await coaCloudPush(true); } catch (e) {} }
}

function buildDropdowns() {
  if (!accounts) return;
  const types = ['asset','liability','capital','expenditure','income'];
  types.forEach(type => {
    const sub = document.getElementById('sub'+type.charAt(0).toUpperCase()+type.slice(1));
    if (!sub) return;
    sub.innerHTML = '';

    (accounts[type]||[]).forEach(acct => {
      const el = document.createElement('div');
      el.className = 'bk-dd-sub-item' + (activeAccount?.id===acct.id ? ' active':'');
      el.textContent = acct.account_name;
      el.onclick = (e) => { e.stopPropagation(); openAccount(type, acct); };
      sub.appendChild(el);
    });

    const addEl = document.createElement('div');
    addEl.className = 'bk-dd-sub-item add-new';
    addEl.textContent = '+ Add New Account';
    addEl.onclick = (e) => { e.stopPropagation(); openAddAccountModal(type); };
    sub.appendChild(addEl);
  });
}

// ── CLOSE DROPDOWN ON OUTSIDE CLICK ──────────────────────────
// (dropdown removed — hamburger menu handles navigation now)

function toggleRecordsDD() { /* nav removed — use hamburger menu */ }

// ── ADD ACCOUNT MODAL ─────────────────────────────────────────
function openAddAccountModal(type) {
  addingForType = type;
  document.getElementById('newAccountName').value = '';
  document.getElementById('newAccountOB').value = '';
  document.getElementById('newAccountOBDate').value = today();
  document.getElementById('addAccountModal').classList.remove('hidden');
  document.getElementById('newAccountName').focus();
}

function closeAddAccountModal() {
  document.getElementById('addAccountModal').classList.add('hidden');
  addingForType = null;
}

async function confirmAddAccount() {
  const name = document.getElementById('newAccountName').value.trim();
  if (!name) { document.getElementById('newAccountName').focus(); return; }
  const ob   = parseFloat(document.getElementById('newAccountOB').value)||0;
  const obDate = document.getElementById('newAccountOBDate').value||null;

  const { data, error } = await bkDb.from('bk_accounts').insert({
    user_id: bkUser.id,
    ...acctBizStamp(),
    record_type: addingForType,
    account_name: name,
    opening_balance: ob,
    opening_date: obDate,
    is_default: false,
  }).select().single();

  if (!error && data) {
    accounts[addingForType].push(data);
    buildDropdowns();
    closeAddAccountModal();
    openAccount(addingForType, data);
  }
}

