// ── BUTTERFI DIALOGS ──────────────────────────────────────────
// Every message and question in the app speaks as "Butterfi", in the app's own
// colours, instead of the browser's grey "<site> says" box. alert() is replaced
// everywhere; questions use bdConfirm / bdChoose / bdPrompt (all promise-based,
// so nothing freezes while they are open).
(function(){
  if (window._bdDialogWired) return; window._bdDialogWired = true;
  const css = document.createElement('style');
  css.textContent = `
  .bdd-ov{position:fixed;inset:0;z-index:30000;background:rgba(10,8,25,0.55);display:flex;align-items:center;justify-content:center;padding:16px;animation:bddIn .12s ease-out;}
  @keyframes bddIn{from{opacity:0}to{opacity:1}}
  .bdd-box{background:var(--surface);color:var(--off);border:1px solid var(--gold);border-radius:16px;max-width:440px;width:100%;padding:20px 20px 16px;box-shadow:0 18px 50px rgba(0,0,0,0.45);max-height:88vh;overflow:auto;}
  .bdd-head{display:flex;align-items:center;gap:9px;margin-bottom:10px;}
  .bdd-ico{width:30px;height:30px;border-radius:9px;background:var(--gold-dim);display:flex;align-items:center;justify-content:center;font-size:1.05rem;flex:none;}
  .bdd-title{font-weight:900;color:var(--gold);font-size:0.95rem;letter-spacing:0.01em;}
  .bdd-msg{font-size:0.86rem;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--white);margin:2px 0 16px;}
  .bdd-input{width:100%;box-sizing:border-box;border:1px solid var(--border2);background:var(--surface2);color:var(--white);border-radius:8px;padding:10px 12px;font-size:0.86rem;margin:0 0 16px;outline:none;}
  .bdd-input:focus{border-color:var(--gold);}
  .bdd-btns{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;}
  .bdd-btn{border:1px solid var(--border2);background:var(--surface2);color:var(--off);font-weight:700;font-size:0.8rem;padding:10px 16px;border-radius:9px;cursor:pointer;font-family:inherit;}
  .bdd-btn:hover{border-color:var(--gold);}
  .bdd-btn.bdd-primary{background:var(--gold);color:var(--accent-ink,#fff);border-color:var(--gold);font-weight:800;}
  .bdd-btn.bdd-danger{background:#dc2626;color:#fff;border-color:#dc2626;font-weight:800;}
  .bdd-sub{display:block;font-weight:500;font-size:0.68rem;opacity:0.85;margin-top:2px;}
  @media (max-width:560px){.bdd-btns{flex-direction:column-reverse}.bdd-btn{width:100%;padding:13px 16px;font-size:0.86rem;text-align:center}.bdd-box{padding:18px 16px 14px}}`;
  document.head.appendChild(css);
})();
let _bddQueue = Promise.resolve();
function bdDialog(o) {
  const run = () => new Promise(resolve => {
    const ov = document.createElement('div');
    ov.className = 'bdd-ov'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true');
    const btns = (o.buttons && o.buttons.length ? o.buttons : [{ label: 'OK', value: true, primary: true }]);
    ov.innerHTML = '<div class="bdd-box"><div class="bdd-head"><span class="bdd-ico">' + bfiMark(24) + '</span><span class="bdd-title">' + escH(o.title || 'Butterfi says') + '</span></div>'
      + '<div class="bdd-msg">' + escH(String(o.message == null ? '' : o.message)) + '</div>'
      + (o.input ? '<input class="bdd-input" id="bddInput" type="text" value="' + escH(o.input.value || '') + '" placeholder="' + escH(o.input.placeholder || '') + '"/>' : '')
      + '<div class="bdd-btns' + (btns.length === 2 ? ' bdd-two' : '') + '">' + btns.map((b, i) => '<button class="bdd-btn' + (b.primary ? ' bdd-primary' : '') + (b.danger ? ' bdd-danger' : '') + '" data-i="' + i + '">' + escH(b.label) + (b.sub ? '<span class="bdd-sub">' + escH(b.sub) + '</span>' : '') + '</button>').join('') + '</div></div>';
    let done = false;
    const close = v => { if (done) return; done = true; document.removeEventListener('keydown', key, true); ov.remove(); resolve(v); };
    const cancelVal = o.cancelValue !== undefined ? o.cancelValue : false;
    const valOf = i => { const b = btns[i]; if (o.input && b.value === true) return document.getElementById('bddInput').value; return b.value; };
    const key = e => { if (e.key === 'Escape') { e.stopPropagation(); close(cancelVal); } else if (e.key === 'Enter' && !(e.target && e.target.tagName === 'BUTTON')) { const pi = btns.findIndex(b => b.primary); if (pi >= 0) { e.preventDefault(); close(valOf(pi)); } } };
    ov.addEventListener('click', e => { if (e.target === ov && !o.modal) close(cancelVal); const b = e.target.closest && e.target.closest('.bdd-btn'); if (b) close(valOf(+b.dataset.i)); });
    document.addEventListener('keydown', key, true);
    document.body.appendChild(ov);
    const f = ov.querySelector('#bddInput') || ov.querySelector('.bdd-primary') || ov.querySelector('.bdd-btn'); if (f) { try { f.focus(); if (f.select) f.select(); } catch (e) {} }
  });
  const p = _bddQueue.then(run, run); _bddQueue = p.catch(() => {}); return p;
}
function bdConfirm(message, o) { o = o || {}; return bdDialog({ message, cancelValue: false, buttons: [{ label: o.cancel || 'Cancel', value: false }, { label: o.ok || 'OK', value: true, primary: !o.danger, danger: !!o.danger }] }); }
function bdChoose(message, buttons, cancelValue) { return bdDialog({ message, buttons, cancelValue: cancelValue === undefined ? null : cancelValue }); }
function bdPrompt(message, def) { return bdDialog({ message, input: { value: def || '' }, cancelValue: null, buttons: [{ label: 'Cancel', value: null }, { label: 'OK', value: true, primary: true }] }); }
window.alert = function (m) { try { bdDialog({ message: m, buttons: [{ label: 'OK', value: true, primary: true }] }); } catch (e) { console.log(m); } };


// ── FETCH EVERY ROW ───────────────────────────────────────────
// Supabase returns at most 1,000 rows per request and says nothing when it
// cuts the rest off. With the newest dates last, the ledger silently lost
// its latest postings once a record type passed 1,000 legs. This pulls page
// after page until a short page comes back. `make` must build a FRESH query.
async function bkFetchAll(make, pageSize){
  const PS = pageSize || 1000, out = [];
  for (let from = 0; from < 200000; from += PS) {
    const res = await make().range(from, from + PS - 1);
    if (res.error) return { data: out.length ? out : null, error: res.error };
    const d = res.data || [];
    out.push(...d);
    if (d.length < PS) break;
  }
  return { data: out, error: null };
}
const bkNameKey = n => String(n == null ? '' : n).replace(/\s+/g,' ').trim().toLowerCase();

async function openAccount(type, acct) {
  try { bdSaveRoute('ledger:'+type+':'+(acct?.id||'')); } catch(e) {}
  recordsPageChrome();
  if (!activeAccount || activeAccount.id !== acct?.id) undoReset();
  activeType    = type;
  activeAccount = acct;
  isDirty       = false;
  searchQuery   = '';
  ledColFilters = {};
  dateFrom      = '';
  dateTo        = '';
  document.getElementById('recordsDD')?.classList.add('hidden');
  buildDropdowns(); // refresh active state

  document.getElementById('bkContent').innerHTML = '<div class="bk-loading">Loading…</div>';

  try {
    let data;
    if (!navigator.onLine) {
      const cached = bdCacheRead('ledger', acct.id);
      window._bdShowingOfflineData = !!cached;
      data = cached ? cached.data : [];
    } else {
      window._bdShowingOfflineData = false;
      const _mkLq = () => {
        let q = bkDb.from('bk_transactions').select('*').eq('record_type', type);
        q = activeBusiness?.id
          ? q.or('business_id.eq.'+activeBusiness.id+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
          : q.eq('user_id', bkUser.id);
        return q.order('txn_date', { ascending:true }).order('row_order', { ascending:true }).order('id', { ascending:true });
      };
      // Every transaction of this record_type (scoped to the business), ALL
      // pages, then matched by account name in JS (a name with a quote or
      // comma can't break a filter string; spacing/case differences can't
      // hide a posting).
      const res = await bkFetchAll(_mkLq);
      if (res.error) throw res.error;
      const _want = bkNameKey(acct.account_name);
      data = (res.data||[]).filter(r => !r.account_name || bkNameKey(r.account_name) === _want);
      bdCacheWrite('ledger', data, acct.id);
    }

    rows = (data||[]).map(r=>({
      id:r.id, txn_date:r.txn_date||'', payee:r.payee||'',
      payer:r.payer||'', narration:r.narration||'',
      debit:parseFloat(r.debit)||0, credit:parseFloat(r.credit)||0,
      balance:parseFloat(r.balance)||0, row_order:r.row_order, created_at:r.created_at||null, saved:true, _dbBal:parseFloat(r.balance)||0,
      // Carried through so deleteRow() can tell a Master-Journal-backed
      // posting apart from a standalone one — see deleteRow()'s comment.
      journal_id:r.journal_id||null,
    }));

    // Drop empty leftover rows (only a date/balance, no entry) that earlier versions saved — and clear them from the database.
    {
      const junk = rows.filter(r => r.id && !r.journal_id && !hasData(r));
      if (junk.length) {
        rows = rows.filter(r => !junk.includes(r));
        try { bkDb.from('bk_transactions').delete().in('id', junk.map(r => r.id)).then(() => {}, () => {}); } catch (e) {}
      }
    }
    // Keep only saved rows — no empty padding when there's actual data.
    // If the account has no entries at all, rows stays empty and renderRows shows the empty state.
    const savedCount = rows.filter(r => r.id).length;
    if (savedCount === 0) rows = []; // show empty state, not blank rows
    recalcBalances();
    renderLedger();
    ledRestoreScroll();
  } catch (e) {
    // Previously an error here (a failed query, or any exception while
    // processing/rendering the result) left the "Loading…" placeholder
    // on screen forever — nothing ever replaced it, and since refreshing
    // just re-runs this same call, refreshing looked like it "didn't
    // work" and the page appeared permanently frozen. Show a real error
    // with a way forward instead of silently hanging.
    console.error('openAccount failed:', e);
    document.getElementById('bkContent').innerHTML = `
      <div style="max-width:420px;margin:60px auto;text-align:center;padding:0 16px;">
        <div style="font-size:2rem;margin-bottom:10px;">⚠️</div>
        <div style="font-weight:800;color:var(--white);margin-bottom:6px;">Couldn't load this ledger</div>
        <div style="font-size:0.82rem;color:var(--muted);margin-bottom:20px;">${escH(e?.message || 'An unexpected error occurred.')}</div>
        <button class="bk-btn bk-btn-gold" style="margin-right:8px;" onclick="openAccount('${escJs(type)}', accounts['${escJs(type)}'].find(a=>String(a.id)==='${escJs(String(acct?.id||''))}'))">↻ Retry</button>
        <button class="bk-btn bk-btn-outline" onclick="renderCOA()">← Back to Chart of Accounts</button>
      </div>`;
  }
}

function emptyRow(order) {
  return { id:null, txn_date:today(), payee:'', payer:'', narration:'',
           debit:0, credit:0, balance:0, row_order:order, saved:false };
}

function today() {
  const d=new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

// ── RENDER LEDGER ─────────────────────────────────────────────
// ── Ledger column model + selection ─────────────────────────
let ledSel = { active:false, picked:[] };
function _ledCustom(){ try { return JSON.parse(localStorage.getItem('bd_led_custom')||'[]'); } catch(e){ return []; } }
function _ledSetCustom(c){ localStorage.setItem('bd_led_custom', JSON.stringify(c)); }
function _ledVals(){ try { return JSON.parse(localStorage.getItem('bd_led_custvals')||'{}'); } catch(e){ return {}; } }
function _ledLabels(){ try { return JSON.parse(localStorage.getItem('bd_led_labels')||'{}'); } catch(e){ return {}; } }
function _ledHidden(){ try { return JSON.parse(localStorage.getItem('bd_led_hidden')||'{}'); } catch(e){ return {}; } }
function ledCustomInput(idx, key, val) {
  const r = rows[idx]; if (!r) return;
  r.custom = r.custom||{}; r.custom[key]=val;
  if (r.id) { const m=_ledVals(); m[r.id]=m[r.id]||{}; m[r.id][key]=val; localStorage.setItem('bd_led_custvals', JSON.stringify(m)); }
}
function _ledMeta(){ try { return JSON.parse(localStorage.getItem('bd_led_colmeta')||'{}'); } catch(e){ return {}; } }
function ledColEditCells(key) {
  if (!String(key).startsWith('lc')) { alert('Cell options can be set on custom columns you create.'); return; }
  const meta = _ledMeta();
  const c = _ledCustom().find(x=>x.key===key);
  openOptionsPortal('CELL OPTIONS — '+(c?c.label:''), meta[key]||[], opts=>{
    if (opts.length) meta[key]=opts; else delete meta[key];
    localStorage.setItem('bd_led_colmeta', JSON.stringify(meta));
    renderLedger();
  });
}

function ledColMenu(ev, key) {
  // Only the Date header has a menu now (date range, format, arrange by). Every other header is just click-to-search.
  if (key === 'date') bdDatePortal(ev, 'ledger');
}
// ── Ledger header search: click a header's name to search that column ──
function ledColLabelOf(key) {
  const lbl = Object.assign({date:'Date',payee:'Payee',payer:'Payer',narr:'Narration',dr:'Debit',cr:'Credit',bal:'Balance'}, _ledLabels());
  const c = _ledCustom().find(x => x.key === key);
  return c ? c.label : (lbl[key] || key);
}
function ledColFilterApply(key) {
  const v = (document.getElementById('jcolInput') || {}).value || '';
  if (v.trim()) ledColFilters[key] = v.trim(); else delete ledColFilters[key];
  document.getElementById('jcolPopup')?.remove();
  renderLedger();
}
function ledColFilterClear(key, ev) {
  if (ev) ev.stopPropagation();
  delete ledColFilters[key];
  document.getElementById('jcolPopup')?.remove();
  renderLedger();
}
function ledColFilterClearAll() { ledColFilters = {}; document.getElementById('jcolPopup')?.remove(); renderLedger(); }
function ledColFilterPopup(key, ev) {
  ev.stopPropagation();
  document.getElementById('jcolPopup')?.remove();
  const th = ev.currentTarget.closest('th');
  const popup = document.createElement('div');
  popup.id = 'jcolPopup'; popup.className = 'jcol-filter-popup';
  popup.innerHTML = '<label>Search ' + escH(ledColLabelOf(key)) + '</label>' +
    '<input type="text" id="jcolInput" placeholder="Type to search…" value="' + escH(ledColFilters[key] || '') + '" onkeydown="if(event.key===\'Enter\')ledColFilterApply(\'' + key + '\')"/>' +
    '<div class="jcol-filter-row"><button class="jcol-filter-apply" onclick="ledColFilterApply(\'' + key + '\')">Apply</button>' +
    '<button class="jcol-filter-clearbtn" onclick="ledColFilterClear(\'' + key + '\')">Clear</button></div>';
  document.body.appendChild(popup);
  const rect = th.getBoundingClientRect();
  requestAnimationFrame(function(){
    const pw = popup.offsetWidth || 220, ph = popup.offsetHeight || 112;
    popup.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - pw - 8)) + 'px';
    let top = rect.bottom + 6; if (top + ph > window.innerHeight) top = Math.max(8, rect.top - ph - 6);
    popup.style.top = top + 'px';
  });
  document.getElementById('jcolInput').focus();
  setTimeout(function(){
    document.addEventListener('click', function onDoc(e){
      if (!e.target.closest('#jcolPopup') && !e.target.closest('.jcol-filter-label')) { popup.remove(); document.removeEventListener('click', onDoc); }
    });
  }, 10);
}
function ledColFiltersActive() { return Object.keys(ledColFilters).some(k => ledColFilters[k]); }
function ledRowMatchesCols(r) {
  const keys = Object.keys(ledColFilters).filter(k => ledColFilters[k]);
  if (!keys.length) return true;
  const custom = r.custom || (r.id ? (_ledVals()[r.id] || {}) : {});
  return keys.every(k => {
    const q = String(ledColFilters[k]).toLowerCase();
    let v;
    if (k === 'date') v = (r.txn_date || '') + ' ' + (r.txn_date ? formatDateDisplay(r.txn_date) : '');
    else if (k === 'payee') v = r.payee; else if (k === 'payer') v = r.payer; else if (k === 'narr') v = r.narration;
    else if (k === 'dr') v = (r.debit > 0 ? r.debit + ' ' + fmtNum(r.debit) : '');
    else if (k === 'cr') v = (r.credit > 0 ? r.credit + ' ' + fmtNum(r.credit) : '');
    else if (k === 'bal') v = (r.balance ? r.balance + ' ' + fmtNum(r.balance) : '');
    else v = custom[k];
    return String(v == null ? '' : v).toLowerCase().includes(q.replace(/,/g, '')) || String(v == null ? '' : v).toLowerCase().includes(q);
  });
}
function ledColFilterBar() {
  const keys = Object.keys(ledColFilters).filter(k => ledColFilters[k]);
  if (!keys.length) return '';
  return '<div class="jrn-filterbar" style="padding:6px 0;">' + keys.map(k => '<span class="jrn-filter-chip">' + escH(ledColLabelOf(k)) + ': ' + escH(ledColFilters[k]) + '<span class="x" onclick="ledColFilterClear(\'' + k + '\',event)">✕</span></span>').join('') +
    '<span class="jrn-filter-clearall" onclick="ledColFilterClearAll()">Clear all filters</span></div>';
}
// ── Remember where the user was on each ledger ──
function _ledScrollKey() { return (activeBusiness && activeBusiness.id || '') + ':' + (activeAccount && activeAccount.id || ''); }
function _ledScrollMap() { try { return JSON.parse(localStorage.getItem('bd_led_scroll') || '{}') || {}; } catch (e) { return {}; } }
let _ledScrollRaf = 0;
function ledSaveScroll() {
  if (!activeAccount || !activeAccount.id) return;
  const table = document.getElementById('ledgerTable'); if (!table) return;
  const wrap = table.closest('.bk-sheet-wrap');
  try {
    const m = _ledScrollMap(); m[_ledScrollKey()] = { y: Math.round(window.scrollY), x: wrap ? Math.round(wrap.scrollLeft) : 0 };
    const ks = Object.keys(m); if (ks.length > 200) delete m[ks[0]];
    localStorage.setItem('bd_led_scroll', JSON.stringify(m));
  } catch (e) {}
}
function ledRestoreScroll() {
  if (!activeAccount || !activeAccount.id) return;
  const pos = _ledScrollMap()[_ledScrollKey()]; if (!pos || (!pos.y && !pos.x)) return;
  const go = () => { window.scrollTo(0, pos.y || 0); const w = document.getElementById('ledgerTable')?.closest('.bk-sheet-wrap'); if (w && pos.x) w.scrollLeft = pos.x; try { bdSyncStickyClones(); } catch (e) {} };
  requestAnimationFrame(() => { go(); setTimeout(go, 120); });
}
window.addEventListener('scroll', function(){ if (_ledScrollRaf) return; _ledScrollRaf = requestAnimationFrame(function(){ _ledScrollRaf = 0; ledSaveScroll(); }); }, { passive: true });
document.addEventListener('scroll', function(e){ if (e.target && e.target.classList && e.target.classList.contains('bk-sheet-wrap') && e.target.querySelector('#ledgerTable')) ledSaveScroll(); }, { passive: true, capture: true });
function ledColRename(key) {
  const labels=_ledLabels();
  const custom=_ledCustom().find(c=>c.key===key);
  const cur = custom ? custom.label : (labels[key] || {date:'Date',payee:'Payee',payer:'Payer',narr:'Narration',dr:'Debit',cr:'Credit',bal:'Balance'}[key] || key);
  openTextPortal('RENAME HEADER', cur, name=>{
    if (custom) { custom.label=name; _ledSetCustom(_ledCustom().map(c=>c.key===key?custom:c)); }
    else { labels[key]=name; localStorage.setItem('bd_led_labels', JSON.stringify(labels)); }
    renderLedger();
  });
}
function ledColInsert(key, side) {
  const name = 'New Column';
  const cols = _ledCustom();
  const idx = cols.findIndex(c=>c.key===key);
  const entry = { key:'lc'+Date.now(), label:name.trim() };
  if (idx>=0) cols.splice(side==='left'?idx:idx+1, 0, entry);
  else if (['dr','cr','bal'].includes(key) || side==='right' && key==='narr') cols.push(entry);
  else cols.unshift(entry);
  _ledSetCustom(cols);
  renderLedger();
}
async function ledColDelete(key) {
  if (!String(key).startsWith('lc')) { alert('Built-in ledger columns cannot be deleted — use Hide column instead.'); return; }
  if (!(await bdConfirm('Delete this column and its contents?'))) return;
  _ledSetCustom(_ledCustom().filter(c=>c.key!==key));
  renderLedger();
}
async function ledColClear(key) {
  if (!(await bdConfirm('Clear all values in this column?'))) return;
  pushUndoState();
  if (String(key).startsWith('lc')) { rows.forEach(r=>{ if(r.custom) delete r.custom[key]; }); }
  else rows.forEach(r=>{
    if (key==='payee') r.payee=''; else if (key==='payer') r.payer='';
    else if (key==='narr') r.narration=''; else if (key==='date') r.txn_date='';
    else if (key==='dr'){ r.debit=0; r.saved=false; } else if (key==='cr'){ r.credit=0; r.saved=false; }
    else return;
    r.saved=false;
  });
  recalcBalances();
  renderRows(rows);
}
function ledColHide(key) {
  const h=_ledHidden(); h[key]=true;
  localStorage.setItem('bd_led_hidden', JSON.stringify(h));
  renderLedger();
}
function ledColUnhide(key) {
  const h=_ledHidden(); delete h[key];
  localStorage.setItem('bd_led_hidden', JSON.stringify(h));
  renderLedger();
}

// ── LEDGER TOOLS (same toolbox as the Master Journal) ─────────
let ledTb = { open:false, font:'Nunito' };
try { ledTb.open = localStorage.getItem('bd_ledtb_open') === '1'; ledTb.font = localStorage.getItem('bd_ledtb_font') || 'Nunito'; } catch(e) {}
function ledToggleToolbox(){ ledTb.open = !ledTb.open; try { localStorage.setItem('bd_ledtb_open', ledTb.open?'1':'0'); } catch(e) {} renderLedger(); }
function ledSetFont(f){ ledTb.font = f; try { localStorage.setItem('bd_ledtb_font', f); } catch(e) {} renderLedger(); }
// Upload from a ledger runs the Master Journal's own upload + posting, so every
// leg lands in this ledger, the Master Journal and each other ledger it touches.
// The journal is loaded silently first (so serial numbers, duplicate checks and
// the ledger-leg verification all see the real books); this page stays on screen.
async function ledOpenUpload(){
  if (!activeAccount || !bkUser) return;
  if (!navigator.onLine) { bdToast('Upload needs a connection', 'error'); return; }
  if (_sheetUploadKind) return;
  const ctx = { type: activeType, id: activeAccount.id };
  const msg = document.getElementById('ledUploadMsg');
  if (msg) { msg.textContent = 'Preparing…'; msg.className = 'bk-save-msg pending'; }
  try { await openJournal(true); } catch(e) { console.error('journal preload failed', e); if (msg) { msg.textContent = 'Could not load the Master Journal — try again'; msg.className = 'bk-save-msg err'; } return; }
  if (msg) { msg.textContent = ''; }
  window._ledUploadBank = ctx.type === 'asset' ? activeAccount.account_name : '';
  _sheetUploadKind = 'ledger';
  jrnOpenUploadModal();
  const t = setInterval(async function(){
    if (document.getElementById('jrnUploadOverlay')) return;
    clearInterval(t); _sheetUploadKind = null; window._ledUploadBank = '';
    try { await saveJournal(); } catch(e) { console.error(e); }
    // Still on this ledger? Reload it so the new postings show.
    if (activeType === ctx.type && activeAccount && activeAccount.id === ctx.id) {
      const acct = (accounts[ctx.type]||[]).find(a => a.id === ctx.id) || activeAccount;
      openAccount(ctx.type, acct);
    }
  }, 400);
}

function ledSelButton() {
  ledSel.active = !ledSel.active;
  ledSel.picked = [];
  renderLedger();
}
function ledSelToggle(i) {
  const p = ledSel.picked.indexOf(i);
  if (p>=0) ledSel.picked.splice(p,1); else ledSel.picked.push(i);
  const bar = document.getElementById('ledSelCount');
  if (bar) bar.textContent = ledSel.picked.length + ' selected';
  const el = document.querySelector('#row_'+i+' .op-circle');
  if (el) el.classList.toggle('on');
}
function ledSelectAll() {
  const all = [...document.querySelectorAll('#ledgerTable tbody tr[id^="row_"]')].filter(tr=>tr.offsetParent!==null||tr.style.display!=='none')
    .map(tr=>parseInt(tr.id.slice(4))).filter(i=>!isNaN(i) && rows[i] && hasData(rows[i]));
  const every = all.length && all.every(i => ledSel.picked.includes(i));
  ledSel.picked = every ? [] : all;
  document.querySelectorAll('#ledgerTable tbody .op-circle').forEach(el=>{
    const tr = el.closest('tr'); const i = tr ? parseInt(tr.id.slice(4)) : -1;
    el.classList.toggle('on', ledSel.picked.includes(i));
  });
  const bar = document.getElementById('ledSelCount'); if (bar) bar.textContent = ledSel.picked.length + ' selected';
}
async function ledDeleteSelected() {
  if (!ledSel.picked.length) return;
  if (!(await bdConfirm('Delete '+ledSel.picked.length+' selected row(s)?'))) return;
  pushUndoState();
  const idxs = ledSel.picked.slice().sort((a,b)=>b-a);
  for (const i of idxs) {
    if (rows[i]?.id) await bkDb.from('bk_transactions').delete().eq('id',rows[i].id);
    rows.splice(i,1);
  }
  ledSel = { active:false, picked:[] };
  recalcBalances();
  renderLedger();
  await refreshEquation();
}

// ── ONE PRINT STYLE FOR EVERY SHEET AND LEDGER ───────────────
// Same header, table look, totals and footer as the Master Journal print-out.
// Reads the table that is on screen (inputs → their values, selects → the chosen
// text, account chips → "A › B › C"), drops button-only columns, and lays it out.
function bdPrintTable(o) {
  const table = o.table; if (!table) return;
  const orient = o.orientation || 'portrait';
  const txt = el => {
    if (!el) return '';
    const c = el.cloneNode(true);
    c.querySelectorAll('button,.col-tri,.jdate-filter-btn,.op-circle,.jrn-sn-tri,.party-caret').forEach(x => x.remove());
    c.querySelectorAll('input[type=hidden]').forEach(x => x.remove());
    c.querySelectorAll('input,textarea').forEach(i => { if (i.type === 'checkbox' || i.type === 'radio') i.remove(); else i.replaceWith(document.createTextNode(i.value || '')); });
    c.querySelectorAll('select').forEach(sel => sel.replaceWith(document.createTextNode(sel.options && sel.selectedIndex >= 0 ? (sel.options[sel.selectedIndex].text || '').replace(/^—$/, '') : '')));
    c.querySelectorAll('.apk-trail').forEach(t => t.replaceWith(document.createTextNode([...t.querySelectorAll('.apk-chip')].map(ch => ch.textContent.replace(/\s+/g, ' ').trim()).join(' › '))));
    return (c.textContent || '').replace(/\s+/g, ' ').trim();
  };
  const ths = [...table.querySelectorAll('thead tr:first-child th')];
  const rowsEls = [...table.querySelectorAll('tbody tr')].filter(tr => !tr.classList.contains('hidden') && tr.style.display !== 'none');
  const data = rowsEls.map(tr => [...tr.children].map(td => ({ t: txt(td), span: td.colSpan || 1 })));
  const foot = [...table.querySelectorAll('tfoot tr')].map(tr => [...tr.children].map(td => ({ t: txt(td), span: td.colSpan || 1 })));
  const heads = ths.map(th => txt(th));
  const n = heads.length;
  const keep = [];
  for (let i = 0; i < n; i++) {
    const anyText = data.some(r => r[i] && r[i].span === 1 && r[i].t);
    if (heads[i] || anyText) keep.push(i);
  }
  const isNum = i => /debit|credit|balance|amount|price|qty|quantity|total|cost|stock|₦|\$|£|€/i.test(heads[i]) ||
    (data.length && data.filter(r => r[i] && r[i].t).length && data.filter(r => r[i] && r[i].t).every(r => /^[-+(]?[₦$£€]?\s?[\d,]+(\.\d+)?\)?$/.test(r[i].t)));
  const num = keep.map(isNum);
  const fsRem = orient === 'portrait' ? 0.62 : 0.74;
  const cell = (c, k, tag) => '<' + tag + (num[k] ? ' class="num"' : '') + '>' + escH(c ? c.t : '') + '</' + tag + '>';
  const body = data.map(r => {
    const first = r[0];
    if (first && first.span >= keep.length && keep.length > 1) return '<tr class="splitsub"><td colspan="' + keep.length + '">' + escH(first.t) + '</td></tr>';
    return '<tr>' + keep.map((i, k) => cell(r[i], k, 'td')).join('') + '</tr>';
  }).join('');
  const footHtml = foot.map(r => {
    let out = '', pos = 0;
    r.forEach(c => { const span = c.span; const ks = keep.filter(i => i >= pos && i < pos + span); pos += span; if (!ks.length) return; out += '<td' + (ks.length > 1 ? ' colspan="' + ks.length + '" class="lab"' : (num[keep.indexOf(ks[0])] ? ' class="num"' : '')) + '>' + escH(c.t) + '</td>'; });
    return '<tr>' + out + '</tr>';
  }).join('');
  const biz = (activeBusiness && activeBusiness.name) || businessDisplayName || '';
  const today0 = formatDateDisplay(new Date().toISOString().slice(0, 10));
  const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + escH(o.title) + '</title><style>' +
    '*{box-sizing:border-box;}@page{size:' + orient + ';margin:12mm;}' +
    "body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1a1a1a;padding:0 4px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}" +
    '.ph{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2.5px solid #111;padding-bottom:14px;margin-bottom:4px;}' +
    '.ph-biz{font-size:1.3rem;font-weight:800;color:#111;}.ph-addr{font-size:0.72rem;color:#555;margin-top:3px;}' +
    '.ph-title{text-align:right;}.ph-title .t{font-size:1rem;font-weight:800;color:#111;letter-spacing:0.08em;text-transform:uppercase;}.ph-title .r{font-size:0.74rem;color:#555;margin-top:3px;}' +
    '.meta{display:flex;justify-content:space-between;font-size:0.68rem;color:#777;margin:10px 0 16px;gap:12px;}' +
    'table{width:100%;border-collapse:collapse;table-layout:auto;font-size:' + fsRem + 'rem;border:1px solid #888;}tfoot{display:table-row-group;}' +
    'th,td{border-left:1px solid #aaa;border-right:1px solid #aaa;}' +
    'thead th{text-align:left;font-size:' + (fsRem * 0.88).toFixed(3) + 'rem;font-weight:800;color:#333;text-transform:uppercase;letter-spacing:0.02em;padding:6px 4px;border-bottom:1.5px solid #111;border-top:1px solid #111;background:#f3f3f3;}' +
    'thead th.num{text-align:right;}tbody td{padding:5px 4px;border-bottom:1px solid #aaa;color:#1a1a1a;vertical-align:top;overflow-wrap:anywhere;}' +
    'td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;}' +
    'tr.splitsub td{font-size:' + (fsRem * 0.92).toFixed(3) + 'rem;color:#333;padding:3px 6px 5px;background:#fafafa;}' +
    'tfoot td{padding:7px 4px;font-weight:800;border-top:2px solid #111;border-bottom:1px solid #111;}tfoot td.lab{text-align:right;}' +
    'tr{break-inside:avoid;}.pf{display:flex;justify-content:space-between;margin-top:30px;padding-top:12px;border-top:1px solid #ddd;font-size:0.64rem;color:#999;}' +
    '</style></head><body><div class="ph"><div><div class="ph-biz">' + escH(biz) + '</div><div class="ph-addr">' + escH(bkUser ? (bkUser.email || '') : '') + '</div></div>' +
    '<div class="ph-title"><div class="t">' + escH(o.title) + '</div><div class="r">' + escH(o.subtitle || '') + '</div></div></div>' +
    '<div class="meta"><span>Printed ' + escH(today0) + ' · Butterfly Dynamix</span><span>' + escH(o.meta || (data.length + ' ' + (data.length === 1 ? 'row' : 'rows'))) + '</span></div>' +
    '<table><thead><tr>' + keep.map((i, k) => '<th' + (num[k] ? ' class="num"' : '') + '>' + escH(heads[i]) + '</th>').join('') + '</tr></thead><tbody>' + body + '</tbody>' + (footHtml ? '<tfoot>' + footHtml + '</tfoot>' : '') + '</table>' +
    '<div class="pf"><span>Butterfly Dynamix — app.butterflydynamixllc.com</span><span>Page 1 of 1</span></div></body></html>';
  const w = window.open('', '_blank');
  if (!w) { alert('Your browser blocked the print preview. Please allow pop-ups for this site and try again.'); return; }
  w.document.write(html); w.document.close();
  setTimeout(() => w.print(), 300);
}

function ledStackDate(iso) {
  if (!iso) return '';
  const d = new Date(iso + 'T00:00:00'); if (isNaN(d)) return escH(iso);
  const mo = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const day = d.getDate();
  const suf = (day % 10 === 1 && day !== 11) ? 'st' : (day % 10 === 2 && day !== 12) ? 'nd' : (day % 10 === 3 && day !== 13) ? 'rd' : 'th';
  return day + suf + '<br>' + mo[d.getMonth()] + '<br>' + d.getFullYear();
}
// Ledger print-out — same letterhead, table look, totals row and footer as the Master Journal print-out.
function ledPrint(orient) {
  const table = document.getElementById('ledgerTable'); if (!table) return;
  const portrait = (orient || 'portrait') === 'portrait';
  const orientation = portrait ? 'portrait' : 'landscape';
  const sym = CURRENCIES[activeCurrency].symbol;
  const money = n => sym + Number(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  const ob = parseFloat(activeAccount && activeAccount.opening_balance) || 0;
  const lbl = Object.assign({ date: 'Date', payee: 'Payee', payer: 'Payer', narr: 'Narration', dr: 'Debit', cr: 'Credit', bal: 'Balance' }, _ledLabels());
  const hid = _ledHidden(), custom = _ledCustom().filter(c => !hid[c.key]);
  try { partyLoad && partyLoad(); } catch (e) {}
  // Rows currently shown on screen (respects search and column filters)
  const idxs = [...table.querySelectorAll('tbody tr')].filter(tr => /^row_\d+$/.test(tr.id) && tr.style.display !== 'none' && !tr.classList.contains('hidden'))
    .map(tr => parseInt(tr.id.slice(4), 10)).filter(i => rows[i] && (rows[i].debit > 0 || rows[i].credit > 0 || rows[i].narration || rows[i].payee || rows[i].payer));
  const list = idxs.map(i => rows[i]);
  if (!list.length && !ob) { bdToast('Nothing to print — this ledger has no entries.'); return; }
  const totalDr = list.reduce((a, r) => a + (parseFloat(r.debit) || 0), 0);
  const totalCr = list.reduce((a, r) => a + (parseFloat(r.credit) || 0), 0);
  const withBal = rows.filter(r => r.id && (r.debit > 0 || r.credit > 0));
  const closing = withBal.length ? (parseFloat(withBal[withBal.length - 1].balance) || ob) : ob;
  const dates = list.map(r => r.txn_date).filter(Boolean).sort();
  const dateRange = dates.length ? (dates[0] === dates[dates.length - 1] ? formatDateDisplay(dates[0]) : formatDateDisplay(dates[0]) + ' – ' + formatDateDisplay(dates[dates.length - 1])) : '';
  const party = v => {
    const n = String(v || '').trim(); if (!n) return '<span style="color:#bbb;">—</span>';
    let sub = ''; try { sub = partySubFor(n) || ''; } catch (e) {}
    return escH(n) + (sub ? '<div class="sub">' + escH(sub) + '</div>' : '');
  };
  const fsRem = portrait ? 0.6 : 0.72;
  const pageMm = portrait ? 184 : 271;
  let widestPx = 0;
  try {
    const cv = document.createElement('canvas').getContext('2d');
    cv.font = '800 ' + (fsRem * 16) + 'px -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif';
    [money(totalDr), money(totalCr), money(closing), ...list.map(r => money(Math.max(r.debit || 0, r.credit || 0, Math.abs(r.balance || 0))))].forEach(t => { widestPx = Math.max(widestPx, cv.measureText(t).width); });
  } catch (e) {}
  if (!widestPx) widestPx = 60;
  const amtMm = Math.ceil(widestPx * 0.2646 * 1.06 + 4);
  const snMm = 8, dateMm = portrait ? 12 : 13, custMm = portrait ? 18 : 22;
  const textCols = [];
  if (!hid.payee) textCols.push(['payee', 22]);
  if (!hid.payer) textCols.push(['payer', 22]);
  if (!hid.narr) textCols.push(['narr', 34]);
  const rest = Math.max(60, pageMm - snMm - dateMm - custom.length * custMm - 3 * amtMm);
  const wsum = textCols.reduce((a, c) => a + c[1], 0) || 1;
  const mm = [snMm, dateMm, ...textCols.map(c => rest * c[1] / wsum), ...custom.map(() => custMm), amtMm, amtMm, amtMm];
  const tot = mm.reduce((a, b) => a + b, 0);
  const colgroup = '<colgroup>' + mm.map(v => '<col style="width:' + (v / tot * 100).toFixed(3) + '%">').join('') + '</colgroup>';
  const vals = _ledVals();
  const obRow = ob ? '<tr class="obr"><td class="sn"></td><td class="dt">' + (activeAccount.ob_date ? ledStackDate(activeAccount.ob_date) : '') + '</td><td colspan="' + (textCols.length + custom.length) + '"><b>Opening Balance</b></td><td class="num"></td><td class="num"></td><td class="num">' + money(ob) + '</td></tr>' : '';
  const body = obRow + list.map((r, i) => {
    const cv = r.custom || (r.id ? (vals[r.id] || {}) : {});
    return '<tr><td class="sn">' + (i + 1) + '</td><td class="dt">' + ledStackDate(r.txn_date) + '</td>' +
      (hid.payee ? '' : '<td>' + party(r.payee) + '</td>') + (hid.payer ? '' : '<td>' + party(r.payer) + '</td>') +
      (hid.narr ? '' : '<td>' + escH(r.narration || '') + '</td>') +
      custom.map(c => '<td>' + escH(cv[c.key] || '') + '</td>').join('') +
      '<td class="num">' + (r.debit > 0 ? money(r.debit) : '') + '</td><td class="num">' + (r.credit > 0 ? money(r.credit) : '') + '</td><td class="num">' + (r.balance || r.balance === 0 ? money(r.balance) : '') + '</td></tr>';
  }).join('');
  const biz = (activeBusiness && activeBusiness.name) || businessDisplayName || '';
  const head = '<th class="sn">S/N</th><th>' + escH(lbl.date) + '</th>' + (hid.payee ? '' : '<th>' + escH(lbl.payee) + '</th>') + (hid.payer ? '' : '<th>' + escH(lbl.payer) + '</th>') +
    (hid.narr ? '' : '<th>' + escH(lbl.narr) + '</th>') + custom.map(c => '<th>' + escH(c.label) + '</th>').join('') +
    '<th class="num">' + escH(lbl.dr) + '</th><th class="num">' + escH(lbl.cr) + '</th><th class="num">' + escH(lbl.bal) + '</th>';
  const labSpan = 2 + textCols.length + custom.length;
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escH(activeAccount.account_name || 'Ledger')}</title><style>
    *{box-sizing:border-box;}
    @page{size:${orientation};margin:12mm;}
    body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1a1a1a;padding:0 4px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
    .ph{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2.5px solid #111;padding-bottom:14px;margin-bottom:4px;}
    .ph-biz{font-size:1.3rem;font-weight:800;color:#111;}.ph-addr{font-size:0.72rem;color:#555;margin-top:3px;}
    .ph-title{text-align:right;}.ph-title .t{font-size:1rem;font-weight:800;color:#111;letter-spacing:0.08em;text-transform:uppercase;}.ph-title .r{font-size:0.74rem;color:#555;margin-top:3px;}
    .meta{display:flex;justify-content:space-between;font-size:0.68rem;color:#777;margin:10px 0 16px;}
    table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:${fsRem}rem;border:1px solid #888;}
    tfoot{display:table-row-group;}
    th,td{border-left:1px solid #aaa;border-right:1px solid #aaa;}
    thead th{text-align:left;vertical-align:bottom;font-size:${(fsRem * 0.88).toFixed(3)}rem;font-weight:800;color:#333;text-transform:uppercase;letter-spacing:0.02em;padding:6px 3px;border-bottom:1.5px solid #111;border-top:1px solid #111;background:#f3f3f3;overflow-wrap:break-word;}
    thead th.num{text-align:right;}thead th.sn{text-align:center;}
    tbody td{padding:5px 3px;border-bottom:1px solid #aaa;color:#1a1a1a;vertical-align:top;overflow-wrap:break-word;}
    td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;}
    td.sn{color:#999;white-space:nowrap;text-align:center;}
    td.dt{line-height:1.3;white-space:nowrap;}
    .sub{font-size:${(fsRem * 0.88).toFixed(3)}rem;color:#666;margin-top:1px;line-height:1.25;}
    tr.obr td{background:#fafafa;}
    tfoot td{padding:7px 3px;font-weight:800;border-top:2px solid #111;border-bottom:1px solid #111;}
    tfoot td.lab{text-align:right;border-left:none;padding-right:6px;}
    tr{break-inside:avoid;}
    .pf{display:flex;justify-content:space-between;margin-top:30px;padding-top:12px;border-top:1px solid #ddd;font-size:0.64rem;color:#999;}
  </style></head><body>
    <div class="ph"><div><div class="ph-biz">${escH(biz)}</div><div class="ph-addr">${escH(bkUser ? (bkUser.email || '') : '')}</div></div>
    <div class="ph-title"><div class="t">${escH(activeAccount.account_name || 'Ledger')}</div><div class="r">${escH(dateRange)}</div></div></div>
    <div class="meta"><span>Printed ${formatDateDisplay(new Date().toISOString().slice(0, 10))} · Butterfly Dynamix</span><span>${escH((SCHEDULE_META[activeType] && SCHEDULE_META[activeType].label) || 'Ledger')} · ${list.length} entr${list.length === 1 ? 'y' : 'ies'} · Closing balance ${money(closing)}</span></div>
    <table>${colgroup}<thead><tr>${head}</tr></thead><tbody>${body}</tbody>
    <tfoot><tr><td colspan="${labSpan}" class="lab">Totals</td><td class="num">${money(totalDr)}</td><td class="num">${money(totalCr)}</td><td class="num">${money(closing)}</td></tr></tfoot></table>
    <div class="pf"><span>Butterfly Dynamix — app.butterflydynamixllc.com</span><span>Page 1 of 1</span></div>
  </body></html>`;
  const w = window.open('', '_blank');
  if (!w) { alert('Your browser blocked the print preview. Please allow pop-ups for this site and try again.'); return; }
  w.document.write(html); w.document.close();
  setTimeout(() => w.print(), 300);
}

function renderLedger() {
  const typeLabel = activeType.charAt(0).toUpperCase()+activeType.slice(1);
  const content   = document.getElementById('bkContent');
  const ob        = parseFloat(activeAccount.opening_balance)||0;

  // Apply search/filter
  let displayRows = rows;
  if (searchQuery||dateFrom||dateTo) {
    const q = searchQuery.toLowerCase();
    displayRows = rows.filter(r=>{
      const matchText = !q || r.narration.toLowerCase().includes(q) ||
        r.payee.toLowerCase().includes(q) || r.payer.toLowerCase().includes(q);
      const matchFrom = !dateFrom || r.txn_date >= dateFrom;
      const matchTo   = !dateTo   || r.txn_date <= dateTo;
      return matchText && matchFrom && matchTo;
    });
  }

  // Compute closing balance
  const dataRows = rows.filter(r => r.id && (r.debit > 0 || r.credit > 0));
  const closingBal = dataRows.length > 0
    ? parseFloat(dataRows[dataRows.length-1].balance) || ob
    : ob;
  const meta  = SCHEDULE_META[activeType] || { color:'var(--gold)' };
  const color = meta.color || 'var(--gold)';
  const balText = fmt(Math.abs(closingBal));

  content.innerHTML = `
    <div class="bk-sticky-wrap" id="ledStickyHead" style="padding-bottom:8px;">
    <div style="padding:0 0 10px;"><button class="bk-btn bk-btn-outline" style="font-size:0.74rem;" onclick="renderCOA()">← Back</button></div>
    ${bdOfflineBanner()}
    <div class="sched-total-banner" id="ledgerTotalBanner" style="border-left:4px solid ${color};margin-bottom:0;">
      <div class="sched-total-label">${escH(activeAccount.account_name)}</div>
      <div class="sched-total-val" id="ledgerTotalVal" style="color:${color};">${balText}</div>
    </div>
    </div>
    <div style="display:flex;justify-content:flex-end;gap:6px;padding:0 0 8px;flex-wrap:wrap;">
      <span class="bk-save-msg" id="ledUploadMsg"></span>
      <button class="bk-btn bk-btn-outline${(ledTb.open||ledSel.active)?' jrn-filter-active':''}" style="font-size:0.72rem;" onclick="ledToggleToolbox()" title="Tools">⚙ Tools</button>
    </div>
    ${ledTb.open?`<div class="sheet-toolbox" style="margin:0 0 8px;">
      <button class="bk-btn bk-btn-gold" style="font-size:0.72rem;" onclick="ledOpenUpload()">📤 Upload</button>
      <span style="display:inline-flex;align-items:center;background:var(--surface2);border:1px solid var(--border2);border-radius:7px;overflow:hidden;">
        <input id="ledSearchBox" class="bk-input" placeholder="Search…" value="${escH(searchQuery)}" style="width:120px;background:transparent;border:none;color:var(--white);padding:6px 9px;font-size:0.74rem;outline:none;" oninput="onSearchInput(this.value)"/>
        <span style="color:var(--gold);padding:6px 8px;border-left:1px solid var(--border2);font-size:0.8rem;">🔍</span>
      </span>
      <button class="tb-icon" title="Print portrait" onclick="ledPrint('portrait')">🖨</button>
      <button class="tb-icon" title="Print landscape" onclick="ledPrint('landscape')">🖨▭</button>
      <button class="tb-icon ${ledSel.active?'tb-active':''}" title="Select rows" onclick="ledSelButton()">☑ Select</button>
      <button class="tb-icon" title="Delete selected rows" onclick="ledDeleteSelected()">🗑 Delete</button>
    </div>`:''}
    ${ledSel.active?`<div class="op-selbar" style="margin:0 0 8px;"><span id="ledSelCount" style="color:var(--gold);font-weight:800;">0 selected</span>
      <button class="op-cancel-btn" onclick="ledSelectAll()">☑ Select all</button>
      <button class="op-bundle-btn" onclick="ledDeleteSelected()">🗑 Delete selected</button>
      <button class="op-cancel-btn" onclick="ledSelButton()">Cancel</button></div>`:''}
    ${(()=>{ const h=_ledHidden(); const keys=Object.keys(h).filter(k=>h[k]); if(!keys.length) return '';
      const lbl=Object.assign({date:'Date',payee:'Payee',payer:'Payer',narr:'Narration',dr:'Debit',cr:'Credit',bal:'Balance'}, _ledLabels());
      return '<div style="display:flex;gap:6px;flex-wrap:wrap;padding:0 0 8px;align-items:center;"><span style="font-size:0.66rem;color:var(--muted);">Hidden:</span>'
        + keys.map(k=>{ const c=_ledCustom().find(x=>x.key===k);
          return '<span onclick="ledColUnhide(\''+k+'\')" style="font-size:0.66rem;background:var(--surface2);border:1px solid var(--border2);color:var(--off);padding:3px 9px;border-radius:9px;cursor:pointer;">'+escH(c?c.label:(lbl[k]||k))+' ✕</span>'; }).join('') + '</div>'; })()}
    ${ledColFilterBar()}
    <div class="bk-sheet-wrap" style="font-family:'${ledTb.font}',sans-serif;">
      <table class="bk-sheet ${(()=>{const h=_ledHidden();return Object.keys(h).filter(k=>h[k]&&!String(k).startsWith('lc')).map(k=>'led-hide-'+k).join(' ');})()}" id="ledgerTable" style="min-width:960px;width:100%;">
        <thead>
          <tr>
            ${ledSel.active?'<th style="width:34px;"></th>':''}
            <th class="col-sn num" style="width:40px;">S/N</th>
            ${(()=>{ const lbl=Object.assign({date:'Date',payee:'Payee',payer:'Payer',narr:'Narration',dr:'Debit',cr:'Credit',bal:'Balance'}, _ledLabels());
              const tri=k=>'<span class="col-tri col-tri-show" style="position:static;font-size:0.5rem;margin-left:3px;" onclick="event.stopPropagation();ledColMenu(event,\''+k+'\')">▼</span>';
              const sym=CURRENCIES[activeCurrency].symbol;
              const lab=(k,text)=>{ const act=!!ledColFilters[k]; return '<span class="jcol-filter-label'+(act?' jcol-active':'')+'" onclick="event.stopPropagation();ledColFilterPopup(\''+k+'\',event)" title="Click to search this column">'+text+'</span>'+(act?'<span class="jcol-filter-clear" title="Clear search" onclick="event.stopPropagation();ledColFilterClear(\''+k+'\',event)">✕</span>':''); };
              let h='';
              h+='<th class="col-date col-head" style="width:110px;">'+lab('date',escH(lbl.date))+' <button class="jdate-filter-btn" onclick="event.stopPropagation();bdDatePortal(event,\'ledger\')" title="Date range, format and arrange by">📅</button>'+tri('date')+'</th>';
              h+='<th class="col-payee col-head" style="width:120px;">'+lab('payee',escH(lbl.payee))+'</th>';
              h+='<th class="col-payer col-head" style="width:120px;">'+lab('payer',escH(lbl.payer))+'</th>';
              h+='<th class="col-narr col-head" style="width:auto;min-width:240px;">'+lab('narr',escH(lbl.narr))+'</th>';
              const hid=_ledHidden();
              h+=_ledCustom().filter(c=>!hid[c.key]).map(c=>'<th class="col-head" style="width:120px;">'+lab(c.key,escH(c.label))+'</th>').join('');
              h+='<th class="col-dr num col-head" style="width:110px;">'+lab('dr',escH(lbl.dr)+' ('+sym+')')+'</th>';
              h+='<th class="col-cr num col-head" style="width:110px;">'+lab('cr',escH(lbl.cr)+' ('+sym+')')+'</th>';
              h+='<th class="col-bal num col-head" style="width:120px;">'+lab('bal',escH(lbl.bal)+' ('+sym+')')+'</th>';
              return h; })()}
            <th style="width:34px;"></th>
          </tr>
        </thead>
        <tbody id="ledgerBody"></tbody>
      </table>
    </div>
    <div style="padding:10px 0 0;"><button class="staff-add-cust-btn" onclick="addRow()">+ Add Row</button></div>
    <div class="sched-below-table">
      <div class="sched-subacct-wrap">
        <label class="sched-subacct-label">Sub Accounts</label>
        <select class="acct-input sched-subacct-select"
          onchange="switchLedgerAccount(this.value)">
          ${(accounts[activeType]||[]).map(a=>`<option value="${a.id}" ${a.id===activeAccount.id?'selected':''}>${a.account_name}</option>`).join('')}
        </select>
        ${ob ? `<span style="font-size:0.72rem;color:var(--gold);">Opening Balance: ${fmt(ob)}</span>` : ''}
      </div>
    </div>`;

  renderRows(displayRows);
  requestAnimationFrame(()=>{ try { bdApplyStickyLayout('#ledgerTable thead th', null); bdSyncStickyClones(); } catch(e){} });
}

function ledVisibleColCount() {
  const ths = [...document.querySelectorAll('#ledgerTable thead tr:first-child th')].filter(th => getComputedStyle(th).display !== 'none');
  return Math.max(1, ths.length || 8);
}
function renderRows(displayRows) {
  displayRows = displayRows || rows;
  const tbody = document.getElementById('ledgerBody');
  if (!tbody) return;
  const ob = parseFloat(activeAccount?.opening_balance)||0;

  // Opening balance row
  const _obHid = _ledHidden();
  const _obNarrSpan = 1 + _ledCustom().filter(c=>!_obHid[c.key]).length;
  const obRow = `
    <tr class="ob-row" id="row_ob">
      ${ledSel.active?'<td></td>':''}
      <td style="text-align:center;padding:4px 2px;font-size:0.72rem;color:var(--muted);">—</td>
      <td class="col-date"><input class="bk-cell" type="text" readonly id="obDate" data-iso="${escH(activeAccount?.ob_date||'')}"
        value="${activeAccount?.ob_date ? escH(formatDateDisplay(activeAccount.ob_date)) : ''}" placeholder="Date" style="cursor:pointer;"
        onclick="ledOpenObDate(this)"/></td>
      ${_obHid.payee?'':'<td></td>'}
      ${_obHid.payer?'':'<td></td>'}
      <td colspan="${Math.max(1,_obNarrSpan)}" style="padding:6px 10px;">
        <span style="font-size:0.76rem;font-weight:700;color:var(--gold);">Opening Balance</span>
      </td>
      <td class="col-dr" style="text-align:right;padding:4px 6px;color:var(--muted);">—</td>
      <td class="col-cr" style="text-align:right;padding:4px 6px;color:var(--muted);">—</td>
      <td class="col-bal" style="padding:4px 6px;position:relative;">
        <span style="position:absolute;left:8px;top:50%;transform:translateY(-50%);font-size:0.72rem;color:var(--gold);pointer-events:none;">${CURRENCIES[activeCurrency].symbol}</span>
        <input class="bk-cell num" id="obBalInput" type="text" inputmode="decimal"
          value="${ob!==0?fmtNum(ob):''}" placeholder="0"
          style="font-weight:800;color:var(--gold);padding-left:18px;"
          oninput="ledgerOBChanged(this.value)"
          onblur="ledgerOBChanged(this.value);obFlush()"/>
      </td>
      <td><button class="del-btn" onclick="clearOpeningBalance()" title="Clear opening balance">✕</button></td>
    </tr>`;

  // Rendering never mutates data — the trailing blank row is guaranteed
  // by ensureTrailingBlank(), called explicitly wherever rows can change.
  ensureTrailingBlank();
  const sns = []; { let n = 0; rows.forEach((row, i) => { sns[i] = hasData(row) ? (++n) : ''; }); }
  const vis = ledVisibleRows();
  const note = vis.filtered
    ? `<tr class="led-note-row"><td colspan="${ledVisibleColCount()}" style="padding:6px 10px;font-size:0.7rem;color:var(--muted);background:var(--surface2);">Showing ${vis.items.filter(x => hasData(x.r)).length} of ${rows.filter(hasData).length} entries${(dateFrom || dateTo) ? ' · ' + (dateFrom ? formatDateDisplay(dateFrom) : '…') + ' → ' + (dateTo ? formatDateDisplay(dateTo) : '…') : ''} · <span style="color:var(--gold);cursor:pointer;" onclick="dateFrom='';dateTo='';searchQuery='';ledColFilters={};renderLedger()">Show all</span></td></tr>` : '';
  const bodyHtml = vis.items.map(x => buildEditableRow(x.r, x.i, sns[x.i])).join('');
  tbody.innerHTML = obRow + note + bodyHtml;
  if (!tbody._autoHook) { tbody._autoHook=true; tbody.addEventListener('input', ()=>{ isDirty=true; ledgerAutosave(); }); }
  setTimeout(()=>{ initColumnResize(); initRowResize(); initDragRows(); }, 50);
}

// Format number with commas as user types
function ledgerFmtInput(input, idx, field) {
  const raw = input.value.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
  const num = parseFloat(raw) || 0;
  rows[idx][field] = num;
  rows[idx].saved = false;
  // Reformat with commas, preserve cursor and any trailing decimals
  const dot = raw.indexOf('.');
  const intPart = dot>=0 ? raw.slice(0,dot) : raw;
  const decPart = dot>=0 ? '.'+raw.slice(dot+1) : '';
  const formatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + decPart;
  const cursorPos = input.selectionStart;
  const prevLen = input.value.length;
  input.value = formatted;
  // Restore cursor position adjusted for added/removed commas
  const diff = formatted.length - prevLen;
  input.setSelectionRange(cursorPos + diff, cursorPos + diff);
  if (field === 'debit' || field === 'credit') ledgerCellChanged(idx);
}

function fmtNum(n){ n=parseFloat(n)||0; return n.toLocaleString('en-NG',{maximumFractionDigits:4}); }

function buildEditableRow(row, idx, sn) {
  const bal      = hasData(row) ? (parseFloat(row.balance)||0) : 0;
  const balClass = bal > 0 ? 'pos' : bal < 0 ? 'neg' : 'zero';
  const dateVal  = row.txn_date || '';
  const sym      = CURRENCIES[activeCurrency]?.symbol || '₦';

  return `<tr id="row_${idx}" ondblclick="ledDblClickRow(event,${idx})" title="Double-click to see this entry in the Master Journal">
    ${ledSel.active?`<td class="op-selcell"><span onclick="ledSelToggle(${idx})" class="op-circle ${ledSel.picked.includes(idx)?'on':''}"></span></td>`:''}
    <td class="col-sn" style="text-align:center;padding:4px 2px;font-size:0.72rem;color:var(--muted);white-space:nowrap;">${sn}</td>
    <td class="col-date"><input class="bk-cell" type="text" readonly value="${escH(dateVal ? formatDateDisplay(dateVal) : '')}" placeholder="Date" style="cursor:pointer;"
      onclick="ledOpenDate(${idx},this)"/></td>
    <td class="col-payee"><input class="bk-cell" type="text" data-party="ledger" value="${escH(row.payee||'')}" placeholder="Payee…"
      oninput="rows[${idx}].payee=this.value;rows[${idx}].saved=false"/></td>
    <td class="col-payer"><input class="bk-cell" type="text" data-party="ledger" value="${escH(row.payer||'')}" placeholder="Payer…"
      oninput="rows[${idx}].payer=this.value;rows[${idx}].saved=false"/></td>
    <td class="col-narr"><input class="bk-cell" type="text" value="${escH(row.narration||'')}" placeholder="Narration…"
      oninput="rows[${idx}].narration=this.value;rows[${idx}].saved=false"/></td>
    ${(()=>{const hid=_ledHidden();const vals=(row.custom)||(row.id?(_ledVals()[row.id]||{}):{});
      const meta=_ledMeta();
      return _ledCustom().filter(c=>!hid[c.key]).map(c=>{
        const opts = meta[c.key];
        if (opts && opts.length) return `<td><select class="bk-cell" onchange="ledCustomInput(${idx},'${c.key}',this.value)">
          <option value=""></option>${opts.map(o=>`<option ${(vals[c.key]||'')===o?'selected':''}>${escH(o)}</option>`).join('')}</select></td>`;
        return `<td><input class="bk-cell" type="text" value="${escH(vals[c.key]||'')}"
      oninput="ledCustomInput(${idx},'${c.key}',this.value)"/></td>`;}).join('');})()}
    <td class="col-dr"><input class="bk-cell num" type="text" inputmode="decimal"
      value="${row.debit>0?fmtNum(row.debit):''}" placeholder="0"
      oninput="ledgerFmtInput(this,${idx},'debit')"/></td>
    <td class="col-cr"><input class="bk-cell num" type="text" inputmode="decimal"
      value="${row.credit>0?fmtNum(row.credit):''}" placeholder="0"
      oninput="ledgerFmtInput(this,${idx},'credit')"/></td>
    <td class="col-bal" style="position:relative;">
      <span style="position:absolute;left:6px;top:50%;transform:translateY(-50%);font-size:0.72rem;color:var(--muted);pointer-events:none;">${sym}</span>
      <input class="bk-cell num bal ${balClass}" id="balCell_${idx}" type="text" inputmode="decimal"
        value="${bal!==0?fmtNum(bal):''}" placeholder="0" style="padding-left:18px;"
        oninput="ledgerFmtInput(this,${idx},'balance');ledgerUpdateTotalBanner()"/></td>
    <td><button class="del-btn" onclick="deleteRow(${idx})" title="Delete row">✕</button></td>
  </tr>`;
}

function ledOpenObDate(el) {
  const set = v => { el.dataset.iso = v || ''; el.value = v ? formatDateDisplay(v) : ''; saveOpeningBalance(document.getElementById('obBalInput')?.value || ''); };
  jcalOpen(el, { value: el.dataset.iso || '', clearLabel: 'Clear', onPick: set, onToday: () => set(today()), onClear: () => set('') });
}
function ledOpenDate(idx, el) {
  const set = v => { if (!rows[idx]) return; rows[idx].txn_date = v; rows[idx]._userDate = !!v; rows[idx].saved = false; el.value = v ? formatDateDisplay(v) : ''; ledgerCellChanged(idx); isDirty = true; ledgerAutosave();
    const li = rows.length - 1;
    if (idx !== li) { const b4 = rows[li] && rows[li].txn_date; ledSyncBlankDate(); if (rows[li] && rows[li].txn_date !== b4) { const inp = document.querySelector('#row_' + li + ' .col-date input'); if (inp) inp.value = rows[li].txn_date ? formatDateDisplay(rows[li].txn_date) : ''; } } };
  jcalOpen(el, { value: (rows[idx] && rows[idx].txn_date) || '', clearLabel: 'Clear', onPick: set, onToday: () => set(today()), onClear: () => set('') });
}
function buildEmptyEditableRows(count, startIdx) {
  startIdx = startIdx || rows.length;
  let html = '';
  for (let i = 0; i < count; i++) {
    const idx = startIdx + i;
    while (rows.length <= idx) rows.push(emptyRow(rows.length));
    html += buildEditableRow(rows[idx], idx, '');
  }
  return html;
}

// Clear opening balance back to zero
async function clearOpeningBalance() {
  const input = document.getElementById('obBalInput');
  if (input) {
    input.value = '';
    ledgerOBChanged('0'); // recalc all rows in DOM immediately
  }
  await saveOpeningBalance('0');
}
let _obT = null, _obPend = null, _obChain = Promise.resolve();
function ledgerOBChanged(val) {
  const newOB = parseFloat(String(val).replace(/,/g,'')) || 0;
  if (activeAccount) activeAccount.opening_balance = newOB;
  ledgerCellChanged(0); // recalc from the top
  if (!activeAccount || !bkUser) return;
  // Save by itself a moment after typing stops (remembering WHICH account it was for,
  // so leaving the page can never save it onto the wrong one).
  _obPend = { acct: activeAccount, type: activeType, val: val };
  clearTimeout(_obT); _obT = setTimeout(obFlush, 700);
  setSaveMsg('Saving…', 'pending');
}
function obFlush() {
  clearTimeout(_obT);
  const p = _obPend; if (!p) return _obChain;
  _obPend = null;
  return saveOpeningBalance(p.val, p.acct, p.type);
}
// Anything still waiting is saved the moment you leave the page or switch tabs.
document.addEventListener('visibilitychange', () => { if (document.hidden) obFlush(); });
window.addEventListener('pagehide', () => { obFlush(); });

// Save opening balance to bk_accounts. Runs one at a time, and checks the database
// really changed a row (an update that matches nothing used to look like success).
function saveOpeningBalance(val, acct, type) {
  acct = acct || activeAccount; type = type || activeType;
  if (!acct || !bkUser) return Promise.resolve();
  const isActive = acct === activeAccount;
  if (_obPend && _obPend.acct === acct) { _obPend = null; clearTimeout(_obT); }
  const newOB = parseFloat(String(val).replace(/,/g,'')) || 0;
  acct.opening_balance = newOB;
  const obDate = isActive ? (document.getElementById('obDate')?.dataset.iso || null) : (acct.ob_date || null);
  acct.ob_date = obDate;
  if (isActive) { recalcBalances(); ledgerUpdateTotalBanner(); setSaveMsg('Saving…', 'pending'); }
  _obChain = _obChain.then(async () => {
    try {
      if (!acct.id) {
        const {data:na, error:e0} = await bkDb.from('bk_accounts').insert({
          user_id: bkUser.id, ...acctBizStamp(), account_name: acct.account_name,
          record_type: type, opening_balance: newOB, ob_date: obDate,
        }).select().single();
        if (e0) throw e0;
        acct.id = na.id;
      } else {
        const {data:upd, error:e1} = await bkDb.from('bk_accounts').update({
          opening_balance: newOB, ob_date: obDate,
        }).eq('id', acct.id).select('id');
        if (e1) throw e1;
        if (!upd || !upd.length) throw new Error("this account couldn't be updated — you may not have permission to change it");
      }
      if (acct === activeAccount) setSaveMsg('✓ Opening balance saved', 'ok');
      const acctArr = accounts[type] || [];
      const idx = acctArr.findIndex(a => a.id === acct.id);
      if (idx >= 0) { acctArr[idx].opening_balance = newOB; acctArr[idx].ob_date = obDate; }
      if (_coaBalCache) { try { _coaLoadBalances(); } catch(e) {} }
    } catch(e) {
      console.warn('opening balance save failed', e);
      if (!_obPend) _obPend = { acct, type, val };   // keep it so the next save (or the › button) retries
      if (acct === activeAccount) setSaveMsg('Not saved — tap › to retry', 'err');
      bdToast("Opening balance wasn't saved: " + ((e && e.message) || 'please try again'), 'error');
    }
  });
  return _obChain;
}


function ledgerCellChanged(changedIdx) {
  recalcBalances();
  // Update all balance cells in the DOM
  rows.forEach((r,i) => {
    const cell = document.getElementById('balCell_'+i);
    if (cell) {
      const bal = hasData(r) ? (parseFloat(r.balance)||0) : 0;
      cell.value = bal !== 0 ? fmtNum(bal) : '';
      cell.className = 'bk-cell num bal ' + (bal>0?'pos':bal<0?'neg':'zero');
    }
  });
  ledgerUpdateTotalBanner();
}

// Update the total banner at the top with the latest closing balance
function ledgerUpdateTotalBanner() {
  const ob = parseFloat(activeAccount?.opening_balance)||0;
  const dataRows = rows.filter(r => hasData(r));
  const closing = dataRows.length > 0
    ? parseFloat(dataRows[dataRows.length-1].balance) || ob
    : ob;
  const el = document.getElementById('ledgerTotalVal');
  if (el) el.textContent = fmt(Math.abs(closing));
}

function hasData(r) {
  return !!(r.payee||r.payer||r.narration||r.debit>0||r.credit>0);
}

// ── SEARCH STATE ─────────────────────────────────────────────

function onSearchInput(val) {
  searchQuery = val;
  clearTimeout(searchTimer);
  searchTimer = setTimeout(() => {
    applyFilter();
  }, 300); // wait 300ms after user stops typing before re-rendering
}

// Which ledger rows to show, and in what order: search and date range filter, then "arrange by".
// Running balances always follow the real order of the entries, whatever the screen order is.
function ledVisibleRows() {
  const q = (searchQuery || '').toLowerCase();
  const filtered = !!(q || dateFrom || dateTo || ledColFiltersActive());
  const data = [], blanks = [];
  rows.forEach((r, i) => {
    if (!hasData(r)) { blanks.push({ r, i }); return; }
    if (filtered) {
      const okText = !q || (r.narration || '').toLowerCase().includes(q) || (r.payee || '').toLowerCase().includes(q) || (r.payer || '').toLowerCase().includes(q);
      const okFrom = !dateFrom || (r.txn_date || '') >= dateFrom;
      const okTo = !dateTo || (r.txn_date || '') <= dateTo;
      if (!(okText && okFrom && okTo && ledRowMatchesCols(r))) return;
    }
    data.push({ r, i });
  });
  return { items: bdArrangeSort(data, 'ledger').concat(filtered ? [] : blanks), filtered };
}
function applyFilter() {
  // Re-render rows only — not the whole ledger (preserves focus)
  renderRows();
}

function escH(s) {
  return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
// Makes a string safe to drop inside a single-quoted JS string literal
// that's itself embedded in an inline onclick="..." HTML attribute —
// escapes backslashes and single quotes. escH() alone does NOT do this
// (it only escapes & < > "), so any account/customer/product name or
// narration containing an apostrophe (e.g. "Ishiagu's Army Generator")
// would terminate the JS string early and leave the rest as a syntax
// error, silently turning that whole onclick handler into a no-op —
// which is exactly what made the Chart of Accounts' ✕ delete button
// "click into" the account instead: its own handler broke on the
// apostrophe before event.stopPropagation() ever ran, so the click
// fell through to the row's own onclick underneath it. Use as
// escH(escJs(value)) (or escJs(escH(value)) — order doesn't matter,
// the two escape disjoint character sets) wherever a free-text value
// is interpolated inside a single-quoted onclick argument.
function escJs(s) {
  return (s==null?'':String(s)).replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\r?\n/g,'\\n');
}

// ── CELL CHANGES ──────────────────────────────────────────────
function cellChange(i, field, val) {
  pushUndoState(true);
  rows[i][field]=val; rows[i].saved=false; isDirty=true;
  setSaveMsg('Unsaved…','pending');
  ledgerAutosave();
}

function numChange(i, field, val) {
  pushUndoState(true);
  rows[i][field]=parseFloat(String(val).replace(/,/g,''))||0; rows[i].saved=false; isDirty=true;
  recalcBalances();
  // Update balance cells from row i onwards without full re-render
  for (let j=i; j<rows.length; j++) {
    const tr=document.getElementById(`row_${j}`); if(!tr) continue;
    const inputs=tr.querySelectorAll('input');
    const bal=rows[j].balance;
    const balClass=bal>0?'pos':bal<0?'neg':'zero';
    if(inputs[6]){inputs[6].value=bal!==0?fmtNum(bal):'';inputs[6].className=`bk-cell bal ${balClass}`;}
    if(inputs[7]){inputs[7].value=hasData(rows[j])?j+1:'';}
  }
  setSaveMsg('Unsaved…','pending');
}

// ── BALANCE CALCULATION ───────────────────────────────────────
// Accounting convention (not banking):
// Asset & Expenditure accounts: Debit INCREASES balance (positive)
// Capital, Liability & Income:  Credit INCREASES balance (positive)
function recalcBalances() {
  const ob = parseFloat(activeAccount?.opening_balance)||0;
  let running = ob;
  const debitNormal = DEBIT_NORMAL.includes(activeType);
  rows.forEach((r,i)=>{
    const dr = parseFloat(r.debit)||0;
    const cr = parseFloat(r.credit)||0;
    if (debitNormal) {
      running += dr - cr; // debit increases, credit decreases
    } else {
      running += cr - dr; // credit increases, debit decreases
    }
    rows[i].balance = running;
    rows[i].serial_number = hasData(r) ? i+1 : null;
  });
}

// ── ROW MANAGEMENT ───────────────────────────────────────────
// ── Offline read cache: last-known-good data for key views ──
window._bdShowingOfflineData = false;
function bdCacheKey(view, extra) { return 'bd_cache_'+view+'_'+(activeBusiness?.id||'all')+(extra?'_'+extra:''); }
function bdCacheWrite(view, data, extra) {
  try { localStorage.setItem(bdCacheKey(view,extra), JSON.stringify({ data, cachedAt: Date.now() })); } catch(e){}
}
function bdCacheRead(view, extra) {
  try { const raw = localStorage.getItem(bdCacheKey(view,extra)); return raw ? JSON.parse(raw) : null; } catch(e){ return null; }
}
function bdOfflineBanner() {
  return window._bdShowingOfflineData
    ? `<div style="background:var(--gold-dim);border:1px solid var(--gold);color:var(--gold);font-size:0.7rem;font-weight:700;padding:8px 14px;border-radius:8px;margin-bottom:12px;text-align:center;">
        \u25CB Offline — showing the last data saved to this device. It will refresh automatically once you're back online.
      </div>`
    : '';
}

// ── Shared barcode scanner: camera-based, with hardware-scanner
//    compatibility (a USB/Bluetooth scanner gun just types into
//    focused inputs, so it needs no special code at all).
// ─────────────────────────────────────────────────────────────
// ── Sales sheet: search-and-select a registered product ──────
let salesProductCache = [];
let salesProductCacheBizId = undefined;
let salesProductCustomCols = [];
let salesProductColMeta = {};
let _salesProdT = 0;
async function bdLoadSalesProductCache(force) {
  const bizId = activeBusiness?.id || null;
  if (!force && salesProductCacheBizId === bizId) return; // already loaded for this business
  try {
    let q = bkDb.from('bk_products').select('*').eq('is_service', false).eq('is_active', true);
    q = bizId ? q.or('business_id.eq.'+bizId+',and(business_id.is.null,user_id.eq.'+bkUser.id+')') : q.eq('user_id', bkUser.id);
    const { data } = await q.order('product_name');
    salesProductCache = data || [];
    salesProductCacheBizId = bizId; _salesProdT = Date.now();
  } catch(e) { salesProductCache = []; }
  try {   // the income accounts the sheet itself posts to (products and services): these always show on the Sales Record
    let iq = bkDb.from('bk_products').select('income_account,custom').eq('is_active', true);
    iq = bizId ? iq.or('business_id.eq.'+bizId+',and(business_id.is.null,user_id.eq.'+bkUser.id+')') : iq.eq('user_id', bkUser.id);
    const { data: ia } = await iq;
    const set = new Set(['sales revenue', 'service income', 'barbing revenue']);
    (ia || []).forEach(x => [x.income_account, x.custom && x.custom.__sub].forEach(n => { if (n) set.add(String(n).trim().toLowerCase()); }));
    _salesOwnInc = set;
  } catch(e) {}
  try {
    let sq = bkDb.from('bk_sheet_settings').select('settings').eq('sheet_key', 'products');
    sq = bizId ? sq.eq('business_id', bizId) : sq.is('business_id', null).eq('user_id', bkUser.id);
    const { data: settingsRow } = await sq.maybeSingle();
    salesProductCustomCols = settingsRow?.settings?.customCols || [];
    salesProductColMeta = settingsRow?.settings?.colMeta || {};
  } catch(e) { salesProductCustomCols = []; }
  await _loadSalesSuggestSettings(bizId);
}
// Which Products/Services columns show in the sales dropdown (max 3)
// and which of those get written into the narration field on pick —
// configured from the Sales toolbox's own "Suggestions" panel, stored
// under its own sheet_key so it's independent of the Products page's
// own settings row, business-scoped like everything else here.
let salesSuggestCols = ['product_type','product_name'];
let salesNarrationCols = ['product_type','product_name'];
async function _loadSalesSuggestSettings(bizId) {
  salesSuggestCols = ['product_type','product_name'];
  salesNarrationCols = ['product_type','product_name'];
  try {
    let sq = bkDb.from('bk_sheet_settings').select('settings').eq('sheet_key', 'sales_suggest');
    sq = bizId ? sq.eq('business_id', bizId) : sq.is('business_id', null).eq('user_id', bkUser.id);
    const { data: row } = await sq.maybeSingle();
    if (row?.settings?.suggestCols?.length) salesSuggestCols = row.settings.suggestCols;
    if (row?.settings?.narrationCols) salesNarrationCols = row.settings.narrationCols;
  } catch(e) {}
}
async function _saveSalesSuggestSettings() {
  const bizId = activeBusiness?.id || null;
  const payload = {
    user_id: bkUser.id, business_id: bizId, sheet_key: 'sales_suggest',
    settings: { suggestCols: salesSuggestCols, narrationCols: salesNarrationCols },
    updated_at: new Date().toISOString(),
  };
  const onConflict = bizId ? 'business_id,sheet_key' : 'user_id,sheet_key';
  try { await bkDb.from('bk_sheet_settings').upsert(payload, { onConflict }); } catch(e) {}
}
// Every available product column, built-in and custom, that could be
// shown in the sales dropdown or written into the narration — same
// combined list the Products page's own Columns menu shows.
function _salesAvailableProductCols() {
  const builtIn = (PS_COL_DEFS.products||[]).filter(c=>c.id!=='name').map(c=>({id:c.id, label:c.label}));
  const custom = (salesProductCustomCols||[]).map(c=>({id:c.key, label:c.name}));
  return [{id:'product_name', label:'Product Name'}, ...builtIn, ...custom];
}
// Reads one configured column's value off a product row — handles
// the built-in fields directly and custom columns via their `custom`
// object, so the suggestion/narration logic doesn't need to care
// which kind of column it's showing.
function _salesColValue(p, colId) {
  const num = v => (v != null && v !== '') ? fmt(v) : '';
  if (colId === 'product_name') return p.product_name || '';
  if (colId === 'product_type') return p.product_type || '';
  if (colId === 'cost_price') return num(p.cost_price);
  if (colId === 'sell_price' || colId === 'price') return num(p.price);
  if (colId === 'barcode') return p.barcode || '';
  if (colId === 'qty_in_stock' || colId === 'qty') return p.qty_in_stock != null ? salesProdStock(p) : '';
  if (colId === 'qty_date') { const d = p.qty_as_at || ((parseFloat(p.qty_in_stock) > 0 && p.created_at) ? String(p.created_at).slice(0, 10) : ''); try { return d && typeof psFormatQtyDate === 'function' ? psFormatQtyDate(d, _psQtyDateFormat()) : (d || ''); } catch (e) { return d || ''; } }
  if (colId === 'total_cost') { const v = (parseFloat(p.cost_price) || 0) * (parseFloat(p.qty_in_stock) || 0); return v ? fmt(v) : ''; }
  if (colId === 'total_sell') { const v = (parseFloat(p.price) || 0) * (parseFloat(p.qty_in_stock) || 0); return v ? fmt(v) : ''; }
  if (colId === 'income_acct') return p.income_account || (p.custom && p.custom.__sub) || '';
  return (p.custom && p.custom[colId]) || '';
}
// How a product reads in the sales sheet: name, type and any measurements, then price and stock in its own unit.
function salesProdParts(p) {
  const parts = [p.product_name, p.product_type].filter(x => x && String(x).trim());
  (salesProductCustomCols || []).forEach(c => {
    const own = p.custom_meta && Object.prototype.hasOwnProperty.call(p.custom_meta, c.key) ? p.custom_meta[c.key] : salesProductColMeta[c.key];
    const m = _acNormalizeMeta(own);
    const v = p.custom && p.custom[c.key];
    if (m && m.type === 'measurement' && v && String(v).trim()) parts.push(String(v).trim());
  });
  return parts;
}
function salesProdText(p) { return salesProdParts(p).join(', '); }
function salesProdStock(p) {
  const u = (p.unit || '').trim(), q = (parseFloat(p.qty_in_stock) || 0).toLocaleString('en-NG', { maximumFractionDigits: 4 });
  return q + (u && u.toLowerCase() !== 'unit' ? ' ' + u : '') + ' left';
}
// The labelled details a product shows in the dropdown: the columns ticked in Assign products, or a sensible set by default.
function salesProdDetailPairs(p) {
  const cc = salesCellCols();
  const lab = { product_type: 'Type', barcode: 'Barcode', cost_price: 'Cost price', qty_date: 'Stock as at', total_cost: 'Total at cost', total_sell: 'Total at selling price', income_acct: 'Posts to' };
  const custom = (salesProductCustomCols || []);
  let ids;
  if (cc) ids = cc.map(c => c.id).filter(id => !['product_name', 'sell_price', 'qty', 'qty_in_stock'].includes(id));
  else ids = ['product_type', 'barcode', 'cost_price', 'qty_date', 'total_cost', 'total_sell', 'income_acct'].concat(custom.map(c => c.key));   // nothing assigned: everything the Products page has
  return ids.map(id => {
    const v = _salesColValue(p, id); if (!v || !String(v).trim() || String(v).trim() === '0') return '';
    const cname = (custom.find(c => c.key === id) || {}).name;
    const l = lab[id] || cname || '';
    return l ? l + ': ' + String(v).replace(/\n+/g, ' \u00B7 ') : String(v);
  }).filter(Boolean);
}
// Which Products-page columns the Product cell shows once a product is picked: [{id, main}] (null = the default text).
function salesCellCols() { const a = _lsJson('bd_sales_cell_cols', null); return Array.isArray(a) && a.length ? a : null; }
function salesProdMainText(p) {
  const cc = salesCellCols(); if (!cc) return salesProdText(p);
  const t = cc.filter(c => c.main).map(c => _salesColValue(p, c.id)).filter(x => x && String(x).trim());
  return t.length ? t.join(', ') : salesProdText(p);
}
function salesProdSubHtml(r) {
  const cc = salesCellCols(); if (!cc || !r || !r.product_id) return '';
  const p = salesProductCache.find(x => String(x.id) === String(r.product_id)); if (!p) return '';
  const lab = { cost_price: 'Cost', sell_price: 'Price', barcode: 'Barcode' };
  return cc.filter(c => !c.main).map(c => {
    const v = _salesColValue(p, c.id); if (!v || !String(v).trim()) return '';
    const stock = (c.id === 'qty' || c.id === 'qty_in_stock');
    const out = stock && !(parseFloat(p.qty_in_stock) > 0);
    return '<div' + (out ? ' style="color:var(--red,#e5534b)"' : '') + '>' + escH((lab[c.id] ? lab[c.id] + ' ' : '') + v) + '</div>';
  }).join('');
}
// Keeps the sheet in step with the Products page: stock and prices are re-read every few seconds and after each save.
let _salesProdSig = '';
function salesProdSig() { return salesProductCache.map(p => p.id + ':' + p.qty_in_stock + ':' + p.price + ':' + p.cost_price + ':' + p.product_name + ':' + p.product_type).join('|'); }
async function salesProdRefreshNow() {
  if (!document.getElementById('sheetTable_sales') || !bkUser || !navigator.onLine) return;
  try { await bdLoadSalesProductCache(true); } catch (e) { return; }
  const sig = salesProdSig(); if (sig === _salesProdSig) return; _salesProdSig = sig;
  sheetRows('sales').forEach((r, i) => { const el = document.getElementById('spSub_' + i); if (el) el.innerHTML = salesProdSubHtml(r); });
}
setInterval(() => { if (!document.hidden) salesProdRefreshNow(); }, 8000);
window.addEventListener('focus', () => { salesProdRefreshNow(); });
function bdShowProductSuggestions(i, query) {
  bdHideProductSuggestions(i); // only one suggestion box open at a time
  const q = (query||'').trim().toLowerCase();
  // Only the products picked with Assign (header ▼) are offered; with nothing picked, every registered product is.
  const asg = salesAssignedSet();
  const pool = salesProductCache.filter(p => !asg || asg.has(String(p.id)));
  const matches = (q ? pool.filter(p => (salesProdText(p) + ' ' + (p.barcode || '') + ' ' + Object.values(p.custom || {}).filter(v => typeof v === 'string').join(' ')).toLowerCase().includes(q)) : pool).slice(0, q ? 12 : 80);
  if (!matches.length && !q) return;
  const input = document.getElementById('salesProdInput_'+i);
  if (!input) return;
  const rect = input.getBoundingClientRect();

  const box = document.createElement('div');
  box.id = 'bdSuggestPortal';
  box.className = 'bd-suggest-box';
  // position:fixed + appended to document.body — escapes the sales
  // sheet's own scroll/overflow clipping, which is why this dropdown
  // was getting cut off before: it was a child of the scrollable
  // table body, and position:absolute is still clipped by a
  // scrollable ancestor regardless of its own z-index.
  box.style.cssText = 'position:fixed;z-index:12000;';
  box.innerHTML = matches.map(p => {
    const zero = !((parseFloat(p.qty_in_stock) || 0) > 0);
    return `<div class="bd-suggest-item sp-card" onmousedown="bdPickProduct(${i},'${p.id}')">
    <div class="sp-card-top"><span class="sp-card-name">${escH(p.product_name || '')}</span><span class="sp-card-price">${fmt(p.price)}</span></div>
    <div class="sp-card-grid">${salesProdDetailPairs(p).map(x => `<span>${escH(x)}</span>`).join('')}<span style="color:${zero ? 'var(--red,#e5534b)' : 'var(--green,#3fb27f)'}">${escH(salesProdStock(p))}</span></div>
  </div>`;
  }).join('') + (q && !matches.some(p => salesProdText(p).toLowerCase() === q)
    ? `<div class="bd-suggest-item" style="color:var(--muted);cursor:default;"><span>Keep typing to use \u201c${escH(query.trim())}\u201d as a product that is not registered yet</span></div>` : '');
  box.style.maxHeight = '260px'; box.style.overflowY = 'auto';
  document.body.appendChild(box);
  const bw = Math.min(Math.max(rect.width, 340), window.innerWidth - 16);
  box.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - bw - 8)) + 'px';
  box.style.width = bw + 'px';

  // Measure the box's REAL rendered height, now that its width is set
  // — an estimate based on item count alone is wrong whenever a longer
  // product name wraps within a narrow narration column, which would
  // throw off the flip-above decision below.
  const boxHeight = box.getBoundingClientRect().height;
  let top = rect.bottom + 2;
  if (top + boxHeight > window.innerHeight) top = Math.max(8, rect.top - boxHeight - 2); // flip above if no room below
  box.style.top = top + 'px';
}
function bdHideProductSuggestions(i) {
  document.getElementById('bdSuggestPortal')?.remove();
}
function bdPickProduct(i, productId) {
  bdHideProductSuggestions(i); // close immediately — left open, this silently blocks the next click (e.g. Save All) landing underneath it
  const p = salesProductCache.find(x => String(x.id) === String(productId));
  if (!p) return;
  const row = salesRows[i];
  if (!row) return;
  row.product = salesProdMainText(p);
  row.narration = row.product;            // the product cell IS the journal narration
  row._ptyped = false;
  row.unit_price = parseFloat(p.price)||0;
  row.product_id = p.id;
  row.qty = row.qty || 1;
  row.total = (row.unit_price||0) * row.qty;
  row._posted = false;
  renderRecordSheet('sales');
  sheetAutosaveTrigger('sales');
}

async function bdOpenScanner(onResult) {
  closeColMenu();
  try { await bkEnsureLibs(['zxing']); } catch(e) { /* the check below reports it */ }
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    alert('Camera scanning needs a secure (https) connection and camera permission on this device. You can also type the barcode in by hand, or use a USB/Bluetooth barcode scanner — those work automatically in any barcode field.');
    return;
  }
  const wrap = document.createElement('div');
  wrap.id = 'bdScannerModal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;';
  wrap.innerHTML = `
    <video id="bdScanVideo" style="width:100%;max-width:480px;border-radius:12px;background:#111;" playsinline muted></video>
    <div style="color:#fff;font-size:0.8rem;margin-top:16px;text-align:center;">Point the camera steadily at the barcode</div>
    <button id="bdScanCancel" style="margin-top:18px;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.8rem;padding:10px 26px;border-radius:20px;cursor:pointer;">Cancel</button>
  `;
  document.body.appendChild(wrap);

  let reader = null;
  let stopped = false;
  const cleanup = () => {
    stopped = true;
    try { reader && reader.reset(); } catch(e){}
    wrap.remove();
  };
  document.getElementById('bdScanCancel').onclick = cleanup;

  if (typeof ZXing === 'undefined' || !ZXing.BrowserMultiFormatReader) {
    alert('The scanner library did not load correctly — check your connection and try again.');
    cleanup();
    return;
  }

  // Deliberately the simplest possible setup: no format restrictions,
  // no hints map. Those are optimizations, and a misconfigured hints
  // object is exactly the kind of thing that silently stops decoding
  // while the camera preview keeps running — better to decode every
  // supported format than to risk decoding nothing at all.
  reader = new ZXing.BrowserMultiFormatReader();
  reader.decodeFromVideoDevice(null, 'bdScanVideo', (result, err) => {
    if (stopped) return;
    if (result) {
      const text = result.getText ? result.getText() : String(result);
      cleanup();
      onResult(text);
    }
    // NotFoundException fires continuously while no barcode is in view —
    // that is normal scanning behaviour, not an error to react to.
  }).catch(err => {
    alert('Could not access the camera: ' + (err && err.message ? err.message : err));
    cleanup();
  });
}

// Look up a product by barcode, scoped to the active business
async function bdFindProductByBarcode(code) {
  let q = bkDb.from('bk_products').select('*').eq('barcode', code).eq('is_active', true);
  q = activeBusiness?.id
    ? q.or('business_id.eq.'+activeBusiness.id+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
    : q.eq('user_id', bkUser.id);
  const { data } = await q.limit(1);
  return (data && data[0]) || null;
}

// Unknown barcode scanned during a sale — quick-register without
// leaving the sale, then drop it straight into the current row.
function bdQuickAddProductForBarcode(code, kind) {
  closeColMenu();
  const wrap = document.createElement('div');
  wrap.id='colMenuPortal'; wrap.style.cssText='position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;padding:20px;';
  const box = document.createElement('div');
  box.style.cssText='background:var(--surface);border:1px solid var(--gold);border-radius:14px;max-width:340px;width:100%;padding:20px;';
  box.innerHTML = `
    <div style="font-weight:900;color:var(--gold);margin-bottom:4px;">New barcode scanned</div>
    <div style="font-size:0.68rem;color:var(--muted);margin-bottom:12px;">${escH(code)} isn't registered yet. Add it now — it'll be saved for next time and added to this sale.</div>
    <label class="su-label">PRODUCT NAME</label>
    <input class="bk-login-input" id="qaName" style="margin-bottom:8px;"/>
    <label class="su-label">SELLING PRICE</label>
    <input class="bk-login-input" id="qaPrice" inputmode="decimal" style="margin-bottom:14px;"/>
    <button id="qaSave" style="width:100%;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.78rem;padding:10px;border-radius:8px;cursor:pointer;">Add &amp; Use in Sale</button>
    <button onclick="document.getElementById('colMenuPortal').remove()" style="width:100%;background:none;color:var(--muted);border:1px solid var(--border2);font-size:0.74rem;padding:8px;border-radius:8px;cursor:pointer;margin-top:8px;">Cancel</button>
  `;
  wrap.appendChild(box);
  document.body.appendChild(wrap);
  wrap.addEventListener('click', e=>{ if(e.target===wrap) wrap.remove(); });
  setTimeout(()=>document.getElementById('qaName')?.focus(), 50);
  document.getElementById('qaSave').onclick = async () => {
    const name = document.getElementById('qaName').value.trim();
    const price = parseFloat(document.getElementById('qaPrice').value)||0;
    if (!name) { alert('Enter a product name.'); return; }
    try {
      const { data:newProd, error } = await bkDb.from('bk_products').insert({
        user_id: bkUser.id, business_id: activeBusiness?.id||null, product_name: name, price, cost_price:0,
        qty_in_stock:0, unit:'unit', barcode: code, is_service:false, is_active:true,
      }).select().single();
      if (error) throw error;
      wrap.remove();
      salesProductCacheBizId = undefined; // force the picker cache to refresh next time it's opened
      bdAddScannedItemToSale({ product_name:name, price, id:newProd?.id }, kind);
      bdToast('\u2713 '+name+' added and registered for next time');
    } catch(e) { alert('Could not add product: '+(e.message||'')); }
  };
}

// Drop a found/created product into the sale sheet — bump quantity
// if it's already the current row, otherwise add a fresh row.
function bdAddScannedItemToSale(product, kind) {
  const rows = sheetRows(kind);
  let target = rows.find(r => !r._posted && r.product === product.product_name);
  if (!target) {
    const last = rows[rows.length-1];
    if (last && !last.product && !last.narration && !(last.total>0)) target = last;
    else { target = staffEmptySaleRow(rows.length+1); rows.push(target); }
  }
  target.product = product.product_name;
  target.unit_price = parseFloat(product.price)||0;
  target.qty = (target.qty||0) + 1;
  target.total = target.unit_price * target.qty;
  if (product.id) target.product_id = product.id;
  renderRecordSheet(kind);
}

// Toolbox entry point for the Sales page
function sheetScanToSell(kind) {
  bdOpenScanner(async code => {
    const product = await bdFindProductByBarcode(code);
    if (product) {
      bdAddScannedItemToSale(product, kind);
      bdToast('\u2713 '+product.product_name+' added \u2014 scan again to add another');
    } else {
      bdQuickAddProductForBarcode(code, kind);
    }
  });
}

// \u2500\u2500 Scan-a-Sale: snap/upload a photo of a receipt or sales note, read
// it into structured rows, let the user fix anything uncertain, then
// post the confirmed rows into the Sales sheet exactly like any row
// typed in by hand (same salesRows array, same autosave/post path). \u2500\u2500
let _salesScanState = null; // { imageDataUrl, items:[...], payMode, payModeConfidence }

function sheetScanSaleEntry(kind) {
  if (kind !== 'sales') return;
  const overlay = document.createElement('div');
  overlay.id = 'salesScanOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;max-width:360px;width:100%;padding:22px;text-align:center;" onclick="event.stopPropagation()">
      <div style="font-weight:900;color:var(--gold);font-size:1rem;margin-bottom:4px;">Scan Sale Record</div>
      <div style="font-size:0.72rem;color:var(--muted);margin-bottom:18px;line-height:1.5;">Snap a photo of a receipt or sales note \u2014 we'll read the details and fill in a row for you.</div>
      <input type="file" id="salesScanCameraInput" accept="image/*" capture="environment" style="display:none;" onchange="salesScanFileChosen(this)"/>
      <input type="file" id="salesScanGalleryInput" accept="image/*" style="display:none;" onchange="salesScanFileChosen(this)"/>
      <button style="width:100%;background:var(--gold);color:#fff;border:none;font-weight:800;font-size:0.82rem;padding:13px;border-radius:9px;cursor:pointer;margin-bottom:8px;" onclick="document.getElementById('salesScanCameraInput').click()">\ud83d\udcf7 Take Photo</button>
      <button style="width:100%;background:var(--surface2);color:var(--gold);border:1px solid var(--gold);font-weight:800;font-size:0.82rem;padding:13px;border-radius:9px;cursor:pointer;margin-bottom:12px;" onclick="document.getElementById('salesScanGalleryInput').click()">\ud83d\uddbc Choose from Gallery</button>
      <div style="font-size:0.62rem;color:var(--muted2);line-height:1.5;margin-bottom:12px;">Tip: flatten the paper and make sure the writing is well lit for the best results.</div>
      <button style="background:none;color:var(--muted);border:1px solid var(--border2);font-size:0.74rem;padding:9px 14px;border-radius:8px;cursor:pointer;" onclick="document.getElementById('salesScanOverlay').remove()">Cancel</button>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

async function salesScanFileChosen(input) {
  const file = input.files && input.files[0];
  if (!file) return;
  if (file.size > 10 * 1024 * 1024) { alert('Image must be under 10MB.'); return; }
  const overlay = document.getElementById('salesScanOverlay');
  if (overlay) overlay.innerHTML = `<div style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;padding:30px;text-align:center;color:var(--off);font-size:0.82rem;font-weight:700;">\u23f3 Reading your photo\u2026</div>`;

  try {
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
    const match = /^data:(.+?);base64,(.+)$/.exec(dataUrl) || [];
    const mediaType = match[1], base64 = match[2];
    if (!base64) throw new Error('Could not read that image file.');

    const res = await fetch('/api/sales-scan/extract', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ image_base64: base64, media_type: mediaType }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.error) throw new Error(data.error || 'Could not read that photo.');
    if (!data.items || !data.items.length) throw new Error("We couldn't make out any sale details in that photo \u2014 try a clearer, well-lit shot.");

    _salesScanState = { imageDataUrl: dataUrl, items: data.items, payMode: data.payment_mode || 'cash', payModeConfidence: data.payment_mode_confidence || 'low' };
    renderSalesScanReview();
  } catch (e) {
    if (overlay) overlay.remove();
    alert('Scan failed: ' + (e.message || 'Please try again.'));
  } finally {
    input.value = '';
  }
}

function renderSalesScanReview() {
  const overlay = document.getElementById('salesScanOverlay');
  if (!overlay || !_salesScanState) return;
  const s = _salesScanState;
  const payOptions = [['cash','Cash'],['transfer','Bank Transfer'],['debitcard','Debit Card'],['creditcard','Credit Card'],['pos','POS'],['cheque','Cheque'],['credit','On Credit']];
  const okStyle  = 'border:1px solid var(--green);background:var(--green-l);';
  const lowStyle = 'border:1px solid #d97706;background:#fff4e5;';
  const badge = ok => ok ? `<span style="font-size:0.72rem;color:var(--green);">\u2713</span>` : `<span style="font-size:0.72rem;color:#d97706;">\u26a0</span>`;

  const itemsHtml = s.items.map((it, i) => {
    const total = (parseFloat(it.unit_price) || 0) * (parseFloat(it.qty) || 0);
    return `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px;margin-bottom:10px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <span style="font-size:0.62rem;font-weight:800;color:var(--muted2);text-transform:uppercase;letter-spacing:0.03em;">Item ${i+1}</span>
        ${s.items.length>1 ? `<span style="font-size:0.62rem;color:var(--muted);cursor:pointer;" onclick="salesScanRemoveItem(${i})">\ud83d\uddd1 Remove</span>` : ''}
      </div>
      <label style="display:block;font-size:0.62rem;font-weight:700;color:var(--muted);margin-bottom:4px;">Narration</label>
      <div style="display:flex;align-items:center;gap:6px;border-radius:8px;padding:8px 9px;margin-bottom:9px;${it.narration_confidence==='high'?okStyle:lowStyle}">
        <input type="text" value="${escH(it.narration||'')}" oninput="salesScanEditItem(${i},'narration',this.value)" style="flex:1;min-width:0;border:none;background:transparent;font-size:0.76rem;outline:none;color:var(--white);"/>
        ${badge(it.narration_confidence==='high')}
      </div>
      <div style="display:flex;gap:8px;margin-bottom:9px;">
        <div style="flex:1;">
          <label style="display:block;font-size:0.62rem;font-weight:700;color:var(--muted);margin-bottom:4px;">Unit Price</label>
          <div style="display:flex;align-items:center;gap:6px;border-radius:8px;padding:8px 9px;${it.unit_price_confidence==='high'?okStyle:lowStyle}">
            <input type="text" inputmode="decimal" value="${it.unit_price||0}" oninput="salesScanEditItem(${i},'unit_price',this.value)" style="flex:1;min-width:0;border:none;background:transparent;font-size:0.76rem;outline:none;color:var(--white);"/>
            ${badge(it.unit_price_confidence==='high')}
          </div>
        </div>
        <div style="flex:1;">
          <label style="display:block;font-size:0.62rem;font-weight:700;color:var(--muted);margin-bottom:4px;">Qty</label>
          <div style="display:flex;align-items:center;gap:6px;border-radius:8px;padding:8px 9px;${it.qty_confidence==='high'?okStyle:lowStyle}">
            <input type="text" inputmode="decimal" value="${it.qty||1}" oninput="salesScanEditItem(${i},'qty',this.value)" style="flex:1;min-width:0;border:none;background:transparent;font-size:0.76rem;outline:none;color:var(--white);"/>
            ${badge(it.qty_confidence==='high')}
          </div>
        </div>
      </div>
      <label style="display:block;font-size:0.62rem;font-weight:700;color:var(--muted);margin-bottom:4px;">Total</label>
      <div style="border:1px solid var(--border);background:var(--surface2);border-radius:8px;padding:8px 9px;font-size:0.76rem;font-weight:800;color:var(--white);">
        ${staffFmtAmt(total)} <span style="font-weight:400;color:var(--muted2);font-size:0.6rem;">\u2014 calculated automatically</span>
      </div>
    </div>`;
  }).join('');

  const payConfident = s.payModeConfidence === 'high';

  overlay.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;max-width:400px;width:100%;max-height:92vh;overflow-y:auto;padding:18px;" onclick="event.stopPropagation()">
      <div style="text-align:center;margin-bottom:6px;">
        <div style="font-weight:900;color:var(--gold);font-size:0.98rem;">Review &amp; Confirm</div>
        <div style="font-size:0.66rem;color:var(--muted);margin-top:4px;line-height:1.45;">We filled in what we could read from your photo \u2014 please check anything marked \u26a0 before adding it.</div>
      </div>

      <div style="display:flex;align-items:center;gap:10px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:8px 10px;margin:12px 0;">
        <img src="${s.imageDataUrl}" style="width:40px;height:40px;object-fit:cover;border-radius:7px;"/>
        <div style="flex:1;font-size:0.7rem;color:var(--off);font-weight:700;">Scanned photo</div>
        <div style="font-size:0.66rem;color:var(--gold);font-weight:700;cursor:pointer;" onclick="window.open('${s.imageDataUrl}','_blank')">View full \u203a</div>
      </div>

      ${itemsHtml}

      <div style="text-align:center;padding:2px 0 14px;">
        <span style="font-size:0.72rem;font-weight:700;color:var(--gold);cursor:pointer;" onclick="salesScanAddItem()">+ Add another item</span>
      </div>

      <label style="display:block;font-size:0.62rem;font-weight:700;color:var(--muted);margin-bottom:4px;">Payment Mode</label>
      <div style="display:flex;align-items:center;gap:6px;border-radius:8px;padding:8px 9px;margin-bottom:${payConfident?'4px':'2px'};${payConfident?okStyle:lowStyle}">
        <select onchange="salesScanSetPayMode(this.value)" style="flex:1;border:none;background:transparent;font-size:0.76rem;outline:none;color:var(--white);">
          ${payOptions.map(([v,l])=>`<option value="${v}" ${s.payMode===v?'selected':''}>${l}</option>`).join('')}
        </select>
        <span style="font-size:0.72rem;color:${payConfident?'var(--green)':'#d97706'};">${payConfident?'\u2713':'\u26a0'}</span>
      </div>
      ${payConfident ? '' : `<div style="font-size:0.6rem;color:#d97706;margin-bottom:14px;">Couldn't tell how this was paid \u2014 please confirm</div>`}

      <div style="display:flex;flex-direction:column;gap:8px;margin-top:${payConfident?'14px':'0'};">
        <button style="background:var(--gold);color:#fff;border:none;font-weight:800;font-size:0.82rem;padding:12px;border-radius:9px;cursor:pointer;" onclick="salesScanConfirmAdd()">Add to Sales Sheet</button>
        <button style="background:none;color:var(--muted);border:1px solid var(--border2);font-size:0.76rem;padding:10px;border-radius:8px;cursor:pointer;" onclick="document.getElementById('salesScanOverlay').remove();_salesScanState=null;">Discard Scan</button>
      </div>
    </div>`;
}

function salesScanEditItem(i, field, val) {
  if (!_salesScanState) return;
  const it = _salesScanState.items[i];
  if (!it) return;
  it[field] = val;
  // The user typing into a flagged field is itself the confirmation \u2014
  // promote it to "high" confidence so the warning clears as they fix it.
  if (field === 'unit_price') it.unit_price_confidence = 'high';
  if (field === 'qty') it.qty_confidence = 'high';
  if (field === 'narration') it.narration_confidence = 'high';
  renderSalesScanReview();
}
function salesScanSetPayMode(v) {
  if (!_salesScanState) return;
  _salesScanState.payMode = v;
  _salesScanState.payModeConfidence = 'high';
  renderSalesScanReview();
}
function salesScanAddItem() {
  if (!_salesScanState) return;
  _salesScanState.items.push({ narration:'', narration_confidence:'low', unit_price:0, unit_price_confidence:'low', qty:1, qty_confidence:'low' });
  renderSalesScanReview();
}
function salesScanRemoveItem(i) {
  if (!_salesScanState) return;
  _salesScanState.items.splice(i, 1);
  renderSalesScanReview();
}

function salesScanConfirmAdd() {
  if (!_salesScanState) return;
  const payMode = _salesScanState.payMode || 'cash';
  const rows = sheetRows('sales');
  let added = 0;
  _salesScanState.items.forEach(it => {
    const unitPrice = parseFloat(String(it.unit_price).replace(/,/g,'')) || 0;
    const qty = parseFloat(String(it.qty).replace(/,/g,'')) || 1;
    const narration = (it.narration||'').trim();
    if (!narration || unitPrice <= 0) return;
    const row = staffEmptySaleRow(rows.length+1);
    row.narration = narration;
    row.unit_price = unitPrice;
    row.qty = qty;
    row.total = unitPrice * qty;
    row.pay_mode = payMode;
    rows.push(row);
    added++;
  });
  document.getElementById('salesScanOverlay')?.remove();
  _salesScanState = null;
  if (!added) { alert('No complete items to add \u2014 each item needs a narration and a price above zero.'); return; }
  renderRecordSheet('sales');
  sheetAutosaveTrigger('sales');
  bdToast('\u2713 '+added+' item'+(added>1?'s':'')+' added from your scan');
}

// ── Sales/Expenses: auto-save & post, like Google Sheets ──────
let _sheetAutoT = {};
let _sheetSaving = {}, _sheetSaveAgain = {};
function sheetAutosaveTrigger(kind, delay) {
  try { sheetPendCommit(kind); } catch(e) {}
  clearTimeout(_sheetAutoT[kind]);
  { const m = document.getElementById('sheetSaveMsg_'+kind); if (m && sheetRows(kind).some(r => !r._posted && parseFloat(r.total) > 0)) { m.textContent = 'Saving\u2026'; m.className = 'bk-save-msg pending'; } }
  _sheetAutoT[kind] = setTimeout(()=>sheetAutosave(kind), delay || 600);
}
async function sheetAutosave(kind) {
  if (_sheetSaving[kind]) { _sheetSaveAgain[kind] = true; return; }
  _sheetSaving[kind] = true;
  try { await _sheetAutosaveRun(kind); }
  finally { _sheetSaving[kind] = false; if (_sheetSaveAgain[kind]) { _sheetSaveAgain[kind] = false; sheetAutosaveTrigger(kind); } }
}
async function _sheetAutosaveRun(kind) {
  const rows = sheetRows(kind);
  const pending = rows.filter(r => !r._posted && parseFloat(r.total) > 0);
  if (!pending.length) return;
  const msg = document.getElementById('sheetSaveMsg_'+kind);
  if (msg) { msg.textContent = 'Saving…'; msg.className = 'bk-save-msg pending'; }
  const saveFn = kind==='sales' ? salesSaveRow : expSaveRow;
  for (const r of pending) {
    const i = rows.indexOf(r);
    if (i >= 0) { try { await saveFn(i); } catch(e) {} }
  }
  if (kind === 'sales') { try { salesProdRefreshNow(); } catch (e) {} }
  const left = rows.filter(r => !r._posted && parseFloat(r.total) > 0).length;
  const m2 = document.getElementById('sheetSaveMsg_'+kind);
  if (m2) { m2.textContent = left ? 'Not saved \u2014 will retry' : '\u2713 Saved'; m2.className = 'bk-save-msg ' + (left ? 'err' : 'ok'); }
  if (left) setTimeout(() => sheetAutosaveTrigger(kind), 4000);
}

function ensureTrailingBlank() {
  // Idempotent: guarantees exactly one blank row at the end, never more.
  // This is the ONLY place in the app allowed to push a blank ledger row.
  if (rows.length === 0 || hasData(rows[rows.length-1])) rows.push(ledBlankRow());
  ledSyncBlankDate();
}
// The empty row at the bottom always takes the date of the row above it, unless the user picked its date.
function ledSyncBlankDate() {
  const last = rows[rows.length-1];
  if (!last || hasData(last) || last._userDate) return;
  for (let k = rows.length - 2; k >= 0; k--) if (rows[k] && rows[k].txn_date) { last.txn_date = rows[k].txn_date; return; }
}
// A new blank row starts with the date of the row above it (today when the ledger is empty).
function ledBlankRow() {
  const r = emptyRow(rows.length);
  for (let k = rows.length - 1; k >= 0; k--) { if (rows[k] && rows[k].txn_date) { r.txn_date = rows[k].txn_date; break; } }
  return r;
}
function addRow() {
  // Always append one fresh blank row through the single guarded appender.
  rows.push(ledBlankRow());
  renderRows();
  setTimeout(()=>{
    const tr=document.getElementById(`row_${rows.length-1}`);
    if(tr) tr.querySelector('input')?.focus();
  },40);
}

async function deleteRow(i) {
  const removed = rows[i];
  if (!removed) return;
  // Remove from the screen immediately — no waiting on the network.
  // (Other legs of the same journal entry in this ledger go too, as the database does.)
  const gone = [];
  if (removed.id && removed.journal_id) {
    for (let k = rows.length - 1; k >= 0; k--) if (rows[k].journal_id === removed.journal_id) gone.push([k, rows[k]]);
  } else gone.push([i, removed]);
  gone.sort((x, y) => y[0] - x[0]).forEach(g => rows.splice(g[0], 1));
  recalcBalances();
  renderRows();
  setSaveMsg('Deleted', 'ok');
  try { refreshEquation(); } catch (e) {}
  const undo = (msg) => {
    gone.slice().sort((x, y) => x[0] - y[0]).forEach(g => rows.splice(g[0], 0, g[1]));
    recalcBalances(); renderRows(); try { refreshEquation(); } catch (e) {}
    bdToast('Could not delete this row: ' + (msg || 'unknown error'), 'error');
  };
  if (!removed.id) return;     // a row that was never saved has nothing in the database
  try {
    if (removed.journal_id) {
      await bdCascadeDeleteJournalEntry(removed.journal_id);
    } else {
      const { data: del, error } = await bkDb.from('bk_transactions').delete().eq('id', removed.id).select('id');
      if (error) throw error;
      if (!del || !del.length) throw new Error("it couldn't be removed — you may not have permission");
    }
    if (_coaBalCache) { try { _coaLoadBalances(); } catch (e) {} }
  } catch (e) { undo(e && e.message); }
}

// ── SAVE ─────────────────────────────────────────────────────
let _ledAutoT = null;
function ledgerAutosave(){ clearTimeout(_ledAutoT); _ledAutoT = setTimeout(()=>{ if(isDirty) saveAll(); }, 700); }
// Leaving or hiding the page saves a ledger edit that is still waiting.
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden' && typeof isDirty !== 'undefined' && isDirty && activeAccount) { try { clearTimeout(_ledAutoT); } catch(e) {} saveAll(); } });
window.addEventListener('pagehide', () => { if (typeof isDirty !== 'undefined' && isDirty && activeAccount) { try { clearTimeout(_ledAutoT); } catch(e) {} saveAll(); } });

let _ledSaving = false, _ledSaveAgain = false;
async function saveAll() {
  if(!activeAccount||!bkUser) return;
  // One save at a time; edits made meanwhile are picked up by the next pass.
  if (_ledSaving) { _ledSaveAgain = true; return; }
  _ledSaving = true;
  try {
    setSaveMsg('Saving…','pending');
    recalcBalances();
    const toSave  = rows.filter(r=>hasData(r));
    const ordOf = new Map(toSave.map((r,k)=>[r,k]));
    // Only what changed goes over the wire: new rows, rows you edited, and rows whose
    // running balance or position moved because of an edit above them.
    const changed = r => !r.id || r.saved === false ||
      (r._dbBal !== undefined && Math.abs((parseFloat(r._dbBal)||0) - (parseFloat(r.balance)||0)) > 0.0001) ||
      ((r._dbOrd !== undefined ? r._dbOrd : r.row_order) !== ordOf.get(r));
    const newRows = toSave.filter(r=>!r.id);
    const existRows = toSave.filter(r=>r.id && changed(r));
    let err = null;

    if (newRows.length) {
      const { data, error } = await bkDb.from('bk_transactions').insert(
        newRows.map(r=>({
          user_id:bkUser.id, business_id:activeBusiness?.id||null, record_type:activeType,
          account_name:activeAccount.account_name,
          serial_number:r.serial_number, txn_date:r.txn_date||null,
          payee:r.payee||null, payer:r.payer||null, narration:r.narration||null,
          debit:r.debit||0, credit:r.credit||0, balance:r.balance||0,
          row_order:ordOf.get(r),
        }))
      ).select();
      if (error) err=error;
      else data?.forEach((d,i)=>{ newRows[i].id=d.id; newRows[i].saved=true; newRows[i]._dbBal=newRows[i].balance; newRows[i]._dbOrd=ordOf.get(newRows[i]); });
    }

    // Existing rows: ONE batched upsert (only the listed columns are touched; the
    // business, journal link and anything else on the row stay exactly as they were).
    const mk = r => ({
      id:r.id, user_id:bkUser.id, record_type:activeType, account_name:activeAccount.account_name,
      serial_number:r.serial_number, txn_date:r.txn_date||null,
      payee:r.payee||null, payer:r.payer||null, narration:r.narration||null,
      debit:r.debit||0, credit:r.credit||0, balance:r.balance||0,
      row_order:ordOf.get(r), updated_at:new Date().toISOString(),
    });
    const markOk = r => { r.saved=true; r._dbBal=r.balance; r._dbOrd=ordOf.get(r); };
    for (let s=0; s<existRows.length; s+=200) {
      const chunk = existRows.slice(s, s+200);
      const { error } = await bkDb.from('bk_transactions').upsert(chunk.map(mk));
      if (!error) { chunk.forEach(markOk); continue; }
      for (const r of chunk) {   // find the one that failed
        const { error:e1 } = await bkDb.from('bk_transactions').update({
          account_name:activeAccount.account_name, serial_number:r.serial_number, txn_date:r.txn_date||null,
          payee:r.payee||null, payer:r.payer||null, narration:r.narration||null,
          debit:r.debit||0, credit:r.credit||0, balance:r.balance||0, row_order:ordOf.get(r), updated_at:new Date().toISOString(),
        }).eq('id',r.id).eq('user_id',bkUser.id);
        if (e1) err = e1; else markOk(r);
      }
    }

    if(err){ setSaveMsg('Error: '+err.message,'err'); return; }
    isDirty = rows.some(r=>hasData(r) && r.saved === false);
    setSaveMsg('✓ Saved','ok');
    refreshEquation();
  } finally {
    _ledSaving = false;
    if (_ledSaveAgain) { _ledSaveAgain = false; saveAll(); }
  }
}

function setSaveMsg(msg, type) {
  const el=document.getElementById('saveMsg'); if(!el) return;
  el.textContent=msg; el.className='bk-save-msg '+type;
}

// ── EQUATION ─────────────────────────────────────────────────
let _eqT = null;
function refreshEquation() {
  // Never holds a save up: runs once, shortly after the last change.
  clearTimeout(_eqT); _eqT = setTimeout(() => { _refreshEquationNow().catch(()=>{}); }, 1200);
  return Promise.resolve();
}
async function _refreshEquationNow() {
  if(!bkUser) return;
  if (!document.getElementById('bkMainChrome') ||
      document.getElementById('bkMainChrome').style.display === 'none') return;
  const { data } = await bkFetchAll(()=>bkDb.from('bk_transactions')
    .select('record_type,debit,credit').match(bizMatch()).order('id'));
  const { data:accts } = await acctBizFilter(bkDb.from('bk_accounts')
    .select('record_type,opening_balance'));

  let cap=0, lia=0, ast=0, rev=0, exp=0;
  (accts||[]).forEach(a=>{
    const ob=parseFloat(a.opening_balance)||0;
    if(a.record_type==='capital')   cap+=ob;
    if(a.record_type==='liability') lia+=ob;
    if(a.record_type==='asset')     ast+=ob;
  });
  (data||[]).forEach(r=>{
    const dr=parseFloat(r.debit)||0, cr=parseFloat(r.credit)||0;
    if(r.record_type==='capital')     cap += cr-dr;
    if(r.record_type==='liability')   lia += cr-dr;
    if(r.record_type==='asset')       ast += dr-cr;
    if(r.record_type==='income')      rev += cr-dr;
    if(r.record_type==='expenditure') exp += dr-cr;
  });

  const profitLoss = rev - exp;
  const setEl = (id,v) => { const e=document.getElementById(id); if(e) e.textContent=v; };
  setEl('eqCapital',    fmt(cap));
  setEl('eqLiabilities',fmt(lia));
  setEl('eqAssets',     fmt(ast));
  const plEl = document.getElementById('eqProfitLoss');
  if (plEl) {
    plEl.textContent = fmt(Math.abs(profitLoss));
    plEl.style.color = profitLoss >= 0 ? 'var(--green)' : 'var(--red)';
    plEl.closest('.bk-eq-block')?.querySelector('.bk-eq-label')
      && (plEl.closest('.bk-eq-block').querySelector('.bk-eq-label').textContent =
        profitLoss >= 0 ? 'Profit' : 'Loss');
  }

  const check = document.getElementById('eqCheck');
  if (!check) return;
  const lhs = cap + profitLoss + lia;
  const diff = Math.abs(lhs - ast);
  if (!data || data.length === 0) {
    check.textContent = 'Enter transactions to see the equation update.';
    check.className = 'bk-eq-check';
  } else if (diff < 0.01) {
    check.textContent = '✓ Books are balanced';
    check.className = 'bk-eq-check balanced';
  } else {
    check.innerHTML = `<span style="cursor:pointer;" onclick="smartErrorDetect(${diff.toFixed(2)})">⚠ Difference of ${fmt(diff)} — tap to find the problem ✨</span>`;
    check.className = 'bk-eq-check unbalanced';
  }
}

// ── Collapse/expand the entire equation widget ────────────────
function toggleEqBar(){
  const body = document.getElementById('eqBarBody');
  const btn  = document.getElementById('eqCollapseBtn');
  if (!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : '';
  if (btn) btn.textContent = open ? '▸' : '▾';
}

function toggleExtEq() {
  const panel = document.getElementById('extEqPanel');
  const btn   = document.getElementById('extEqBtn');
  if (!panel) return;
  const open = panel.style.display !== 'none';
  panel.style.display = open ? 'none' : 'block';
  if (btn) btn.textContent = open ? '▸ Show Extended Equation' : '▾ Hide Extended Equation';
}

// ── Show/hide the "Show Extended Equation" collapsible — hidden on the
//    Dashboard specifically, visible on every other page ──
function hideExtEqToggle(){
  const wrap  = document.getElementById('extEqToggleWrap');
  const panel = document.getElementById('extEqPanel');
  if (wrap)  wrap.style.display  = 'none';
  if (panel) panel.style.display = 'none'; // also collapse it if it was open
}
function showExtEqToggle(){
  const wrap = document.getElementById('extEqToggleWrap');
  if (wrap) wrap.style.display = '';
}

// ── SMART ERROR DETECTION ─────────────────────────────────────
async function smartErrorDetect(diff) {
  const check = document.getElementById('eqCheck');
  check.innerHTML = '🔍 Analysing your entries…';
  check.className = 'bk-eq-check unbalanced';

  // Fetch all journal entries
  const { data:jnl } = await bkDb.from('bk_journal')
    .select('*').match(bizMatch())
    .order('created_at', { ascending: false }).limit(50);

  if (!jnl || jnl.length === 0) {
    check.innerHTML = `⚠ Difference of ${fmt(diff)} — no journal entries found to analyse.`;
    return;
  }

  // Find imbalanced entries (debit ≠ credit)
  const imbalanced = jnl.filter(j => {
    const dr = parseFloat(j.debit_amount) || 0;
    const cr = parseFloat(j.credit_amount) || 0;
    return Math.abs(dr - cr) > 0.01;
  });

  // Find entries where amount matches the diff
  const matching = jnl.filter(j => {
    const dr = parseFloat(j.debit_amount) || 0;
    const cr = parseFloat(j.credit_amount) || 0;
    return Math.abs(dr - diff) < 0.01 || Math.abs(cr - diff) < 0.01 ||
           Math.abs(Math.abs(dr - cr) - diff) < 0.01;
  });

  const suspect = imbalanced[0] || matching[0] || null;

  // Ask AI to analyse with specific data
  const context = jnl.slice(0, 10).map((j, i) =>
    `${i+1}. Date:${j.txn_date||'?'} | ${j.narration||'No description'} | Dr:${fmt(parseFloat(j.debit_amount)||0)} to "${j.debit_account_name||'?'}" | Cr:${fmt(parseFloat(j.credit_amount)||0)} to "${j.credit_account_name||'?'}"`
  ).join('\n');

  let aiAnalysis = '';
  try {
    const res = await fetch(`${SUPABASE_URL}/functions/v1/ai-chat`, {
      method: 'POST',
      headers: { 'Content-Type':'application/json', 'Authorization':`Bearer ${SUPABASE_ANON_KEY}` },
      body: JSON.stringify({ message:
        `I am an accountant reviewing a bookkeeping system. The accounting equation is out of balance by ${fmt(diff)}.

Here are the last 10 journal entries:
${context}

${suspect ? `The most likely problem entry is: "${suspect.narration||'No desc'}" — Debit: ${fmt(parseFloat(suspect.debit_amount)||0)} / Credit: ${fmt(parseFloat(suspect.credit_amount)||0)}` : ''}

In 3 bullet points maximum, tell me:
1. Which specific entry number is most likely causing the ${fmt(diff)} imbalance and exactly why
2. The exact correction needed (which account, which amount, debit or credit)
3. Nothing else — be direct and specific, no general advice.` })
    });
    const d = await res.json();
    aiAnalysis = d.content?.[0]?.text || '';
  } catch(e) {
    aiAnalysis = 'Could not reach AI — check your internet connection.';
  }

  // Build the smart error panel
  const panel = document.createElement('div');
  panel.id = 'smartErrorPanel';
  panel.style.cssText = `background:var(--surface);border:1px solid var(--red);border-radius:10px;padding:16px;margin-top:10px;text-align:left;`;
  panel.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
      <div style="font-size:0.78rem;font-weight:800;color:var(--red);">⚠ Balance Error — ${fmt(diff)} Difference</div>
      <button onclick="document.getElementById('smartErrorPanel').remove()"
        style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:1rem;">✕</button>
    </div>
    ${suspect ? `
    <div style="background:rgba(248,113,113,0.08);border:1px solid rgba(248,113,113,0.2);border-radius:6px;padding:10px;margin-bottom:10px;">
      <div style="font-size:0.7rem;font-weight:700;color:var(--muted);text-transform:uppercase;margin-bottom:4px;">Most Likely Problem Entry</div>
      <div style="font-size:0.8rem;color:var(--white);">${escH(suspect.narration||'Untitled entry')} — ${suspect.txn_date||'No date'}</div>
      <div style="font-size:0.75rem;color:var(--muted);margin-top:3px;">
        Dr: <span style="color:#4ade80;">${fmt(parseFloat(suspect.debit_amount)||0)}</span> →
        Cr: <span style="color:#f87171;">${fmt(parseFloat(suspect.credit_amount)||0)}</span>
        ${Math.abs((parseFloat(suspect.debit_amount)||0)-(parseFloat(suspect.credit_amount)||0))>0.01
          ? `<span style="color:var(--red);margin-left:6px;">⚠ Imbalanced by ${fmt(Math.abs((parseFloat(suspect.debit_amount)||0)-(parseFloat(suspect.credit_amount)||0)))}</span>`
          : ''}
      </div>
      <button onclick="smartAutoCorrect('${suspect.id}', ${parseFloat(suspect.debit_amount)||0}, ${parseFloat(suspect.credit_amount)||0})"
        style="margin-top:8px;background:var(--gold);border:none;color:var(--accent-ink);font-size:0.76rem;font-weight:700;padding:7px 16px;border-radius:6px;cursor:pointer;">
        ✓ Auto-Correct This Entry
      </button>
    </div>` : ''}
    <div style="font-size:0.78rem;color:var(--off);line-height:1.6;white-space:pre-wrap;">${escH(aiAnalysis)}</div>`;

  const bar = document.querySelector('.bk-eq-bar');
  const existing = document.getElementById('smartErrorPanel');
  if (existing) existing.remove();
  if (bar) bar.appendChild(panel);

  check.innerHTML = `⚠ Difference of ${fmt(diff)} — <span style="cursor:pointer;color:var(--gold);" onclick="smartErrorDetect(${diff})">Re-analyse ↻</span>`;
}

async function smartAutoCorrect(journalId, drAmt, crAmt) {
  // The larger of the two is the correct amount — add the missing side
  const correctAmt = Math.max(drAmt, crAmt);
  if (correctAmt <= 0) return;

  const { error } = await bkDb.from('bk_journal').update({
    debit_amount:  correctAmt,
    credit_amount: correctAmt,
    updated_at:    new Date().toISOString(),
  }).eq('id', journalId).eq('user_id', bkUser.id);

  if (!error) {
    document.getElementById('smartErrorPanel')?.remove();
    await refreshEquation();
    if (activeAccount) { recalcBalances(); renderRows(); }
  }
}

// ── DASHBOARD ─────────────────────────────────────────────────
// showDashboard is defined above in the COA/settings section

// ── Page guard — prevents stale async callbacks from navigating away ──
let currentPage = 'dashboard'; // updated by every page-entry function
// Converts an internal route string (e.g. "products", or a
// colon-separated one like "ledger:123:456") into a clean URL path
// ("/products", "/ledger/123/456") and back. This is what makes pages
// bookmarkable/shareable and lets the browser's own back/forward
// buttons work — previously every page rendered under the exact same
// URL, so Back left the app entirely instead of going to the
// previous in-app page.
const BD_ROUTE_SLUGS = {
  'dashboard':'home', 'all-businesses':'all-businesses', 'journal':'master-journal', 'coa':'chart-of-accounts', 'settings':'settings',
  'products':'products', 'services':'services', 'suppliers':'vendors', 'ap-vendors':'vendors', 'ap-bills':'bills', 'ap-aging':'ap-aging',
  'staff':'staff', 'sales-record':'sales', 'expenses-record':'expenses', 'record-choice':'record', 'record-biz-choice':'record-business',
  'mode-choice':'choose-mode', 'register-business':'register-business', 'register-products':'register-products',
  'personal-setup':'personal-setup', 'personal-home':'personal', 'personal-txns':'personal-transactions', 'search-business':'search-business',
  'sales-dashboard':'sales-dashboard', 'sales-customers':'customers', 'sales-invoices':'invoices', 'sales-new-invoice':'new-invoice', 'sales-view-invoice':'view-invoice',
  'sales-quotes':'quotes', 'sales-new-quote':'new-quote', 'sales-ar-aging':'ar-aging', 'ap-new-bill':'new-bill', 'ap-view-bill':'view-bill',
  'source-docs-hub':'source-documents', 'bank-feeds':'bank-feeds',
};
const BD_REPORT_SLUGS = { trial:'trial-balance', pl:'profit-and-loss', bs:'balance-sheet', cf:'cash-flow', eq:'equity' };
const BD_TYPE_SLUGS = { capital:'capital', liability:'liabilities', asset:'assets', income:'income', expenditure:'expenditure' };
const BD_DAYBOOK_SLUGS = { salesday:'sales', purchday:'purchases', salesreturns:'sales-returns', purchreturns:'purchases-returns', cash:'cash-book' };
function _bdInv(o) { const r = {}; Object.keys(o).forEach(k => { if (!(o[k] in r)) r[o[k]] = k; }); return r; }
const BD_SLUG_ROUTES = _bdInv(BD_ROUTE_SLUGS), BD_REPORT_FROM = _bdInv(BD_REPORT_SLUGS), BD_TYPE_FROM = _bdInv(BD_TYPE_SLUGS), BD_DAYBOOK_FROM = _bdInv(BD_DAYBOOK_SLUGS);
function _bdSlugify(t) { return String(t || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60); }
// Converts an internal route string into a readable URL path and back, so every page has a
// proper name in the address bar (/master-journal, /reports/profit-and-loss,
// /accounts/assets/cash-at-bank~<id>), pages are bookmarkable, and reloading lands on the same page.
function _bdRouteToPath(route) {
  if (!route) return '/';
  if (BD_ROUTE_SLUGS[route]) return '/' + BD_ROUTE_SLUGS[route];
  const parts = route.split(':'), head = parts[0];
  if (head === 'report' && parts[1]) return '/reports/' + (BD_REPORT_SLUGS[parts[1]] || encodeURIComponent(parts[1]));
  if (head === 'ledger-type' && parts[1]) return '/accounts/' + (BD_TYPE_SLUGS[parts[1]] || encodeURIComponent(parts[1]));
  if (head === 'ledger' && parts[1]) {
    const ts = BD_TYPE_SLUGS[parts[1]] || encodeURIComponent(parts[1]);
    if (!parts[2]) return '/accounts/' + ts;
    let nm = ''; try { const a = (accounts[parts[1]] || []).find(x => String(x.id) === String(parts[2])); nm = a ? _bdSlugify(a.account_name) : ''; } catch (e) {}
    return '/accounts/' + ts + '/' + (nm ? nm + '~' : '') + encodeURIComponent(parts[2]);
  }
  if (head === 'daybook' && parts[1]) return '/day-book/' + (BD_DAYBOOK_SLUGS[parts[1]] || encodeURIComponent(parts[1]));
  if (head === 'warehouse' && parts[1]) return '/inventory/' + encodeURIComponent(parts[1].replace(/_/g, '-'));
  return '/' + parts.map(encodeURIComponent).join('/');
}
function _bdPathToRoute(path) {
  const segs = String(path || '').replace(/^\/|\/$/g, '').split('/').filter(Boolean).map(x => { try { return decodeURIComponent(x); } catch (e) { return x; } });
  if (!segs.length) return null;
  const s0 = segs[0].toLowerCase();
  if (segs.length === 1 && BD_SLUG_ROUTES[s0]) return BD_SLUG_ROUTES[s0];
  if (s0 === 'reports' && segs[1]) return 'report:' + (BD_REPORT_FROM[segs[1].toLowerCase()] || segs[1]);
  if (s0 === 'accounts' && segs[1]) {
    const type = BD_TYPE_FROM[segs[1].toLowerCase()] || segs[1];
    if (segs[2]) { const id = segs[2].indexOf('~') >= 0 ? segs[2].slice(segs[2].lastIndexOf('~') + 1) : segs[2]; return 'ledger:' + type + ':' + id; }
    return 'ledger-type:' + type;
  }
  if (s0 === 'day-book' && segs[1]) return 'daybook:' + (BD_DAYBOOK_FROM[segs[1].toLowerCase()] || segs[1]);
  if (s0 === 'inventory' && segs[1]) return 'warehouse:' + segs[1].replace(/-/g, '_');
  return segs.join(':');   // older style links such as /report/pl or /ledger/asset/<id>
}

// ── REMEMBER WHERE YOU STOPPED ────────────────────────────────
// Master Journal, Sales and Expenses sheets: leave the page (or log out) and the
// sheet opens again right where you were working, not back at row 1. Position is
// kept per business on this device.
const BD_POS_PAGES = { 'journal':1, 'sales-record':1, 'expenses-record':1 };
let _bdPosPending = null, _bdPosScrollT = 0;
function _bdPosKey(page) { return 'bd_pos_' + page + '_' + ((typeof activeBusiness !== 'undefined' && activeBusiness && activeBusiness.id) || (typeof bkUser !== 'undefined' && bkUser && bkUser.id) || 'x'); }
function _bdPosRead(page) { try { return JSON.parse(localStorage.getItem(_bdPosKey(page)) || 'null'); } catch(e) { return null; } }
function _bdPosWrite(page, patch) { try { const cur = _bdPosRead(page) || {}; localStorage.setItem(_bdPosKey(page), JSON.stringify(Object.assign(cur, patch, { t: Date.now() }))); } catch(e) {} }
function _bdPosPageNow() { return (typeof currentPage !== 'undefined' && BD_POS_PAGES[currentPage]) ? currentPage : null; }
function _bdPosRowCount(page) { try { return page === 'journal' ? journalRows.length : (page === 'sales-record' ? salesRows : staffExpRows).length; } catch(e) { return 0; } }
function bdPosArm(page) { if (BD_POS_PAGES[page]) _bdPosPending = { page, until: Date.now() + 20000 }; }
function bdPosRestore(page) {
  const pend = _bdPosPending; if (!pend || pend.page !== page || Date.now() > pend.until) return;
  const saved = _bdPosRead(page); if (!saved) { _bdPosPending = null; return; }
  const n = _bdPosRowCount(page);
  const go = () => {
    if (!_bdPosPending || _bdPosPending.page !== page) return;
    let tr = null;
    if (saved.n !== n && saved.idx != null) tr = document.getElementById(page === 'journal' ? 'jrow_' + saved.idx : (page === 'sales-record' ? 'sales' : 'expenses') + 'row_' + saved.idx);
    if (tr) tr.scrollIntoView({ block: 'center' });
    else if (saved.y != null) window.scrollTo({ top: saved.y, left: 0, behavior: 'instant' });
    if (saved.y == null || tr || Math.abs(window.scrollY - saved.y) < 60) _bdPosPending = null;   // reached it (or the page is not tall enough yet — try again on the next render)
  };
  requestAnimationFrame(() => requestAnimationFrame(go));
}
if (!window._bdPosWired) {
  window._bdPosWired = true;
  const cancel = () => { _bdPosPending = null; };
  ['wheel', 'touchmove', 'keydown', 'pointerdown'].forEach(ev => document.addEventListener(ev, cancel, { capture: true, passive: true }));
  document.addEventListener('focusin', e => {
    const t = e.target; if (!t || !t.closest) return;
    const pg = _bdPosPageNow(); if (!pg) return;
    let tr = null, idx = null;
    if (pg === 'journal') { tr = t.closest('#journalBody tr[id^="jrow_"]'); if (tr) idx = +tr.id.slice(5); }
    else { tr = t.closest('#sheetTable_' + (pg === 'sales-record' ? 'sales' : 'expenses') + ' tbody tr[data-idx]'); if (tr) idx = +tr.dataset.idx; }
    if (idx != null && !isNaN(idx)) _bdPosWrite(pg, { idx, n: _bdPosRowCount(pg), y: window.scrollY });
  }, true);
  window.addEventListener('scroll', () => {
    const now = Date.now(); if (now - _bdPosScrollT < 350) return; _bdPosScrollT = now;
    if (_bdPosPending) return;
    const pg = _bdPosPageNow(); if (pg) _bdPosWrite(pg, { y: window.scrollY, n: _bdPosRowCount(pg) });
  }, { passive: true });
  const flush = () => { const pg = _bdPosPageNow(); if (pg && !_bdPosPending) _bdPosWrite(pg, { y: window.scrollY, n: _bdPosRowCount(pg) }); };
  window.addEventListener('pagehide', flush);
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') flush(); });
}

function bdSaveRoute(page) {
  bdPosArm(page);
  currentPage = page;
  try { sessionStorage.setItem('bd_route', page); } catch(e) {}
  try {
    const path = _bdRouteToPath(page);
    if (window.location.pathname !== path) history.pushState({ bdRoute: page }, '', path);
  } catch(e) {}
  try { setActiveNav(bkRouteToMenuId(page)); } catch(e) {}
}

// Maps a bdSaveRoute() route string to the hamburger-menu element (top
// level or nested submenu item) that represents it, so the menu can
// show "you are here" without every single page having to know about
// the menu. Covers dynamic routes (report:pl, ledger-type:capital,
// daybook:cash, source-doc-receipt, etc.) by prefix/segment, not just
// exact matches — most pages already call bdSaveRoute() for routing
// (back button, deep links), so this rides along for free.
function bkRouteToMenuId(route) {
  if (!route) return null;
  if (route === 'dashboard') return 'mnu-dashboard';
  if (route.indexOf('requisition') === 0) return 'mnu-requisitions';
  if (route === 'source-docs-hub' || route.indexOf('source-doc-') === 0 || route === 'source-doc-view') return 'mnu-source-docs';
  if (route === 'journal') return 'sub-item-journal';
  if (route.indexOf('daybook:') === 0) return 'sub-item-' + route.split(':')[1];
  if (route === 'coa') return 'sub-item-coa';
  if (route.indexOf('ledger-type:') === 0) return 'sub-item-sched-' + route.split(':')[1];
  if (route.indexOf('ledger:') === 0) return 'sub-item-sched-' + route.split(':')[1];
  if (route.indexOf('report:') === 0) {
    const t = route.split(':')[1];
    return t === 'trial' ? 'sub-item-trial' : 'sub-item-report-' + t;
  }
  if (route === 'products' || route === 'register-products') return 'sub-item-products';
  if (route === 'services') return 'sub-item-services';
  const SALES_ROUTE_MAP = { 'sales-dashboard':'sub-item-sales-dash', 'sales-record':'sub-item-sales-record', 'sales-customers':'sub-item-sales-customers', 'sales-invoices':'sub-item-sales-invoices', 'sales-new-invoice':'sub-item-sales-invoices', 'sales-view-invoice':'sub-item-sales-invoices', 'sales-quotes':'sub-item-sales-quotes', 'sales-new-quote':'sub-item-sales-quotes', 'sales-ar-aging':'sub-item-sales-araging' };
  if (SALES_ROUTE_MAP[route]) return SALES_ROUTE_MAP[route];
  const AP_ROUTE_MAP = { 'ap-bills':'sub-item-ap-bills', 'ap-new-bill':'sub-item-ap-bills', 'ap-view-bill':'sub-item-ap-bills', 'ap-vendors':'sub-item-ap-vendors', 'suppliers':'sub-item-ap-vendors', 'ap-aging':'sub-item-ap-aging' };
  if (AP_ROUTE_MAP[route]) return AP_ROUTE_MAP[route];
  if (route === 'bank-feeds') return 'mnu-bank-feeds';
  if (route === 'staff') return 'mnu-staff-directory';
  if (route === 'settings') return 'mnu-settings';
  return null;
}

// Highlights the given menu item (top-level or nested submenu item) and,
// if it's nested, also lights up its parent and expands that submenu so
// reopening the hamburger shows context instead of everything collapsed.
function setActiveNav(menuId) {
  document.querySelectorAll('.bk-menu-item.active, .bk-submenu-item.active').forEach(el => el.classList.remove('active'));
  if (!menuId) return;
  const el = document.getElementById(menuId);
  if (!el) return;
  el.classList.add('active');
  const submenu = el.closest('.bk-submenu');
  if (submenu) {
    const parent = document.querySelector('.bk-menu-parent[data-target="' + submenu.id + '"]');
    if (parent) parent.classList.add('active');
    bkExpandSubmenu(submenu.id);
  }
}
function bkExpandSubmenu(id) {
  const sub = document.getElementById(id);
  if (!sub) return;
  document.querySelectorAll('.bk-submenu').forEach(s => s.classList.remove('open'));
  document.querySelectorAll('.bk-menu-arrow').forEach(a => a.classList.remove('open'));
  sub.classList.add('open');
  const arrow = document.getElementById('arrow-' + id.replace('sub-', ''));
  if (arrow) arrow.classList.add('open');
}

// ── MENU SEARCH ──────────────────────────────────────────────────
// A flat index of every destination in the hamburger menu, independent
