function bkMenuSearch(value) {
  const q = (value || '').trim().toLowerCase();
  const clearBtn = document.getElementById('bkMenuSearchClearBtn');
  if (clearBtn) clearBtn.style.display = q ? 'flex' : 'none';
  if (!q) { bkMenuSearchClear(); return; }
  document.getElementById('bkMenuNormal').style.display = 'none';
  const isOwnerOrManager = (typeof userRole !== 'undefined') && (userRole === 'owner' || userRole === 'manager');
  const matches = BK_MENU_INDEX.filter(item => {
    if (item.role === 'owner-manager' && !isOwnerOrManager) return false;
    return item.label.toLowerCase().indexOf(q) !== -1;
  });
  const results = document.getElementById('bkMenuSearchResults');
  results.style.display = 'block';
  results.innerHTML = matches.length
    ? matches.map(m => `<div class="bk-menu-result-item" onclick="bkMenuRunAction(${JSON.stringify(m.action)})"><span class="bk-menu-icon">${m.icon}</span> ${escH(m.label)}<span class="hint">${m.parent ? 'in ' + escH(m.parent) : 'Top level'}</span></div>`).join('')
    : `<div class="bk-menu-result-empty">No matches for "${escH(value)}".</div>`;
}
function bkMenuRunAction(action) {
  try { Function(action)(); } catch (e) { console.error('bkMenuRunAction failed', e); }
  closeBkMenu();
}
function bkMenuSearchClear() {
  const input = document.getElementById('bkMenuSearchInput');
  if (input) input.value = '';
  const clearBtn = document.getElementById('bkMenuSearchClearBtn');
  if (clearBtn) clearBtn.style.display = 'none';
  const results = document.getElementById('bkMenuSearchResults');
  if (results) { results.style.display = 'none'; results.innerHTML = ''; }
  const normal = document.getElementById('bkMenuNormal');
  if (normal) normal.style.display = '';
}
// Anything that goes wrong while opening a page shows this (with a way out) instead of an endless "Loading…".
function bdRouteFail(msg) {
  const c = document.getElementById('bkContent'); if (!c) return;
  const route = currentPage || '';
  c.innerHTML = `<div style="max-width:420px;margin:60px auto;padding:26px;text-align:center;background:var(--surface);border:1px solid var(--border2);border-radius:14px;">
    <div style="margin-bottom:8px;">${bfiMark(40)}</div>
    <div style="font-weight:900;margin-bottom:6px;">This page didn't load</div>
    <div style="font-size:0.78rem;color:var(--muted);line-height:1.5;margin-bottom:16px;">${escH(msg || 'Something got in the way. Check your connection and try again.')}</div>
    <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;">
      <button class="bk-btn" onclick="bdRestoreRoute()">Try again</button>
      <button class="bk-btn bk-btn-outline" onclick="showDashboard()">Go to Homepage</button></div></div>`;
}
let _bdRouteWatch = null;
function bdRestoreRoute(routeOverride) {
  // The URL is the primary source of truth (direct links, bookmarks and refreshing mid-page);
  // sessionStorage is only the fallback for the plain root path.
  const pathRoute = _bdPathToRoute(window.location.pathname);
  const r = routeOverride || pathRoute || sessionStorage.getItem('bd_route');
  const run = fn => { try { const x = fn(); if (x && x.catch) x.catch(e => { console.error('page failed to open', r, e); bdRouteFail('The page hit a problem while opening.'); }); } catch (e) { console.error('page failed to open', r, e); bdRouteFail('The page hit a problem while opening.'); } };
  // If a page is still on "Loading…" after a long wait, say so instead of spinning forever.
  clearTimeout(_bdRouteWatch);
  _bdRouteWatch = setTimeout(() => { const c = document.getElementById('bkContent'); if (c && c.querySelector(':scope > .bk-loading') && !c.querySelector(':scope > :not(.bk-loading)')) bdRouteFail('It is taking longer than usual to open.'); }, 25000);
  const T = {
    'all-businesses': () => showAllBusinessesDashboard(), 'journal': () => openJournal(), 'settings': () => roleAwareSettings(),
    'products': () => showProductsPage('products'), 'services': () => showProductsPage('services'),
    'suppliers': () => openAPVendors(), 'ap-vendors': () => openAPVendors(), 'ap-bills': () => openAPBills(), 'ap-aging': () => openAPAging(),
    'staff': () => showTeam(), 'team': () => showTeam(), 'join-business': () => showJoinBusiness(), 'record-biz-choice': () => showRecordBusinessChoice(), 'mode-choice': () => showDashboard(),
    'register-business': () => showRegisterBusinessPage(), 'register-products': () => showRegisterProductsPage(),
    'personal-setup': () => showPersonalSetup(), 'personal-home': () => showPersonalHome(), 'personal-txns': () => showPersonalTransactions(),
    'search-business': () => showSearchBusinessPage(), 'record-choice': () => showRecordChoice(), 'sales-record': () => showRecordSales(), 'expenses-record': () => showRecordExpenses(),
    'coa': () => openChartOfAccounts(), 'sales-dashboard': () => openSalesDashboard(), 'sales-customers': () => openSalesCustomers(),
    'sales-invoices': () => openSalesInvoices(), 'sales-new-invoice': () => openSalesInvoices(), 'sales-view-invoice': () => openSalesInvoices(),
    'sales-quotes': () => openSalesQuotes(), 'sales-new-quote': () => openSalesQuotes(), 'sales-ar-aging': () => openSalesARAging(),
    'ap-new-bill': () => openAPBills(), 'ap-view-bill': () => openAPBills(), 'source-docs-hub': () => openSourceDocuments(), 'bank-feeds': () => openBankFeeds(),
    'dashboard': () => showDashboard(),
  };
  if (userRole === 'employee' && !(r && (r.startsWith('requisition') || r === 'settings' || r === 'join-business'))) { run(() => goToHomepage()); return; }
  if (r && T[r]) { run(T[r]); return; }
  if (r && r.startsWith('report:')) { run(() => showReport(r.slice(7))); return; }
  if (r && r.startsWith('source-doc')) { run(() => openSourceDocuments()); return; }
  if (r && r.startsWith('requisition')) { run(() => openRequisitions()); return; }
  if (r && r.startsWith('ledger-type:')) { run(() => showSchedule(r.slice(12))); return; }
  if (r && r.startsWith('daybook:')) { run(() => showDayBook(r.slice(8))); return; }
  if (r && r.startsWith('warehouse:')) { run(() => showWarehousePage(r.slice(10))); return; }
  if (r && r.startsWith('ledger:')) {
    const parts = r.split(':');
    run(() => {
      const acct = (accounts[parts[1]] || []).find(a => String(a.id) === String(parts[2]));
      if (acct) return openAccount(parts[1], acct);
      return showSchedule(parts[1]);    // that account is gone (or not in this business): show its list instead of a blank page
    });
    return;
  }
  run(() => showDashboard());
}
// Fires when the user clicks the browser's Back/Forward buttons. The
// browser has already updated window.location itself at this point —
// bdRestoreRoute() just needs to render whatever page that now points
// to, without pushing another history entry (that would break Forward).
window.addEventListener('popstate', function(){
  if (typeof bkUser !== 'undefined' && bkUser) bdRestoreRoute();
});

// A debounced settings save (adding a Products column, toggling its
// visibility, changing alignment, etc.) has a short delay before it
// actually reaches the database. Refreshing or closing the tab within
// that window — plausible right after making a change, since
// refreshing is a natural way to check whether it took — previously
// lost that change entirely, since the delayed timer never got to
// fire. Flushing here, the instant the page starts to go away, gives
// that save its best chance to actually complete before the browser
// tears the page down.
function _bdFlushPendingSaves() {
  if (_psSaveDebounceTimer) {
    clearTimeout(_psSaveDebounceTimer);
    _psSaveDebounceTimer = null;
    try { _psSaveSheetSettingsImmediate(); } catch(e) {}
  }
}
window.addEventListener('beforeunload', _bdFlushPendingSaves);
document.addEventListener('visibilitychange', function(){
  if (document.visibilityState === 'hidden') _bdFlushPendingSaves();
});


// ── SALES & EXPENSES BREAKDOWN DRILLDOWN ─────────────────────
async function showSalesBreakdown() {
  staffHideChrome();
  document.getElementById('bkContent').innerHTML = '<div class="bk-loading">Loading sales breakdown...</div>';
  const { data:T } = await bkFetchAll(()=>bkDb.from('bk_transactions').select('*')
    .match(bizMatch()).eq('record_type','income').order('txn_date',{ascending:false}).order('id'));
  const rows = T||[];
  // Group by payment mode based on account name (debit side)
  const { data:J } = await bkDb.from('bk_journal').select('*').match(bizMatch());
  const jMap = {};
  (J||[]).forEach(j=>{ jMap[j.id]=j; });
  // Categorise each transaction
  let cash=0,bank=0,pos=0,credit=0;
  rows.forEach(r=>{
    const j=jMap[r.journal_id];
    if(!j) return;
    const dr=j.debit_account_name||'';
    if(dr==='Cash in Hand') cash+=(parseFloat(r.credit)||0);
    else if(dr==='Cash at Bank') bank+=(parseFloat(r.credit)||0);
    else if(dr==='Debtors') credit+=(parseFloat(r.credit)||0);
    else cash+=(parseFloat(r.credit)||0);
  });
  const total=cash+bank+credit;
  document.getElementById('bkContent').innerHTML=`
    <div class="bk-content-header">
      <div class="bk-content-title">SALES BREAKDOWN</div>
      <button class="bk-btn bk-btn-outline" style="font-size:0.76rem;" onclick="showDashboard()">&larr; Back</button>
    </div>
    <div style="padding:16px;">
      <div class="dash-card" style="margin-bottom:12px;">
        <div class="dash-kpi-label" style="margin-bottom:4px;">Total Sales</div>
        <div style="font-size:1.4rem;font-weight:900;color:#4ade80;">${fmt(total)}</div>
      </div>
      ${[['Cash Sales','Cash in Hand',cash,'#4ade80'],['Bank Transfer',null,bank,'#60a5fa'],['Credit Sales (Owed)',null,credit,'#f97316']].map(([label,acct,val,col])=>`
      <div class="dash-card" style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;align-items:center;">
          <div>
            <div class="dash-acct-name" style="font-size:0.82rem;">${label}</div>
            <div class="dash-acct-bar" style="margin-top:6px;"><div class="dash-acct-bar-fill" style="width:${total>0?Math.round(val/total*100):0}%;background:${col};"></div></div>
          </div>
          <div style="font-size:1.1rem;font-weight:800;color:${col};margin-left:16px;">${fmt(val)}</div>
        </div>
        <div style="font-size:0.68rem;color:var(--muted);margin-top:4px;">${total>0?Math.round(val/total*100):0}% of total sales</div>
      </div>`).join('')}
    </div>`;
}

