function renderPL(t) {
  const A = window._reportByAcct || {income:{},expenditure:{}};
  const sym = CURRENCIES[activeCurrency].symbol;
  const incomeItems = Object.entries(A.income).map(([n,v])=>[n,-v]).filter(([,v])=>Math.abs(v)>0.004);
  const cosItems  = Object.entries(A.expenditure).filter(([n])=>isCOSAccount(n)).map(([n,v])=>[n,v]).filter(([,v])=>Math.abs(v)>0.004);
  const opexItems = Object.entries(A.expenditure).filter(([n])=>!isCOSAccount(n)).map(([n,v])=>[n,v]).filter(([,v])=>Math.abs(v)>0.004);
  const revenue = incomeItems.reduce((s,[,v])=>s+v,0);
  const cos     = cosItems.reduce((s,[,v])=>s+v,0);
  const gross   = revenue - cos;
  const opex    = opexItems.reduce((s,[,v])=>s+v,0);
  const profit  = gross - opex;
  const line = ([n,v]) => `<tr><td style="padding-left:22px;">${escH(n)}</td><td class="num">${fmt(v)}</td></tr>`;
  document.getElementById('bkContent').innerHTML=`
    <div class="bk-content-header">
      <div><div class="bk-content-title">STATEMENT OF PROFIT OR LOSS</div>
      <div style="font-size:0.7rem;color:var(--muted);margin-top:2px;">${escH((window._reportBizName||activeBusiness?.name)||'')} — IFRS presentation</div></div>
      <div class="bk-header-actions"></div>
    </div>
    <div class="report-wrap">
      <table class="report-table">
        <thead><tr><th>Item</th><th class="num">Amount (${sym})</th></tr></thead>
        <tbody>
          <tr class="section-hdr"><td colspan="2">Revenue</td></tr>
          ${incomeItems.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">No revenue recorded</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td>Total Revenue</td><td class="num">${fmt(revenue)}</td></tr>
          <tr class="section-hdr"><td colspan="2">Cost of Sales</td></tr>
          ${cosItems.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td>Total Cost of Sales</td><td class="num">(${fmt(cos)})</td></tr>
          <tr class="total-row"><td><b>GROSS PROFIT</b></td><td class="num"><b>${fmt(gross)}</b></td></tr>
          <tr class="section-hdr"><td colspan="2">Operating Expenses</td></tr>
          ${opexItems.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td>Total Operating Expenses</td><td class="num">(${fmt(opex)})</td></tr>
          <tr class="${profit>=0?'profit-row':'loss-row'} total-row"><td><b>${profit>=0?'PROFIT':'LOSS'} FOR THE PERIOD</b></td><td class="num"><b>${fmt(profit)}</b></td></tr>
        </tbody>
      </table>
    </div>`;
}

let bsToolboxOpen = false;
function bsToggleToolbox(){ bsToolboxOpen = !bsToolboxOpen; showReport('bs'); }

// ── Balance Sheet — "Delete Balance Sheet Data" ────────────────
// Deliberately narrow in what it removes: only journal entries where
// BOTH sides are Asset/Liability/Capital (capital injections, loans
// drawn or repaid, transfers between asset accounts, and the like) —
// never one where the other side is Income or Expenditure. A sale or
// an expense payment also posts an Asset leg (the Cash side), but
// deleting just that leg would leave the Income/Expenditure leg
// without its other half — breaking that entry's own double entry and
// silently corrupting the P&L this button has no business touching.
// Standalone postings with no journal_id (Accounts Payable bills,
// which post directly to bk_transactions — see the AP audit notes on
// bdCascadeDeleteJournalEntry) are left alone for the same reason:
// there is no way to reverse a bill's own balance from here safely.
function bsOpenDeleteModal() {
  const bizName = (window._reportBizName || activeBusiness?.name || '').trim();
  const confirmPhrase = bizName || 'DELETE';
  const overlay = document.createElement('div');
  overlay.className = 'bk-modal-overlay';
  overlay.id = 'bsDeleteModalOverlay';
  overlay.innerHTML = `
    <div class="bk-modal danger">
      <div class="bk-modal-icon">⚠️</div>
      <h3>Delete all Balance Sheet data?</h3>
      <p>This permanently deletes${bizName?', for <b style="color:var(--white)">'+escH(bizName)+'</b> only':''}:</p>
      <ul>
        <li>Every Master Journal entry that is purely between <b>Asset</b>, <b>Liability</b>, and <b>Capital</b> accounts (capital injections, loans, transfers, etc.) and their ledger legs</li>
        <li>The <b>opening balance</b> on every Asset, Liability, and Capital account (reset to zero)</li>
      </ul>
      <p style="color:#e0796d;font-weight:700;">This cannot be undone.</p>
      <p>Sales, Expense, and Accounts Payable postings are not touched, even the Cash side of them — removing just that side would break those entries' own double entry.</p>
      <label class="confirm-label">Type <span class="confirm-bizname">${escH(confirmPhrase)}</span> to confirm</label>
      <input class="confirm-input" id="bsDeleteConfirmInput" placeholder="${bizName?'Business name…':'Type DELETE…'}" oninput="bsConfirmInputChanged(this.value)" autocomplete="off"/>
      <div class="bk-modal-actions">
        <button class="bk-btn bk-btn-outline" onclick="bsCloseDeleteModal()">Cancel</button>
        <button class="bk-btn bk-btn-danger" id="bsDeleteConfirmBtn" disabled onclick="bsExecuteDelete()">Delete Everything</button>
      </div>
    </div>`;
  overlay._confirmPhrase = confirmPhrase;
  document.body.appendChild(overlay);
  setTimeout(()=>document.getElementById('bsDeleteConfirmInput')?.focus(), 30);
}
function bsCloseDeleteModal() {
  document.getElementById('bsDeleteModalOverlay')?.remove();
}
function bsConfirmInputChanged(val) {
  const overlay = document.getElementById('bsDeleteModalOverlay');
  const btn = document.getElementById('bsDeleteConfirmBtn');
  if (!overlay || !btn) return;
  btn.disabled = val.trim() !== overlay._confirmPhrase;
}
async function bsExecuteDelete() {
  const btn = document.getElementById('bsDeleteConfirmBtn');
  if (!btn || btn.disabled) return;
  const original = btn.textContent;
  btn.disabled = true; btn.textContent = 'Deleting…';
  try {
    const BS_TYPES = ['asset','liability','capital'];
    const { data: candidates } = await acctBizFilter(bkDb.from('bk_journal')
      .select('id,debit_record_type,credit_record_type'));
    const pureIds = (candidates||[])
      .filter(j => BS_TYPES.includes(j.debit_record_type) && BS_TYPES.includes(j.credit_record_type))
      .map(j => j.id);
    for (const jid of pureIds) {
      await acctBizFilter(bkDb.from('bk_transactions').delete().eq('journal_id', jid));
      await acctBizFilter(bkDb.from('bk_journal').delete().eq('id', jid));
    }
    for (const type of BS_TYPES) {
      await acctBizFilter(bkDb.from('bk_accounts').update({ opening_balance: 0, ob_date: null }))
        .eq('record_type', type);
      const acctArr = accounts[type] || [];
      acctArr.forEach(a => { a.opening_balance = 0; a.ob_date = null; });
    }
    bsCloseDeleteModal();
    bdToast('Balance Sheet data deleted', 'ok');
    await showReport('bs');
    refreshEquation();
    bdRefreshDashboardIfVisible();
  } catch (e) {
    btn.disabled = false; btn.textContent = original;
    alert('Could not complete the delete: '+(e?.message||'unknown error'));
  }
}

function renderBS(t) {
  const A = window._reportByAcct || {asset:{},liability:{},capital:{},income:{},expenditure:{}};
  const sym = CURRENCIES[activeCurrency].symbol;
  const assets = Object.entries(A.asset).filter(([,v])=>Math.abs(v)>0.004);
  const fixedA = assets.filter(([n])=>isFixedAsset(n));
  const currA  = assets.filter(([n])=>!isFixedAsset(n));
  const liabs  = Object.entries(A.liability).map(([n,v])=>[n,-v]).filter(([,v])=>Math.abs(v)>0.004);
  const ltl    = liabs.filter(([n])=>isLongTermLiab(n));
  const ctl    = liabs.filter(([n])=>!isLongTermLiab(n));
  const capItems = Object.entries(A.capital).map(([n,v])=>[n,-v]).filter(([,v])=>Math.abs(v)>0.004);
  const income = -Object.values(A.income).reduce((s,v)=>s+v,0);
  const exp    =  Object.values(A.expenditure).reduce((s,v)=>s+v,0);
  const profit = income - exp;
  const sum = arr => arr.reduce((s,[,v])=>s+v,0);
  const totalAssets = sum(fixedA)+sum(currA);
  const totalEq = sum(capItems)+profit;
  const totalLiab = sum(ltl)+sum(ctl);
  const line = ([n,v]) => `<tr><td style="padding-left:22px;">${escH(n)}</td><td class="num">${fmt(v)}</td></tr>`;
  document.getElementById('bkContent').innerHTML=`
    <div class="bk-content-header">
      <div><div class="bk-content-title">STATEMENT OF FINANCIAL POSITION</div>
      <div style="font-size:0.7rem;color:var(--muted);margin-top:2px;">${escH((window._reportBizName||activeBusiness?.name)||'')} — IFRS presentation</div></div>
      <div class="bk-header-actions">
        <button class="bk-btn bk-btn-outline" onclick="bsToggleToolbox()">⚙ Tools</button>
      </div>
    </div>
    ${bsToolboxOpen?`<div class="sheet-toolbox">
      <button class="tb-icon tb-danger" onclick="bsOpenDeleteModal()">🗑 Delete Balance Sheet Data</button>
    </div>`:''}
    <div class="report-wrap">
      <table class="report-table">
        <thead><tr><th>Item</th><th class="num">Amount (${sym})</th></tr></thead>
        <tbody>
          <tr class="section-hdr"><td colspan="2">ASSETS</td></tr>
          <tr class="section-hdr"><td colspan="2" style="font-size:0.7rem;padding-left:12px;">Non-current Assets (Fixed Assets)</td></tr>
          ${fixedA.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td style="padding-left:12px;">Total Non-current Assets</td><td class="num">${fmt(sum(fixedA))}</td></tr>
          <tr class="section-hdr"><td colspan="2" style="font-size:0.7rem;padding-left:12px;">Current Assets</td></tr>
          ${currA.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td style="padding-left:12px;">Total Current Assets</td><td class="num">${fmt(sum(currA))}</td></tr>
          <tr class="total-row"><td><b>TOTAL ASSETS</b></td><td class="num"><b>${fmt(totalAssets)}</b></td></tr>
          <tr class="section-hdr"><td colspan="2">EQUITY</td></tr>
          ${capItems.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr><td style="padding-left:22px;">Profit for the period</td><td class="num">${fmt(profit)}</td></tr>
          <tr class="total-row"><td>Total Equity</td><td class="num">${fmt(totalEq)}</td></tr>
          <tr class="section-hdr"><td colspan="2">LIABILITIES</td></tr>
          <tr class="section-hdr"><td colspan="2" style="font-size:0.7rem;padding-left:12px;">Non-current Liabilities</td></tr>
          ${ltl.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="section-hdr"><td colspan="2" style="font-size:0.7rem;padding-left:12px;">Current Liabilities</td></tr>
          ${ctl.map(line).join('')||'<tr><td style="padding-left:22px;color:var(--muted);">—</td><td class="num">—</td></tr>'}
          <tr class="total-row"><td>Total Liabilities</td><td class="num">${fmt(totalLiab)}</td></tr>
          <tr class="total-row"><td><b>TOTAL EQUITY &amp; LIABILITIES</b></td><td class="num"><b>${fmt(totalEq+totalLiab)}</b></td></tr>
        </tbody>
      </table>
    </div>`;
}

