      let groupOpen = false;
      const openGroup = () => { if (!groupOpen) { html += `<optgroup label="${optgroupLabel}">`; groupOpen = true; } };
      const closeGroup = () => { if (groupOpen) { html += '</optgroup>'; groupOpen = false; } };
      openGroup();
