let _jrnUploadState = null; // { fileName, entries:[{_checked, txn_date, narration, debit_account_name, debit_record_type, debit_account_matched, credit_account_name, credit_record_type, credit_account_matched, debit_amount, credit_amount, confidence, flag_reason}] }

