// ── Why a file or scan couldn't be read, in plain words ──
function jrnUploadWhy(err, file) {
  const d = window._upDiag || {}, m = String((err && err.message) || err || '');
  const name = (file && file.name) || '', ext = (name.split('.').pop() || '').toLowerCase();
  const img = !!(file && stmtIsImage(file));
  const R = [];
  if (!navigator.onLine || /failed to fetch|networkerror|load failed|network request failed/i.test(m)) R.push("There's no working internet connection to the reading service. Check your connection and try again.");
  if (d.pdfPassword) R.push('This PDF is password-protected. Open it with the password, save or print it as a new PDF without one, then upload that.');
  if (/under 20MB/i.test(m)) R.push('The file is larger than 20 MB. Split it into smaller parts (for example a few pages or a month at a time), or reduce the picture size.');
  if (/unsupported file type/i.test(m)) R.push('That file type isn\'t supported' + (ext ? ' (.' + ext + ')' : '') + '. Use a PDF, Excel (.xlsx / .xls), CSV, or a photo (JPG, PNG, WebP).');
  if (/no sheets/i.test(m)) R.push('The spreadsheet has no sheets with data in it.');
  if (/couldn't open that picture/i.test(m) || d.imageOpen) R.push("The picture couldn't be opened" + (/heic|heif/.test(ext) ? ". HEIC photos from some phones can't be opened in every browser — take the photo again as a JPG, or share it as JPG/PNG." : ". It may be damaged or in a format this browser can't show. Try a JPG or PNG."));
  if (/did not load/i.test(m)) R.push('One of the file readers did not load (usually a weak connection). Refresh the page and try again.');
  if (img || d.scanned) {
    if (d.ocrUnavailable) R.push("The on-device scan reader couldn't start on this device, so the backup reader was used instead.");
    if (d.ocrWords != null && d.ocrWords < 12) R.push('Almost no text could be made out in the ' + (img ? 'picture' : 'scan') + ' (' + d.ocrWords + ' word' + (d.ocrWords === 1 ? '' : 's') + '). It may be blurry, too dark, too small, shot at an angle, or have glare or a shadow across it.');
    if (d.pdfTooLong) R.push('This scanned PDF has more pages than the on-device reader handles at once, so it was sent to the backup reader.');
  }
  if (ext === 'pdf' && d.noTextLayer && !img) R.push('This PDF is a picture of a document with no readable text inside it, and the scan reader could not make out the table.');
  if (/couldn't find any transactions/i.test(m)) R.push("The file opened fine, but no transaction lines (a date, a description and an amount) could be found in it. It may be a cover page, a summary, a blank page, or something other than a statement, receipt list or sales record.");
  const srv = m.match(/couldn't read any transactions\s*[—-]\s*(.*)$/i);
  if (srv) {
    const t = srv[1] || '';
    if (/overload|busy|rate|429|529|503|temporar/i.test(t)) R.push('The reading service is busy right now. Wait a minute and try again.');
    else if (/too large|too big|413|payload|exceed|size|limit/i.test(t)) R.push('The file is too large for the reading service in one go. Try fewer pages, or a smaller picture.');
    else if (/time.?out|timed out|504|502/i.test(t)) R.push('The reading service took too long to answer. Try again, or upload fewer pages at a time.');
    else if (/password|encrypt/i.test(t)) R.push('The file is protected or encrypted and can\'t be opened. Remove the protection and upload it again.');
    else R.push('The reading service said: "' + t.replace(/^.*?:\s*/, '').slice(0, 160) + '"');
  }
  if (!R.length) R.push(m ? m : 'Something went wrong while reading it.');
  const tips = img || d.scanned
    ? 'Tips for a better scan: lay the page flat, fill the frame with the whole page, use bright even light, avoid glare and shadows, and hold the camera steady.'
    : 'If the file keeps failing, try exporting it again from your bank or app as an Excel, CSV or PDF, or take a clear photo of it instead.';
  return { title: img ? "That scan couldn't be read" : "That file couldn't be read", message: (name ? name + '\n\n' : '') + R.map(x => '• ' + x).join('\n') + '\n\n' + tips };
}
function jrnUploadFail(err, file) {
  document.getElementById('jrnUploadOverlay')?.remove();
  const w = jrnUploadWhy(err, file);
  bdDialog({ title: w.title, message: w.message, buttons: [{ label: 'OK', value: true, primary: true }] });
}


// ═════════════════════════════════════════════════════════════════
// RECEIPT / VOUCHER / INVOICE READER — free, on the person's own device.
// Turns the text of ONE document (a receipt, voucher, invoice, transfer slip …) into a draft journal entry.
// Pure functions (no page needed) so it can be tested on its own.
