    const low = text.toLowerCase(); let best = null;
    products.forEach(p => { const n = (p.name || '').toLowerCase(); if (n.length >= 3 && low.includes(n) && (!best || n.length > best.name.length)) best = p; });
    if (!best) products.forEach(p => { const ws = ((p.name || '').toLowerCase().match(/[a-z]{4,}/g) || []); if (ws.length && ws.some(w => low.includes(w.replace(/s$/, ''))) && !best) best = p; });
