  if (!toF) { const bi = lines.findIndex(l => /biller\s+information/i.test(l)); if (bi >= 0) { for (let k = bi + 1; k < Math.min(lines.length, bi + 4); k++) if (/^\s*name\b/i.test(lines[k])) { toF = { v: rcAfter(lines, k, /^\s*name\b/i), i: k }; break; } } }
