  if (toF && /^[\d\s]+$/.test(toF.v)) toF = (bl > 0 && /[A-Za-z]{3,}/.test(lines[bl - 1]) && !/sender|amount|type|date/i.test(lines[bl - 1])) ? { v: rcClean(lines[bl - 1]), i: bl - 1 } : null;
