// ── Match narration text to accounting rules ─────────────────
function matchAccountingRule(text) {
  if (!text || text.length < 3) return null;
  const lower = text.toLowerCase();
  let bestMatch = null, bestScore = 0;

  for (const rule of ACCOUNTING_RULES) {
    let score = 0;
    for (const key of rule.keys) {
      if (lower.includes(key)) {
        score += key.length; // longer keyword match = more specific = higher score
      }
    }
    if (score > bestScore) { bestScore = score; bestMatch = rule; }
  }
  return bestMatch;
}

// ── Resolve rule account names to actual user accounts ───────
function resolveAccount(ruleName, preferredType) {
  // Try to find a matching account in the user's chart of accounts
  const allAccts = [];
  Object.entries(accounts).forEach(([type, list]) => {
    (list||[]).forEach(a => allAccts.push({ name:a.account_name, type }));
  });

  const lower = ruleName.toLowerCase();
  // Exact match first
  let match = allAccts.find(a => a.name.toLowerCase() === lower);
  if (match) return match.name;
  // Partial match
  match = allAccts.find(a => a.name.toLowerCase().includes(lower.split(' ')[0]));
  if (match) return match.name;
  // Return rule name as-is (will need to be created)
  return ruleName;
}

// ── Smart Entry hint (shows as user types) ───────────────────
function smartEntryHint(val) {
  const hint = document.getElementById('smartEntryHint');
  if (!hint) return;
  if (!val.trim()) { hint.textContent = ''; return; }
  const rule = matchAccountingRule(val);
  if (rule) {
    hint.innerHTML = `<span style="color:var(--gold);">Detected: ${rule.id.replace(/_/g,' ').toUpperCase()}</span> — Dr: <b>${rule.debit}</b> / Cr: <b>${rule.credit}</b>`;
  } else {
    hint.innerHTML = '<span style="color:var(--muted);">Tip: mention the transaction type, e.g. "paid rent", "sold goods", "received loan"</span>';
  }
}

// ── Smart Entry: generate full journal entry from description ─
async function smartEntry() {
  const input  = document.getElementById('smartEntryInput');
  const result = document.getElementById('smartEntryResult');
  const btn    = document.getElementById('smartEntryBtn');
  const text   = input?.value.trim();
  if (!text) { input?.focus(); return; }

  btn.textContent = '⏳ Thinking…'; btn.disabled = true;
  result.style.display = 'none';

  // Step 1: Try rules engine first (instant)
  const rule = matchAccountingRule(text);

  // Step 2: Extract amount from description
  const amtMatch = text.match(/[₦$£€]?\s*([\d,]+(?:\.\d{1,2})?)/);
  const amount   = amtMatch ? parseFloat(amtMatch[1].replace(/,/g,'')) : 0;

  if (rule && amount > 0) {
    // Rules engine found it — show result immediately
    showSmartResult(rule, amount, text, rule.principle);
    btn.textContent = '✨ Generate Entry'; btn.disabled = false;
    return;
  }

  // Step 3: Fall back to AI for complex/unusual transactions
  const accountList = Object.entries(accounts)
    .flatMap(([type, list]) => (list||[]).map(a => `${type}: ${a.account_name}`))
    .join('\n');

  try {
    const res = await fetch(`${SUPABASE_URL}/functions/v1/ai-chat`, {
      method:'POST',
      headers:{ 'Content-Type':'application/json', 'Authorization':`Bearer ${SUPABASE_ANON_KEY}` },
      body: JSON.stringify({ message:
        `You are an expert Nigerian accountant. A business owner described this transaction: "${text}"

Their chart of accounts:
${accountList || 'Cash and Bank, Sales Revenue, Purchases, Expenses'}

Extract:
1. The amount (if mentioned)
2. The correct debit account (from their chart or suggest a standard one)
3. The correct credit account (from their chart or suggest a standard one)
4. A brief plain-English explanation of the accounting treatment (1 sentence)

Respond ONLY with valid JSON, no other text:
{"debit":"account name","credit":"account name","amount":0,"reason":"one sentence explanation"}` })
    });
    const d  = await res.json();
    const txt = (d.content?.[0]?.text || '').trim();
    const json = JSON.parse(txt.replace(/```json|```/g,'').trim());
    const fakeRule = {
      debit: json.debit, credit: json.credit,
      principle: json.reason,
      id: 'ai_suggested'
    };
    showSmartResult(fakeRule, json.amount||amount||0, text, json.reason);
  } catch(e) {
    result.style.display = 'block';
    result.innerHTML = `<span style="color:var(--red);">Could not analyse — please describe the transaction more clearly or type the entry manually.</span>`;
  }

  btn.textContent = '✨ Generate Entry'; btn.disabled = false;
}

