function toggleWrap() {
  wrapActive = !wrapActive;
  const table = document.querySelector('.bk-sheet');
  if (table) table.classList.toggle('text-wrap', wrapActive);
  const btn = document.getElementById('tbWrap');
  if (btn) btn.classList.toggle('active', wrapActive);
}

const ROW_HEIGHT_CYCLE = ['normal','compact','expanded'];
const ROW_HEIGHT_LABELS = { normal:'⬛ Normal', compact:'▪ Compact', expanded:'⬛ Tall' };

function cycleRowHeight() {
  const idx = ROW_HEIGHT_CYCLE.indexOf(rowHeightState);
  rowHeightState = ROW_HEIGHT_CYCLE[(idx+1) % ROW_HEIGHT_CYCLE.length];
  const table = document.querySelector('.bk-sheet');
  if (table) {
    table.classList.remove('rows-compact','rows-normal','rows-expanded');
    if (rowHeightState !== 'normal') table.classList.add(`rows-${rowHeightState}`);
  }
  const btn = document.getElementById('tbRowH');
  if (btn) btn.textContent = ROW_HEIGHT_LABELS[rowHeightState];
}

function tbInsertRow() {
  if (activeAccount) {
    const idx = selectedRowIdx !== null ? selectedRowIdx : rows.length;
    rows.splice(idx, 0, emptyRow(idx));
    recalcBalances();
    renderRows();
  } else if (document.getElementById('journalTable')) {
    const idx = selectedRowIdx !== null ? selectedRowIdx : journalRows.length;
    journalRows.splice(idx, 0, emptyJournalRow(idx));
    renderJournalRows();
  }
}

function tbDeleteSelected() {
  if (selectedRowIdx === null) return;
  if (activeAccount) deleteRow(selectedRowIdx);
  else deleteJournalRow(selectedRowIdx);
  selectedRowIdx = null;
}

// Track selected row
document.addEventListener('click', e => {
  const tr = e.target.closest('tr[id^="row_"], tr[id^="jrow_"]');
  if (!tr) { selectedRowIdx = null; return; }
  document.querySelectorAll('tr.row-selected').forEach(r => r.classList.remove('row-selected'));
  tr.classList.add('row-selected');
  const match = tr.id.match(/\d+$/);
  selectedRowIdx = match ? parseInt(match[0]) : null;
});

// ── Drag-to-scroll for sheet wraps (desktop mouse) ───────────
// Touch devices already get momentum scrolling via CSS.
// This adds click-and-drag horizontal scrolling on desktop.
function initSheetDragScroll(wrap) {
  if (!wrap || wrap._dragInited) return;
  wrap._dragInited = true;
  let startX = 0, scrollLeft = 0, dragging = false;
  wrap.addEventListener('mousedown', function(e) {
    // Only drag if click is directly on the wrap or the table, not on an input/select/button
    if (e.target.closest('input,select,button,a,textarea')) return;
    dragging = true;
    startX = e.pageX - wrap.offsetLeft;
    scrollLeft = wrap.scrollLeft;
    wrap.style.cursor = 'grabbing';
    e.preventDefault();
  });
  document.addEventListener('mousemove', function(e) {
    if (!dragging) return;
    const x = e.pageX - wrap.offsetLeft;
    wrap.scrollLeft = scrollLeft - (x - startX);
  });
  document.addEventListener('mouseup', function() {
    if (!dragging) return;
    dragging = false;
    wrap.style.cursor = '';
  });
}

// Attach drag-scroll to any .bk-sheet-wrap that currently exists or
// is added later (MutationObserver watches bkContent for new tables)
function initAllSheetWraps() {
  document.querySelectorAll('.bk-sheet-wrap').forEach(initSheetDragScroll);
}
const _sheetWrapObserver = new MutationObserver(initAllSheetWraps);
function attachSheetObserver(){
  const target = document.getElementById('bkContent') || document.body;
  _sheetWrapObserver.observe(target, { childList:true, subtree:true });
  initAllSheetWraps();
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', attachSheetObserver);
} else {
  attachSheetObserver();
}

function tbPDF() {
  if (document.getElementById('journalTable')) exportJournalPDF();
  else exportPDF();
}

// ── CSV EXPORT ────────────────────────────────────────────────
function exportCSV() {
  const table = document.querySelector('.bk-sheet');
  if (!table) { alert('Open a ledger or journal first.'); return; }

  const headers = Array.from(table.querySelectorAll('thead th'))
    .map(th => `"${th.textContent.trim()}"`).join(',');

  const bodyRows = Array.from(table.querySelectorAll('tbody tr'))
    .map(tr => Array.from(tr.querySelectorAll('input,select'))
      .map(el => `"${(el.value||'').replace(/"/g,'""')}"`)
      .join(','))
    .filter(r => r.replace(/","/g,'').replace(/"/g,'').trim());

  const csv = [headers, ...bodyRows].join('\n');
  const blob = new Blob([csv], { type:'text/csv' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url;
  a.download = `bd-${(activeAccount?.account_name||'journal').toLowerCase().replace(/\s/g,'-')}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

// ── COLUMN RESIZE ─────────────────────────────────────────────
let _colResizeCfg = null, _colResizeDelegated = false;
function initColumnResize(selector, onResize) {
  const table = document.querySelector(selector || '.bk-sheet');
  if (!table) return;
  _colResizeCfg = { selector: selector || '.bk-sheet', onResize: onResize };
  if (!_colResizeDelegated) {
    _colResizeDelegated = true;
    // The pinned (scrolled) copy of the header has no listeners of its own: pass the drag to the real header.
    document.addEventListener('pointerdown', function(e){
      const h = e.target.closest && e.target.closest('.col-resize-handle');
      const box = h && h.closest('[id^=bdClone_thead]');
      if (!box || !_colResizeCfg) return;
      const cth = h.closest('th'); const key = cth.dataset.colKey;
      const tbl = document.querySelector(_colResizeCfg.selector); if (!tbl) return;
      const idx = Array.prototype.indexOf.call(cth.parentNode.children, cth);
      const real = key ? tbl.querySelector('thead th[data-col-key="'+key+'"]') : tbl.querySelectorAll('thead th')[idx];
      const rh = real && real.querySelector('.col-resize-handle'); if (!rh) return;
      e.preventDefault(); e.stopPropagation();
      const mv = function(){ try { bdSyncStickyClones(); } catch(x){} };
      const up = function(){ document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up); setTimeout(mv, 30); };
      document.addEventListener('pointermove', mv); document.addEventListener('pointerup', up);
      rh.dispatchEvent(new PointerEvent('pointerdown', { clientX:e.clientX, clientY:e.clientY, bubbles:true, cancelable:true }));
    }, true);
  }

  table.querySelectorAll('thead th').forEach(th => {
    // Remove any existing handles
    const existing = th.querySelector('.col-resize-handle');
    if (existing) existing.remove();

    const handle = document.createElement('div');
    handle.className = 'col-resize-handle';
    th.appendChild(handle);

    let startX, startW;
    handle.addEventListener('pointerdown', e => {
      startX = e.pageX;
      startW = th.offsetWidth;
      handle.classList.add('dragging');
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';

      const onMove = e2 => {
        const newW = Math.max(40, startW + (e2.pageX - startX));
        th.style.width = newW + 'px';
        th.style.minWidth = newW + 'px';
      };
      const onUp = () => {
        handle.classList.remove('dragging');
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('pointermove', onMove);
        document.removeEventListener('pointerup', onUp);
        // Persist the final width — without this, any later re-render
        // (adding a row, switching tabs, etc.) rebuilds <th> elements
        // fresh from their default widths and silently discards the
        // resize, since it only ever existed as an inline DOM style.
        if (onResize) {
          const key = th.dataset.colKey;
          if (key) onResize(key, th.offsetWidth);
        }
      };
      document.addEventListener('pointermove', onMove);
      document.addEventListener('pointerup', onUp);
      e.preventDefault();
    });
  });
}

// Row height resize via drag on row bottom border
function initRowResize(onlyRows) {
  const table = document.querySelector('#ledgerTable, #journalTable');
  if (!table) return;
  (onlyRows || table.querySelectorAll('tbody tr')).forEach(tr => {
    if (tr.querySelector('.row-resize-h')) return;
    const host = tr.firstElementChild; if (!host) return;   // lives inside the first cell: a stray <div> directly in a <tr> becomes a hidden extra column that stops the table filling its width
    host.style.position = 'relative';
    const handle = document.createElement('div');
    handle.className = 'row-resize-h';
    handle.style.cssText = 'position:absolute;bottom:0;left:0;right:0;height:3px;cursor:row-resize;z-index:10;';
    handle.addEventListener('pointerdown', e => {
      const startY = e.pageY;
      const startH = tr.offsetHeight;
      document.body.style.cursor = 'row-resize';
      const onMove = e2 => {
        const newH = Math.max(24, startH + (e2.pageY - startY));
        tr.style.height = newH + 'px';
        tr.querySelectorAll('.bk-cell').forEach(c => c.style.height = newH + 'px');
      };
      const onUp = () => {
        document.body.style.cursor = '';
        document.removeEventListener('pointermove', onMove);
        document.removeEventListener('pointerup', onUp);
      };
      document.addEventListener('pointermove', onMove);
      document.addEventListener('pointerup', onUp);
      e.preventDefault();
    });
    host.appendChild(handle);
  });
}

// ── QUICK INPUT WIDGET ────────────────────────────────────────
let qiState   = {}; // current quick input state
let qiProducts = []; // loaded user products

