async function openQuickInput() {
  qiState = { step:'type', txnType:null, product:null, qty:1, amount:0, payment:'cash', customerName:'' };

  // Load user products
  const { data } = await (activeBusiness?.id
      ? bkDb.from('bk_products').select('*').or('business_id.eq.'+activeBusiness.id+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
      : (activeBusiness?.id
      ? bkDb.from('bk_products').select('*').or('business_id.eq.'+activeBusiness.id+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
      : bkDb.from('bk_products').select('*').eq('user_id', bkUser.id))).eq('is_active', true).order('product_name');
  qiProducts = data || [];

  document.getElementById('qiOverlay').classList.remove('hidden');
  renderQI();
}

function closeQuickInput() {
  document.getElementById('qiOverlay').classList.add('hidden');
  qiState = {};
}

