function renderQITotal() {
  const el = document.getElementById('qiTotal');
  if (el) {
    const sym   = CURRENCIES[activeCurrency].symbol;
    const total = (parseFloat(qiState.qty)||1) * (parseFloat(qiState.amount)||0);
    el.textContent = sym + total.toLocaleString();
  }
}

function qiSetType(type) {
  qiState.txnType = type;
  if (type === 'expense') {
    qiState.step = 'expense';
    qiState.payment = 'cash';
  } else if (type === 'other') {
    qiState.step = 'product';
  } else {
    qiState.step = 'product';
  }
  renderQI();
}

function qiSelectByIndex(el) {
  const idx = parseInt(el.dataset.qi);
  const prods = window._qiFilteredProds || [];
  if (prods[idx]) qiSelectProduct(prods[idx]);
}

function qiSelectProduct(product) {
  qiState.product = product;
  qiState.amount  = product.p || 0;
  qiState.qty     = 1;
  qiState.step    = 'details';
  renderQI();
}

// Determine accounts automatically based on transaction type
function getQuickAccounts(txnType, payment) {
  const creditSide = payment === 'credit' ? 'Trade Debtors' : 'Cash at Bank';
  const creditType = payment === 'credit' ? 'asset'         : 'asset';

  if (txnType === 'sale') {
    return {
      debitAccount:  creditSide,
      debitType:     creditType,
      creditAccount: 'Sales Revenue',
      creditType:    'income',
    };
  }
  if (txnType === 'service') {
    return {
      debitAccount:  creditSide,
      debitType:     creditType,
      creditAccount: 'Service Income',
      creditType:    'income',
    };
  }
  if (txnType === 'other') {
    return {
      debitAccount:  'Cash at Bank',
      debitType:     'asset',
      creditAccount: 'Share Capital',
      creditType:    'capital',
    };
  }
  return { debitAccount:'Cash at Bank', debitType:'asset', creditAccount:'Sales Revenue', creditType:'income' };
}

async function recordQuickInput() {
  const qty    = parseFloat(qiState.qty)||1;
  const amount = parseFloat(qiState.amount)||0;
  const total  = qty * amount;
  if (!total) { alert('Please enter an amount.'); return; }

  const accounts = getQuickAccounts(qiState.txnType, qiState.payment);
  const narration = [
    qiState.txnType==='sale'?`Sale of ${qiState.product?.n}`:`${qiState.product?.n||'Service'} income`,
    qty>1?`x ${qty} units`:'',
    qiState.customerName?`— ${qiState.customerName}`:'',
    qiState.note?`(${qiState.note})`:'',
  ].filter(Boolean).join(' ');

  await postJournalEntry({
    debitAccount:  accounts.debitAccount,
    debitType:     accounts.debitType,
    creditAccount: accounts.creditAccount,
    creditType:    accounts.creditType,
    amount: total,
    narration,
    payee:  qiState.customerName || null,
    payer:  null,
  });

  qiState.successMsg = `<strong>${narration}</strong><br>
    Dr ${accounts.debitAccount} ${fmt(total)}<br>
    Cr ${accounts.creditAccount} ${fmt(total)}<br>
    <span style="color:var(--gold);">Payment: ${qiState.payment}</span>`;
  qiState.step = 'success';
  renderQI();
  await refreshEquation();
}

async function recordExpense() {
  const amount = parseFloat(qiState.amount)||0;
  if (!amount) { alert('Please enter an amount.'); return; }
  if (!qiState.expenseAccount) { alert('Please select an expense category.'); return; }

  const creditAccount = qiState.payment === 'credit' ? 'Trade Creditors' : 'Cash at Bank';
  const creditType    = qiState.payment === 'credit' ? 'liability'        : 'asset';
  const narration = [
    qiState.expenseAccount,
    qiState.payee?`— ${qiState.payee}`:'',
    qiState.note?`(${qiState.note})`:'',
  ].filter(Boolean).join(' ');

  await postJournalEntry({
    debitAccount:  qiState.expenseAccount,
    debitType:     'expenditure',
    creditAccount,
    creditType,
    amount,
    narration,
    payee:  qiState.payee || null,
    payer:  null,
  });

  qiState.successMsg = `<strong>${narration}</strong><br>
    Dr ${qiState.expenseAccount} ${fmt(amount)}<br>
    Cr ${creditAccount} ${fmt(amount)}`;
  qiState.step = 'success';
  renderQI();
  await refreshEquation();
}

async function postJournalEntry({ debitAccount, debitType, creditAccount, creditType, amount, narration, payee, payer }) {
  const today = new Date().toISOString().slice(0,10);
  const { data: journalEntry } = await bkDb.from('bk_journal').insert({
    user_id:             bkUser.id,
    business_id:         activeBusiness?.id||null,
    txn_date:            today,
    payee:               payee || null,
    payer:               payer || null,
    narration,
    debit_account_name:  debitAccount,
    debit_record_type:   debitType,
    credit_account_name: creditAccount,
    credit_record_type:  creditType,
    debit_amount:        amount,
    credit_amount:       amount,
    serial_number:       1,
    row_order:           0,
  }).select().single();

  if (journalEntry) {
    await postToLedgers(journalEntry.id, {
      txn_date:            today,
      payee:               payee || null,
      payer:               payer || null,
      narration,
      debit_account_name:  debitAccount,
      debit_record_type:   debitType,
      credit_account_name: creditAccount,
      credit_record_type:  creditType,
      debit_amount:        amount,
      credit_amount:       amount,
      row_order:           0,
    });
  }
}

// ── TOOLBAR TOGGLE ────────────────────────────────────────────
let toolbarOpen = true;
function toggleToolbar() {
  toolbarOpen = !toolbarOpen;
  const tb  = document.getElementById('bkToolbar');
  const btn = document.getElementById('tbCollapseBtn');
  if (tb)  tb.classList.toggle('collapsed', !toolbarOpen);
  if (btn) btn.textContent = toolbarOpen ? '▾' : '▸';
}

function changeDecimals(dir) {
  decimalPlaces = Math.max(0, Math.min(6, decimalPlaces + dir));
  // Re-render current view to apply new decimal setting everywhere
  if (activeAccount) {
    recalcBalances(); renderRows();
  } else if (document.getElementById('journalTable')) {
    renderJournalRows();
  } else {
    refreshEquation(); // update the equation bar values
  }
}

// Override fmt to use decimalPlaces
// fmt() defined at top of script

// ── DATE FORMAT ───────────────────────────────────────────────
let dateFormat = 'month_day_year'; // default: Month-Day-Year e.g. Jun/30th/2026

function setDateFormat(fmt) {
  dateFormat = fmt;
  if (activeAccount) renderRows();
  else if (document.getElementById('journalTable')) renderJournalRows();
}

function formatDateDisplay(isoDate) {
  if (!isoDate) return '';
  const d = new Date(isoDate+'T00:00:00');
  if (isNaN(d)) return isoDate;
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const day = d.getDate();
  const suf = (day%10===1&&day!==11)?'st':(day%10===2&&day!==12)?'nd':(day%10===3&&day!==13)?'rd':'th';
  const fmtPref = localStorage.getItem('bd_jrn_datefmt')||'mdy';
  if (fmtPref==='dm') return day+suf+'/'+months[d.getMonth()];
  if (fmtPref==='md') return months[d.getMonth()]+'/'+day+suf;
  return fmtPref==='dmy'
    ? day+suf+'/'+months[d.getMonth()]+'/'+d.getFullYear()
    : months[d.getMonth()]+'/'+day+suf+'/'+d.getFullYear();
}


// ── SAVE INDIVIDUAL LEDGER ROW ────────────────────────────────
async function saveRow(idx) {
  if (!activeAccount || !bkUser) return;
  const r = rows[idx];
  if (!hasData(r)) return;

  recalcBalances();

  if (!navigator.onLine && !r.id) {
    // Offline and this is a brand-new row: queue it, mark it locally as saved
    // so the UI doesn't keep nagging, and sync automatically on reconnect.
    await bdQueueOp('ledger_row', { insertPayload: {
      user_id: bkUser.id, business_id: activeBusiness?.id||null, record_type: activeType,
      account_name: activeAccount.account_name,
      serial_number: r.serial_number, txn_date: r.txn_date||null,
      payee: r.payee||null, payer: r.payer||null, narration: r.narration||null,
      debit: r.debit||0, credit: r.credit||0, balance: r.balance||0,
      row_order: idx,
    }});
    rows[idx].saved = true;
    setSaveMsg('✓ Saved offline — will sync when back online','ok');
    bdUpdateSyncBadge();
    return;
  }

  if (!r.id) {
    const { data, error } = await bkDb.from('bk_transactions').insert({
      user_id: bkUser.id, business_id: activeBusiness?.id||null, record_type: activeType,
      account_name: activeAccount.account_name,
      serial_number: r.serial_number, txn_date: r.txn_date||null,
      payee: r.payee||null, payer: r.payer||null, narration: r.narration||null,
      debit: r.debit||0, credit: r.credit||0, balance: r.balance||0,
      row_order: idx,
    }).select().single();
    if (!error && data) { rows[idx].id = data.id; rows[idx].saved = true; }
    if (error) { setSaveMsg('Error: '+error.message,'err'); return; }
  } else {
    const { error } = await bkDb.from('bk_transactions').update({
      account_name: activeAccount.account_name,
      serial_number: r.serial_number, txn_date: r.txn_date||null,
      payee: r.payee||null, payer: r.payer||null, narration: r.narration||null,
      debit: r.debit||0, credit: r.credit||0, balance: r.balance||0,
      row_order: idx, updated_at: new Date().toISOString(),
    }).eq('id', r.id).eq('user_id', bkUser.id);
    if (error) { setSaveMsg('Error: '+error.message,'err'); return; }
  }

  rows[idx].saved = true;
  setSaveMsg('✓ Row saved','ok');
  await refreshEquation();
  bdRefreshDashboardIfVisible();
  // Flash the save button green
  const btn = document.querySelector(`#row_${idx} .save-row-btn`);
  if (btn) {
    btn.textContent = '✓';
    btn.style.color = 'var(--green)';
    setTimeout(()=>{ btn.textContent='›'; btn.style.color=''; }, 1500);
  }
}

// ── SAVE INDIVIDUAL JOURNAL ROW ───────────────────────────────
// Row-level save goes through the same lock as saveJournal(), so the › button
// can never race the autosave and insert the same row twice. The row is
// captured NOW (its index can shift while waiting for the lock).
function saveJournalRow(i) {
  const rowRef = journalRows[i];
  return jrnWithLock(() => _saveJournalRowImpl(rowRef));
}
async function _saveJournalRowImpl(rowRef) {
  const i = journalRows.indexOf(rowRef);
  if (i < 0) return;
  const row = journalRows[i];
  if (!journalHasData(row)) return;

  const msg = document.getElementById('journalSaveMsg');

  // Validate
  if (Math.abs((parseFloat(row.debit_amount)||0) - (parseFloat(row.credit_amount)||0)) > 0.005) {
    if (msg) { msg.textContent=`⚠ Row ${i+1}: Dr ≠ Cr`; msg.className='bk-save-msg err'; }
    throw new Error('Debit and credit must be equal on this row');
  }
  if (!row.debit_account_name || !row.credit_account_name) {
    if (msg) { msg.textContent='Select both debit and credit accounts'; msg.className='bk-save-msg err'; }
    throw new Error('Select both a debit and a credit account');
  }

  if (!navigator.onLine && !row.id) {
    const legs = [];
    const base = { user_id: bkUser.id, business_id: activeBusiness?.id||null, txn_date: row.txn_date||null, narration: row.narration||null, balance:0 };
    const drS = row._drSplits && row._drSplits.length ? row._drSplits : null;
    const crS = row._crSplits && row._crSplits.length ? row._crSplits : null;
    if (drS) drS.forEach(s=>legs.push({...base, record_type:s.record_type, account_name:s.account_name, narration:s.narration||'', payee:s.payee||base.payee, debit:s.amount, credit:0}));
    else if (row.debit_account_name && row.debit_record_type && row.debit_amount>0)
      legs.push({...base, record_type: row.debit_record_type, account_name: row.debit_account_name, debit: row.debit_amount, credit: 0});
    if (crS) crS.forEach(s=>legs.push({...base, record_type:s.record_type, account_name:s.account_name, narration:s.narration||'', debit:0, credit:s.amount}));
    else if (row.credit_account_name && row.credit_record_type && row.credit_amount>0)
      legs.push({...base, record_type: row.credit_record_type, account_name: row.credit_account_name, debit: 0, credit: row.credit_amount});
    await bdQueueOp('journal_row', {
      journalPayload: {
        user_id: bkUser.id, business_id: activeBusiness?.id||null, txn_date: row.txn_date||null,
        payee: row.payee||null, payer: row.payer||null, narration: row.narration||null,
        debit_account_name: row.debit_account_name, debit_record_type: row.debit_record_type,
        credit_account_name: row.credit_account_name, credit_record_type: row.credit_record_type,
        debit_amount: row.debit_amount, credit_amount: row.credit_amount, payment_method: row.payment_method||null,
        serial_number: i+1, row_order: i,
      },
      legs,
    });
    journalRows[i].saved = true;
    if (msg) { msg.textContent='✓ Saved offline — will sync when back online'; msg.className='bk-save-msg ok'; }
    bdUpdateSyncBadge();
    return;
  }
  if (!row.id) {
    const { data, error } = await bkDb.from('bk_journal').insert({
      user_id: bkUser.id, business_id: activeBusiness?.id||null, txn_date: row.txn_date||null,
      payee: row.payee||null, payer: row.payer||null, narration: row.narration||null,
      debit_account_name: row.debit_account_name, debit_record_type: row.debit_record_type,
      credit_account_name: row.credit_account_name, credit_record_type: row.credit_record_type,
      debit_amount: row.debit_amount, credit_amount: row.credit_amount, payment_method: row.payment_method||null,
      serial_number: i+1, row_order: i,
    }).select().single();

    if (error) {
      if (msg) { msg.textContent='Error: '+error.message; msg.className='bk-save-msg err'; }
      throw error;
    }
    journalRows[i].id = data.id;
    // Same auto-creation saveJournal() gives new rows saved from the Sheet
    // "Save & Post" button — a row saved one-at-a-time (Sheet "›" button,
    // Card "Save & Post") should get a Receipt Voucher too, not just a
    // batch save.
    try { await jrnAutoCreateSourceDocs([journalRows[i]]); } catch(e) { console.error('jrnAutoCreateSourceDocs failed', e); }
    await postToLedgers(data.id, row);
  } else {
    // Scoped by business (acctBizFilter), not by "user_id = whoever is
    // logged in right now" — same fix as bdCascadeDeleteJournalEntry's
    // delete path, and for the same reason: a journal entry belongs to
    // the BUSINESS, so any of that business's staff should be able to
    // edit an entry a colleague created. The old `.eq('user_id',
    // bkUser.id)` filter matched zero rows when Staff B edited Staff
    // A's entry — update() silently no-ops on zero matches, so the
    // edit looked saved (journalRows[i].saved = true below) but never
    // reached the database and was lost on reload.
    const { error: updErr } = await acctBizFilter(bkDb.from('bk_journal').update({
      txn_date: row.txn_date||null, payee: row.payee||null, payer: row.payer||null,
      narration: row.narration||null, debit_account_name: row.debit_account_name,
      debit_record_type: row.debit_record_type, credit_account_name: row.credit_account_name,
      credit_record_type: row.credit_record_type, debit_amount: row.debit_amount,
      credit_amount: row.credit_amount, payment_method: row.payment_method||null, updated_at: new Date().toISOString(),
    }).eq('id', row.id));
    if (updErr) {
      if (msg) { msg.textContent='Error: '+updErr.message; msg.className='bk-save-msg err'; }
      throw updErr;
    }
    await bkDb.from('bk_transactions').delete().eq('journal_id', row.id);
    await postToLedgers(row.id, row);
  }

  journalRows[i].saved = true;
  journalRows[i]._saveErr = null;
  journalRows[i]._sig = jrnRowSig(journalRows[i]);
  await refreshEquation();
  bdRefreshDashboardIfVisible();
  if (msg) { msg.textContent='✓ Posted'; msg.className='bk-save-msg ok'; }
}

