// ── DATE FILTER (Journal) ─────────────────────────────────────
let jDateFrom = '', jDateTo = '';

function toggleJDateFilter(e) {
  e.stopPropagation();
  let popup = document.getElementById('jDateFilterPopup');
  if (popup) { popup.remove(); return; }
  const btn = e.currentTarget;
  const th  = btn.closest('th');
  if (!th) return;
  th.style.position = 'relative';
  popup = document.createElement('div');
  popup.id = 'jDateFilterPopup';
  popup.className = 'jdate-filter-popup';
  popup.innerHTML = `
    <div style="font-size:0.72rem;font-weight:700;color:var(--gold);margin-bottom:12px;">Filter by Date</div>
    <label>Single date</label>
    <input type="date" id="jdf_single" value="${jDateFrom===jDateTo?jDateFrom:''}"
      onchange="jApplyDateFilter(this.value,this.value)"/>
    <label>Date range — From</label>
    <input type="date" id="jdf_from" value="${jDateFrom}"
      onchange="jDateFrom=this.value"/>
    <label>Date range — To</label>
    <input type="date" id="jdf_to" value="${jDateTo}"
      onchange="jDateTo=this.value"/>
    <div class="jdate-filter-row">
      <button class="bk-btn bk-btn-gold" style="flex:1;font-size:0.76rem;"
        onclick="jApplyDateFilter(jDateFrom,jDateTo)">Apply Filter</button>
      <button class="bk-btn bk-btn-outline" style="font-size:0.76rem;"
        onclick="jClearDateFilter()">Clear</button>
    </div>
    <div style="padding:16px;"><button class="pf-save-btn" style="max-width:340px;" onclick="bdToast('\u2713 Settings saved')">Save Settings</button></div>`;
  th.appendChild(popup);
  // Close on outside click
  setTimeout(function(){
    document.addEventListener('click', function jClose(ev){
      if (!ev.target.closest('#jDateFilterPopup') && !ev.target.closest('.jdate-filter-btn')) {
        popup.remove(); document.removeEventListener('click', jClose);
      }
    });
  }, 10);
}

function jApplyDateFilter(from, to) {
  jDateFrom = from || '';
  jDateTo   = to   || '';
  document.getElementById('jDateFilterPopup')?.remove();
  renderJournalRows();
  // Show filter active indicator on the Date header
  const btn = document.querySelector('.jdate-filter-btn');
  if (btn) btn.style.opacity = (from||to) ? '1' : '0.6';
}

function jClearDateFilter() {
  jDateFrom = ''; jDateTo = '';
  jApplyDateFilter('','');
}

// ── FILL HANDLE (Journal cells) ──────────────────────────────
// Allows dragging from bottom-right corner of a cell to copy its
// value into adjacent cells in the same column — like Google Sheets.
let jFillSrcRow = null, jFillSrcField = null, jFillSrcVal = null;
let jFillDragging = false;

function jCellFocus(el, rowIdx, field) {
  // Remove any existing fill handle
  document.querySelectorAll('.jfill-handle').forEach(h => h.remove());
  document.querySelectorAll('.jcell-selected').forEach(c => c.classList.remove('jcell-selected'));

  const cell = el.closest('td');
  if (!cell) return;
  cell.classList.add('jcell-selected');
  cell.style.position = 'relative';

  const handle = document.createElement('div');
  handle.className = 'jfill-handle';
  handle.title = 'Drag to copy value to adjacent cells';
  handle.onmousedown = function(e) {
    e.preventDefault();
    jFillSrcRow   = rowIdx;
    jFillSrcField = field;
    jFillSrcVal   = el.value || el.textContent;
    jFillDragging = true;
    document.body.style.userSelect = 'none';
    document.onmousemove = jFillDragMove;
    document.onmouseup  = jFillDragEnd;
  };
  cell.appendChild(handle);
}

function jFillDragMove(e) {
  if (!jFillDragging) return;
  // Highlight cells being dragged over
  const target = document.elementFromPoint(e.clientX, e.clientY);
  if (!target) return;
  const td = target.closest('td');
  if (!td) return;
  const tr = td.closest('tr[id^="jrow_"]');
  if (!tr) return;
  const tgtRowIdx = parseInt(tr.id.replace('jrow_',''));
  if (isNaN(tgtRowIdx) || tgtRowIdx === jFillSrcRow) return;
  // Highlight target cell
  document.querySelectorAll('.jcell-fill-target').forEach(c => c.classList.remove('jcell-fill-target'));
  const min = Math.min(jFillSrcRow, tgtRowIdx);
  const max = Math.max(jFillSrcRow, tgtRowIdx);
  for (let i = min; i <= max; i++) {
    const targetRow = document.getElementById('jrow_'+i);
    if (targetRow) {
      const inputs = targetRow.querySelectorAll('input, select');
      inputs.forEach(function(inp){
        if (inp.id && inp.id.startsWith('jnarr_')) targetRow.cells[3]?.classList.add('jcell-fill-target');
      });
    }
  }
}

function jFillDragEnd(e) {
  if (!jFillDragging) return;
  jFillDragging = false;
  document.body.style.userSelect = '';
  document.onmousemove = null;
  document.onmouseup  = null;
  document.querySelectorAll('.jcell-fill-target').forEach(c => c.classList.remove('jcell-fill-target'));

  const target = document.elementFromPoint(e.clientX, e.clientY);
  if (!target) return;
  const tr = target.closest('tr[id^="jrow_"]');
  if (!tr) return;
  const tgtRowIdx = parseInt(tr.id.replace('jrow_',''));
  if (isNaN(tgtRowIdx) || tgtRowIdx === jFillSrcRow) return;

  const min = Math.min(jFillSrcRow, tgtRowIdx);
  const max = Math.max(jFillSrcRow, tgtRowIdx);
  for (let i = min; i <= max; i++) {
    if (i === jFillSrcRow) continue;
    // Ensure row exists in journalRows
    while (journalRows.length <= i) journalRows.push(emptyJournalRow(journalRows.length));
    if (jFillSrcField && jFillSrcVal !== null) {
      journalRows[i][jFillSrcField] = jFillSrcVal;
      journalRows[i].saved = false;
    }
  }
  renderJournalRows();
}

