// ── EQUATION ERROR EXPLAINER ──────────────────────────────────
async function explainEquationError(diff) {
  // Remove any existing modal
  document.getElementById('eqErrorModal')?.remove();

  const modal = document.createElement('div');
  modal.id = 'eqErrorModal';
  modal.className = 'col-help-tooltip';
  modal.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:900;max-width:400px;width:90%;';
  modal.innerHTML = `
    <div class="col-help-title">⚠ Accounting Equation Imbalance</div>
    <div class="col-help-text" id="eqErrText">✨ AI is analysing your books…</div>
    <div class="col-help-actions" style="margin-top:12px;">
      <button class="col-help-close" onclick="document.getElementById('eqErrorModal')?.remove()">Close</button>
    </div>`;
  document.body.appendChild(modal);

  // Overlay
  const overlay = document.createElement('div');
  overlay.id = 'eqErrorOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:899;';
  overlay.onclick = () => { modal.remove(); overlay.remove(); };
  document.body.insertBefore(overlay, modal);

  try {
    const { data: { session } } = await bkDb.auth.getSession();
    const res = await fetch(`${SUPABASE_URL}/functions/v1/ai-chat`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
      },
      body: JSON.stringify({
        messages: [{ role: 'user', content:
          `In my bookkeeping software, the accounting equation (Capital + Liabilities = Assets) shows a difference of ${fmt(diff)}. This means my books are not balanced. Please explain in simple terms what this means and give me 3 specific steps to find and fix the problem. Be concise and beginner-friendly.`
        }],
        system: 'You are a bookkeeping tutor. Give clear, practical advice for beginners. Keep response under 200 words.',
      }),
    });
    const json = await res.json();
    const answer = json.reply || json.content || 'Could not get explanation. Please check your entries.';
    const el = document.getElementById('eqErrText');
    if (el) el.textContent = answer;
  } catch(e) {
    const el = document.getElementById('eqErrText');
    if (el) el.textContent = 'Could not connect to AI. The imbalance means one side of a transaction was recorded without the other. Check your Master Records for entries where the debit and credit amounts do not match.';
  }
}

// ── DRAGGABLE ROWS ────────────────────────────────────────────
let draggedRowIdx = null;

function initDragRows() {
  const tbody = document.getElementById('ledgerBody');
  if (!tbody) return;
  tbody.querySelectorAll('tr[draggable]').forEach(tr => {
    tr.addEventListener('dragstart', e => {
      draggedRowIdx = parseInt(tr.id.replace('row_',''));
      tr.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    tr.addEventListener('dragend', () => {
      tr.classList.remove('dragging');
      document.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
    });
    tr.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      document.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
      tr.classList.add('drag-over');
    });
    tr.addEventListener('dragleave', () => tr.classList.remove('drag-over'));
    tr.addEventListener('drop', e => {
      e.preventDefault();
      tr.classList.remove('drag-over');
      const targetIdx = parseInt(tr.id.replace('row_',''));
      if (draggedRowIdx === null || draggedRowIdx === targetIdx) return;
      const moved = rows.splice(draggedRowIdx, 1)[0];
      rows.splice(targetIdx, 0, moved);
      recalcBalances();
      renderRows();
      draggedRowIdx = null;
    });
  });
}

