// ── Main account (Capital/Liability/Asset/Income/Expenditure)
//    codes — overridable, and changing one cascades the shift down
//    to every main sub-ledger and account currently numbered under it.
function _coaMainCodes() { try { return JSON.parse(localStorage.getItem('bd_coa_main_codes')||'{}'); } catch(e){ return {}; } }
function coaMainCode(type) {
  const o = _coaMainCodes();
  return (o[type]!==undefined && o[type]!==null && o[type]!=='') ? parseInt(o[type]) : COA_BASES[type];
}
function coaSetMainCode(type, newCodeStr) {
  const newCode = parseInt(newCodeStr);
  if (isNaN(newCode)) return;
  const oldCode = coaMainCode(type);
  if (newCode === oldCode) return;
  const delta = newCode - oldCode;
  const lo = oldCode, hi = oldCode + 999;

  // Shift every account code and every group code currently numbered
  // within this main account's old range, by the same delta.
  const codes = _coaCodes();
  Object.keys(codes).forEach(id=>{
    const n = parseFloat(codes[id]);
    if (!isNaN(n) && n>=lo && n<=hi) codes[id] = String(n+delta);
  });
  localStorage.setItem('bd_coa_codes', JSON.stringify(codes));

  const gcodes = _coaGroupCodes();
  Object.keys(gcodes).forEach(title=>{
    const n = parseFloat(gcodes[title]);
    if (!isNaN(n) && n>=lo && n<=hi) gcodes[title] = String(n+delta);
  });
  localStorage.setItem('bd_coa_group_codes', JSON.stringify(gcodes));

  const o = _coaMainCodes();
  o[type] = newCode;
  localStorage.setItem('bd_coa_main_codes', JSON.stringify(o));
}

