    + '<div style="font-size:1.3rem;font-weight:800;margin:8px 0;color:var(--gold);">' + fmt(n.bal) + ' <span class="coa-tp-sm">' + (drNormal ? 'Dr normal' : 'Cr normal') + '</span></div>';
