// Match whatever was typed to the closest industry above. Returns { label, exact }.
function coaTplMatch(text) {
  const q = String(text || '').toLowerCase().trim();
  if (!q) return { label: 'General Business', exact: false };
  const exact = Object.keys(COA_TPL_DATA).find(k => k.toLowerCase() === q);
  if (exact) return { label: exact, exact: true };
  const words = q.split(/[^a-z0-9]+/).filter(w => w.length >= 3);
  let best = null, bestScore = 0;
  Object.keys(COA_TPL_DATA).forEach(k => {
    if (k === 'General Business') return;
    const kws = (COA_TPL_DATA[k].kw + ' ' + k.toLowerCase()).split(/[^a-z0-9-]+/).filter(Boolean);
    let sc = 0;
    words.forEach(w => { if (kws.indexOf(w) >= 0) sc += 3; else if (kws.some(x => x.length >= 4 && (x.indexOf(w) === 0 || w.indexOf(x) === 0))) sc += 2; else if (kws.some(x => x.length >= 5 && w.length >= 5 && (x.indexOf(w) >= 0 || w.indexOf(x) >= 0))) sc += 1; });
    if (q.length >= 4 && (k.toLowerCase().indexOf(q) >= 0)) sc += 4;
    if (sc > bestScore) { bestScore = sc; best = k; }
  });
  return best ? { label: best, exact: false } : { label: 'General Business', exact: false, none: true };
}
function coaTplBuild(label) {
  const m = coaTplMatch(label), t = COA_TPL_DATA[m.label];
  const seen = new Set(), out = [];
  const add = line => {
    const type = COA_TPL_TYPE_CODE[line[0]], ess = line[1] === '*', name = line.slice(2).trim();
    const k = name.toLowerCase(); if (!type || !name || seen.has(k)) return; seen.add(k);
    out.push({ name, record_type: type, essential: ess });
  };
  t.items.forEach(add);
  COA_TPL_CORE.forEach(add);
  return { matched: m.label, exact: m.exact, none: !!m.none, accounts: out };
}

let _coaTpl = null; // { step, search, cat, chosenLabel, accounts:[{name,record_type,essential,already,checked}] }

function coaOpenTemplatePicker() {
  _coaTpl = { step:1, search:'', cat:'All', chosenLabel:null };
  const overlay = document.createElement('div');
  overlay.id = 'coaTplOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px;overflow:auto;';
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
  _coaTplRender();
}

function _coaTplStepRow(active) {
  const steps = ['Pick a business type','Review & select accounts','Done'];
  return `<div style="display:flex;align-items:center;gap:8px;font-size:0.64rem;font-weight:700;color:var(--muted2);text-transform:uppercase;letter-spacing:0.06em;margin-bottom:16px;flex-wrap:wrap;">
    ${steps.map((s,i)=>{
      const n=i+1, done = n<active, cur = n===active;
      return `<span style="display:flex;align-items:center;gap:6px;">
        <span style="width:18px;height:18px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.6rem;flex-shrink:0;
          ${done?'background:var(--green,#3fb871);color:var(--accent-ink);':cur?'background:var(--gold);color:var(--accent-ink,#000);':'background:var(--surface2);border:1px solid var(--border2);color:var(--muted2);'}">${done?'✓':n}</span>
        <span style="${cur?'color:var(--white);':''}">${s}</span>
      </span>${i<steps.length-1?'<span style="width:22px;height:1px;background:var(--border2);"></span>':''}`;
    }).join('')}
  </div>`;
}

function _coaTplRender() {
  const overlay = document.getElementById('coaTplOverlay');
  if (!overlay || !_coaTpl) return;
  if (_coaTpl.step === 1) overlay.innerHTML = _coaTplPickerHtml();
  else if (_coaTpl.step === 2) overlay.innerHTML = _coaTplReviewHtml();
  setTimeout(()=>document.getElementById('coaTplSearch')?.focus(), 30);
}

function _coaTplPickerHtml() {
  const search = (_coaTpl.search||'').trim().toLowerCase();
  const list = COA_BIZ_TYPES.filter(b =>
    (_coaTpl.cat==='All' || b.cat===_coaTpl.cat) &&
    (!search || b.label.toLowerCase().includes(search) || b.desc.toLowerCase().includes(search)));
  const exactMatch = list.some(b => b.label.toLowerCase() === search);
  const customCard = (search && !exactMatch) ? `
    <div class="biz-card ${_coaTpl.chosenLabel==='__custom__'?'sel':''}" style="background:var(--surface);border:1.5px solid ${_coaTpl.chosenLabel==='__custom__'?'var(--gold)':'var(--border)'};border-radius:10px;padding:14px 16px;cursor:pointer;${_coaTpl.chosenLabel==='__custom__'?'background:var(--gold-dim,rgba(201,168,76,0.12));':''}"
      onclick="coaTplChoose('__custom__')">
      <div style="font-size:1.3rem;margin-bottom:6px;">✨</div>
      <div style="font-size:0.82rem;font-weight:700;color:var(--white);margin-bottom:3px;">Use "${escH(_coaTpl.search)}"</div>
      <div style="font-size:0.68rem;color:var(--muted);line-height:1.4;">Not on the list — we'll match it to the closest business type</div>
    </div>` : '';
  return `
    <div style="background:var(--bg);border:1px solid var(--border2);border-radius:14px;max-width:900px;width:100%;max-height:92vh;overflow:auto;" onclick="event.stopPropagation()">
      <div style="padding:16px 22px;border-bottom:1px solid var(--border);display:flex;align-items:flex-start;justify-content:space-between;">
        <div>
          <div style="font-size:1rem;font-weight:800;">Chart of Accounts · <span style="color:var(--gold);">Choose a Template</span></div>
          <div style="font-size:0.7rem;color:var(--muted);margin-top:2px;">Your 5 main accounts stay the same — a template just adds the sub-accounts typical for your kind of business</div>
        </div>
        <span style="color:var(--muted);font-size:1.1rem;cursor:pointer;" onclick="document.getElementById('coaTplOverlay').remove()">✕</span>
      </div>
      <div style="padding:18px 22px 22px;">
        ${_coaTplStepRow(1)}
        <div style="display:flex;align-items:center;gap:10px;background:var(--surface);border:1.5px solid var(--border2);border-radius:10px;padding:10px 14px;margin-bottom:14px;">
          <span style="color:var(--muted);">🔍</span>
          <input id="coaTplSearch" value="${escH(_coaTpl.search)}" placeholder="Search any business type — e.g. &ldquo;poultry farm&rdquo;, &ldquo;law firm&rdquo;, &ldquo;bakery&rdquo;, &ldquo;logistics&rdquo;…"
            style="flex:1;background:none;border:none;outline:none;color:var(--white);font-size:0.82rem;font-family:inherit;"
            oninput="_coaTpl.search=this.value;_coaTpl.chosenLabel=null;_coaTplRenderGridOnly();"/>
        </div>
        <div id="coaTplCats" style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;">
          ${COA_BIZ_CATS.map(c=>`<span style="font-size:0.68rem;font-weight:700;padding:5px 12px;border-radius:20px;cursor:pointer;
            ${c===_coaTpl.cat?'color:var(--gold);border:1px solid var(--gold);background:var(--gold-dim,rgba(201,168,76,0.12));':'color:var(--muted);background:var(--surface2);border:1px solid var(--border);'}"
            onclick="_coaTpl.cat='${c.replace(/'/g,"\\'")}';_coaTplRenderGridOnly();">${c}</span>`).join('')}
        </div>
        <div id="coaTplGrid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;">
          ${customCard}
          ${list.map(b=>`<div class="biz-card ${_coaTpl.chosenLabel===b.label?'sel':''}" style="background:var(--surface);border:1.5px solid ${_coaTpl.chosenLabel===b.label?'var(--gold)':'var(--border)'};border-radius:10px;padding:14px 16px;cursor:pointer;${_coaTpl.chosenLabel===b.label?'background:var(--gold-dim,rgba(201,168,76,0.12));':''}"
            onclick="coaTplChoose('${b.label.replace(/'/g,"\\'")}')">
            <div style="font-size:1.3rem;margin-bottom:6px;">${b.emoji}</div>
            <div style="font-size:0.82rem;font-weight:700;color:var(--white);margin-bottom:3px;">${escH(b.label)}</div>
            <div style="font-size:0.68rem;color:var(--muted);line-height:1.4;">${escH(b.desc)}</div>
          </div>`).join('')}
          ${(!list.length && !customCard) ? '<div style="grid-column:1/-1;text-align:center;color:var(--muted);font-size:0.78rem;padding:20px;">No matches — try a different search term.</div>' : ''}
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:22px;padding-top:16px;border-top:1px solid var(--border);">
          <span style="font-size:0.74rem;color:var(--muted);cursor:pointer;" onclick="document.getElementById('coaTplOverlay').remove()">Skip — I'll build my chart of accounts manually</span>
          <button id="coaTplNextBtn" class="coa-add-btn" style="padding:11px 24px;font-size:0.8rem;${_coaTpl.chosenLabel?'':'opacity:0.4;cursor:default;'}"
            onclick="${_coaTpl.chosenLabel?'coaTplPreview()':''}">Preview Template →</button>
        </div>
      </div>
    </div>`;
}

// Re-renders just the search/category-dependent parts without losing
// focus in the search input on every keystroke (same scroll/focus
// lesson learned on the journal upload review screen — re-rendering the
// whole overlay on oninput would steal the cursor and close the
// on-screen keyboard on mobile).
function _coaTplRenderGridOnly() {
  const grid = document.getElementById('coaTplGrid');
  const cats = document.getElementById('coaTplCats');
  const nextBtn = document.getElementById('coaTplNextBtn');
  if (!grid) return;
  const tmp = document.createElement('div');
  tmp.innerHTML = _coaTplPickerHtml();
  const freshGrid = tmp.querySelector('#coaTplGrid');
  const freshCats = tmp.querySelector('#coaTplCats');
  const freshBtn = tmp.querySelector('#coaTplNextBtn');
  if (freshGrid) grid.innerHTML = freshGrid.innerHTML;
  if (freshCats && cats) cats.innerHTML = freshCats.innerHTML;
  if (freshBtn && nextBtn) { nextBtn.outerHTML = freshBtn.outerHTML; }
}

function coaTplChoose(label) {
  _coaTpl.chosenLabel = label;
  _coaTplRenderGridOnly();
}

async function coaTplPreview() {
  const label = _coaTpl.chosenLabel === '__custom__' ? _coaTpl.search.trim() : _coaTpl.chosenLabel;
  if (!label) return;
  const built = coaTplBuild(label);
  const have = new Set();
  Object.keys(accounts||{}).forEach(t => (accounts[t]||[]).forEach(a => have.add((a.account_name||'').trim().toLowerCase())));
  _coaTpl.businessLabel = (_coaTpl.chosenLabel === '__custom__') ? built.matched : label;
  _coaTpl.matchNote = (_coaTpl.chosenLabel === '__custom__')
    ? (built.none ? '"' + label + '" didn\'t match a specific business type, so this is a general starter set. Tick only what fits, or go back and pick the closest type.'
                  : 'We matched "' + label + '" to ' + built.matched + '. Tick only what fits — you can always add more accounts yourself later.')
    : '';
  _coaTpl.accounts = built.accounts.map(a => {
    const already = have.has(a.name.trim().toLowerCase());
    return { name: a.name, record_type: a.record_type, essential: !!a.essential, already, checked: !already && !!a.essential };
  });
  _coaTpl.step = 2;
  _coaTplRender();
}

function coaTplBack() {
  _coaTpl.step = 1;
  _coaTplRender();
}

// Same two sub-ledger buckets per type the live Chart of Accounts page
// already groups by, purely for how this preview displays suggestions —
// the accounts themselves land in those same buckets automatically once
// created, via the same isFixedAsset()/isLongTermLiab()/isCOSAccount()
// pattern matching renderCOA() already uses.
function _coaTplGroupsFor(type) {
  const g = {
    asset: [['Current Assets', n=>!isFixedAsset(n)], ['Fixed Assets', n=>isFixedAsset(n)]],
    liability: [['Current Liabilities', n=>!isLongTermLiab(n)], ['Long-term Liabilities', n=>isLongTermLiab(n)]],
    expenditure: [['Cost of Sales', n=>isCOSAccount(n)], ['Operating Expenses', n=>!isCOSAccount(n)]],
    income: [['Operating Income', n=>!/other|interest|dividend|gain/i.test(n)], ['Other Income', n=>/other|interest|dividend|gain/i.test(n)]],
    capital: [['Capital & Equity', ()=>true]],
  };
  return g[type] || [['Accounts', ()=>true]];
}

function _coaTplReviewHtml() {
  const types = ['asset','liability','capital','expenditure','income'];
  const checkedCount = _coaTpl.accounts.filter(a=>a.checked && !a.already).length;
  const alreadyCount = _coaTpl.accounts.filter(a=>a.already).length;
  const sections = types.map(type => {
    const inType = _coaTpl.accounts.map((a,idx)=>({a,idx})).filter(o=>o.a.record_type===type);
    if (!inType.length) return '';
    const groups = _coaTplGroupsFor(type);
    const body = groups.map(([title,test])=>{
      const items = inType.filter(o=>test(o.a.name));
      if (!items.length) return '';
      return `<div style="font-size:0.62rem;font-weight:800;color:var(--gold);text-transform:uppercase;letter-spacing:0.06em;padding:8px 16px 5px;background:var(--surface);">${escH(title)}</div>` +
        items.map(o=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 16px;border-top:1px solid var(--border);${o.a.already?'opacity:0.55;':'cursor:pointer;'}"
            ${o.a.already?'':`onclick="coaTplToggle(${o.idx})"`}>
          <span style="width:16px;height:16px;border-radius:4px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:0.58rem;
            ${o.a.already?'background:var(--surface2);border:1.5px solid var(--border);color:var(--muted2);':o.a.checked?'background:var(--gold);border:1.5px solid var(--gold);color:var(--accent-ink,#000);':'border:1.5px solid var(--border2);color:transparent;'}">✓</span>
          <span style="flex:1;font-size:0.78rem;color:${o.a.already?'var(--muted);':'var(--off);'}">${escH(o.a.name)}</span>
          ${o.a.already?'<span style="font-size:0.6rem;font-weight:700;color:var(--muted2);background:var(--surface2);padding:2px 8px;border-radius:10px;">already have</span>'
            :(o.a.essential?'<span style="font-size:0.6rem;font-weight:700;color:var(--green,#3fb871);background:rgba(63,184,113,0.14);padding:2px 8px;border-radius:10px;">new</span>':'<span style="font-size:0.6rem;font-weight:700;color:var(--muted2);background:var(--surface2);padding:2px 8px;border-radius:10px;">optional</span>')}
        </div>`).join('');
    }).join('');
    return `<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;overflow:hidden;margin-bottom:14px;">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:var(--surface2);border-bottom:1px solid var(--border);">
        <div style="font-size:0.78rem;font-weight:800;color:var(--white);">${COA_LABELS[type]}<span style="color:var(--gold);font-weight:700;margin-left:6px;">${coaMainCode(type)}</span></div>
        <div style="font-size:0.66rem;color:var(--muted2);">${inType.length} suggested</div>
      </div>
      ${body}
    </div>`;
  }).join('');
  return `
    <div style="background:var(--bg);border:1px solid var(--border2);border-radius:14px;max-width:1040px;width:100%;max-height:92vh;overflow:auto;" onclick="event.stopPropagation()">
      <div style="padding:16px 22px;border-bottom:1px solid var(--border);display:flex;align-items:flex-start;justify-content:space-between;">
        <div>
          <div style="font-size:1rem;font-weight:800;">Chart of Accounts · <span style="color:var(--gold);">Review Template</span></div>
          <div style="font-size:0.7rem;color:var(--muted);margin-top:2px;">${escH(_coaTpl.businessLabel)} — standard 5 main accounts plus IFRS sub-ledgers, pre-checked below</div>
        </div>
        <span style="color:var(--muted);font-size:1.1rem;cursor:pointer;" onclick="document.getElementById('coaTplOverlay').remove()">✕</span>
      </div>
      <div style="padding:18px 22px 22px;">
        ${_coaTplStepRow(2)}
        ${_coaTpl.matchNote ? `<div style="font-size:0.72rem;color:var(--off);background:var(--gold-t008);border:1px solid var(--gold-t03);border-radius:8px;padding:9px 12px;margin-bottom:12px;line-height:1.5;">${escH(_coaTpl.matchNote)}</div>` : ''}
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;">
          <span style="font-size:0.72rem;color:var(--muted);">Importing <b style="color:var(--gold);">${checkedCount}</b> of ${_coaTpl.accounts.length} suggested accounts${alreadyCount?` · ${alreadyCount} already exist in your books and will be reused, not duplicated`:''}</span>
          <span style="font-size:0.72rem;color:var(--gold);font-weight:700;cursor:pointer;" onclick="coaTplBack()">← Choose a different type</span>
        </div>
        <div style="columns:2 360px;column-gap:16px;">${sections}</div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding-top:16px;border-top:1px solid var(--border);">
          <span style="font-size:0.76rem;color:var(--muted);cursor:pointer;" onclick="coaTplBack()">← Back</span>
          <button class="coa-add-btn" style="padding:11px 24px;font-size:0.8rem;${checkedCount?'':'opacity:0.4;cursor:default;'}" onclick="${checkedCount?'coaTplImport()':''}">Add ${checkedCount} Account${checkedCount===1?'':'s'} to My Chart of Accounts →</button>
        </div>
      </div>
    </div>`;
}

// Scroll-preserving re-render for the review step — toggling a checkbox
// shouldn't jump the scroll position back to the top of a long list, the
// same lesson as the journal upload review screen.
function _coaTplReviewRerender() {
  const box = document.querySelector('#coaTplOverlay > div');
  const scrollTop = box ? box.scrollTop : 0;
  _coaTplRender();
  const newBox = document.querySelector('#coaTplOverlay > div');
  if (newBox) newBox.scrollTop = scrollTop;
}

function coaTplToggle(idx) {
  const a = _coaTpl.accounts[idx];
  if (!a || a.already) return;
  a.checked = !a.checked;
  _coaTplReviewRerender();
}

async function coaTplImport() {
  const toAdd = _coaTpl.accounts.filter(a => a.checked && !a.already);
  if (!toAdd.length || !bkUser) return;
  const overlay = document.getElementById('coaTplOverlay');
  if (overlay) overlay.innerHTML = `<div style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;padding:34px;text-align:center;color:var(--off);font-size:0.82rem;font-weight:700;" onclick="event.stopPropagation()">⏳ Adding ${toAdd.length} account${toAdd.length===1?'':'s'}…</div>`;
  try {
    const inserts = toAdd.map(a => ({
      user_id: bkUser.id, ...acctBizStamp(), record_type: a.record_type, account_name: a.name, opening_balance: 0, is_default: false,
    }));
    const { data, error } = await bkDb.from('bk_accounts').insert(inserts).select();
    if (error) throw error;
    (data||[]).forEach(row => {
      if (!accounts[row.record_type]) accounts[row.record_type] = [];
      accounts[row.record_type].push(row);
      if (_coaBalCache) _coaBalCache.byId[row.id] = 0;
      _coaTplMarkTagged(row.id);
    });
    buildDropdowns();
    document.getElementById('coaTplOverlay')?.remove();
    _coaTpl = null;
    coaActiveType = 'asset';
    renderCOA();
    bdToast(`✓ Added ${toAdd.length} account${toAdd.length===1?'':'s'} from the template`);
  } catch (e) {
    alert('Could not add the accounts: ' + (e.message||''));
    _coaTplRender();
  }
}

// ── ACCOUNT SETTINGS PAGE ─────────────────────────────────────
