  setActiveNav('');
  document.getElementById('recordsDD')?.classList.add('hidden');
  document.getElementById('bkContent').innerHTML='<div class="bk-loading">Loading…</div>';

  const [{ data:bkProf },{ data:settings }] = await Promise.all([
    bkDb.from('bk_business_profiles').select('*').eq('user_id',bkUser.id).maybeSingle(),
    bkDb.from('bk_settings').select('*').eq('user_id',bkUser.id).maybeSingle(),
  ]);

  // Load saved display preferences
