// Sales toolbox panel — choose up to 3 Products columns to show in
// the sale-narration dropdown, and which of those get written into
// the narration itself when a product is picked. Same portal pattern
// as the Products page's own Columns menu (position:fixed, appended
// to document.body, closes on outside click).
function toggleSalesSuggestSelector() {
  const existing = document.getElementById('salesSuggestSelectorPortal');
  if (existing) { existing.remove(); return; }
  const btn = document.querySelector('[onclick="toggleSalesSuggestSelector()"]');
  if (!btn) return;
  renderSalesSuggestSelectorPanel(btn.getBoundingClientRect());
}
function renderSalesSuggestSelectorPanel(rect) {
  document.getElementById('salesSuggestSelectorPortal')?.remove();
  const available = _salesAvailableProductCols();
  const atMax = salesSuggestCols.length >= 3;

  const showRows = available.map(c => {
    const checked = salesSuggestCols.includes(c.id);
    const disable = !checked && atMax;
    return `<div class="col-row"${disable?' style="opacity:0.4;"':''}>
      <label class="col-left" style="display:flex;align-items:center;gap:9px;font-size:0.78rem;">
        <input type="checkbox" ${checked?'checked':''} ${disable?'disabled':''} onchange="salesSuggestColToggle('${c.id}',this.checked)"/>
        <span>${escH(c.label)}</span>
      </label>
    </div>`;
  }).join('');

  const narrRows = salesSuggestCols.length ? salesSuggestCols.map(id => {
    const col = available.find(c=>c.id===id);
    const checked = salesNarrationCols.includes(id);
    return `<div class="col-row" style="display:flex;align-items:center;justify-content:space-between;">
      <span style="font-size:0.78rem;">${escH(col?col.label:id)}</span>
      <label style="display:flex;align-items:center;gap:6px;font-size:0.66rem;color:${checked?'var(--gold)':'var(--muted)'};font-weight:${checked?'700':'400'};cursor:pointer;">
        <input type="checkbox" ${checked?'checked':''} onchange="salesNarrationColToggle('${id}',this.checked)"/> include
      </label>
    </div>`;
  }).join('') : '<div style="font-size:0.7rem;color:var(--muted);padding:6px 2px;">Pick suggestion columns above first.</div>';

  const wrap = document.createElement('div');
  wrap.id = 'salesSuggestSelectorPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;';
  wrap.addEventListener('click', e => { if (e.target === wrap) wrap.remove(); });

  const panel = document.createElement('div');
  panel.className = 'ps-col-selector';
  panel.style.cssText = 'position:fixed;z-index:12001;top:'+(rect.bottom+6)+'px;left:'+Math.min(rect.left, window.innerWidth-300)+'px;width:280px;max-height:80vh;overflow-y:auto;';
  panel.addEventListener('click', e => e.stopPropagation());
  panel.innerHTML = `
    <div class="ps-col-selector-title">Suggestion columns</div>
    <div style="font-size:0.66rem;color:var(--muted);margin:-2px 0 8px;line-height:1.5;">Pick up to 3 columns from Products &amp; Services to show in the sales dropdown.</div>
    ${showRows}
    <div style="font-size:0.64rem;color:${atMax?'var(--gold)':'var(--muted)'};background:${atMax?'var(--gold-dim)':'transparent'};border-radius:6px;padding:6px 8px;margin-top:6px;">
      ${salesSuggestCols.length} of 3 selected${atMax?' — uncheck one to pick a different column.':''}
    </div>
    <div class="ps-col-selector-title" style="margin-top:16px;">Insert into the Product cell</div>
    <div style="font-size:0.66rem;color:var(--muted);margin:-2px 0 8px;line-height:1.5;">Of the columns above, choose which text fills the Product cell when a product is picked.</div>
    ${narrRows}
  `;
  wrap.appendChild(panel);
  document.body.appendChild(wrap);
}
function salesSuggestColToggle(colId, checked) {
  if (checked) {
    if (salesSuggestCols.length >= 3) return; // shouldn't happen — checkbox is disabled at the limit, but guard anyway
    salesSuggestCols.push(colId);
  } else {
    salesSuggestCols = salesSuggestCols.filter(c => c !== colId);
    salesNarrationCols = salesNarrationCols.filter(c => c !== colId); // a column no longer shown shouldn't stay picked for narration either
  }
  _saveSalesSuggestSettings();
  const btn = document.querySelector('[onclick="toggleSalesSuggestSelector()"]');
  if (btn) renderSalesSuggestSelectorPanel(btn.getBoundingClientRect());
}
function salesNarrationColToggle(colId, checked) {
  if (checked) { if (!salesNarrationCols.includes(colId)) salesNarrationCols.push(colId); }
  else salesNarrationCols = salesNarrationCols.filter(c => c !== colId);
  _saveSalesSuggestSettings();
  const btn = document.querySelector('[onclick="toggleSalesSuggestSelector()"]');
  if (btn) renderSalesSuggestSelectorPanel(btn.getBoundingClientRect());
}

function togglePsColSelector() {
  const existing = document.getElementById('psColSelectorPortal');
  if (existing) { existing.remove(); return; }

  const btn = document.getElementById('psColBtn');
  if (!btn) return;
  const rect = btn.getBoundingClientRect();

  renderColSelectorPanel(rect);
}
function renderColSelectorPanel(rect) {
  document.getElementById('psColSelectorPortal')?.remove();

  // Every column, built-in AND custom, in one list — previously this
  // only ever showed PS_COL_DEFS (built-in columns), so a custom
  // column someone had added was invisible here entirely and could
  // never be re-shown once hidden, or found at all if added elsewhere.
  const builtIn = PS_COL_DEFS[psType].filter(c => c.id !== 'name'); // name is always shown, never listed as optional
  const custom = _psCustomCols();
  const selectorRows = builtIn.map(c => ({ id: c.id, label: c.label, isCustom: false }))
    .concat(custom.map(c => ({ id: c.key, label: c.name, isCustom: true })))
    .map(c => {
      const checked = _psIsColVisible(c.id);
      return '<div class="ps-col-row">'
        + '<label class="ps-col-label">'
        + '<input type="checkbox" class="ps-col-check" data-col="'+c.id+'"'
        + (checked?' checked':'')
        + ' onchange="psColCheck(this.dataset.col,this.checked)"/>'
        + escH(c.label)
        + (c.isCustom ? ' <span style="color:var(--muted);font-size:0.62rem;">(custom)</span>' : '')
        + '</label></div>';
    }).join('');

  const wrap = document.createElement('div');
  wrap.id = 'psColSelectorPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;';
  wrap.addEventListener('click', e => { if (e.target === wrap) wrap.remove(); });

  const panel = document.createElement('div');
  panel.id = 'psColSelector';
  panel.className = 'ps-col-selector';
  panel.style.cssText = 'position:fixed;z-index:12001;top:'+(rect.bottom+6)+'px;left:'+Math.min(rect.left, window.innerWidth-286)+'px;';
  panel.addEventListener('click', e => e.stopPropagation());
  panel.innerHTML = '<div class="ps-col-selector-title">Show / hide columns</div>'
    + selectorRows
    + '<button onclick="psAddColumnFromSelector()" id="psAddColBtn"'
    + ' style="width:100%;margin-top:10px;background:transparent;color:var(--gold);border:1px dashed var(--gold);font-size:0.76rem;font-weight:700;padding:8px;border-radius:7px;cursor:pointer;">'
    + '+ Add New Column</button>'
    + '<div onclick="psResetDefaultColumns()" style="text-align:center;font-size:0.7rem;color:var(--muted);text-decoration:underline;cursor:pointer;margin-top:10px;">Reset to default columns</div>';

  wrap.appendChild(panel);
  document.body.appendChild(wrap);
}
// Every change here saves immediately (via _psSettingSet's own debounce
// further down) — there's no separate "Save & Close" step to remember,
// and no risk of losing a toggle by clicking away from the panel.
function psColCheck(colId, checked) {
  psSetColVisible(colId, checked);
  psRenderTable();
}
function psResetDefaultColumns() {
  const defHidden = (PS_COL_DEFS[psType]||[]).filter(c=>c.def===false).map(c=>c.id);
  const custom = _psCustomCols();
  _psPersistHiddenCustom(defHidden);
  _psSettingSet('colMin', {});
  if (psType === 'products') {
    const others = ['other1','other2'];
    others.forEach(k=>{ if (!custom.some(c=>c.key===k)) custom.push({name: k==='other1'?'Other Details 1':'Other Details 2', key:k}); });
    _psSetCustomCols(custom);
    const rest = custom.map(c=>c.key).filter(k=>!others.includes(k));
    _psPersistColOrder(['qty_date','name','product_type','other1','other2','barcode','cost_price','sell_price','qty','total_cost','total_sell','income_acct'].concat(rest));
  } else {
    _psPersistColOrder(null);
  }
  document.getElementById('psColSelectorPortal')?.remove();
  renderProductsPage();
  bdToast('Columns reset to the default layout');
}
// Adds a new custom column directly from the Columns menu, at the end
// of the column order, then keeps the menu open with the new column
// already checked and visible — so it can be immediately renamed via
// the usual column-header menu without hunting for it afterward.
function psAddColumnFromSelector() {
  const btn = document.getElementById('psColBtn');
  const rect = btn ? btn.getBoundingClientRect() : null;
  const newKey = 'c'+Date.now();
  const order = _psEffectiveColOrder();
  order.push(newKey);
  _psPersistColOrder(order);
  const cols = _psCustomCols();
  cols.push({name:'New Column', key:newKey});
  _psSetCustomCols(cols);
  renderProductsPage();
  if (rect) renderColSelectorPanel(rect); // reopen so the new column shows immediately, already visible
}


// ── Products page toolbox (mirrors the sales-record toolbox) ──
let psSheet = { open:false, search:'', decimals:null, font:'Nunito', wrap:'overflow', undo:[], redo:[] };
// ── SHARED, BUSINESS-SCOPED SHEET SETTINGS ─────────────────────
// Custom columns, column types, widths, alignment, Total formulas,
// renamed labels, hidden columns, column order and date format used
// to live only in this browser's localStorage — meaning switching
// between businesses showed the same formatting regardless of which
// business was active, and different devices/employees working on the
// same business saw completely different setups. These now live in
// the database, scoped to the active business (or the user, when no
// business is selected), so the same business looks the same
// everywhere.
let _psSheetSettings = {};
let _psSheetSettingsScope = null;

function _psSettingsScopeKey() {
  return (activeBusiness?.id || bkUser?.id || 'none') + '::' + psType;
}

// Must be awaited before rendering the Products/Services page — every
// getter below reads from the in-memory _psSheetSettings this loads.
async function psEnsureSheetSettingsLoaded() {
  const scopeKey = _psSettingsScopeKey();
  if (_psSheetSettingsScope === scopeKey) return;
  _psSheetSettingsScope = scopeKey; // set first, so concurrent calls don't double-load
  try {
    let q = bkDb.from('bk_sheet_settings').select('*').eq('sheet_key', psType);
    q = activeBusiness?.id ? q.eq('business_id', activeBusiness.id) : q.is('business_id', null).eq('user_id', bkUser.id);
    const { data } = await q.maybeSingle();
    if (data) {
      _psSheetSettings = data.settings || {};
    } else if (!localStorage.getItem('bd_ps_migrated_'+psType)) {
      // No row yet, and this browser has never migrated its old
      // localStorage-only settings for this sheet before. This can
      // only ever happen once per sheet, regardless of which business
      // happens to be active at that moment — the flag below prevents
      // it from ever firing again, so switching to (or creating) a
      // genuinely different business later always starts empty rather
      // than inheriting this same old data too.
      localStorage.setItem('bd_ps_migrated_'+psType, '1');
      const migrated = _psMigrateLegacyLocalStorage();
      _psSheetSettings = migrated;
      if (Object.keys(migrated).length) _psSaveSheetSettingsNow();
    } else {
      _psSheetSettings = {};
    }
  } catch(e) {
    _psSheetSettings = {};
  }
  // If a local backup still exists at this point, the database save
  // for it never actually completed (a successful save clears this
  // backup) — most likely the tab was closed or refreshed before the
  // network request could finish. Recover from it instead of silently
  // using the older, saved-but-now-outdated database version, and
  // immediately try to push it through again.
  try {
    const pending = localStorage.getItem('bd_ps_pending_'+scopeKey);
    if (pending) {
      _psSheetSettings = JSON.parse(pending);
      _psSaveSheetSettingsNow();
    }
  } catch(e) {}
  // Seed default-hidden built-in columns (e.g. Cost Price) the first
  // time this sheet's settings are ever loaded — without this, a
  // column meant to start hidden would incorrectly show for anyone
  // who hasn't explicitly touched the Columns menu yet, since an
  // empty hidden-list otherwise just means "nothing is hidden".
  let _psSeeded = false;
  if (_psSheetSettings.hiddenCustom === undefined) {
    const defaultHidden = (PS_COL_DEFS[psType]||[]).filter(c=>c.def===false).map(c=>c.id);
    _psSheetSettings.hiddenCustom = defaultHidden;
    _psSeeded = defaultHidden.length > 0;
  }
  // Default Products layout: S/N, Stock as at, Product, Product Type, Other Details 1, Other Details 2,
  // Selling Price, Quantity, Total in stock as at selling price. Only for a sheet nobody has set up yet.
  if (psType === 'products' && _psSheetSettings.customCols === undefined && _psSheetSettings.colOrder === undefined) {
    _psSheetSettings.customCols = [{name:'Other Details 1', key:'other1'}, {name:'Other Details 2', key:'other2'}];
    _psSeeded = true;
  }
  // The standard Products layout for everyone: S/N, Stock as at, Product, Unit price (selling price), Quantity,
  // Total (at selling price) — and Post to, which the books need. Applied once per business; every other column is
  // only hidden (never deleted), so it can be turned back on from the Columns menu.
  if (psType === 'products' && !_psSheetSettings.defaultsV2) {
    const show = ['qty_date','name','sell_price','qty','total_sell','income_acct'];
    const all = (PS_COL_DEFS.products || []).map(c => c.id).concat((_psSheetSettings.customCols || []).map(c => c.key).filter(Boolean));
    const rest = all.filter(k => !show.includes(k));
    _psSheetSettings.colOrder = show.concat(rest);
    _psSheetSettings.hiddenCustom = rest;
    _psSheetSettings.defaultsV2 = true;
    _psSeeded = true;
  }
  if (_psSeeded) _psSaveSheetSettingsNow();
}

function _psMigrateLegacyLocalStorage() {
  const map = {
    customCols: 'bd_ps_custom_'+psType,
    colMeta: 'bd_ps_colmeta_'+psType,
    colWidths: 'bd_ps_colwidths_'+psType,
    colAlign: 'bd_ps_colalign_'+psType,
    colOrder: 'bd_ps_colorder_'+psType,
    totalFormulas: 'bd_ps_totalformulas_'+psType,
    labels: 'bd_ps_labels_'+psType,
    hiddenCustom: 'bd_ps_hiddencustom_'+psType,
  };
  const s = {};
  Object.entries(map).forEach(([key, lsKey]) => {
    try { const v = JSON.parse(localStorage.getItem(lsKey)||'null'); if (v!=null) s[key]=v; } catch(e){}
  });
  try { const qdf = localStorage.getItem('bd_ps_qtydateformat_'+psType); if (qdf) s.qtyDateFormat = qdf; } catch(e){}
  return s;
}

let _psSaveDebounceTimer = null;
function _psSaveSheetSettingsNow() {
  clearTimeout(_psSaveDebounceTimer);
  _psSaveDebounceTimer = setTimeout(_psSaveSheetSettingsImmediate, 400);
}
async function _psSaveSheetSettingsImmediate() {
  if (!bkUser?.id) return;
  try {
    const payload = {
      sheet_key: psType,
      settings: _psSheetSettings,
      user_id: bkUser.id,
      business_id: activeBusiness?.id || null,
      updated_at: new Date().toISOString(),
    };
    const onConflict = activeBusiness?.id ? 'business_id,sheet_key' : 'user_id,sheet_key';
    const { error } = await bkDb.from('bk_sheet_settings').upsert(payload, { onConflict });
    if (!error) { try { localStorage.removeItem('bd_ps_pending_'+_psSettingsScopeKey()); } catch(e) {} }
  } catch(e) {}
}

// Generic get/set matching the old per-setting function shapes below,
// so every existing caller throughout the codebase keeps working
// completely unchanged.
function _psSettingGet(key, fallback) { return _psSheetSettings[key] !== undefined ? _psSheetSettings[key] : fallback; }
// Writes a synchronous localStorage backup immediately, before the
// debounced database save even starts. A network request can be cut
// off mid-flight the instant the page unloads, no matter how early it
// was started — this was the real reason a change made right before a
// refresh could still be lost even after flushing early on unload.
// localStorage.setItem is synchronous and completes instantly, so it
// can't be interrupted the same way; psEnsureSheetSettingsLoaded()
// checks for this backup on the next load and re-syncs it if the
// database save never actually made it through.
function _psSettingSet(key, value) {
  _psSheetSettings[key] = value;
  try { localStorage.setItem('bd_ps_pending_'+_psSettingsScopeKey(), JSON.stringify(_psSheetSettings)); } catch(e) {}
  _psSaveSheetSettingsNow();
}
function _psCustomVals(){ try { return JSON.parse(localStorage.getItem('bd_ps_customvals')||'{}'); } catch(e){ return {}; } }
function _psCustomCols(){ return _psSettingGet('customCols', []); }
function _psSetCustomCols(c){ _psSettingSet('customCols', c); }
function _psColMeta(){ return _psSettingGet('colMeta', {}); }
function _psPersistColMeta(m){ _psSettingSet('colMeta', m); }
function _psLabels(){ return _psSettingGet('labels', {}); }
function _psPersistLabels(m){ _psSettingSet('labels', m); }
function _psBuiltinDefaultLabel(key){
  if (key==='name') return psType==='services' ? 'Service' : 'Product';
  const def = (PS_COL_DEFS[psType]||[]).find(x=>x.id===key);
  return def ? def.label : key;
}
// A column gets a total if it's a genuine "sum of this makes sense"
// figure — quantities and extended totals, plus any custom column
// explicitly typed as Number or Measurement via Assign Cells. Unit
// prices (Cost/Selling Price) are deliberately excluded — summing
// per-unit prices across different products isn't a meaningful figure.
// Only columns that calculate an actual monetary amount get a total —
// Quantity is a count, not money, and custom Number/Measurement columns
// (e.g. "Boxes", "Weight") aren't inherently monetary either, so none
// of those get summed here even though they're numeric.
function psColIsSummable(key, customByKey) {
  return key === 'total_cost' || key === 'total_sell';
}
function psColumnTotal(key, visibleRows, customByKey) {
  if (key === 'total_cost' || key === 'total_sell') return visibleRows.reduce((s,r)=>s+psComputeConfiguredTotal(r, key),0);
  return null;
}
function psRenderTotalsRow(visibleKeys, customByKey, visibleRows) {
  const tfoot = document.getElementById('psTfoot');
  if (!tfoot) return;
  const hasAnySummable = visibleKeys.some(k => psColIsSummable(k, customByKey));
  if (!hasAnySummable || !visibleRows.length) { tfoot.innerHTML = ''; return; }

  let html = '<tr class="ps-total-row"><td>TOTAL</td>';
  visibleKeys.forEach(key => {
    if (psColIsSummable(key, customByKey)) {
      const result = psColumnTotal(key, visibleRows, customByKey);
      const display = fmt(result); // fmt() already includes the currency symbol
      html += '<td class="num">'+display+'</td>';
    } else {
      html += '<td></td>';
    }
  });
  html += '<td></td><td></td></tr>';
  tfoot.innerHTML = html;
}

// Opens Assign Cells scoped to ONE cell rather than the whole column.
// customMeta[key] absent = no override, defers to the column's type.
// customMeta[key] present (even {type:'text'}) = an explicit override,
// which is why "Free text" here still needs to be stored explicitly
// rather than treated the same as "no override" the way the column-
// level dialog treats it.
function psCellAssignCells(i, key) {
  const r = psRows[i];
  const hasOverride = !!(r.customMeta && Object.prototype.hasOwnProperty.call(r.customMeta, key));
  const effectiveMeta = hasOverride ? r.customMeta[key] : _psColMeta()[key];
  const cols = _psCustomCols();
  const colName = (cols.find(c=>c.key===key)||{}).name || '';

  openAssignCellsDialog(colName + ' — this cell', effectiveMeta, newMeta => {
    r.customMeta = r.customMeta || {};
    r.customMeta[key] = newMeta || { type: 'text' };
    if (newMeta && newMeta.type === 'text' && newMeta.fields && !(r.custom && r.custom[key])) { r.custom = r.custom || {}; r.custom[key] = fxEncode(Object.fromEntries(newMeta.fields.map(f => [f.label, f.detail || ''])), newMeta.fields); }   // details typed in Assign Cells fill this cell
    r.saved = false;
    renderProductsPage();
    psAutosaveTrigger();
  }, hasOverride ? {
    label: 'Use column default instead',
    onReset: () => {
      delete r.customMeta[key];
      r.saved = false;
      renderProductsPage();
      psAutosaveTrigger();
    },
  } : null, true);
}

// ── STOCK AS AT: custom calendar with a format switcher ─────────
// A native <input type="date"> can't be modified — its calendar popup
// is rendered entirely by the browser with zero access for page JS/CSS
// to inject anything into it. This is a fully custom calendar instead,
// giving full control over the format-switcher's placement.
function _psQtyDateFormat(){ return _psSettingGet('qtyDateFormat', 'slash'); }
function _psPersistQtyDateFormat(f){ _psSettingSet('qtyDateFormat', f); }
function _psOrdinalSuffix(n) {
  const s = ['th','st','nd','rd'], v = n % 100;
  return s[(v-20)%10] || s[v] || s[0];
}
const PS_MONTH_FULL   = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const PS_MONTH_ABBREV = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sept','Oct','Nov','Dec'];
const PS_DATE_FORMAT_LABELS = { slash:'09/16/2026', full:'September 16th 2026', abbrev:'Sept 16th 2026' };
function psLocalIso(ts) {
  const d = new Date(ts); if (isNaN(d)) return '';
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function psFormatQtyDate(iso, format) {
  if (!iso) return '';
  const d = new Date(iso+'T00:00:00');
  const day = d.getDate(), year = d.getFullYear();
  if (format === 'full')   return PS_MONTH_FULL[d.getMonth()]+' '+day+_psOrdinalSuffix(day)+' '+year;
  if (format === 'abbrev') return PS_MONTH_ABBREV[d.getMonth()]+' '+day+_psOrdinalSuffix(day)+' '+year;
  return String(d.getMonth()+1).padStart(2,'0')+'/'+String(day).padStart(2,'0')+'/'+year;
}

let _psCalState = null;
let _psCalOutsideClickHandler = null;
function psOpenDatePicker(ev, rowIndex) {
  ev.stopPropagation();
  psCloseDatePicker(); // in case a different cell's calendar is still open
  const cellRect = ev.currentTarget.getBoundingClientRect();
  const iso = psRows[rowIndex].qty_date;
  const base = iso ? new Date(iso+'T00:00:00') : new Date();
  _psCalState = { rowIndex, year: base.getFullYear(), month: base.getMonth() };

  const panel = document.createElement('div');
  panel.id = 'psDatePanel';
  panel.className = 'col-menu';
  panel.style.cssText = 'position:fixed;z-index:12001;padding:12px;width:270px;top:'+(cellRect.bottom+6)+'px;left:'+Math.min(cellRect.left, window.innerWidth-286)+'px;';
  panel.addEventListener('click', e=>e.stopPropagation());
  panel.innerHTML = psCalendarHtml();
  document.body.appendChild(panel);

  // Close on any click outside the panel — but NOT a full-screen
  // overlay, which would block clicks meant for a different date
  // cell (forcing an extra click just to dismiss this one first).
  // Deferred to the next tick so the click that just opened this
  // panel doesn't immediately trigger its own close.
  setTimeout(() => {
    _psCalOutsideClickHandler = e => {
      if (!panel.contains(e.target) && !e.target.closest('.ps-date-cell')) psCloseDatePicker();
    };
    document.addEventListener('click', _psCalOutsideClickHandler, true);
  }, 0);
}
function psCloseDatePicker(){
  document.getElementById('psDatePanel')?.remove();
  if (_psCalOutsideClickHandler) { document.removeEventListener('click', _psCalOutsideClickHandler, true); _psCalOutsideClickHandler = null; }
  _psCalState = null;
}

function psCalendarHtml() {
  const { year, month, rowIndex } = _psCalState;
  const selectedISO = psRows[rowIndex].qty_date;
  const fmt = _psQtyDateFormat();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month+1, 0).getDate();
  const daysInPrevMonth = new Date(year, month, 0).getDate();

  let cells = '';
  for (let i=0;i<firstDay;i++) {
    cells += '<div class="ps-cal-day ps-cal-out">'+(daysInPrevMonth-firstDay+i+1)+'</div>';
  }
  for (let d=1; d<=daysInMonth; d++) {
    const iso = year+'-'+String(month+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    cells += '<div class="ps-cal-day'+(iso===selectedISO?' ps-cal-selected':'')+'" onclick="psPickDate(\''+iso+'\')">'+d+'</div>';
  }
  const trailing = (7 - ((firstDay+daysInMonth) % 7)) % 7;
  for (let i=1;i<=trailing;i++) cells += '<div class="ps-cal-day ps-cal-out">'+i+'</div>';

  return '<div style="position:relative;margin-bottom:10px;">'
    + '<button onclick="psToggleFormatMenu(event)" class="ps-cal-format-btn">'
    + '<span>Format: '+escH(PS_DATE_FORMAT_LABELS[fmt])+'</span><span>\u25BE</span></button>'
    + '<div id="psFormatMenu" class="ps-cal-format-menu hidden">'
    + Object.entries(PS_DATE_FORMAT_LABELS).map(([key,label])=>
        '<div class="ps-cal-format-opt" onclick="psSetQtyDateFormat(\''+key+'\')">'+label+'</div>').join('')
    + '</div></div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">'
    + '<button onclick="psCalNav(-1)" class="ps-cal-nav">\u2039</button>'
    + '<span style="font-size:0.78rem;font-weight:700;color:var(--white);">'+PS_MONTH_FULL[month]+' '+year+'</span>'
    + '<button onclick="psCalNav(1)" class="ps-cal-nav">\u203a</button></div>'
    + '<div class="ps-cal-grid ps-cal-dow">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<div>'+d+'</div>').join('')+'</div>'
    + '<div class="ps-cal-grid" id="psCalDays">'+cells+'</div>'
    + '<button onclick="psClearDate()" class="ps-cal-clear">Clear date</button>';
}

function psCalNav(delta) {
  _psCalState.month += delta;
  if (_psCalState.month < 0) { _psCalState.month = 11; _psCalState.year--; }
  if (_psCalState.month > 11) { _psCalState.month = 0; _psCalState.year++; }
  document.getElementById('psDatePanel').innerHTML = psCalendarHtml();
}
function psPickDate(iso) {
  const { rowIndex } = _psCalState;
  psRows[rowIndex].qty_date = iso;
  psRows[rowIndex].saved = false;
  psCloseDatePicker();
  psRenderTable();
  psAutosaveTrigger();
}
function psClearDate() {
  const { rowIndex } = _psCalState;
  psRows[rowIndex].qty_date = '';
  psRows[rowIndex].saved = false;
  psCloseDatePicker();
  psRenderTable();
  psAutosaveTrigger();
}
function psToggleFormatMenu(ev) {
  ev.stopPropagation();
  document.getElementById('psFormatMenu')?.classList.toggle('hidden');
}
function psSetQtyDateFormat(f) {
  _psPersistQtyDateFormat(f);
  if (document.getElementById('psDatePanel')) document.getElementById('psDatePanel').innerHTML = psCalendarHtml();
  psRenderTable(); // applies the new format to every Stock as at cell, not just this one
}

// ── CONFIGURABLE TOTAL FORMULAS ──────────────────────────────
// total_cost and total_sell default to cost_price×qty / sell_price×qty,
// but users can reassign which columns feed into them and how.
function _psTotalFormulas(){ return _psSettingGet('totalFormulas', {}); }
function _psPersistTotalFormulas(f){ _psSettingSet('totalFormulas', f); }
function _psDefaultTotalFormula(key) {
  if (key === 'total_cost') return { columns: ['cost_price','qty'], operation: 'multiply' };
  if (key === 'total_sell') return { columns: ['sell_price','qty'], operation: 'multiply' };
  return { columns: [], operation: 'multiply' };
}
function _psEffectiveTotalFormula(key) {
  const stored = _psTotalFormulas()[key];
  return stored || _psDefaultTotalFormula(key);
}
// Columns eligible to feed a total formula — must be numeric-compatible:
// the three numeric built-ins, plus any custom column typed as Number
// or Measurement via Assign Cells.
function psTotalFormulaEligibleColumns() {
  // Built-in names read through psColLabel() so a renamed column shows
  // its current name here too, not the original default.
  const cols = [
    { key:'cost_price', name:psColLabel('cost_price') },
    { key:'sell_price', name:psColLabel('sell_price') },
    { key:'qty', name:psColLabel('qty') },
  ];
  // Every custom column is eligible, regardless of whether its type has
  // been explicitly set via Assign Cells — a freshly-added column with
  // no type set yet (which renders as plain text) may still hold
  // numeric-looking values the user wants to use in a formula, and
  // _psNumericValueOf() already parses whatever's actually there.
  _psCustomCols().forEach(c => cols.push({ key:c.key, name:c.name }));
  return cols;
}
function _psColDisplayName(key) {
  const found = psTotalFormulaEligibleColumns().find(c=>c.key===key);
  return found ? found.name : key;
}
function _psNumericValueOf(row, key) {
  if (key === 'cost_price') return parseFloat(row.cost_price) || 0;
  if (key === 'sell_price') return parseFloat(row.sell_price) || 0;
  if (key === 'qty') return parseFloat(row.qty) || 0;
  const meta = _psColMeta()[key];
  const raw = (row.custom && row.custom[key]) || '';
  if (meta && meta.type === 'measurement') {
    const unitSuffix = ' ' + meta.unit;
    const num = raw.endsWith(unitSuffix) ? raw.slice(0,-unitSuffix.length) : raw;
    return parseFloat(num) || 0;
  }
  return parseFloat(raw) || 0;
}
function psComputeConfiguredTotal(row, key) {
  const formula = _psEffectiveTotalFormula(key);
  if (!formula.columns.length) return 0;
  // A column with nothing entered (parses to 0) is skipped rather than
  // included as 0 — otherwise a genuinely-filled Selling Price gets
  // wiped out to blank just because Quantity hasn't been entered yet.
  // If only one selected column actually has a value, the total is
  // simply that value.
  const values = formula.columns.map(c => _psNumericValueOf(row, c)).filter(v => v !== 0);
  if (!values.length) return 0;
  let result = values[0];
  for (let i=1; i<values.length; i++) {
    if (formula.operation==='multiply') result *= values[i];
    else if (formula.operation==='add') result += values[i];
    else if (formula.operation==='subtract') result -= values[i];
    else if (formula.operation==='divide') result = values[i]!==0 ? result/values[i] : result;
  }
  return result;
}

function psColLabel(key){ return _psLabels()[key] || _psBuiltinDefaultLabel(key); }

let _psFormulaDialogState = null;
function psOpenTotalFormulaDialog(key) {
  closeColMenu();
  const formula = _psEffectiveTotalFormula(key);
  _psFormulaDialogState = { key, columns: [...formula.columns], operation: formula.operation };

  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:20px;';
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  const panel = document.createElement('div');
  panel.className = 'col-menu psFormulaPanel';
  panel.style.cssText = 'padding:16px;width:min(380px,94vw);';
  panel.addEventListener('click', e=>e.stopPropagation());
  panel.innerHTML = psTotalFormulaHtml();
  wrap.appendChild(panel);
  document.body.appendChild(wrap);
}
function psTotalFormulaHtml() {
  const { key, columns, operation } = _psFormulaDialogState;
  const eligible = psTotalFormulaEligibleColumns();
  const availableToAdd = eligible.filter(c => !columns.includes(c.key));
  const opLabels = { multiply:'\u00d7', add:'+', subtract:'\u2212', divide:'\u00f7' };
  const previewText = columns.length
    ? columns.map(c=>_psColDisplayName(c)).join(' '+opLabels[operation]+' ')
    : 'Select at least one column';

  return `<label class="su-label">CONFIGURE TOTAL \u2014 ${escH(psColLabel(key))}</label>
    <div style="font-size:0.64rem;color:var(--muted);margin-bottom:12px;">Choose which columns combine to produce this total, and how.</div>
    <div style="font-size:0.68rem;color:var(--muted);margin-bottom:6px;">Columns</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;">
      ${columns.map((c,idx)=>`<span style="background:var(--gold-t012);color:var(--gold);font-size:0.72rem;padding:5px 8px;border-radius:6px;display:inline-flex;align-items:center;gap:5px;">${escH(_psColDisplayName(c))}<span style="cursor:pointer;" onclick="psFormulaRemoveCol(${idx})">\u2715</span></span>`).join('')}
      ${availableToAdd.length ? `<select onchange="if(this.value){psFormulaAddCol(this.value);this.value='';}" style="font-size:0.72rem;background:var(--surface2);color:var(--off);border:1px dashed var(--border2);border-radius:6px;padding:5px 8px;">
        <option value="">+ Add column</option>
        ${availableToAdd.map(c=>`<option value="${c.key}">${escH(c.name)}</option>`).join('')}
      </select>` : ''}
    </div>
    <div style="font-size:0.68rem;color:var(--muted);margin:10px 0 6px;">Operation</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:12px;">
      ${Object.entries(opLabels).map(([op,sym])=>`<button onclick="psFormulaSetOp('${op}')" style="padding:9px 0;font-size:0.85rem;border-radius:7px;cursor:pointer;border:1px solid ${operation===op?'var(--gold)':'var(--border2)'};background:${operation===op?'var(--gold-t012)':'var(--surface2)'};color:${operation===op?'var(--gold)':'var(--off)'};">${sym}</button>`).join('')}
    </div>
    <div style="background:var(--surface2);border-radius:7px;padding:8px 10px;font-size:0.7rem;color:var(--muted);margin-bottom:14px;">
      Preview: <span style="color:var(--white);font-weight:600;">${escH(previewText)}</span>
    </div>
    <div style="display:flex;gap:8px;">
      <button onclick="closeColMenu()" style="flex:1;background:var(--surface2);color:var(--off);border:1px solid var(--border2);font-weight:700;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Cancel</button>
      <button onclick="psFormulaSave()" style="flex:1;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Save</button>
    </div>`;
}
function psFormulaRefresh() { document.querySelector('.psFormulaPanel').innerHTML = psTotalFormulaHtml(); }
function psFormulaRemoveCol(idx) { _psFormulaDialogState.columns.splice(idx,1); psFormulaRefresh(); }
function psFormulaAddCol(key) { _psFormulaDialogState.columns.push(key); psFormulaRefresh(); }
function psFormulaSetOp(op) { _psFormulaDialogState.operation = op; psFormulaRefresh(); }
function psFormulaSave() {
  const { key, columns, operation } = _psFormulaDialogState;
  if (!columns.length) { alert('Select at least one column.'); return; }
  const formulas = _psTotalFormulas();
  formulas[key] = { columns, operation };
  _psPersistTotalFormulas(formulas);
  closeColMenu();
  renderProductsPage();
  // No autosave/DB write needed here — total_cost/total_sell are
  // computed at render time from existing row data, never stored as
  // their own fields. Only the formula config itself (in localStorage)
  // changed.
}

// Per-built-in-column styling (used to build each <th>, replacing what
// used to be inline per-field width/class literals in a fixed sequence).
const PS_BUILTIN_META = {
  name:         { numClass:false, style:'' },
  barcode:      { numClass:false, style:'width:150px;' },
  product_type: { numClass:false, style:'min-width:110px;' },
  service_type: { numClass:false, style:'min-width:110px;' },
  cost_price:   { numClass:true,  style:'width:110px;' },
  sell_price:   { numClass:true,  style:'width:110px;' },
  qty:          { numClass:true,  style:'width:90px;' },
  qty_date:     { numClass:false, style:'width:130px;' },
  total_cost:   { numClass:true,  style:'width:136px;white-space:normal;line-height:1.25;' },
  total_sell:   { numClass:true,  style:'width:136px;white-space:normal;line-height:1.25;' },
  income_acct:  { numClass:false, style:'width:230px;' },
};
// Which built-in columns are even candidates for the current type —
// mirrors the isSvc/!isSvc checks the old fixed-sequence renderer used.
function _psColApplies(key, isSvc) {
  if (key==='sell_price' || key==='income_acct') return true;
  if (key==='service_type') return isSvc;
  return !isSvc; // barcode, product_type, cost_price, qty, qty_date, total_cost, total_sell
}
function _psDefaultColOrder() {
  return ['qty_date','name','product_type','service_type','barcode','cost_price','sell_price','qty','total_cost','total_sell','income_acct'];
}
function _psColOrder(){ return _psSettingGet('colOrder', null) || _psDefaultColOrder(); }
function _psPersistColOrder(arr){ _psSettingSet('colOrder', arr); }
// Merges the stored order with any keys not yet present — a newly
// created custom column, or (for forward-compatibility) a built-in id
// added in some future update — so nothing silently disappears.
function _psEffectiveColOrder() {
  const order = _psColOrder().slice();
  _psDefaultColOrder().forEach(k => { if (!order.includes(k)) order.push(k); });
  _psCustomCols().forEach(c => { if (!order.includes(c.key)) order.push(c.key); });
  // Force qty_date first regardless of what's already stored — there's
  // no drag-to-reorder for built-in columns, only Insert-adjacent for
  // new custom ones, so nobody could have deliberately placed it
  // elsewhere; any existing stored order simply predates this change.
  const qtyDateIdx = order.indexOf('qty_date');
  if (qtyDateIdx > 0) { order.splice(qtyDateIdx, 1); order.unshift('qty_date'); }
  return order;
}
function _psHiddenCustomCols(){ return _psSettingGet('hiddenCustom', []); }
function _psPersistHiddenCustom(arr){ _psSettingSet('hiddenCustom', arr); }

// ── Products custom-column triangle menu (mirrors the Sales sheet) ──
function psColMenuOpen(ev, key) {
  const items = [
    ['\u270F\uFE0F Rename Header', "psColRename('"+key+"')"],
    ['+ Insert column left', "psColInsert('"+key+"','left')"],
    ['+ Insert column right', "psColInsert('"+key+"','right')"],
    ['\uD83D\uDDD1 Delete column', "psColDeleteOne('"+key+"')"],
    ['\u2699 Assign Cells', "psColAssignCells('"+key+"')"],
    ['\u2715 Clear column', "psColClear('"+key+"')"],
    ['\uD83D\uDEAB\uD83D\uDC41 Hide column', "psColHide('"+key+"')"],
    ['\u25C2 Minimize column', "psColToggleMin('"+key+"')"],
  ];
  if (key === 'qty_date') {
    ['slash','full','abbrev'].forEach(function(f){ items.push(['\uD83D\uDCC5 Date format: '+PS_DATE_FORMAT_LABELS[f], "psSetQtyDateFormat('"+f+"')"]); });
  }
  if (key === 'total_cost' || key === 'total_sell') {
    items.splice(4, 0, ['\uD83D\uDD22 Configure total', "psOpenTotalFormulaDialog('"+key+"')"]);
  }
  openColMenuPortal(ev, items);
}
function psColRename(key) {
  const cols = _psCustomCols();
  const c = cols.find(x=>x.key===key);
  if (c) {
    openTextPortal('RENAME HEADER', c.name, name=>{ c.name = name; _psSetCustomCols(cols); renderProductsPage(); });
    return;
  }
  const labels = _psLabels();
  openTextPortal('RENAME HEADER', labels[key] || _psBuiltinDefaultLabel(key), name=>{
    labels[key] = name; _psPersistLabels(labels); renderProductsPage();
  });
}
// ── Move a column: hold the strip above its header text and drag it. S/N and "Stock as at" stay put. ──
function psColMoveTo(key, targetKey, after) {
  if (!key || !targetKey || key === targetKey || key === 'qty_date') return;
  const order = _psEffectiveColOrder().filter(k => k !== key);
  let idx = order.indexOf(targetKey); if (idx < 0) return;
  if (after) idx++;
  const lock = order.indexOf('qty_date'); if (lock >= 0 && idx <= lock) idx = lock + 1;
  order.splice(idx, 0, key);
  _psPersistColOrder(order);
  psRenderTable();
}
(function(){
  let drag = null;
  function realThs() { return [...document.querySelectorAll('#bkContent .ps-table thead th[data-col-key]')]; }
  function pick(x) {
    const ths = realThs(); if (!ths.length) return null;
    for (const th of ths) { const r = th.getBoundingClientRect(); if (x >= r.left && x <= r.right) return { th, after: x > (r.left + r.right) / 2 }; }
    const first = ths[0].getBoundingClientRect(), last = ths[ths.length - 1].getBoundingClientRect();
    return x < first.left ? { th: ths[0], after: false } : { th: ths[ths.length - 1], after: true };
  }
  document.addEventListener('pointerdown', function(e){
    const g = e.target.closest && e.target.closest('.ps-colgrab'); if (!g || e.button > 0) return;
    e.preventDefault(); e.stopPropagation();
    const key = g.getAttribute('data-grab');
    const ind = document.createElement('div');
    ind.style.cssText = 'position:fixed;z-index:12050;width:3px;background:var(--gold);border-radius:2px;pointer-events:none;display:none;box-shadow:0 0 0 1px rgba(0,0,0,0.15);';
    document.body.appendChild(ind);
    const src = realThs().find(t => t.getAttribute('data-col-key') === key);
    if (src) src.style.opacity = '0.45';
    drag = { key, ind, src, target: null };
    document.body.style.cursor = 'grabbing'; document.body.style.userSelect = 'none';
  }, true);
  document.addEventListener('pointermove', function(e){
    if (!drag) return;
    const t = pick(e.clientX); if (!t) return;
    const tk = t.th.getAttribute('data-col-key');
    let after = t.after;
    if (tk === 'qty_date') after = true;     // nothing can go before Stock as at
    drag.target = { key: tk, after };
    const r = t.th.getBoundingClientRect();
    drag.ind.style.display = 'block';
    drag.ind.style.left = ((after ? r.right : r.left) - 1) + 'px';
    drag.ind.style.top = r.top + 'px'; drag.ind.style.height = r.height + 'px';
  });
  function end(commit) {
    if (!drag) return; const d = drag; drag = null;
    d.ind.remove(); if (d.src) d.src.style.opacity = '';
    document.body.style.cursor = ''; document.body.style.userSelect = '';
    if (commit && d.target) psColMoveTo(d.key, d.target.key, d.target.after);
  }
  document.addEventListener('pointerup', function(){ end(true); });
  document.addEventListener('pointercancel', function(){ end(false); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') end(false); });
})();
function psColInsert(key, side) {
  const newKey = 'c'+Date.now();

  // Compute the order BEFORE the new column is registered as a custom
  // column — otherwise _psEffectiveColOrder()'s own merge step would see
  // it as an unplaced custom column and auto-append it a second time,
  // on top of the position we splice it into below.
  const order = _psEffectiveColOrder();
  const idx = order.indexOf(key);
  const at = idx===-1 ? order.length : (side==='left' ? idx : idx+1);
  order.splice(at, 0, newKey);
  _psPersistColOrder(order);

  const cols = _psCustomCols();
  cols.push({name:'New Column', key:newKey});
  _psSetCustomCols(cols);

  renderProductsPage();
}
async function psColDeleteOne(key) {
  const cols = _psCustomCols();
  const c = cols.find(x=>x.key===key);
  if (!c) { alert('Built-in columns cannot be deleted — use Hide column instead.'); return; }
  if (!(await bdConfirm('Delete column "'+c.name+'" and its contents?'))) return;
  _psSetCustomCols(cols.filter(x=>x.key!==key));
  psRows.forEach(r=>{ if (r.custom) delete r.custom[key]; });
  const meta = _psColMeta(); delete meta[key]; _psPersistColMeta(meta);
  _psPersistColOrder(_psEffectiveColOrder().filter(k=>k!==key));
  renderProductsPage();
}
function psColAssignCells(key) {
  const cols = _psCustomCols();
  const c = cols.find(x=>x.key===key);
  const PS_ASSIGNABLE = ['name','barcode','product_type','service_type','qty'];
  if (!c && !PS_ASSIGNABLE.includes(key)) { alert('This column is calculated or fixed (dates and prices), so it keeps its own format.'); return; }
  const meta = _psColMeta();
  openAssignCellsDialog(c ? c.name : psColLabel(key), meta[key], newMeta => {
    if (!c && key==='qty' && newMeta && newMeta.type!=='measurement') { bdToast('Quantity takes a measurement unit (kg, tons, inches…) — choose Measurement or Free text'); return; }
    if (newMeta) meta[key]=newMeta; else delete meta[key];
    _psPersistColMeta(meta);
    psRows.forEach(r=>{ r.saved=false; });
    renderProductsPage();
    psAutosaveTrigger();
  });
}
async function psColClear(key) {
  const cols = _psCustomCols();
  const c = cols.find(x=>x.key===key);
  if (!(await bdConfirm('Clear all values in this column?'))) return;
  if (c) {
    psRows.forEach(r=>{ if (r.custom) delete r.custom[key]; });
    const vals = _psCustomVals();
    Object.keys(vals).forEach(id=>{ if(vals[id]) delete vals[id][key]; });
    localStorage.setItem('bd_ps_customvals', JSON.stringify(vals));
    renderProductsPage();
    return;
  }
  if (key==='total_cost' || key==='total_sell') { alert('This total is calculated — clear Cost Price, Selling Price, or Quantity instead.'); return; }
  psRows.forEach(r=>{
    if (key==='name') r.name='';
    else if (key==='barcode') r.barcode='';
    else if (key==='product_type' || key==='service_type') r.product_type='';
    else if (key==='cost_price') r.cost_price=0;
    else if (key==='sell_price') r.sell_price=0;
    else if (key==='qty') r.qty=0;
    else if (key==='qty_date') r.qty_date='';
    else if (key==='income_acct') r.income_account='';
    r.saved=false;
  });
  renderProductsPage();
}
function psColHide(key) {
  const cols = _psCustomCols();
  const c = cols.find(x=>x.key===key);
  if (c) {
    const hidden = _psHiddenCustomCols();
    if (!hidden.includes(key)) hidden.push(key);
    _psPersistHiddenCustom(hidden);
    renderProductsPage();
    return;
  }
  if (key==='name') { alert('The name column cannot be hidden.'); return; }
  psSetColVisible(key, false);
  renderProductsPage();
}
function psColUnhide(key) {
  _psPersistHiddenCustom(_psHiddenCustomCols().filter(k=>k!==key));
  renderProductsPage();
}
function psCustomInput(i, key, val){
  psRows[i].custom = psRows[i].custom || {};
  psRows[i].custom[key] = val;
  psRows[i].saved = false;
  psUpdateTotals(i);
}
let psSel = { active:false, picked:[] };
function psSelButton(){ psSel = { active: !psSel.active, picked:[] }; renderProductsPage(); }
function psSelToggle(i){
  const p = psSel.picked.indexOf(i); if (p>=0) psSel.picked.splice(p,1); else psSel.picked.push(i);
  const el = document.querySelector('#psRow_'+i+' .op-circle'); if (el) el.classList.toggle('on');
  const c = document.getElementById('psSelCount'); if (c) c.textContent = psSel.picked.length + ' selected';
}
function psSelectAll(){
  const all = [...document.querySelectorAll('#psBody tr[id^="psRow_"]')].map(tr=>parseInt(tr.id.slice(6))).filter(i=>!isNaN(i));
  const every = all.length && all.every(i => psSel.picked.includes(i));
  psSel.picked = every ? [] : all;
  document.querySelectorAll('#psBody tr[id^="psRow_"]').forEach(tr=>{
    const i = parseInt(tr.id.slice(6)); const el = tr.querySelector('.op-circle'); if (el) el.classList.toggle('on', psSel.picked.includes(i)); });
  const c = document.getElementById('psSelCount'); if (c) c.textContent = psSel.picked.length + ' selected';
}
async function psDeleteSelected(){
  if (!psSel.picked.length) return;
  if (!(await bdConfirm('Delete '+psSel.picked.length+' selected '+(psType==='services'?'service':'product')+'(s)?'))) return;
  psSnapshot();
  const idxs = psSel.picked.slice().sort((a,b)=>b-a);
  const gone = [];
  idxs.forEach(i => { const r = psRows[i]; if (r) { gone.push({r, i}); psRows.splice(i,1); } });
  psSel = { active:false, picked:[] };
  renderProductsPage();
  const ids = gone.map(g=>g.r.id).filter(Boolean);
  if (ids.length) {
    try {
      const { error } = await bkDb.from('bk_products').update({is_active:false}).in('id',ids).eq('user_id',bkUser.id);
      if (error) throw error;
    } catch(e) {
      gone.sort((a,b)=>a.i-b.i).forEach(g => psRows.splice(Math.min(g.i, psRows.length), 0, g.r));
      renderProductsPage(); bdToast('⚠ Could not delete — they have been put back', 'error');
    }
  }
}
function psSnapshot(){ _psPend = null; psSheet.undo.push(JSON.stringify(psRows)); if(psSheet.undo.length>40)psSheet.undo.shift(); psSheet.redo=[]; }
let _psPend = null;
document.addEventListener('focusin', e => {
  const t = e.target; if (!t || !t.closest || !t.closest('#psBody')) return;
  if (_psPend === null) _psPend = JSON.stringify(psRows);
});
function psPendCommit() {
  if (_psPend === null) return;
  const pend = _psPend; _psPend = null;
  if (psSheet.undo.length && psSheet.undo[psSheet.undo.length-1] === pend) return;
  if (pend === JSON.stringify(psRows)) return;
  psSheet.undo.push(pend); if (psSheet.undo.length > 40) psSheet.undo.shift(); psSheet.redo = [];
}
function psReconcileAfterUndo(before) {
  const prev = new Map(); before.forEach(r => { if (r.id) prev.set(r.id, r); });
  const cur = new Set();
  const strip = r => { const c = Object.assign({}, r); delete c.saved; return JSON.stringify(c); };
  const react = [];
  psRows.forEach(r => {
    if (!r.id) return;
    cur.add(r.id);
    const p = prev.get(r.id);
    if (!p) { react.push(r.id); r.saved = false; return; }           // was deleted: bring it back
    r.saved = (strip(r) === strip(p)) ? p.saved : false;
  });
  const gone = before.filter(r => r.id && !cur.has(r.id)).map(r => r.id);
  if (react.length) Promise.resolve(bkDb.from('bk_products').update({is_active:true}).in('id', react).eq('user_id', bkUser.id)).catch(()=>{});
  if (gone.length) Promise.resolve(bkDb.from('bk_products').update({is_active:false}).in('id', gone).eq('user_id', bkUser.id)).catch(()=>{});
}
function _psUndoApply(from, to) {
  psPendCommit();
  if (!from.length) return;
  const before = psRows;
  to.push(JSON.stringify(before));
  psRows = JSON.parse(from.pop());
  psReconcileAfterUndo(before);
  renderProductsPage();
  if (psRows.some(r => !r.saved && (r.name||'').trim())) { clearTimeout(_psAutoT); _psAutoT = setTimeout(() => psSaveAll(), 120); }
}
function psUndo(){ _psUndoApply(psSheet.undo, psSheet.redo); }
function psRedo(){ _psUndoApply(psSheet.redo, psSheet.undo); }
function psToggleToolbox(){ psSheet.open=!psSheet.open; renderProductsPage(); }
function psSetFont(f){ psSheet.font=f; renderProductsPage(); }
function psSetWrap(w){ psSheet.wrap=w; renderProductsPage(); }

// ── PER-COLUMN CELL ALIGNMENT ────────────────────────────────
// Default is right for every column (built-in or custom); users can
// override individual columns via the toolbox align buttons. Headers
// are never affected — they always stay left-aligned.
function _psColAlign(){ return _psSettingGet('colAlign', {}); }
function _psPersistColAlign(a){ _psSettingSet('colAlign', a); }
function _psEffectiveColAlign(key){ return _psColAlign()[key] || 'right'; }
// Column show/hide, unified onto the single hidden-columns list that
// custom columns already used (_psHiddenCustomCols, further below) —
// built-in columns previously tracked visibility separately in a
// user-scoped bk_settings row that only persisted when a "Save &
// Close" button was explicitly clicked, so a toggle was silently lost
// if the user instead just clicked away to dismiss the panel, which
// is the natural thing to do. Now both use the one already-working,
// business-scoped, auto-saving list.
function _psIsColVisible(key){ return !_psHiddenCustomCols().includes(key); }
function psSetColVisible(key, visible){
  const hidden = _psHiddenCustomCols();
  const idx = hidden.indexOf(key);
  if (visible && idx !== -1) hidden.splice(idx, 1);
  if (!visible && idx === -1) hidden.push(key);
  _psPersistHiddenCustom(hidden);
}
let _psFocusedColKey = null;
function psSetColumnAlign(alignment) {
  if (!_psFocusedColKey) { alert('Click into a cell in the column you want to align first.'); return; }
  const align = _psColAlign();
  align[_psFocusedColKey] = alignment;
  _psPersistColAlign(align);
  psRenderTable();
}
// Sorts rows by when they were originally recorded (not shown anywhere,
// just used as the sort key), rather than any other field. Rows
// missing a created_at (shouldn't normally happen post-fix, but a
// safety net) sort as oldest so they don't jump unpredictably.
function psSortByCreated(direction) {
  psSnapshot();
  psRows.sort((a, b) => {
    const ta = a.created_at ? new Date(a.created_at).getTime() : 0;
    const tb = b.created_at ? new Date(b.created_at).getTime() : 0;
    return direction === 'desc' ? tb - ta : ta - tb;
  });
  renderProductsPage();
}
function psDecimals(d){ psSheet.decimals = Math.max(0, Math.min(4, (psSheet.decimals===null?0:psSheet.decimals)+d)); renderProductsPage(); }
function psToolboxSearch(){ psSheet.search = document.getElementById('psToolSearch')?.value||''; psRenderTable(); }
async function psInsertColumn(){
  const name = await bdPrompt('Column header name:');
  if (!name) return;
  const cols = _psCustomCols();
  cols.push({name:name.trim(), key:'c'+Date.now()});
  _psSetCustomCols(cols);
  renderProductsPage();
}
async function psDeleteColumn(){
  const cols = _psCustomCols();
  if (!cols.length) { alert('No custom columns to delete. Use the ⚙ Columns button to show or hide built-in columns.'); return; }
  const pick = await bdPrompt('Which column do you want to delete?\n'+cols.map((c,i)=>(i+1)+'. '+c.name).join('\n')+'\n\nEnter the number:');
  const n = parseInt(pick);
  if (!n||n<1||n>cols.length) return;
  cols.splice(n-1,1);
  _psSetCustomCols(cols);
  renderProductsPage();
}
function psPrint(orientation){
  bdPrintTable({ table: document.querySelector('.ps-table'), orientation: orientation || 'portrait', title: psType==='services' ? 'Services' : 'Products' });
}
// Renders a text cell as either a plain <input> (Clip/Overflow modes —
// both already work fine with a single-line input) or a <textarea>
// (Wrap mode). white-space:normal alone can never wrap an <input>'s
// value — that's a hard HTML limitation, not a missing style rule —
// so actually wrapping long text requires swapping the element type.
function psTextCellHtml(value, placeholder, onInputExpr, extraStyle) {
  const v = escH(value||'');
  const style = extraStyle||'';
  if (psSheet.wrap === 'wrap') {
    return '<textarea class="ps-cell ps-cell-wrap" style="'+style+'" placeholder="'+escH(placeholder)+'" rows="1"'
      + ' oninput="'+onInputExpr+';psAutoGrowCell(this)">'+v+'</textarea>';
  }
  return '<input class="ps-cell" type="text" value="'+v+'" style="'+style+'" placeholder="'+escH(placeholder)+'"'
    + ' oninput="'+onInputExpr+'"/>';
}
function psAutoGrowCell(el) {
  el.style.height = 'auto';
  el.style.height = el.scrollHeight + 'px';
}

function _psColWidths(){ return _psSettingGet('colWidths', {}); }
function _psPersistColWidths(w){ _psSettingSet('colWidths', w); }
function psColResized(key, widthPx) {
  const widths = _psColWidths();
  widths[key] = widthPx;
  _psPersistColWidths(widths);
}

function psToolboxHtml(){
  return '<div class="sheet-toolbox" style="margin:8px 16px 0;">'
    + '<input id="psToolSearch" class="bk-input" placeholder="Search…" value="'+escH(psSheet.search)+'" style="width:130px;background:var(--surface2);border:1px solid var(--border2);border-radius:7px;color:var(--white);padding:6px 9px;font-size:0.74rem;outline:none;" oninput="psToolboxSearch()"/>'
    + '<button class="tb-icon'+(psSel.active?' tb-active':'')+'" title="Select rows" onclick="psSelButton()">☑ Select</button>'
    + '<button class="tb-icon" title="Undo" onclick="psUndo()">↩</button>'
    + '<button class="tb-icon" title="Redo" onclick="psRedo()">↪</button>'
    + '<button class="tb-icon" title="Print portrait" onclick="psPrint(\'portrait\')">🖨</button>'
    + '<button class="tb-icon" title="Print landscape" onclick="psPrint(\'landscape\')">🖨▭</button>'
    + '<button class="tb-icon" title="Decrease decimals" onclick="psDecimals(-1)">.0←</button>'
    + '<button class="tb-icon" title="Increase decimals" onclick="psDecimals(1)">.00→</button>'
    + '<button class="tb-icon" title="Align cells left — click a cell in the target column first" onclick="psSetColumnAlign(\'left\')">L</button>'
    + '<button class="tb-icon" title="Align cells center — click a cell in the target column first" onclick="psSetColumnAlign(\'center\')">C</button>'
    + '<button class="tb-icon" title="Align cells right — click a cell in the target column first" onclick="psSetColumnAlign(\'right\')">R</button>'
    + '<button class="tb-icon" title="Sort by date/time recorded — ascending (oldest first)" onclick="psSortByCreated(\'asc\')">▲</button>'
    + '<button class="tb-icon" title="Sort by date/time recorded — descending (newest first)" onclick="psSortByCreated(\'desc\')">▼</button>'
    + '<button class="tb-icon" title="Insert column" onclick="psInsertColumn()">+▥</button>'
    + '<button class="tb-icon" title="Delete column" onclick="psDeleteColumn()">−▥</button>'
    + '<button class="tb-icon" id="psColBtn" onclick="togglePsColSelector()">🎛 Columns ▾</button>'
    + '</div>';
}

async function showProductsPage(type) {
  bdSaveRoute(_regOnboarding ? 'register-products' : 'products');
  staffHideChrome();
  psType = type || 'products';
  psSel = { active:false, picked:[] };
  document.getElementById('bkContent').innerHTML = '<div class="bk-loading">Loading…</div>';
  await psEnsureSheetSettingsLoaded();

  let data;
  if (!navigator.onLine) {
    const cached = bdCacheRead('products', psType);
    window._bdShowingOfflineData = !!cached;
    data = cached ? cached.data : [];
  } else {
    window._bdShowingOfflineData = false;
    let _pq = bkDb.from('bk_products').select('*');
    _pq = activeBusiness?.id
      ? _pq.or('business_id.eq.'+activeBusiness.id+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
      : _pq.eq('user_id', bkUser.id);
    const res = await _pq.eq('is_service',psType==='services').eq('is_active',true).order('created_at');
    data = res.data;
    bdCacheWrite('products', data, psType);
  }

  psRows = (data||[]).map(r => ({
    id:             r.id,
    name:           r.product_name || '',
    barcode:        r.barcode || '',
    product_type:   r.product_type || '',
    cost_price:     parseFloat(r.cost_price) || 0,
    sell_price:     parseFloat(r.price) || 0,
    qty:            parseFloat(r.qty_in_stock) || 0,
    qty_date:       r.qty_as_at || ((parseFloat(r.qty_in_stock) > 0 && r.created_at) ? psLocalIso(r.created_at) : ''),
    unit:           r.unit || 'unit',
    income_account: r.income_account || '',
    custom:         r.custom || {},
    customMeta:     r.custom_meta || {},
    created_at:     r.created_at || null,
    saved:          true,
  }));
  // Safety net for anyone who entered custom values before this fix,
  // when they were only ever written to localStorage — merge those in
  // for any key the database doesn't already have, then let the next
  // save persist them properly.
  const _cv = _psCustomVals();
  psRows.forEach(r => {
    if (r.id && _cv[r.id]) r.custom = { ..._cv[r.id], ...r.custom };
  });
  renderProductsPage();
}

function renderProductsPage() {
  const isSvc = psType === 'services';

  document.getElementById('bkContent').innerHTML =
    '<div class="bk-content-header">'
    + '<div><div class="bk-content-title">'+(isSvc?'SERVICES':'PRODUCTS')+'</div>'
    + '<div style="font-size:0.72rem;color:var(--muted);margin-top:2px;">'+(isSvc?'Track services and pricing.':'Track products, pricing and stock.')+'</div></div>'
    + '<div style="display:flex;gap:8px;align-items:center;position:relative;">'
    + '<button class="bk-btn bk-btn-outline" style="font-size:0.74rem;" onclick="showProductsPage(\''+(isSvc?'products':'services')+'\')">'+'Switch to '+(isSvc?'Products':'Services')+'</button>'
    + '<span class="bk-save-msg" id="psSaveMsg"></span>'
    + '<button class="bk-btn bk-btn-outline" style="font-size:0.74rem;" onclick="psToggleToolbox()">⚙ Tools</button>'
    + '</div></div>'
    + (psSheet.open ? psToolboxHtml() : '')
    + (psSel.active ? '<div class="op-selbar" style="margin:8px 16px 0;"><span id="psSelCount" style="color:var(--gold);font-weight:800;">'+psSel.picked.length+' selected</span>'
        + '<button class="op-cancel-btn" onclick="psSelectAll()">☑ Select all</button>'
        + '<button class="op-bundle-btn" onclick="psDeleteSelected()">🗑 Delete selected</button>'
        + '<button class="op-cancel-btn" onclick="psSelButton()">Cancel</button></div>' : '')
    + psUnregBannerHtml()
    + psFilterBarHtml()
    + '<div class="bk-sheet-wrap" style="font-family:\''+psSheet.font+'\',sans-serif;"><table class="ps-table ps-wrap-'+psSheet.wrap+'" style="min-width:400px;">'
    + '<thead id="psThead"></thead><tbody id="psBody"></tbody><tfoot id="psTfoot"></tfoot>'
    + '</table></div>'
    + '<div style="padding:14px 16px;display:flex;justify-content:center;">'
    + '<button class="ps-add-btn" onclick="psAddRow()">+ Add '+(isSvc?'Service':'Product')+'</button>'
    + '</div>'
    + (_regOnboarding ? '<div class="bk-auth-btnrow" style="padding:6px 16px 30px;align-items:center;">'
      + '<button class="bk-login-back" onclick="_regOnboarding=false;showRegisterBusinessPage()">← Back</button>'
      + '<button class="bk-login-btn" style="flex:1 1 220px;background:var(--gold);color:var(--accent-ink);" onclick="_regOnboarding=false;showAllBusinessesDashboard()">Save &amp; Go to Dashboard →</button>'
      + '<span style="font-size:0.72rem;color:var(--muted);flex:1 1 100%;text-align:center;margin-top:6px;">You can add more products &amp; services later from the Products &amp; Services section.</span>'
      + '</div>' : '');

  psRenderTable();

  // #psBody is only (re)created here, when renderProductsPage() rebuilds
  // the whole shell — psRenderTable() just updates its contents on
  // subsequent calls, so attaching once here is enough; it isn't lost
  // on every keystroke re-render.
  const psBodyEl = document.getElementById('psBody');
  if (psBodyEl) {
    psBodyEl.addEventListener('input', psAutosaveTrigger);
    psBodyEl.addEventListener('change', psAutosaveTrigger);
    psBodyEl.addEventListener('focusout', () => { if (psRows.some(r=>!r.saved && (r.name||'').trim())) { clearTimeout(_psAutoT); _psAutoT = setTimeout(()=>psSaveAll(), 250); } });
    psBodyEl.addEventListener('focusin', e => {
      const td = e.target.closest('td[data-col-key]');
      if (td) _psFocusedColKey = td.dataset.colKey;
    });
  }
}

// ── Products: column search (same popup and chips as the Master Journal), minimize ──
function _psFilterKey() { return 'bd_pscolfilters_'+(activeBusiness?.id || bkUser?.id || 'x')+'_'+psType; }
function psColFilters() {
  if (!psSheet.colFilters || psSheet._cfScope !== _psFilterKey()) {
    psSheet._cfScope = _psFilterKey();
    try { psSheet.colFilters = JSON.parse(localStorage.getItem(_psFilterKey())||'{}') || {}; } catch(e) { psSheet.colFilters = {}; }
  }
  return psSheet.colFilters;
}
function _psSaveFilters() { try { localStorage.setItem(_psFilterKey(), JSON.stringify(psColFilters())); } catch(e) {} }
function _psKeyLabel(key) { const c = _psCustomCols().find(x=>x.key===key); return c ? c.name : psColLabel(key); }
function _psCellText(r, key) {
  const n = v => (v>0 ? String(v)+' '+v.toLocaleString('en-NG') : '');
  switch (key) {
    case 'name': return r.name||'';
    case 'barcode': return r.barcode||'';
    case 'product_type': case 'service_type': return r.product_type||'';
    case 'cost_price': return n(r.cost_price);
    case 'sell_price': return n(r.sell_price);
    case 'qty': return n(r.qty);
    case 'qty_date': return (r.qty_date||'')+' '+psFormatQtyDate(r.qty_date, _psQtyDateFormat());
    case 'total_cost': return n(psComputeConfiguredTotal(r,'total_cost'));
    case 'total_sell': return n(psComputeConfiguredTotal(r,'total_sell'));
    case 'income_acct': return r.income_account||'';
    default: return String((r.custom && r.custom[key]) || '');
  }
}
function _psRowVisible(r) {
  if (psSheet.search && (r.name||'').toLowerCase().indexOf(psSheet.search.toLowerCase()) < 0) return false;
  const f = psColFilters(); const keys = Object.keys(f).filter(k=>f[k]);
  if (!keys.length) return true;
  if (!r.id && !(r.name||'').trim()) return true;       // blank new rows stay so you can still type into them
  return keys.every(k => _psCellText(r,k).toLowerCase().indexOf(f[k].toLowerCase()) >= 0);
}
function psFilterBarHtml() {
  const f = psColFilters(); const keys = Object.keys(f).filter(k=>f[k]);
  if (!keys.length) return '';
  return '<div class="jrn-filterbar" style="padding:6px 16px;">'
    + keys.map(k=>'<span class="jrn-filter-chip">'+escH(_psKeyLabel(k))+': '+escH(f[k])+'<span class="x" onclick="psColFilterClear(\''+k+'\',event)">✕</span></span>').join('')
    + '<span class="jrn-filter-clearall" onclick="psColFilterClearAll()">Clear all filters</span></div>';
}
const PS_COL_SUB = { sell_price:'selling price', total_sell:'at selling price' };
function _psThInner(key, label, f) {
  const act = !!(f && f[key]);
  let lab = escH(label);
  if (key === 'total_cost') lab = lab.replace(/ as at /i, '<br>as at ');
  // Default Products headers carry a smaller second line (until the user renames the column themselves).
  if (psType === 'products' && !_psLabels()[key] && PS_COL_SUB[key]) lab += '<br><span style="font-size:0.78em;font-weight:600;text-transform:none;letter-spacing:0;opacity:0.85;">' + escH(PS_COL_SUB[key]) + '</span>';
  return '<span class="col-min-btn" title="Minimize" onclick="event.stopPropagation();psColToggleMin(\''+key+'\')">\u25C2</span>'
    + '<span class="jcol-filter-label'+(act?' jcol-active':'')+'" title="Click to search · double-click to rename" onclick="event.stopPropagation();psColFilterPopup(\''+key+'\',event)" ondblclick="event.stopPropagation();document.getElementById(\'jcolPopup\')?.remove();psColRename(\''+key+'\')">'+lab+'</span>'
    + (act ? '<span class="jcol-filter-clear" title="Clear search" onclick="event.stopPropagation();psColFilterClear(\''+key+'\',event)">✕</span>' : '');
}
function psColFilterPopup(key, ev) {
  ev.stopPropagation();
  document.getElementById('jcolPopup')?.remove();
  const th = ev.currentTarget.closest('th');
  const popup = document.createElement('div');
  popup.id = 'jcolPopup'; popup.className = 'jcol-filter-popup';
  popup.innerHTML = '<label>Search '+escH(_psKeyLabel(key))+'</label>'
    + '<input type="text" id="jcolInput" placeholder="Type to search…" value="'+escH(psColFilters()[key]||'')+'" onkeydown="if(event.key===\'Enter\')psColFilterApply(\''+key+'\')"/>'
    + '<div class="jcol-filter-row"><button class="jcol-filter-apply" onclick="psColFilterApply(\''+key+'\')">Apply</button>'
    + '<button class="jcol-filter-clearbtn" onclick="psColFilterClear(\''+key+'\')">Clear</button></div>';
  document.body.appendChild(popup);
  const rect = th.getBoundingClientRect();
  requestAnimationFrame(function(){
    const pw = popup.offsetWidth || 220, ph = popup.offsetHeight || 112;
    popup.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - pw - 8))+'px';
    let top = rect.bottom + 6; if (top + ph > window.innerHeight) top = Math.max(8, rect.top - ph - 6);
    popup.style.top = top+'px';
  });
  document.getElementById('jcolInput').focus();
  setTimeout(function(){
    document.addEventListener('click', function onDoc(e){
      if (!e.target.closest('#jcolPopup') && !e.target.closest('.jcol-filter-label')) { popup.remove(); document.removeEventListener('click', onDoc); }
    });
  }, 10);
}
function psColFilterApply(key) {
  const input = document.getElementById('jcolInput');
  psColFilters()[key] = input ? input.value.trim() : '';
  document.getElementById('jcolPopup')?.remove();
  _psSaveFilters(); renderProductsPage();
}
function psColFilterClear(key, ev) {
  if (ev) ev.stopPropagation();
  psColFilters()[key] = '';
  document.getElementById('jcolPopup')?.remove();
  _psSaveFilters(); renderProductsPage();
}
function psColFilterClearAll() { const f = psColFilters(); Object.keys(f).forEach(k=>{ f[k]=''; }); _psSaveFilters(); renderProductsPage(); }
function _psColMin() { return _psSettingGet('colMin', {}); }
function psColToggleMin(key) {
  const m = Object.assign({}, _psColMin());
  if (m[key]) delete m[key]; else m[key] = true;
  _psSettingSet('colMin', m);
  psRenderTable();
}
// Posting accounts: choosing "Post to" gives the product its OWN account in the Chart of Accounts, named after
// the product, under the income account it sells into and (for goods) under the inventory account its stock sits in.
// Sales are then recorded in the first, cost of goods sold comes out of the second. Accounts made earlier
// (e.g. one per product type) are left alone.
async function psEnsureSub(type, parentName, subName) {
  parentName = (parentName || '').trim(); subName = (subName || '').trim();
  if (!parentName || !subName || !bkUser) return '';
  const list = accounts[type] || (accounts[type] = []);
  const parent = list.find(a => a.account_name === parentName);
  if (!parent) return '';
  const have = list.find(a => a.account_name === subName && a.parent_id === parent.id);
  if (have) return subName;
  const same = list.find(a => a.account_name === subName && a.id !== parent.id);
  if (same) {
    if (same.parent_id) {                       // made earlier under another account head: "Post to" changed, so move it
      const { error } = await bkDb.from('bk_accounts').update({ parent_id: parent.id }).eq('id', same.id);
      if (!error) { same.parent_id = parent.id; bdToast('Account "' + subName + '" moved under "' + parentName + '"'); return subName; }
    }
    return '';                                  // never take over an unrelated account that already has this name
  }
  const { data, error } = await bkDb.from('bk_accounts').insert({
    user_id: bkUser.id, ...acctBizStamp(), account_name: subName, record_type: type, opening_balance: 0, parent_id: parent.id,
  }).select().single();
  if (error || !data) return '';
  list.push(data);
  try { _jrnAcctPathMap = null; } catch (e) {}
  bdToast('✓ Account "' + subName + '" added under "' + parentName + '" in your Chart of Accounts');
  return subName;
}
// Which columns add a level to the account tree (Product name is always there). Product type is on by default.
function psSubColsGet() { const c = _psSettingGet('subCols', null); return Array.isArray(c) ? c : ['product_type']; }
// The tree under the "Post to" account for one product row: [Product type] › Product › [Size …]. Names of the deeper
// levels carry the product's name, so two products that share a size ("10 - 12.5 mm") never share one account.
function psSubNames(r) {
  const name = (r.name || '').trim(); if (!name) return [];
  const cols = psSubColsGet(), names = [];
  const typeVal = (r.product_type || '').trim();
  if (cols.includes('product_type') && typeVal && typeVal.toLowerCase() !== name.toLowerCase()) names.push(typeVal);
  names.push(name);
  const vals = [];
  _psEffectiveColOrder().forEach(k => {
    if (!cols.includes(k) || !_psCustomCols().some(c => c.key === k)) return;
    const v = String((r.custom && r.custom[k]) || '').trim();
    if (v) { vals.push(v); names.push(name + ' (' + vals.join(', ') + ')'); }
  });
  return names;
}
async function psEnsureChain(type, rootName, names) {
  let parent = rootName, last = '';
  for (const n of names) { const got = await psEnsureSub(type, parent, n); if (!got) break; parent = n; last = n; }
  return last;
}
// Accounts are no longer made for a product. The user picks an existing account from the Chart of Accounts
// (and creates any new one there); the product simply posts to what was picked.
async function psEnsureProductAccount(r) {
  if (!r._postDirty) return;                       // rows the user has not re-picked keep exactly what they have
  r.custom = r.custom || {};
  const has = (t, n) => (accounts[t] || []).some(a => a.account_name === n);
  if (r.income_account && has('income', r.income_account)) r.custom.__sub = r.income_account; else delete r.custom.__sub;
  if (r.custom.__inv && has('asset', r.custom.__inv)) r.custom.__invsub = r.custom.__inv; else delete r.custom.__invsub;
  delete r.custom.__path; delete r.custom.__ipath;
  r._postDirty = false;
}
// Rows whose account tree is out of date (the tree settings changed, or a type / size was edited) get re-saved.
function psTreeCheck() {
  return;   // accounts are no longer generated from product columns
  if (psRows._treeChecked) return; psRows._treeChecked = true;
  let any = false;
  psRows.forEach(r => {
    if (!(r.name || '').trim() || !(r.income_account || (r.custom && r.custom.__inv))) return;
    const sig = psSubNames(r).join('\u0001'), c = r.custom || {};
    if ((r.income_account && c.__path !== r.income_account + '>' + sig) || (c.__inv && c.__ipath !== c.__inv + '>' + sig)) { r.saved = false; any = true; }
  });
  if (any) psAutosaveTrigger();
}
// Accounts a product can post to: income accounts, and (goods only) inventory accounts. Product sub-accounts are not offered.
function psPostChoices() {
  const subs = new Set();
  psRows.forEach(r => { if (r.custom) { if (r.custom.__sub) subs.add(r.custom.__sub); if (r.custom.__invsub) subs.add(r.custom.__invsub); } });
  const income = (accounts.income || []).filter(a => !subs.has(a.account_name) && !a.parent_id).map(a => a.account_name);
  const inv = (accounts.asset || []).filter(a => !subs.has(a.account_name) && !a.parent_id && /inventor|stock/i.test(a.account_name)).map(a => a.account_name);
  return { income, inv };
}
function psPostCell(r, i) {
  const isSvc = psType === 'services';
  const chip = (txt, style) => '<span style="' + style + 'display:block;box-sizing:border-box;border-radius:6px;padding:2px 7px;font-size:0.68rem;line-height:1.3;white-space:normal;overflow-wrap:anywhere;max-width:100%;">' + escH(txt) + '</span>';
  const inc = r.income_account, inv = r.custom && r.custom.__inv;
  const _cn = (t, n) => { const a = (accounts[t] || []).find(x => x.account_name === n); const c = a ? String(_coaCodes()[a.id] || '').trim() : ''; return c ? c + ' · ' + n : n; };
  const chips = (inc ? chip(_cn('income', inc), 'background:var(--gold-dim);color:var(--gold);') : '') + (!isSvc && inv ? chip(_cn('asset', inv), 'background:var(--surface2);color:var(--off);border:1px solid var(--border2);') : '');
  return '<div class="ps-cell" style="display:flex;flex-direction:column;gap:3px;align-items:flex-start;justify-content:center;cursor:pointer;min-height:30px;padding:3px 4px;box-sizing:border-box;width:100%;overflow:visible;height:auto;line-height:1.3;" onclick="psPostMenu(event,' + i + ')">'
    + (chips || '<span style="color:var(--muted);font-size:0.72rem;">Auto-detect</span>') + '</div>';
}
function psPostMenu(ev, i) {
  ev.stopPropagation();
  document.getElementById('psPostPortal')?.remove();
  const r = psRows[i]; if (!r) return;
  r.custom = r.custom || {};
  const isSvc = psType === 'services';
  const wrap = document.createElement('div');
  wrap.id = 'psPostPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;';
  const menu = document.createElement('div');
  menu.className = 'col-menu';
  menu.style.cssText = 'position:fixed;z-index:12001;padding:8px 0;width:min(340px,calc(100vw - 16px));max-width:calc(100vw - 16px);display:flex;flex-direction:column;box-sizing:border-box;';
  menu.innerHTML = '<div style="padding:2px 12px 6px;font-size:0.64rem;color:var(--muted);line-height:1.4;">Pick the account this ' + (isSvc ? 'service' : 'product') + ' posts to. Income accounts take the sale' + (isSvc ? '' : '; asset accounts hold the stock') + '. Need a new one? Create it in the Chart of Accounts first.</div>'
    + '<div style="padding:0 10px 6px;"><input id="psPostQ" placeholder="Search by name or number…" autocomplete="off" style="width:100%;box-sizing:border-box;padding:7px 10px;border:1px solid var(--border2);border-radius:8px;background:var(--surface);color:var(--white);font-size:0.76rem;outline:none;"/></div>'
    + '<div id="psPostList" style="overflow-y:auto;flex:1;min-height:0;"></div>';
  wrap.addEventListener('click', e => { if (e.target === wrap) wrap.remove(); });
  wrap.appendChild(menu); document.body.appendChild(wrap);
  const list = menu.querySelector('#psPostList'), q = menu.querySelector('#psPostQ');
  const head = t => '<div style="padding:8px 12px 3px;font-size:0.6rem;font-weight:800;letter-spacing:0.08em;color:var(--muted);">' + t + '</div>';
  const row = (t, name, code, depth, on, label) => '<div data-t="' + t + '" data-n="' + escH(name) + '" style="padding:6px 12px 6px ' + (12 + depth * 14) + 'px;cursor:pointer;font-size:0.76rem;display:flex;gap:8px;align-items:baseline;'
    + (on ? 'background:var(--gold-dim);color:var(--gold);font-weight:700;' : 'color:var(--off);') + '"><span style="width:12px;flex:none;">' + (on ? '✓' : '') + '</span>'
    + (code ? '<span style="font-size:0.66rem;opacity:.75;flex:none;">' + escH(code) + '</span>' : '') + '<span style="flex:1;">' + escH(label || name) + '</span></div>';
  const draw = () => {
    const f = q.value.trim().toLowerCase(); let h = '';
    const types = isSvc ? ['income'] : ['income', 'asset'];
    types.forEach(t => {
      const cur = t === 'income' ? r.income_account : r.custom.__inv;
      let part = row(t, '', '', 0, !cur, t === 'income' ? 'Auto-detect' : 'None (generic Inventory / Stock)');
      let any = false;
      coaLayout(t).forEach(g => {
        let gh = '';
        g.items.forEach(it => {
          const all = [{ a: it.account, code: it.code, d: 0 }].concat(it.children.map(c => ({ a: c.account, code: c.code, d: c.depth })));
          all.forEach(x => {
            if (f && (x.a.account_name + ' ' + x.code).toLowerCase().indexOf(f) < 0) return;
            gh += row(t, x.a.account_name, x.code, x.d + 1, cur === x.a.account_name);
          });
        });
        if (gh) { any = true; part += '<div style="padding:6px 12px 2px;font-size:0.64rem;color:var(--muted);font-weight:700;">' + (g.code ? escH(g.code) + ' · ' : '') + escH(g.label || g.title) + '</div>' + gh; }
      });
      if (f && !any) part = '';
      if (part) h += head(t === 'income' ? 'INCOME ACCOUNTS — WHERE THE SALE GOES' : 'ASSET ACCOUNTS — WHERE THE STOCK SITS') + part;
    });
    list.innerHTML = h || '<div style="padding:14px;text-align:center;color:var(--muted);font-size:0.76rem;">No account matches.</div>';
  };
  list.addEventListener('click', e => {
    const el = e.target.closest('[data-t]'); if (!el) return;
    const t = el.getAttribute('data-t'), name = el.getAttribute('data-n') || '';
    if (t === 'income') r.income_account = name; else { if (name) r.custom.__inv = name; else { delete r.custom.__inv; delete r.custom.__invsub; } }
    r.saved = false; r._postDirty = true;
    wrap.remove(); psRenderTable(); psAutosaveTrigger();
  });
  q.oninput = draw; draw();
  const rect = ev.currentTarget.getBoundingClientRect(), vh = window.innerHeight;
  menu.style.maxHeight = Math.min(520, vh - 16) + 'px';
  const mh = Math.min(menu.offsetHeight, vh - 16), mw = menu.offsetWidth;
  menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - mw - 8)) + 'px';
  menu.style.top = Math.max(8, Math.min(rect.bottom + 4, vh - mh - 8)) + 'px';
  if (!('ontouchstart' in window)) setTimeout(() => q.focus(), 30);
}

// Only re-renders the table — dropdown stays untouched
function psRenderTable() {
  try { psTreeCheck(); } catch (e) {}
  const isSvc  = psType === 'services';
  const show   = function(id){ return _psIsColVisible(id); };
  const _subNames = new Set(psRows.map(r=>r.custom && r.custom.__sub).filter(Boolean));
  const incomeAccts = (accounts.income || []).filter(function(a){ return !_subNames.has(a.account_name); }).map(function(a){
    return '<option value="'+escH(a.account_name)+'">'+escH(a.account_name)+'</option>';
  }).join('');

  const colWidths = _psColWidths();
  const _bm = k => { const m = _psColMeta()[k]; return (m && m.type && (m.type!=='text' || (m.fields && m.fields.length))) ? m : null; };
  const colMin = _psColMin();
  const colFilt = psColFilters();
  const th = (key, extraCls, extraStyle) => {
    if (colMin[key]) return '<th class="col-head col-head-min" data-col-key="'+key+'" style="width:26px;min-width:26px;max-width:26px;cursor:pointer;" title="Expand '+escH(psColLabel(key))+'" onclick="psColToggleMin(\''+key+'\')">\u25B8</th>';
    const storedW = colWidths[key];
    const widthOverride = storedW ? 'width:'+storedW+'px;min-width:'+storedW+'px;' : '';
    return '<th class="col-head'+(extraCls?' '+extraCls:'')+'" data-col-key="'+key+'" style="'+(extraStyle||'')+widthOverride+'position:relative;">'+_psThInner(key, psColLabel(key), colFilt)
      + (key==='qty_date'?'':'<span class="ps-colgrab" data-grab="'+key+'" title="Hold and drag to move this column"></span>')
      + '<span class="col-tri" onclick="event.stopPropagation();psColMenuOpen(event,\''+key+'\')">\u25BC</span></th>';
  };

  // Column order is now a single reorderable list (built-in + custom keys
  // mixed together), instead of built-ins always rendering in a fixed
  // sequence before any custom column — this is what lets "Insert column
  // left/right" actually insert at the clicked position.
  const order = _psEffectiveColOrder();
  const psHiddenCustom = _psHiddenCustomCols();
  const customByKey = Object.fromEntries(_psCustomCols().map(c=>[c.key,c]));
  const visibleKeys = order.filter(key => {
    if (customByKey[key]) return !psHiddenCustom.includes(key);
    if (key === 'name') return true;
    if (!_psColApplies(key, isSvc)) return false;
    return show(key);
  });

  let thHtml = '<th style="width:36px;">S/N</th>';
  visibleKeys.forEach(key => {
    if (customByKey[key]) {
      if (colMin[key]) { thHtml += '<th class="col-head col-head-min" data-col-key="'+key+'" style="width:26px;min-width:26px;max-width:26px;cursor:pointer;" title="Expand '+escH(customByKey[key].name)+'" onclick="psColToggleMin(\''+key+'\')">\u25B8</th>'; return; }
      const storedW = colWidths[key];
      const customWidthStyle = storedW ? 'width:'+storedW+'px;min-width:'+storedW+'px;' : 'min-width:110px;';
      thHtml += '<th class="col-head" data-col-key="'+key+'" style="'+customWidthStyle+'position:relative;">'+_psThInner(key, customByKey[key].name, colFilt)
        + '<span class="ps-colgrab" data-grab="'+key+'" title="Hold and drag to move this column"></span>'
        + '<span class="col-tri" onclick="event.stopPropagation();psColMenuOpen(event,\''+key+'\')">\u25BC</span></th>';
    } else {
      const m = PS_BUILTIN_META[key] || {};
      thHtml += th(key, m.numClass?'num':null, m.style||'');
    }
  });
  thHtml += '<th style="width:28px;"></th>';

  const _visible = psRows.map(function(r,i){ return {r:r,i:i}; })
    .filter(function(o){ return _psRowVisible(o.r); });
  const bodyHtml = _visible.map(function(o){ const r=o.r, i=o.i;
    const atCost = psComputeConfiguredTotal(r, 'total_cost');
    const atSell = psComputeConfiguredTotal(r, 'total_sell');
    let td = psSel.active ? '<td class="ps-sn op-selcell"><span onclick="psSelToggle('+i+')" class="op-circle '+(psSel.picked.includes(i)?'on':'')+'"></span></td>' : '<td class="ps-sn">'+(i+1)+'</td>';
    visibleKeys.forEach(key => {
      const beforeLen = td.length;
      if (customByKey[key]) {
        const hasOverride = !!(r.customMeta && Object.prototype.hasOwnProperty.call(r.customMeta, key));
        const meta = hasOverride ? r.customMeta[key] : _psColMeta()[key];
        const val = (r.custom && r.custom[key]) || '';
        const onChangeExpr = `psCustomInput(${i},'${key}',VALUE)`;
        const cellHtml = renderAssignedCell(meta, val, onChangeExpr, null, 'ps-cell', psSheet.wrap==='wrap');
        td += '<td style="position:relative;">'
          + cellHtml
          + '<span class="ps-cell-assign-trigger'+(hasOverride?' ps-cell-assign-override':'')+'"'
          + ' title="'+(hasOverride?'Type overridden for this cell — click to change':'Change type for just this cell')+'"'
          + ' onclick="event.stopPropagation();psCellAssignCells('+i+',\''+key+'\')">\u2699</span>'
          + '</td>';
        const patched0 = td.slice(beforeLen).replace(/^<td/, `<td data-col-key="${key}" class="ps-align-${_psEffectiveColAlign(key)}${colMin[key]?' col-min-cell':''}"`);
        td = td.slice(0, beforeLen) + patched0;
        return;
      }
      switch(key) {
        case 'name': if (_bm('name')) { td += '<td>'+renderAssignedCell(_bm('name'), r.name, 'psRows['+i+'].name=VALUE;psRows['+i+'].saved=false', null, 'ps-cell')+'</td>'; break; }
          td += '<td>'+psTextCellHtml(r.name, (isSvc?'Service':'Product')+' name…', 'psRows['+i+'].name=this.value;psRows['+i+'].saved=false')+'</td>'; break;
        case 'barcode': td += '<td>' + (_bm('barcode') ? renderAssignedCell(_bm('barcode'), r.barcode, 'psRows['+i+'].barcode=VALUE;psRows['+i+'].saved=false', null, 'ps-cell') : '') + (_bm('barcode') ? '' : '<div style="display:flex;align-items:center;gap:3px;">'
          + psTextCellHtml(r.barcode, 'Scan or type…', 'psRows['+i+'].barcode=this.value;psRows['+i+'].saved=false', 'flex:1;min-width:0;')
          + '<button type="button" title="Scan barcode" onclick="bdOpenScanner(code=>{psRows['+i+'].barcode=code;psRows['+i+'].saved=false;renderProductsPage();})"'
          + ' style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:0.9rem;padding:2px 4px;flex-shrink:0;">\uD83D\uDCF7</button>'
          + '</div>') + '</td>'; break;
        case 'product_type': if (_bm('product_type')) { td += '<td>'+renderAssignedCell(_bm('product_type'), r.product_type, 'psRows['+i+'].product_type=VALUE;psRows['+i+'].saved=false', null, 'ps-cell')+'</td>'; break; }
          td += '<td>'+psTextCellHtml(r.product_type, 'e.g. Hair care…', 'psRows['+i+'].product_type=this.value;psRows['+i+'].saved=false')+'</td>'; break;
        case 'service_type': if (_bm('service_type')) { td += '<td>'+renderAssignedCell(_bm('service_type'), r.product_type, 'psRows['+i+'].product_type=VALUE;psRows['+i+'].saved=false', null, 'ps-cell')+'</td>'; break; }
          td += '<td>'+psTextCellHtml(r.product_type, 'e.g. Cleaning…', 'psRows['+i+'].product_type=this.value;psRows['+i+'].saved=false')+'</td>'; break;
        case 'cost_price': td += '<td><input class="ps-cell num" type="text" inputmode="decimal" value="'+(r.cost_price>0?r.cost_price.toLocaleString('en-NG'):'')+'"'
          + ' placeholder="0" onclick="this.select()" oninput="psAmtInput(this,'+i+',\'cost_price\')"/></td>'; break;
        case 'sell_price': td += '<td><input class="ps-cell num" type="text" inputmode="decimal" value="'+(r.sell_price>0?r.sell_price.toLocaleString('en-NG'):'')+'"'
          + ' placeholder="0" onclick="this.select()" oninput="psAmtInput(this,'+i+',\'sell_price\')"/></td>'; break;
        case 'qty': { const _qm = _bm('qty'); const _qu = (_qm && _qm.type==='measurement') ? _qm.unit : '';
          const _qin = '<input class="ps-cell num" type="text" inputmode="decimal" value="'+(r.qty>0?r.qty.toLocaleString('en-NG'):'')+'"'
          + ' placeholder="0" onclick="this.select()" oninput="psAmtInput(this,'+i+',\'qty\')"'+(_qu?' style="flex:1;min-width:0;"':'')+'/>';
          td += '<td>'+(_qu ? '<div style="display:flex;align-items:center;gap:4px;">'+_qin+'<span style="color:var(--muted);font-size:0.7rem;flex-shrink:0;padding-right:6px;">'+escH(_qu)+'</span></div>' : _qin)+'</td>'; break; }
        case 'qty_date': td += '<td><div class="ps-cell ps-date-cell" id="psQD_'+i+'" onclick="psOpenDatePicker(event,'+i+')" title="Click to pick a date — it updates by itself whenever the stock changes">'
          + escH(r.qty_date ? psFormatQtyDate(r.qty_date, _psQtyDateFormat()) : '')+'</div></td>'; break;
        case 'total_cost': td += '<td><div id="psAtCost_'+i+'" class="ps-cell ro num">'+(atCost>0?fmt(atCost):'')+'</div></td>'; break;
        case 'total_sell': td += '<td><div id="psAtSell_'+i+'" class="ps-cell ro num">'+(atSell>0?fmt(atSell):'')+'</div></td>'; break;
        case 'income_acct': td += '<td>' + psPostCell(r, i) + '</td>'; break;
        default: td += '<td></td>';
      }
      const patched = td.slice(beforeLen).replace(/^<td/, `<td data-col-key="${key}" class="ps-align-${_psEffectiveColAlign(key)}${colMin[key]?' col-min-cell':''}"`);
      td = td.slice(0, beforeLen) + patched;
    });
    td += '<td><button class="ps-del-btn" onclick="psDeleteRow('+i+')">&#x2715;</button></td>';
    return '<tr id="psRow_'+i+'">'+td+'</tr>';
  }).join('');

  const thead = document.getElementById('psThead');
  const tbody = document.getElementById('psBody');
  if (thead) thead.innerHTML = '<tr>'+thHtml+'</tr>';
  if (tbody) tbody.innerHTML = bodyHtml ||
    '<tr><td colspan="12" style="text-align:center;padding:24px;color:var(--muted);font-size:0.82rem;">No '+(isSvc?'services':'products')+' yet. Click + Add below.</td></tr>';

  psRenderTotalsRow(visibleKeys, customByKey, _visible.map(o=>o.r));
  bdApplyStickyLayout('.ps-table th', '.ps-total-row td');

  setTimeout(()=>initColumnResize('.ps-table', psColResized), 50);

  if (psSheet.wrap === 'wrap' && tbody) {
    tbody.querySelectorAll('.ps-cell-wrap').forEach(psAutoGrowCell);
  }
}


// Live comma-formatting for Products' price cells — same approach as
// the Journal's amount inputs (jAmtInput): strips everything but
// digits/decimal point (so a manually-typed comma is simply absorbed,
// not rejected), then reformats with thousand separators without
// erasing a decimal point mid-typing or jumping the cursor to the end.
// Generic version of the same live comma-formatting psAmtInput does,
// but usable anywhere an onChangeExpr callback is built (e.g. custom
// columns), not just built-in row fields. Reformats the cell's
// displayed value in place and returns the raw numeric string for the
// caller to use.
function psGenericAmtFormat(el) {
  const rawStr = el.value.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
  const dot = rawStr.indexOf('.');
  const intPart = dot >= 0 ? rawStr.slice(0, dot) : rawStr;
  const decPart = dot >= 0 ? '.' + rawStr.slice(dot + 1) : '';
  const formatted = (intPart ? intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',') : '') + decPart;
  if (el.value !== formatted) {
    const pos = el.selectionStart;
    const prevLen = el.value.length;
    el.value = formatted;
    const diff = formatted.length - prevLen;
    try { el.setSelectionRange(pos + diff, pos + diff); } catch(e) {}
  }
  return rawStr;
}
function psAmtInput(el, i, field) {
  const rawStr = el.value.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
  const raw = parseFloat(rawStr) || 0;
  psRows[i][field] = raw;
  psRows[i].saved = false;
  if (field === 'qty') {                       // Stock as at: follows every stock change
    psRows[i].qty_date = today();
    const qd = document.getElementById('psQD_'+i);
    if (qd) qd.textContent = psFormatQtyDate(psRows[i].qty_date, _psQtyDateFormat());
  }

  const dot = rawStr.indexOf('.');
  const intPart = dot >= 0 ? rawStr.slice(0, dot) : rawStr;
  const decPart = dot >= 0 ? '.' + rawStr.slice(dot + 1) : '';
  const formatted = (intPart ? intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',') : '') + decPart;
  if (el.value !== formatted) {
    const pos = el.selectionStart;
    const prevLen = el.value.length;
    el.value = formatted;
    const diff = formatted.length - prevLen;
    try { el.setSelectionRange(pos + diff, pos + diff); } catch(e) {}
  }

  psUpdateTotals(i);
}

function psUpdateTotals(i) {
  const r=psRows[i];
  const ac=document.getElementById(`psAtCost_${i}`), as_=document.getElementById(`psAtSell_${i}`);
  const atCost = psComputeConfiguredTotal(r, 'total_cost');
  const atSell = psComputeConfiguredTotal(r, 'total_sell');
  if(ac) ac.textContent=atCost>0?fmt(atCost):'';
  if(as_) as_.textContent=atSell>0?fmt(atSell):'';
  psRefreshTotalsRow();
}
// Recomputes the grand totals row from current state, without a full
// table rebuild — reads the live column set straight from the DOM
// (data-col-key, set on every <th>) so it always matches what's
// actually showing, including any search filter already applied.
function psRefreshTotalsRow() {
  const thead = document.getElementById('psThead');
  if (!thead) return;
  const visibleKeys = Array.from(thead.querySelectorAll('th[data-col-key]')).map(th => th.dataset.colKey);
  const customByKey = Object.fromEntries(_psCustomCols().map(c=>[c.key,c]));
  const visibleRows = psRows.filter(r => _psRowVisible(r));
  psRenderTotalsRow(visibleKeys, customByKey, visibleRows);
}

function psAddRow() {
  psSnapshot();
  psRows.push({id:null,name:'',barcode:'',product_type:'',cost_price:0,sell_price:0,qty:0,qty_date:'',unit:'unit',income_account:'',created_at:new Date().toISOString(),saved:false});
  renderProductsPage();
  setTimeout(()=>{ document.querySelectorAll('#psBody tr').item(psRows.length-1)?.querySelector('input')?.focus(); },40);
}

async function psDeleteRow(i) {
  psSnapshot();
  const row = psRows[i]; if (!row) return;
  psRows.splice(i,1);
  renderProductsPage();                       // gone from the screen at once; the database catches up behind it
  if (row.id) {
    try {
      const { error } = await bkDb.from('bk_products').update({is_active:false}).eq('id',row.id).eq('user_id',bkUser.id);
      if (error) throw error;
    } catch(e) {
      psRows.splice(Math.min(i, psRows.length), 0, row); renderProductsPage();
      bdToast('⚠ Could not delete — it has been put back', 'error');
    }
  }
}

async function psSaveRow(i) {
  const r=psRows[i]; const btn=document.querySelector(`#psRow_${i} .ps-save-btn`);
  if(!r.name.trim()) return;
  if (r.qty > 0 && !r.qty_date) r.qty_date = today();
  const _qm = _psColMeta()['qty'];
  if (_qm && _qm.type==='measurement' && _qm.unit) r.unit = _qm.unit;
  const payload = {
    product_name:r.name.trim(), price:r.sell_price, cost_price:r.cost_price,
    qty_in_stock:r.qty, unit:r.unit, product_type:r.product_type||null,
    qty_as_at:r.qty_date||null, income_account:r.income_account||null,
    barcode:r.barcode||null, custom:r.custom||{}, custom_meta:r.customMeta||{},
    updated_at:new Date().toISOString(),
  };
  let error = null;
  if(!r.id) {
    const res = await bkDb.from('bk_products').insert({
      ...payload, user_id:bkUser.id, business_id:activeBusiness?.id||null, is_service:psType==='services', is_active:true,
    }).select().single();
    error = res.error;
    if(!error && res.data){ psRows[i].id=res.data.id; psRows[i].saved=true; }
  } else {
    const res = await bkDb.from('bk_products').update(payload).eq('id',r.id).eq('user_id',bkUser.id);
    error = res.error;
    if(!error) psRows[i].saved=true;
  }
  if (error) {
    console.error('psSaveRow failed for row', i, error);
    if(btn){btn.textContent='⚠';btn.style.color='var(--red)';btn.title='Save failed: '+error.message;}
    return;
  }
  if(btn){btn.textContent='✓';btn.style.color='var(--green)';setTimeout(()=>{btn.textContent='›';btn.style.color='';},1500);}
}

// ── EXTENDED REPORTS ─────────────────────────────────────────
// An expenditure account's Cost-of-Sales-vs-Operating-Expenses split is
// normally guessed from its name. But the Chart of Accounts page lets a
// user manually move an account into "Cost of Sales / Production" or
// "Operating Expenses" (via the Move picker or a custom main sub-ledger
// under one of those exact titles) — that manual choice must win over
// the name guess everywhere the split is used (P&L, dropdown grouping,
// dashboard figures), or an account like "Consumption of Oxygen &
// Acetylene" that the user filed under Cost of Sales keeps showing up
// under Operating Expenses in the actual financial statements.
function isCOSAccount(name){
  const label = _coaMemb()[name];
  if (label === 'Cost of Sales / Production') return true;
  if (label === 'Operating Expenses') return false;
  return /cost of (goods|sales|production)|purchase|raw material|direct (labou?r|wages)|carriage inward|production/i.test(name||'');
}
function isFixedAsset(name){ return /equipment|machin|vehicle|motor|building|land|furniture|fixture|plant|computer|premise/i.test(name||''); }
function isLongTermLiab(name){ return /loan|mortgage|debenture|long[- ]?term/i.test(name||''); }

async function showReport(type) {
  bdSaveRoute('report:'+type);
  recordsPageChrome(); // hides toolbar, hero header; keeps equation
  document.getElementById('bkContent').innerHTML='<div class="bk-loading">Loading…</div>';
  const _rb = window._reportBiz;
  window._reportBizName = _rb ? _rb.name : null;
  try {
    const _rbid = _rb ? _rb.id : activeBusiness?.id;
    const {data, error} = await bkFetchAll(()=>{
      let _rq = bkDb.from('bk_transactions').select('record_type,debit,credit,account_name,txn_date').order('id');
      return _rbid
        ? _rq.or('business_id.eq.'+_rbid+',and(business_id.is.null,user_id.eq.'+bkUser.id+')')
        : _rq.eq('user_id', bkUser.id);
    });
    if (error) throw error;
    window._reportBiz = null;
    const T=data||[];
    const tots={capital:{dr:0,cr:0},liability:{dr:0,cr:0},asset:{dr:0,cr:0},income:{dr:0,cr:0},expenditure:{dr:0,cr:0}};
    const byAcct={capital:{},liability:{},asset:{},income:{},expenditure:{}};
    T.forEach(r=>{
      // Skip any row whose record_type isn't one of the five known
      // books — a stray or corrupted row (e.g. an old orphaned entry)
      // used to crash this whole page with `tots[r.record_type]` being
      // undefined, which — since nothing here caught it — left "Loading…"
      // on screen forever and made every refresh repeat the same crash.
      if (!tots[r.record_type]) return;
      tots[r.record_type].dr+=parseFloat(r.debit)||0;tots[r.record_type].cr+=parseFloat(r.credit)||0;
      const nm=r.account_name||'Unspecified';
      byAcct[r.record_type][nm]=(byAcct[r.record_type][nm]||0)+((parseFloat(r.debit)||0)-(parseFloat(r.credit)||0));
    });
    // Opening balances flow into the statements
    try {
      const {data:OBs} = await acctBizFilter(bkDb.from('bk_accounts')
        .select('account_name,record_type,opening_balance'));
      (OBs||[]).forEach(a=>{
        const ob = parseFloat(a.opening_balance)||0;
        if (!ob || !byAcct[a.record_type]) return;
        const nm = a.account_name||'Unspecified';
        const drNormal = a.record_type==='asset' || a.record_type==='expenditure';
        byAcct[a.record_type][nm] = (byAcct[a.record_type][nm]||0) + (drNormal ? ob : -ob);
        tots[a.record_type][drNormal?'dr':'cr'] += ob;
      });
    } catch(e){}
    window._reportByAcct = byAcct;
    if(type==='trial') renderTrialBalance(tots);
    else if(type==='pl')  renderPL(tots);
    else if(type==='bs')  renderBS(tots);
    else if(type==='cf')  renderCashFlow(T,tots);
    else if(type==='eq')  renderEquity(tots);
  } catch (e) {
    window._reportBiz = null;
    console.error('showReport failed:', e);
    document.getElementById('bkContent').innerHTML = `
      <div style="max-width:420px;margin:60px auto;text-align:center;padding:0 16px;">
        <div style="font-size:2rem;margin-bottom:10px;">⚠️</div>
        <div style="font-weight:800;color:var(--white);margin-bottom:6px;">Couldn't load this statement</div>
        <div style="font-size:0.82rem;color:var(--muted);margin-bottom:20px;">${escH(e?.message || 'An unexpected error occurred.')}</div>
        <button class="bk-btn bk-btn-gold" style="margin-right:8px;" onclick="showReport('${escJs(type)}')">↻ Retry</button>
        <button class="bk-btn bk-btn-outline" onclick="showDashboard()">← Back to Dashboard</button>
      </div>`;
  }
}

function renderCashFlow(T,tots) {
  const cashNames=(accounts['asset']||[]).filter(a=>a.account_name.toLowerCase().includes('cash')||a.account_name.toLowerCase().includes('bank')).map(a=>a.account_name);
  const cashIn=T.filter(r=>r.record_type==='asset'&&cashNames.includes(r.account_name)).reduce((a,r)=>a+(parseFloat(r.debit)||0),0);
  const cashOut=T.filter(r=>r.record_type==='asset'&&cashNames.includes(r.account_name)).reduce((a,r)=>a+(parseFloat(r.credit)||0),0);
  const incRec=tots.income.cr-tots.income.dr, expPaid=tots.expenditure.dr-tots.expenditure.cr;
  const capIn=tots.capital.cr-tots.capital.dr, loanIn=tots.liability.cr-tots.liability.dr;
  const loanRep=Math.max(0,tots.liability.dr-tots.liability.cr);
  document.getElementById('bkContent').innerHTML=`
    <div class="bk-content-header"><div class="bk-content-title">CASH FLOW STATEMENT</div>
      
    </div>
    <div class="report-wrap"><table class="report-table">
      <thead><tr><th>Activity</th><th class="num">Amount (${CURRENCIES[activeCurrency].symbol})</th></tr></thead>
      <tbody>
        <tr class="section-hdr"><td colspan="2">Operating Activities</td></tr>
        <tr><td>Income Received</td><td class="num" style="color:#4ade80;">${fmt(incRec)}</td></tr>
        <tr><td>Expenses Paid</td><td class="num" style="color:#f87171;">(${fmt(expPaid)})</td></tr>
        <tr><td><strong>Net from Operations</strong></td><td class="num"><strong>${fmt(incRec-expPaid)}</strong></td></tr>
        <tr class="section-hdr"><td colspan="2">Financing Activities</td></tr>
        <tr><td>Capital Contributions</td><td class="num" style="color:#4ade80;">${fmt(capIn)}</td></tr>
        <tr><td>Loans Received</td><td class="num" style="color:#4ade80;">${fmt(loanIn)}</td></tr>
        <tr><td>Loan Repayments</td><td class="num" style="color:#f87171;">(${fmt(loanRep)})</td></tr>
        <tr class="total-row"><td>NET CASH MOVEMENT</td><td class="num">${fmt(cashIn-cashOut)}</td></tr>
      </tbody>
    </table></div>`;
}

function renderEquity(tots) {
  const openCap=tots.capital.cr-tots.capital.dr;
  const netProfit=(tots.income.cr-tots.income.dr)-(tots.expenditure.dr-tots.expenditure.cr);
  const closing=openCap+netProfit;
  document.getElementById('bkContent').innerHTML=`
    <div class="bk-content-header"><div class="bk-content-title">STATEMENT OF EQUITY</div>
      
    </div>
    <div class="report-wrap"><table class="report-table">
      <thead><tr><th>Component</th><th class="num">Amount (${CURRENCIES[activeCurrency].symbol})</th></tr></thead>
      <tbody>
        <tr class="section-hdr"><td colspan="2">Equity Movement</td></tr>
        <tr><td>Opening Capital / Equity</td><td class="num">${fmt(openCap)}</td></tr>
        <tr><td>Add: Net ${netProfit>=0?'Profit':'Loss'}</td><td class="num" style="color:${netProfit>=0?'#4ade80':'#f87171'};">${netProfit<0?'-':''}${fmt(Math.abs(netProfit))}</td></tr>
        <tr class="${netProfit>=0?'profit-row':'loss-row'} total-row"><td>CLOSING EQUITY</td><td class="num">${fmt(closing)}</td></tr>
        <tr class="section-hdr"><td colspan="2">Capital Sub-accounts</td></tr>
        ${(accounts['capital']||[]).map(a=>`<tr><td>${escH(a.account_name)}</td><td class="num">—</td></tr>`).join('')}
      </tbody>
    </table>
    <p style="font-size:0.74rem;color:var(--muted);margin-top:14px;">ℹ Full equity breakdown requires transactions posted to specific equity sub-accounts.</p>
    </div>`;
}

