// ── Column widths for generic sales spreadsheet ──────────────
let staffColWidths = { sn:34, narration:110, price:110, qty:55, total:110, del:34 };

// ── Date formatting ──────────────────────────────────────────
// Places the cursor at the end of the field's current value, so an
// existing 0 or number can be deleted from the right with backspace
// rather than the user having to first move the cursor manually.
function staffCursorEnd(el){
  const len = el.value ? el.value.length : 0;
  try { el.setSelectionRange(len, len); } catch(e) { /* some input types don't support this */ }
}

function staffFormatDate(dateStr, fmt) {
  if (!dateStr) return '';
  const d = new Date(dateStr + 'T00:00:00');
  if (isNaN(d)) return dateStr;
  const days   = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const day = d.getDate();
  const ord = (n) => {
    if (n>3 && n<21) return n+'th';
    switch(n%10){case 1:return n+'st';case 2:return n+'nd';case 3:return n+'rd';default:return n+'th';}
  };
  if (fmt === 'day_date_year') {
    return days[d.getDay()]+'/'+ord(day)+'/'+months[d.getMonth()]+'/'+d.getFullYear();
  }
  if (fmt === 'month_day_year') {
    return months[d.getMonth()]+'/'+ord(day)+'/'+d.getFullYear();
  }
  if (fmt === 'dd/mm/yyyy') return String(day).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear();
  if (fmt === 'mm/dd/yyyy') return String(d.getMonth()+1).padStart(2,'0')+'/'+String(day).padStart(2,'0')+'/'+d.getFullYear();
  if (fmt === 'dd/mm/yy')   return String(day).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getFullYear()).slice(-2);
  return dateStr;
}

// ── Hide/show the global equation bar + quick input + toolbar
//    so staff pages get a clean, centered, distraction-free screen ──
