// OWNER/MANAGER-FACING STAFF DIRECTORY
// Lists registered staff and their position; click to open a chat.
// Test mode — sample data, chat messages are not persisted.
// ══════════════════════════════════════════════════════════════
// ── Real staff data — loaded from bk_business_profiles ────────
// Shared between owner's Staff directory and employee's Colleagues page
let liveStaffList = []; // populated by fetchStaffList()
let staffChatTarget = null;
let staffChatLog    = {}; // in-memory until Supabase chat table exists
let staffRealtimeChannel = null;

const ROLE_AVATAR = { owner:'👔', manager:'🗂️', employee:'👷' };
const ROLE_LABEL  = { owner:'Owner', manager:'Manager', employee:'Staff' };

// Fetch all users who share this business (same business_name in their profile)
async function fetchStaffList() {
  if (!bkUser || !businessDisplayName) return [];
  try {
    const { data } = await bkDb.from('bk_business_profiles')
      .select('user_id, staff_display_name, role, business_type')
      .eq('business_name', businessDisplayName);
    liveStaffList = (data||[]).map(function(p){
      return {
        id:       p.user_id,
        name:     p.staff_display_name || 'Staff Member',
        position: p.business_type || ROLE_LABEL[p.role] || 'Staff',
        role:     p.role || 'employee',
        avatar:   ROLE_AVATAR[p.role] || '👤',
      };
    });
  } catch(e) { liveStaffList = []; }
  return liveStaffList;
}

// ── Show/hide menu items based on the logged-in user's role ───
function applyRoleMenu(role){
  const isOwnerOrManager = (role === 'owner' || role === 'manager');
  const isEmployee = (role === 'employee');
  document.querySelectorAll('[data-role="owner-manager"]').forEach(function(el){
    el.style.display = isOwnerOrManager ? '' : 'none';
  });
  document.querySelectorAll('[data-role="employee"]').forEach(function(el){
    // Explicitly requires role to actually BE 'employee' — an
    // undefined/unset role (e.g. a brand-new user still mid-setup,
    // before their role is determined) previously fell through to
    // showing these by default, which is exactly why new users were
    // seeing "Colleagues" and the staff "Record" item they shouldn't.
    el.style.display = isEmployee ? '' : 'none';
  });
  document.querySelectorAll('[data-perm]').forEach(function(el){
    if (!isEmployee) return;
    el.style.display = bdCan(el.getAttribute('data-perm')) ? '' : 'none';
  });
}

// Settings means something different depending on who's logged in
function roleAwareSettings(){
  return userRole === 'employee' ? showStaffSettings() : showAccountSettings();
}

