function salesNumChange(i,field,val){
  salesRows[i][field]=parseFloat(String(val).replace(/,/g,''))||0;
  salesRows[i].total=salesRows[i].unit_price*(salesRows[i].qty||1);
  salesRows[i]._posted=false;
  const el=document.getElementById('sale_total_'+i);
  if(el) el.textContent=staffFmtAmt(salesRows[i].total);
  const gt=document.getElementById('sheetGrandTotal_sales');
  if(gt) gt.textContent=staffFmtAmt(salesRows.reduce((a,r)=>a+(r.total||0),0));
}

async function salesSaveRow(i){
  const r=salesRows[i];
  if(!r||!r.total) return;
  if(r._posted) return;
  const err = bdValidateSaleRow(r);
  if (err) { alert(err); return; }
  const btn=document.querySelector('#salesrow_'+i+' .staff-save-row-btn');
  if(btn){btn.textContent='...';btn.disabled=true;}
  try{
    if(navigator.onLine){
      await autoPostSaleRow(r,'',r.txn_date||new Date().toISOString().slice(0,10));
    } else {
      await bdSaveOffline(r,'',r.txn_date||new Date().toISOString().slice(0,10));
      bdUpdateSyncBadge();
    }
    salesRows[i]._posted=true;
    if(btn){btn.textContent='\u2713';btn.style.color='var(--green)';btn.disabled=true;}
  }catch(e){
    if(btn){btn.textContent='!';btn.style.color='var(--red)';btn.disabled=false;}
  }
}

async function salesSaveAll(){
  const date=new Date().toISOString().slice(0,10);
  const flat=[];
  for (const r of salesRows) {
    if (r._bundle && !r._posted) {
      const gid = (crypto.randomUUID ? crypto.randomUUID() : 'g'+Date.now()+Math.random().toString(16).slice(2));
      r.items.forEach(x=>{ if(x.total>0 && !x._posted){ x.txn_group_id=gid; x.pay_mode=r.pay_mode; flat.push(x); } });
      r._posted = true;
    } else if (!r._bundle && r.total>0 && !r._posted) flat.push(r);
  }
  const rows=flat;
  if(!rows.length){ alert('No new rows to save — all have already been posted.'); return; }
  for (const r of rows) {
    const err = bdValidateSaleRow(r);
    if (err) { alert(err); return; }
  }
  for(const r of rows){
    if(navigator.onLine) await autoPostSaleRow(r,'',r.txn_date||date);
    else { await bdSaveOffline(r,'',r.txn_date||date); }
    r._posted=true;
  }
  if(!navigator.onLine) bdUpdateSyncBadge();
  const msg=document.createElement('div');
  msg.style.cssText='position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#1a2a1a;border:1px solid var(--green);color:#4ade80;padding:10px 20px;border-radius:8px;font-size:0.82rem;font-weight:600;z-index:9999;white-space:nowrap;';
  msg.textContent='\u2713 '+rows.length+' sale'+(rows.length>1?'s':'')+(navigator.onLine?' posted':' saved offline');
  document.body.appendChild(msg);
  setTimeout(()=>msg.remove(),2500);
}

