// ── Sheet persistence: drafts per business per date ──────────
function sheetDraftKey(kind) {
  const st = sheetState[kind];
  const d = st.dateFrom || new Date().toISOString().slice(0,10);
  return 'bd_draft_'+kind+'_'+(activeBusiness?.id||'me')+'_'+d;
}
function sheetSaveDraft(kind) {
  try { localStorage.setItem(sheetDraftKey(kind), JSON.stringify(sheetRows(kind))); } catch(e){}
}
async function sheetRestore(kind) {
  // 1) unsaved draft for today?
  try {
    const draft = localStorage.getItem(sheetDraftKey(kind));
    if (draft) {
      const parsed = JSON.parse(draft);
      if (Array.isArray(parsed) && parsed.length) {
        if (kind==='sales') salesRows = parsed; else staffExpRows = parsed;
        return;
      }
    }
  } catch(e){}
  // 2) otherwise load today's posted transactions from the database
  if (!bkUser || !navigator.onLine) return;
  try {
    const today = (typeof window.today==='function') ? window.today() : new Date().toISOString().slice(0,10);
    const rt = kind==='sales' ? 'income' : 'expenditure';
    let {data:T} = await bkDb.from('bk_transactions').select('*')
      .match(bizMatch()).eq('record_type', rt)
      .eq('txn_date', today).order('created_at');
    if (kind==='sales') T = (T||[]).filter(salesIncomeShown);
    if (!T || !T.length) return;
    const flat = T.map((t,n)=>({
      sn:n+1, txn_date:t.txn_date||'', payee:t.payee||'', payer:t.payer||'', narration:t.narration||'', product:(kind==='sales'?(t.narration||''):''), unit_price:Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0)),
      qty:1, total:Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0)),
      pay_mode:t.payment_mode||'cash', _posted:true, _txnId:t.id, _jid:t.journal_id||null, _gid:t.txn_group_id||null,
    }));
    const loaded=[]; const seen={};
    for (const r of flat) {
      if (r._gid) {
        if (seen[r._gid]) { seen[r._gid].items.push(r); continue; }
        const b = { _bundle:true, items:[r], pay_mode:r.pay_mode, expanded:false, _posted:true };
        seen[r._gid]=b; loaded.push(b);
      } else loaded.push(r);
    }
    loaded.push(kind==='sales' ? staffEmptySaleRow(loaded.length+1) : staffEmptyExpRow(loaded.length+1));
    if (kind==='sales') salesRows = loaded; else staffExpRows = loaded;
  } catch(e){}
}

// ── Keep the Sales / Expenses sheets and the Master Journal in step ──
// Income (sales) or expenditure (expenses) entries made in the journal appear as rows here;
// entries changed or deleted in the journal are updated / removed here. Rows typed here are
// already posted into the journal by autosave, so they are matched and never doubled.
let _sheetSyncing = {};
async function sheetSyncFromJournal(kind, noRender) {
  if (!bkUser || !navigator.onLine || _sheetSyncing[kind]) return false;
  _sheetSyncing[kind] = true;
  try {
    const st = sheetState[kind];
    let from = st.dateFrom || today(), to = st.dateTo || from;
    const rt = kind==='sales' ? 'income' : 'expenditure';
    let qq = bkDb.from('bk_transactions').select('*').match(bizMatch()).eq('record_type', rt);
    if (st.allDates) qq = qq.order('txn_date',{ascending:false}).order('id');
    else qq = qq.gte('txn_date', from).lte('txn_date', to).order('created_at');
    const { data: T, error } = await qq;
    if (error || !T) return false;
    if (st.allDates) { T.reverse(); from = T.length >= 1000 ? (T[0].txn_date||'0000') : '0000'; to = '9999'; }
    const list = T.filter(t => t.account_name !== 'Cost of Goods Sold' && (kind !== 'sales' || salesIncomeShown(t)));
    const rows = sheetRows(kind);
    const flat = []; rows.forEach(r => { if (r._bundle) (r.items||[]).forEach(x=>flat.push({x, b:r})); else flat.push({x:r}); });
    const byJid = {}, byTxn = {};
    list.forEach(t => { if (t.journal_id) byJid[t.journal_id] = t; byTxn[t.id] = t; });
    const keyOf = (n, a) => Math.round((parseFloat(a)||0)*100) + '|' + String(n||'').trim().toLowerCase().slice(0,24);
    const used = new Set();                  // db txn ids already shown
    let changed = false;
    // 1) rows already shown: refresh clean ones, drop ones deleted in the journal
    const gone = [], ownCheck = [];
    flat.forEach(({x}) => {
      if (!x._posted) return;
      const t = (x._jid && byJid[x._jid]) || (x._txnId && byTxn[x._txnId]) || null;
      if (t) {
        used.add(t.id);
        const amt = Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0));
        if (!document.activeElement || !document.activeElement.closest || !document.activeElement.closest('#sheetTable_'+kind)) {
          if (x.narration !== (t.narration||'') || (x.payee||'') !== (t.payee||'') || (x.payer||'') !== (t.payer||'') || (x.txn_date||'') !== (t.txn_date||'') || Math.abs((x.total||0)-amt) > 0.004) {
            x.narration = t.narration||''; if (kind==='sales') x.product = t.narration||''; x.payee = t.payee||''; x.payer = t.payer||''; x.txn_date = t.txn_date||x.txn_date;
            if (Math.abs((x.total||0)-amt) > 0.004) { x.unit_price = amt/(x.qty||1); x.total = amt; }
            changed = true;
          }
        }
      } else if (x._txnId && x.txn_date >= from && x.txn_date <= to) gone.push(x);
      else if (x._jid && x.txn_date >= from && x.txn_date <= to) ownCheck.push(x);
    });
    if (ownCheck.length) {
      const { data: J, error: jerr } = await bkDb.from('bk_journal').select('id').in('id', ownCheck.map(x=>x._jid));
      if (!jerr && J) { const have = new Set(J.map(j=>j.id)); ownCheck.forEach(x=>{ if (!have.has(x._jid)) gone.push(x); }); }
    }
    // posted rows from older versions have no link: match them by text + amount
    const loose = {};
    flat.forEach(({x}) => { if (x._posted && !x._jid && !x._txnId) { const k = keyOf(x.narration, x.total); loose[k] = (loose[k]||0)+1; } });
    const fresh = [];
    list.forEach(t => {
      if (used.has(t.id)) return;
      const amt = Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0));
      const k = keyOf(t.narration, amt);
      if (loose[k]) { loose[k]--; return; }
      fresh.push({ sn:0, txn_date:t.txn_date||'', payee:t.payee||'', payer:t.payer||'', narration:t.narration||'', product:(kind==='sales'?(t.narration||''):''),
        unit_price:amt, qty:1, total:amt, pay_mode:t.payment_mode||'cash', _posted:true, _txnId:t.id, _jid:t.journal_id||null });
    });
    if (gone.length) {
      gone.forEach(x => { for (let i=rows.length-1;i>=0;i--) { const r=rows[i]; if (r===x) rows.splice(i,1); else if (r._bundle) { const j=r.items.indexOf(x); if (j>=0) { r.items.splice(j,1); if(!r.items.length) rows.splice(i,1); } } } });
      changed = true;
    }
    if (fresh.length) {
      let last = -1; rows.forEach((r,i)=>{ if (r._bundle || r.total>0 || r.narration || r.payee || r.payer || r.product) last = i; });
      rows.splice(last+1, 0, ...fresh); changed = true;
    }
    if (changed) {
      const blank = r => !r._bundle && !(r.total>0 || r.narration || r.payee || r.payer || r.product);
      if (!rows.length || !blank(rows[rows.length-1])) {
        const nr = kind==='sales' ? staffEmptySaleRow(rows.length+1) : staffEmptyExpRow(rows.length+1);
        const first = rows.find(x=>!x._bundle && !x._posted); if (first && first.txn_date) nr.txn_date = first.txn_date;
        rows.push(nr);
      }
      rows.forEach((r,i)=>{ if (!r._bundle) r.sn = i+1; });
      sheetSaveDraft(kind);
      if (!noRender) {
        const ae = document.activeElement;
        if (!(ae && ae.closest && ae.closest('#sheetTable_'+kind) && /INPUT|SELECT|TEXTAREA/.test(ae.tagName))) renderRecordSheet(kind);
      }
    }
    return changed;
  } catch(e) { return false; }
  finally { _sheetSyncing[kind] = false; }
}
// While a sheet is on screen: refresh from the journal when you come back to the tab and every 15 s.
setInterval(function(){
  if (document.hidden) return;
  ['sales','expenses'].forEach(function(k){ if (document.getElementById('sheetTable_'+k)) sheetSyncFromJournal(k); });
}, 15000);
document.addEventListener('visibilitychange', function(){
  if (document.hidden) return;
  ['sales','expenses'].forEach(function(k){ if (document.getElementById('sheetTable_'+k)) sheetSyncFromJournal(k); });
});

// ── Excel-style drag fill: grab a cell's corner and drag down ─
(function(){
  let fill = null;
  document.addEventListener('pointerdown', e=>{
    const el = e.target;
    if (!(el.tagName==='INPUT' && (el.classList.contains('staff-cell')||el.classList.contains('bk-cell')))) return;
    const r = el.getBoundingClientRect();
    if (e.clientX < r.right-14 || e.clientY < r.bottom-14) return;
    const td = el.closest('td'), tr = el.closest('tr'), tb = el.closest('table');
    if (!td || !tr || !tb || !tb.tBodies[0]) return;
    e.preventDefault();
    fill = { val: el.value, ci: td.cellIndex, tb, startTr: tr, range: null };
  }, true);
  document.addEventListener('pointermove', e=>{
    if (!fill) {
      const el = e.target;
      if (el && el.tagName==='INPUT' && (el.classList.contains('staff-cell')||el.classList.contains('bk-cell')) && !el.readOnly) {
        const r = el.getBoundingClientRect();
        el.style.cursor = (e.clientX > r.right-14 && e.clientY > r.bottom-14) ? 'crosshair' : '';
      }
      return;
    }
    e.preventDefault();
    const overTr = document.elementFromPoint(e.clientX, e.clientY)?.closest('tr');
    if (!overTr || overTr.closest('table') !== fill.tb) return;
    const trs = Array.from(fill.tb.tBodies[0].rows);
    const a = trs.indexOf(fill.startTr), b = trs.indexOf(overTr);
    if (a < 0 || b < 0) return;
    trs.forEach(t=>t.classList.remove('fill-hl'));
    const s = Math.min(a,b), en = Math.max(a,b);
    fill.range = [s,en];
    for (let k=s;k<=en;k++) trs[k].classList.add('fill-hl');
  });
  const finish = ()=>{
    if (!fill) return;
    const trs = Array.from(fill.tb.tBodies[0].rows);
    trs.forEach(t=>t.classList.remove('fill-hl'));
    if (fill.range) {
      const [s,en] = fill.range;
      for (let k=s;k<=en;k++) {
        const cell = trs[k].cells[fill.ci];
        const inp = cell && cell.querySelector('input');
        if (inp && !inp.readOnly && inp.value !== fill.val) {
          inp.value = fill.val;
          inp.dispatchEvent(new Event('input',{bubbles:true}));
        }
      }
    }
    fill = null;
  };
  document.addEventListener('pointerup', finish);
  document.addEventListener('pointercancel', finish);
  document.addEventListener('pointermove', e=>{
    if (fill) return;
    const el = e.target;
    if (!(el.tagName==='INPUT' && (el.classList.contains('staff-cell')||el.classList.contains('bk-cell')))) { return; }
    const r = el.getBoundingClientRect();
    el.style.cursor = (e.clientX >= r.right-14 && e.clientY >= r.bottom-14) ? 'crosshair' : '';
  });
})();
// ── Portal column menu: fixed-position, never clipped ──
function _sheetMeta(kind){ const st=sheetState[kind]; if(!st.colMeta){ try{ st.colMeta=JSON.parse(localStorage.getItem('bd_colmeta_'+kind)||'{}'); }catch(e){ st.colMeta={}; } } return st.colMeta; }
function sheetColAssignCells(kind, key) {
  const st = sheetState[kind];
  const c = st.colOrder.find(x=>x.k===key);
  if (!c || (c.t!=='c' && !['qty','payee','payer','product'].includes(key))) { alert('Cell types can be set on Payee, Payer, Product, Quantity and on custom columns you create. Other built-in columns keep their formats.'); return; }
  const meta = _sheetMeta(kind);
  openAssignCellsDialog(sheetColLabel(kind,c), meta[key], newMeta => {
    if (newMeta) meta[key]=newMeta; else delete meta[key];
    localStorage.setItem('bd_colmeta_'+kind, JSON.stringify(meta));
    renderRecordSheet(kind);
  });
}

// ── Tools: All dates / Cards-Sheet / Upload (same as the Master Journal) ──
function sheetFilterLabel(kind) {
  const st = sheetState[kind];
  if (st.allDates) return 'All dates';
  const d = st.dateFrom || today();
  const l = formatDateDisplay(d);
  return d === today() ? l + ' (Today)' : l;
}
function sheetFilterOpen(ev, kind) {
  ev.stopPropagation();
  const st = sheetState[kind];
  jcalOpen(ev.currentTarget, {
    value: st.allDates ? '' : (st.dateFrom || today()),
    clearLabel: 'All dates',
    onPick: function(d){ sheetSetFilterDate(kind, d); },
    onToday: function(){ sheetSetFilterDate(kind, today()); },
    onClear: function(){ sheetSetFilterDate(kind, null); }
  });
}
async function sheetSetFilterDate(kind, d) {
  const st = sheetState[kind];
  try { await sheetAutosave(kind); } catch(e) {}      // never lose a row that is still waiting to save
  st.allDates = !d; st.dateFrom = d || ''; st.dateTo = d || '';
  try { localStorage.setItem('bd_sheetfilter_'+kind+'_'+(activeBusiness?.id||bkUser?.id||'x'), d || 'all'); } catch(e) {}
  await sheetLoadDateRange(kind);
}
function sheetLoadFilterPref(kind) {
  const st = sheetState[kind];
  let v = null; try { v = localStorage.getItem('bd_sheetfilter_'+kind+'_'+(activeBusiness?.id||bkUser?.id||'x')); } catch(e) {}
  if (!v) return false;
  if (v === 'all') { st.allDates = true; st.dateFrom = ''; st.dateTo = ''; return true; }
  if (v === today()) { st.allDates = false; return false; }
  st.allDates = false; st.dateFrom = v; st.dateTo = v; return true;
}
function sheetSetView(kind, mode) {
  if (mode !== 'sheet' && mode !== 'cards') return;
  sheetState[kind].view = mode;
  try { localStorage.setItem('bd_sheetview_'+kind, mode); } catch(e) {}
  renderRecordSheet(kind);
}
// Upload runs the Master Journal's own upload flow; while it is open the journal page must not
// take over the screen, and when it closes the new entries are pulled into this sheet.
let _sheetUploadKind = null;
function sheetOpenUpload(kind) {
  _sheetUploadKind = kind;
  jrnOpenUploadModal();
  const t = setInterval(function(){
    if (document.getElementById('jrnUploadOverlay')) return;
    clearInterval(t); _sheetUploadKind = null;
    setTimeout(()=>sheetSyncFromJournal(kind), 1500);
    setTimeout(()=>sheetSyncFromJournal(kind), 5000);
  }, 400);
}

// ── Column width + minimize (both sheets) ──
function sheetColW(kind){ const st=sheetState[kind]; if(!st.colW){ try{ st.colW=JSON.parse(localStorage.getItem('bd_colw_'+kind)||'{}'); }catch(e){ st.colW={}; } } return st.colW; }
function sheetColMin(kind){ return {}; }   // minimize/expand arrows were removed — a column is always full width
function _sheetColPersist(kind){ try{ localStorage.setItem('bd_colw_'+kind, JSON.stringify(sheetColW(kind))); localStorage.setItem('bd_colmin_'+kind, JSON.stringify(sheetColMin(kind))); }catch(e){} }
function sheetColToggleMin(kind, key){ const m=sheetColMin(kind); if(m[key]) delete m[key]; else m[key]=true; _sheetColPersist(kind); renderRecordSheet(kind); }
function sheetApplyMinCells(kind, cols, selCol){
  const m=sheetColMin(kind); const keys=Object.keys(m); if(!keys.length) return;
  const off = selCol?1:0;
  document.querySelectorAll('#sheetTable_'+kind+' tbody tr').forEach(tr=>{
    if (tr.classList.contains('op-bundle-row')) return;
    cols.forEach((c,ci)=>{ if(m[c.k]){ const td=tr.children[off+ci]; if(td) td.classList.add('col-min-cell'); } });
  });
}
function sheetColResizeStart(ev, kind, key){
  ev.preventDefault(); ev.stopPropagation();
  const th = ev.currentTarget.closest('th'); if(!th) return;
  const table = document.getElementById('sheetTable_'+kind);
  const ths = [...table.querySelectorAll('thead th')]; const idx = ths.indexOf(th);
  const colEl = table.querySelectorAll('colgroup col')[idx];
  const startX = ev.clientX, startW = th.getBoundingClientRect().width, startTbl = table.getBoundingClientRect().width;
  const w = sheetColW(kind);
  document.body.style.userSelect='none'; document.body.style.cursor='col-resize';
  const mv = e=>{
    const nw = Math.max(44, Math.min(700, Math.round(startW + (e.clientX-startX))));
    w[key]=nw; th.style.width=nw+'px'; if(colEl) colEl.style.width=nw+'px';
    const tw=(startTbl-startW+nw)+'px'; table.style.setProperty('width',tw,'important'); table.style.setProperty('min-width',tw,'important');
  };
  const up = ()=>{
    document.removeEventListener('pointermove',mv); document.removeEventListener('pointerup',up); document.removeEventListener('pointercancel',up);
    document.body.style.userSelect=''; document.body.style.cursor='';
    _sheetColPersist(kind); renderRecordSheet(kind);
  };
  document.addEventListener('pointermove',mv); document.addEventListener('pointerup',up); document.addEventListener('pointercancel',up);
}
function sheetColFit(kind, key){
  const table = document.getElementById('sheetTable_'+kind); if(!table) return;
  const th=[...table.querySelectorAll('thead th')].find(t=>t.querySelector('.col-grip') && t.getAttribute('onclick') && t.getAttribute('onclick').includes("'"+key+"'")); if(!th) return;
  const idx=[...th.parentNode.children].indexOf(th);
  const cv=document.createElement('canvas').getContext('2d');
  let max=0;
  table.querySelectorAll('tbody tr').forEach(tr=>{
    if(tr.classList.contains('op-bundle-row')) return;
    const td=tr.children[idx]; if(!td) return;
    const el=td.querySelector('input,select,.staff-cell,.bk-date-disp-overlay')||td;
    const cs=getComputedStyle(el); cv.font=cs.fontWeight+' '+cs.fontSize+' '+cs.fontFamily;
    const txt = el.tagName==='SELECT' ? (el.options[el.selectedIndex]||{}).text||'' : (el.value!==undefined&&el.value!=='' ? el.value : (el.textContent||''));
    max=Math.max(max, cv.measureText(txt).width + (key==='unit_price'?34:0));
  });
  cv.font='700 11px sans-serif'; max=Math.max(max, cv.measureText((th.textContent||'')).width);
  sheetColW(kind)[key]=Math.max(60, Math.min(600, Math.ceil(max)+36));
  _sheetColPersist(kind); renderRecordSheet(kind);
}

// ── Sales sheet: Date / Payee / Payer / Narration behave like the Master Journal ──
// Payee / Payer / Product cells follow the column's Assign Cells choice. With nothing assigned they keep their default
// (the payee/payer dropdown, or the product picker on the Sales sheet).
function sheetFieldAssigned(kind, f, r, i) {
  const m = _acNormalizeMeta(_sheetMeta(kind)[f]);
  if (!m || !m.type) return '';
  if (m.type === 'text' && !(m.fields && m.fields.length)) return '';
  const val = m.type === 'text' ? ((r.custom && r.custom['_' + f]) || '') : (r[f] || '');
  return renderAssignedCell(m, val, `sheetFieldSet('${kind}',${i},'${f}',VALUE)`);
}
function sheetFieldSet(kind, i, f, v) {
  const r = sheetRows(kind)[i]; if (!r) return;
  const m = _acNormalizeMeta(_sheetMeta(kind)[f]);
  if (m && m.type === 'text' && m.fields) {
    r.custom = r.custom || {}; r.custom['_' + f] = v;
    const pv = fxParse(v, m.fields);
    const mains = m.fields.filter(x => x.main && pv[x.label]).map(x => pv[x.label]);
    r[f] = (mains.length ? mains : m.fields.map(x => pv[x.label]).filter(Boolean)).join(', ');
  } else r[f] = v;
  r._posted = false;
  if (f === 'product' && kind === 'sales') { r.narration = r.product; r.product_id = null; r._ptyped = true; }
}
function sheetRowSet(kind, i, field, val) {
  const r = sheetRows(kind)[i]; if (!r) return;
  r[field] = val; r._posted = false;
}
function bundleItemSetText(kind, bIdx, j, field, val) {
  const b = sheetRows(kind)[bIdx]; if (!b || !b._bundle) return;
  const x = b.items[j]; if (!x) return;
  x[field] = val; x._posted = false; b._posted = false;
}
function sheetQtySet(kind, i, val) {
  const r = sheetRows(kind)[i]; if (!r) return;
  r.qty_raw = val;
  (kind==='sales' ? salesNumChange : staffExpNumChange)(i, 'qty', val);
}
function bundleItemQty(kind, bIdx, j, val) {
  const b = sheetRows(kind)[bIdx]; if (!b || !b._bundle) return;
  if (b.items[j]) b.items[j].qty_raw = val;
  bundleItemChange(kind, bIdx, j, 'qty', val);
}
// Click a date cell: the same in-app calendar the journal uses.
function salesDateOpen(kind, i, ev) {
  ev.stopPropagation();
  const r = sheetRows(kind)[i]; if (!r) return;
  const anchor = ev.currentTarget;
  jcalOpen(anchor, {
    value: r.txn_date || '',
    clearLabel: 'Clear',
    onPick: function(d){
      r.txn_date = d; r._posted = false; anchor.innerHTML = formatDateDisplay(d);
      const rows = sheetRows(kind);
      if (rows[i] === rows.find(x=>!x._bundle)) {        // first row: everyone under it follows
        rows.forEach((x,k)=>{ if (k>i && !x._bundle && !x._posted && !x._dateOwn) { x.txn_date = d; x._posted = false; } });
        renderRecordSheet(kind);
      } else r._dateOwn = true;
      sheetAutosaveTrigger(kind);
    },
    onClear: function(){ r.txn_date = ''; r._posted = false; anchor.innerHTML = '<span style="color:var(--muted2)">Date</span>'; }
  });
}
// Header 📅: start date + date format, exactly like the journal's header menu.
function salesDatePortal(ev, kind) {
  kind = kind || 'sales';
  closeColMenu();
  const rect = ev.target.getBoundingClientRect();
  const fmtPref = localStorage.getItem('bd_jrn_datefmt')||'mdy';
  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;';
  const menu = document.createElement('div');
  menu.className = 'col-menu';
  menu.style.cssText = 'position:fixed;z-index:12001;padding:12px;min-width:240px;';
  menu.innerHTML = `
    <label class="su-label">START DATE</label>
    <input type="date" class="bk-login-input" id="jdpDate" style="margin-bottom:10px;"/>
    <div class="su-label" style="margin-bottom:6px;">FORMAT</div>
    <label style="display:flex;gap:8px;align-items:center;font-size:0.74rem;color:var(--off);margin-bottom:6px;cursor:pointer;">
      <input type="radio" name="jdpFmt" value="mdy" ${fmtPref==='mdy'?'checked':''} style="accent-color:var(--gold);"/> MM/DD/Year= E.g: Jan/1st/2026
    </label>
    <label style="display:flex;gap:8px;align-items:center;font-size:0.74rem;color:var(--off);margin-bottom:6px;cursor:pointer;">
      <input type="radio" name="jdpFmt" value="dmy" ${fmtPref==='dmy'?'checked':''} style="accent-color:var(--gold);"/> DD/MM/Year= E.g: 1st/Jan/2026
    </label>
    <label style="display:flex;gap:8px;align-items:center;font-size:0.74rem;color:var(--off);margin-bottom:6px;cursor:pointer;">
      <input type="radio" name="jdpFmt" value="dm" ${fmtPref==='dm'?'checked':''} style="accent-color:var(--gold);"/> DD/MM= E.g: 1st/Jan
    </label>
    <label style="display:flex;gap:8px;align-items:center;font-size:0.74rem;color:var(--off);margin-bottom:10px;cursor:pointer;">
      <input type="radio" name="jdpFmt" value="md" ${fmtPref==='md'?'checked':''} style="accent-color:var(--gold);"/> MM/DD= E.g: Jan/1st
    </label>
    <button id="jdpApply" style="width:100%;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.74rem;padding:9px;border-radius:8px;cursor:pointer;">Apply</button>`;
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  wrap.appendChild(menu);
  document.body.appendChild(wrap);
  const mw = menu.offsetWidth||260, mh = menu.offsetHeight||260;
  menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - mw - 8))+'px';
  menu.style.top  = (rect.bottom+6+mh > window.innerHeight ? Math.max(8, rect.top-mh-6) : rect.bottom+6)+'px';
  menu.querySelector('#jdpApply').onclick = ()=>{
    const f = menu.querySelector('input[name=jdpFmt]:checked')?.value||'mdy';
    localStorage.setItem('bd_jrn_datefmt', f);
    const d = menu.querySelector('#jdpDate').value;
    closeColMenu();
    if (d) {
      // 1st row = chosen date, 2nd = next day, and so on (rows not yet posted).
      const base = new Date(d+'T00:00:00');
      sheetRows(kind).forEach((r,k)=>{
        if (r._posted || r._bundle) return;
        const dt = new Date(base); dt.setDate(dt.getDate()+k);
        r.txn_date = dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');
      });
    }
    renderRecordSheet(kind);
  };
}
// Column search (Payee / Payer / Narration), same popup and chips as the journal.
const SCOL_LABEL = { payee:'Payee', payer:'Payer', narration:'Narration', product:'Product' };
function _scolKey(kind) { return 'bd_scolfilters_'+kind+'_'+(activeBusiness?.id || bkUser?.id || 'default'); }
function sheetColFilters(kind) {
  const st = sheetState[kind];
  if (!st.colFilters) {
    try { st.colFilters = Object.assign({payee:'',payer:'',narration:'',product:''}, JSON.parse(localStorage.getItem(_scolKey(kind))||'{}')); }
    catch(e) { st.colFilters = {payee:'',payer:'',narration:'',product:''}; }
  }
  return st.colFilters;
}
function _scolSave(kind) { try { localStorage.setItem(_scolKey(kind), JSON.stringify(sheetState[kind].colFilters||{})); } catch(e) {} }
function scolApplyFilter(kind, col) {
  const input = document.getElementById('jcolInput');
  sheetColFilters(kind)[col] = input ? input.value.trim() : '';
  document.getElementById('jcolPopup')?.remove();
  _scolSave(kind); renderRecordSheet(kind);
}
function scolClearFilter(kind, col, ev) {
  if (ev) ev.stopPropagation();
  sheetColFilters(kind)[col] = '';
  document.getElementById('jcolPopup')?.remove();
  _scolSave(kind); renderRecordSheet(kind);
}
function scolClearAll(kind) {
  const f = sheetColFilters(kind); Object.keys(f).forEach(k=>{ f[k]=''; });
  _scolSave(kind); renderRecordSheet(kind);
}
function scolFilterBar(kind) {
  const f = sheetColFilters(kind);
  const chips = Object.keys(f).filter(k=>f[k]);
  if (!chips.length) return '';
  return '<div class="jrn-filterbar" style="padding:6px 16px;">' +
    chips.map(k=>'<span class="jrn-filter-chip">'+escH(SCOL_LABEL[k]||k)+': '+escH(f[k])+'<span class="x" onclick="scolClearFilter(\''+kind+'\',\''+k+'\',event)">✕</span></span>').join('') +
    '<span class="jrn-filter-clearall" onclick="scolClearAll(\''+kind+'\')">Clear all filters</span></div>';
}
function scolToggleFilterPopup(kind, col, ev) {
  ev.stopPropagation();
  document.getElementById('jcolPopup')?.remove();
  const th = ev.currentTarget.closest('th');
  const popup = document.createElement('div');
  popup.id = 'jcolPopup';
  popup.className = 'jcol-filter-popup';
  popup.innerHTML = '<label>Search '+escH(SCOL_LABEL[col]||col)+'</label>'+
    '<input type="text" id="jcolInput" placeholder="Type a name…" value="'+escH(sheetColFilters(kind)[col]||'')+'" onkeydown="if(event.key===\'Enter\')scolApplyFilter(\''+kind+'\',\''+col+'\')"/>'+
    '<div class="jcol-filter-row">'+
      '<button class="jcol-filter-apply" onclick="scolApplyFilter(\''+kind+'\',\''+col+'\')">Apply</button>'+
      '<button class="jcol-filter-clearbtn" onclick="scolClearFilter(\''+kind+'\',\''+col+'\')">Clear</button>'+
    '</div>';
  document.body.appendChild(popup);
  const rect = th.getBoundingClientRect();
  requestAnimationFrame(function(){
    const pw = popup.offsetWidth || 220, ph = popup.offsetHeight || 112;
    popup.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - pw - 8))+'px';
    let top = rect.bottom + 6; if (top + ph > window.innerHeight) top = Math.max(8, rect.top - ph - 6);
    popup.style.top = top+'px';
  });
  document.getElementById('jcolInput').focus();
  setTimeout(function(){
    document.addEventListener('click', function onDoc(e){
      if (!e.target.closest('#jcolPopup') && !e.target.closest('.jcol-filter-label')) { popup.remove(); document.removeEventListener('click', onDoc); }
    });
  }, 10);
}

function sheetColMenuOpen(ev, kind, key) {
  openColMenuPortal(ev, [
    ...((kind==='sales' && key==='product') ? [['\u2611 Assign products', "salesAssignProducts()"]] : []),
    ['\u270F\uFE0F Rename Header', "sheetColRename('"+kind+"','"+key+"')"],
    ['+ Insert column left', "sheetColInsert('"+kind+"','"+key+"','left')"],
    ['+ Insert column right', "sheetColInsert('"+kind+"','"+key+"','right')"],
    ['\uD83D\uDDD1 Delete column', "sheetColDelete('"+kind+"','"+key+"')"],
    ['\u2699 Assign Cells', "sheetColAssignCells('"+kind+"','"+key+"')"],
    ['\u2715 Clear column', "sheetColClear('"+kind+"','"+key+"')"],
    ['\uD83D\uDEAB\uD83D\uDC41 Hide column', "sheetColHide('"+kind+"','"+key+"')"],
  ]);
}

// ── ASSIGN CELLS ─────────────────────────────────────────────
// Shared by every spreadsheet-style page (Sales/Expenses sheet,
// Products/Services) to constrain what kind of value a custom column
// accepts. Column meta shape: null (free text) or
// { type: 'text'|'number'|'measurement'|'color'|'date'|'dropdown',
//   options?: string[], unit?: string }
const ASSIGN_CELL_TYPES = [
  ['text', 'Free text', ''],
  ['number', 'Number', ''],
  ['measurement', 'Measurement', '\u2014 e.g. kg, ltr, pcs'],
  ['color', 'Color', '\u2014 swatch picker'],
  ['date', 'Date', ''],
  ['dropdown', 'Dropdown list', '\u2014 fixed options'],
];
const ASSIGN_CELL_UNITS = ['kg','g','ton','tons','ltr','ml','pcs','box','mm','cm','m','ft','inch','inches','bag','dozen','pack'];

// Normalizes the legacy shape (a plain array of option strings, from
// before Assign Cells existed as "Edit cells") into the new typed
// object shape, so anyone's existing dropdown-list columns keep
// working exactly as before instead of silently reverting to text.
function _acNormalizeMeta(meta) {
  if (Array.isArray(meta)) return meta.length ? { type: 'dropdown', options: meta } : null;
  return meta || null;
}

function openAssignCellsDialog(title, currentMeta, onSave, resetOption, isCellScope) {
  closeColMenu();
  const cur = _acNormalizeMeta(currentMeta) || { type: 'text' };
  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:20px;';
  wrap.innerHTML = `<div class="col-menu" style="padding:16px;width:min(440px,94vw);max-height:92vh;overflow:auto;" onclick="event.stopPropagation()" onkeydown="event.stopPropagation()" onkeypress="event.stopPropagation()" onkeyup="event.stopPropagation()">
    <label class="su-label">ASSIGN CELLS \u2014 ${escH(title)}</label>
    <div style="font-size:0.64rem;color:var(--muted);margin-bottom:10px;">Choose what kind of value this ${isCellScope?'cell':'column'} accepts.</div>
    <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:12px;">
      ${ASSIGN_CELL_TYPES.map(([val,label,hint])=>`
        <label style="display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--border2);border-radius:7px;font-size:0.76rem;color:var(--white);cursor:pointer;">
          <input type="radio" name="acType" value="${val}" ${cur.type===val?'checked':''} onchange="acRenderSubFields('${val}')"/> ${label}
          ${hint?`<span style="color:var(--muted);font-size:0.68rem;">${hint}</span>`:''}
        </label>`).join('')}
    </div>
    <div id="acSubFields"></div>
    ${resetOption ? `<div id="acResetLink" style="text-align:center;font-size:0.7rem;color:var(--muted);text-decoration:underline;cursor:pointer;margin:2px 0 10px;">${escH(resetOption.label)}</div>` : ''}
    <div style="display:flex;gap:8px;margin-top:6px;">
      <button id="acCancel" style="flex:1;background:var(--surface2);color:var(--off);border:1px solid var(--border2);font-weight:700;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Cancel</button>
      <button id="acOk" style="flex:1;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Save</button>
    </div>
  </div>`;
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  document.body.appendChild(wrap);
  window._acCurrentMeta = cur;
  acRenderSubFields(cur.type||'text');
  wrap.querySelector('#acCancel').onclick = closeColMenu;
  if (resetOption) {
    wrap.querySelector('#acResetLink').onclick = () => { closeColMenu(); resetOption.onReset(); };
  }
  wrap.querySelector('#acOk').onclick = () => {
    const type = wrap.querySelector('input[name="acType"]:checked')?.value || 'text';
    let meta = null;
    if (type === 'text') {
      const fl = acReadFields().filter(f => f.label || f.detail).map((f, i) => Object.assign(f, { label: f.label || ('Item ' + (i + 1)) }));
      const st = document.querySelector('input[name="acShowTitle"]:checked');
      meta = fl.length ? { type: 'text', fields: fl, showTitle: st ? st.value === '1' : true } : null;
    } else if (type === 'measurement') {
      meta = { type, unit: document.querySelector('input[name="acUnitSel"]:checked')?.value || acUnits()[0] };
    } else if (type === 'date') {
      const on = document.getElementById('acAlertOn')?.checked;
      meta = on ? { type, alert: document.getElementById('acAlertSel').value } : { type };
    } else if (type === 'dropdown') {
      const opts = (document.getElementById('acOptions')?.value||'').split('\n').map(s=>s.trim()).filter(Boolean);
      if (!opts.length) { alert('Add at least one option, or choose Free text instead.'); return; }
      meta = { type, options: opts };
    } else {
      meta = { type };
    }
    closeColMenu();
    onSave(meta);
  };
}

const AC_ALERTS = [['3m', '3 months', 90], ['2m', '2 months', 60], ['1m', '1 month', 30], ['3w', '3 weeks', 21], ['2w', '2 weeks', 14], ['1w', '1 week', 7], ['5d', '5 days', 5], ['3d', '3 days', 3], ['1d', '1 day', 1]];
function acRenderSubFields(type) {
  const el = document.getElementById('acSubFields');
  if (!el) return;
  const cur = window._acCurrentMeta || {};
  if (type === 'text') {
    window._acFields = (cur.fields && cur.fields.length ? cur.fields : [{ label: '', detail: '', show: true, main: true }]).map(f => Object.assign({ detail: '' }, f));
    window._acShowTitle = cur.type === 'text' && cur.fields ? !!cur.showTitle : true;
    acFieldsPaint();
  } else if (type === 'measurement') {
    window._acUnitSel = cur.unit ? acUnitName(cur.unit) : '';
    acUnitPaint();
  } else if (type === 'dropdown') {
    el.innerHTML = `<label class="su-label">Options</label>
      <div style="font-size:0.64rem;color:var(--muted);margin-bottom:6px;">One option per line.</div>
      <textarea class="bk-login-input" id="acOptions" rows="4" style="margin-bottom:6px;resize:vertical;">${escH((cur.options||[]).join('\n'))}</textarea>`;
  } else if (type === 'color') {
    el.innerHTML = `<div style="font-size:0.68rem;color:var(--muted);margin-bottom:6px;">Cells in this column show a color swatch — click a cell to pick any color.</div>`;
  } else if (type === 'date') {
    const on = !!cur.alert && cur.type === 'date';
    el.innerHTML = `<div style="font-size:0.68rem;color:var(--muted);margin-bottom:8px;">Cells open the same calendar as Stock as at, with a Format switcher.</div>
      <div style="border:1px solid var(--border2);border-radius:8px;padding:10px;margin-bottom:8px;">
        <label style="display:flex;align-items:center;gap:8px;font-size:.78rem;color:var(--white);cursor:pointer;"><input type="checkbox" id="acAlertOn" ${on ? 'checked' : ''} onchange="document.getElementById('acAlertBox').style.display=this.checked?'':'none'"/> Alert me before this date <span style="color:var(--muted);font-size:.68rem">— e.g. stock expiry</span></label>
        <div id="acAlertBox" style="display:${on ? '' : 'none'};margin-top:8px;">
          <div style="font-size:.64rem;color:var(--muted);margin-bottom:4px;">Warn me this long before the date:</div>
          <select id="acAlertSel" class="bk-login-input" style="margin:0 0 6px;">${AC_ALERTS.map(([k, l]) => `<option value="${k}" ${cur.alert === k ? 'selected' : ''}>${l} before</option>`).join('')}</select>
          <div style="font-size:.64rem;color:var(--muted);">The cell then shows e.g. <b style="color:var(--gold)">Expires in 3 months</b> with the date underneath.</div>
        </div></div>`;
  } else {
    el.innerHTML = '';
  }
}

// ── Free text: Title / Details rows (max 5) ──────────────────
function acReadFields() {
  const rows = [...document.querySelectorAll('#acFields .ac-frow')];
  if (!rows.length) return window._acFields || [];
  return rows.map(r => ({ label: r.querySelector('.ac-fl').value.trim(), detail: r.querySelector('.ac-fd').value.trim(), show: r.querySelector('.ac-fs').checked, main: r.querySelector('.ac-fm').value === 'main' }));
}
function acFieldsPaint() {
  const el = document.getElementById('acSubFields'); if (!el) return;
  const f = window._acFields || [];
  const inp = 'background:var(--surface2);border:1px solid var(--border2);color:var(--white);border-radius:6px;padding:6px 8px;font-size:.74rem;font-family:inherit;min-width:0;width:100%;box-sizing:border-box;';
  el.innerHTML = `<label class="su-label">Cell content</label>
    <div style="font-size:0.64rem;color:var(--muted);margin-bottom:6px;">Write a <b>title</b> on the left and its <b>details</b> on the right (up to 10 rows). Tick the rows to show in the cell, and choose which are <b>Main</b> (large text) and which are <b>Sub</b> (smaller text underneath). Click a cell afterwards to type its own details.</div>
    <div style="border:1px solid var(--border2);border-radius:8px;padding:8px;margin-bottom:8px;background:var(--surface);">
      <div style="display:grid;grid-template-columns:1fr 1.3fr 34px 66px 22px;gap:5px;font-size:.6rem;color:var(--muted);font-weight:700;margin-bottom:4px;"><span>TITLE</span><span>DETAILS</span><span style="text-align:center">SHOW</span><span>ROLE</span><span></span></div>
      <div id="acFields">${f.map((x, i) => `<div class="ac-frow" style="display:grid;grid-template-columns:1fr 1.3fr 34px 66px 22px;gap:5px;align-items:center;margin-bottom:5px;">
        <input class="ac-fl" autocomplete="off" spellcheck="false" value="${escH(x.label)}" placeholder="e.g. Drug name" style="${inp}"/>
        <input class="ac-fd" autocomplete="off" spellcheck="false" value="${escH(x.detail || '')}" placeholder="e.g. Viskoback suspension" style="${inp}"/>
        <input type="checkbox" class="ac-fs" ${x.show !== false ? 'checked' : ''} style="justify-self:center;"/>
        <select class="ac-fm" style="${inp}padding:6px 4px;"><option value="main" ${x.main ? 'selected' : ''}>Main</option><option value="sub" ${x.main ? '' : 'selected'}>Sub</option></select>
        <button class="del-btn" ${f.length < 2 ? 'disabled style="opacity:.3"' : ''} onclick="acFieldDel(${i})" title="Remove row">✕</button></div>`).join('')}</div>
      ${f.length < 10 ? '<button class="bk-btn bk-btn-outline" style="font-size:.7rem;" onclick="acFieldAdd()">+ Add row</button>' : '<div style="font-size:.62rem;color:var(--muted)">Maximum of 10 rows.</div>'}
    </div>
    <div style="font-size:.7rem;color:var(--off);margin-bottom:10px;display:flex;gap:14px;flex-wrap:wrap;">
      <label style="cursor:pointer"><input type="radio" name="acShowTitle" value="1" ${window._acShowTitle ? 'checked' : ''}/> Show title and details</label>
      <label style="cursor:pointer"><input type="radio" name="acShowTitle" value="0" ${window._acShowTitle ? '' : 'checked'}/> Show details only</label></div>`;
}
function acFieldAdd() {
  window._acShowTitle = document.querySelector('input[name="acShowTitle"]:checked')?.value !== '0';
  const f = acReadFields(); if (f.length >= 10) return; f.push({ label: '', detail: '', show: true, main: false }); window._acFields = f; acFieldsPaint();
  const ins = document.querySelectorAll('#acFields .ac-fl'); if (ins.length) ins[ins.length - 1].focus();
}
function acFieldDel(i) {
  window._acShowTitle = document.querySelector('input[name="acShowTitle"]:checked')?.value !== '0';
  const f = acReadFields(); if (f.length < 2) return; f.splice(i, 1); window._acFields = f; acFieldsPaint();
}
// A cell's text is stored as readable lines: "Title: details", one per row.
function fxParse(v, fields) {
  const out = {}; const lines = String(v == null ? '' : v).split('\n');
  const mainF = fields.find(x => x.main) || fields[0];
  lines.forEach((l, i) => {
    const k = l.indexOf(': '); const lab = k > 0 ? l.slice(0, k) : null;
    const f = lab ? fields.find(x => x.label === lab) : null;
    if (f) out[f.label] = l.slice(k + 2);
    else if (i === 0 && l && !lab) out[mainF.label] = l;                       // older cells: first line is the main text
    else if (i === 0 && l && lab && !fields.some(x => x.label === lab)) out[mainF.label] = l;
  });
  return out;
}
function fxEncode(vals, fields) {
  const clean = x => String(x || '').replace(/\s*\n\s*/g, ' ').trim();
  return fields.filter(f => clean(vals[f.label])).map(f => f.label + ': ' + clean(vals[f.label])).join('\n');
}
function fxInner(meta, v) {
  const fields = meta.fields, vals = fxParse(v, fields);
  const line = f => (meta.showTitle ? '<span class="fx-t">' + escH(f.label) + ':</span> ' : '') + escH(vals[f.label]);
  const shown = fields.filter(f => f.show !== false && vals[f.label]);
  const mains = shown.filter(f => f.main), subs = shown.filter(f => !f.main);
  const first = fields.find(f => f.show !== false) || fields[0];
  return (mains.length ? mains.map(f => '<div class="fx-main">' + line(f) + '</div>').join('') : (subs.length ? '' : '<div class="fx-main"><span class="fx-ph">' + escH(first.label) + '…</span></div>')) +
    subs.map(f => '<div class="fx-sub">' + line(f) + '</div>').join('');
}
function fxCellHtml(meta, v, onChangeExpr, idHtml) {
  return `<div class="fx-cell" data-fx="${escH(JSON.stringify({ fields: meta.fields, showTitle: !!meta.showTitle }))}" onclick="fxOpen(event,this)">${fxInner(meta, v)}<input type="hidden" class="fx-val"${idHtml} value="${escH(v)}" oninput="${onChangeExpr.replace('VALUE', 'this.value')}"/></div>`;
}
function fxOpen(ev, cell) {
  ev.stopPropagation(); closeColMenu();
  let meta; try { meta = JSON.parse(cell.dataset.fx); } catch (e) { return; }
  const fields = meta.fields; const hid = cell.querySelector('input.fx-val');
  let vals = fxParse(hid.value, fields);
  if (!hid.value) vals = Object.fromEntries(fields.map(f => [f.label, f.detail || '']));   // empty cell starts from the details written in Assign Cells
  const wrap = document.createElement('div'); wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:20px;';
  wrap.innerHTML = `<div class="col-menu" style="padding:14px;width:min(340px,94vw);max-height:90vh;overflow:auto;" onclick="event.stopPropagation()" onkeydown="event.stopPropagation()" onkeypress="event.stopPropagation()" onkeyup="event.stopPropagation()">
    ${fields.map((f, i) => `<label class="su-label">${escH(f.label)}</label><input class="bk-login-input fx-in" data-i="${i}" value="${escH(vals[f.label] || '')}" style="margin-bottom:8px;"/>`).join('')}
    <div style="display:flex;gap:8px;margin-top:4px;"><button id="fxCancel" style="flex:1;background:var(--surface2);color:var(--off);border:1px solid var(--border2);font-weight:700;font-size:.76rem;padding:9px;border-radius:8px;cursor:pointer;">Cancel</button>
    <button id="fxOk" style="flex:1;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:.76rem;padding:9px;border-radius:8px;cursor:pointer;">Save</button></div></div>`;
  wrap.addEventListener('click', e => { if (e.target === wrap) closeColMenu(); });
  document.body.appendChild(wrap);
  const ins = [...wrap.querySelectorAll('.fx-in')]; ins[0] && ins[0].focus();
  const go = () => {
    const nv = {}; ins.forEach(inp => { nv[fields[+inp.dataset.i].label] = inp.value; });
    const enc = fxEncode(nv, fields); closeColMenu();
    hid.value = enc;
    [...cell.children].forEach(c => { if (c !== hid) c.remove(); });
    cell.insertAdjacentHTML('afterbegin', fxInner(meta, enc));
    hid.dispatchEvent(new Event('input', { bubbles: true }));
  };
  wrap.querySelector('#fxOk').onclick = go; wrap.querySelector('#fxCancel').onclick = closeColMenu;
  ins.forEach(i => i.addEventListener('keydown', e => { if (e.key === 'Enter') go(); }));
}

// ── Measurement units: one list to pick from, rename, delete and add to (saved instantly) ──
function acUnits() {
  try { const a = JSON.parse(localStorage.getItem('bd_ac_units') || 'null'); if (Array.isArray(a)) return a; } catch (e) {}
  return ASSIGN_CELL_UNITS.slice();
}
function acUnitsSave(list) { try { localStorage.setItem('bd_ac_units', JSON.stringify(list)); } catch (e) {} }
function acUnitAlias() { try { return JSON.parse(localStorage.getItem('bd_ac_unit_alias') || '{}') || {}; } catch (e) { return {}; } }
function acUnitName(u) { const m = acUnitAlias(); let n = 0; while (m[u] && n++ < 10) u = m[u]; return u; }
function acUnitPaint() {
  const el = document.getElementById('acSubFields'); if (!el) return;
  const list = acUnits(); let sel = window._acUnitSel;
  if (!sel || (!list.includes(sel) && !window._acUnitKeep)) sel = list.includes(sel) ? sel : (list[0] || '');
  window._acUnitSel = sel;
  const shown = list.includes(sel) || !sel ? list : list.concat([sel]);
  el.innerHTML = `<label class="su-label">Unit of measurement</label>
    <div style="font-size:.64rem;color:var(--muted);margin-bottom:6px;">Select the unit for this column. Rename any unit by typing over it, remove ones you don't need with ✕, or add your own below. Changes save instantly.</div>
    <div style="border:1px solid var(--border2);border-radius:8px;background:var(--surface);max-height:210px;overflow:auto;margin-bottom:8px;">
      ${shown.map((u, i) => `<div style="display:flex;align-items:center;gap:8px;padding:5px 8px;border-bottom:1px solid var(--border2);">
        <input type="radio" name="acUnitSel" value="${escH(u)}" ${u === sel ? 'checked' : ''} onchange="window._acUnitSel=this.value" title="Use this unit"/>
        <input class="ac-un" value="${escH(u)}" data-i="${i}" data-o="${escH(u)}" onchange="acUnitRename(this)" style="flex:1;min-width:0;background:transparent;border:1px solid transparent;color:var(--white);font-size:.78rem;padding:4px 6px;border-radius:5px;font-family:inherit;" onfocus="this.style.borderColor='var(--gold)'" onblur="this.style.borderColor='transparent'"/>
        <button class="del-btn" onclick="acUnitDel(${i})" title="Delete this unit">✕</button></div>`).join('') || '<div style="padding:12px;font-size:.72rem;color:var(--muted)">No units yet — add one below.</div>'}
    </div>
    <div style="display:flex;gap:6px;margin-bottom:10px;"><input id="acUnitNew" placeholder="Add a unit, e.g. Bottles" style="flex:1;min-width:0;background:var(--surface2);border:1px solid var(--border2);color:var(--white);border-radius:6px;padding:7px 9px;font-size:.76rem;font-family:inherit;" onkeydown="if(event.key==='Enter'){event.preventDefault();acUnitAdd();}"/><button class="bk-btn bk-btn-gold" style="font-size:.72rem;" onclick="acUnitAdd()">+ Add</button></div>`;
}
function acUnitRename(inp) {
  const list = acUnits(), i = +inp.dataset.i, old = inp.dataset.o, nv = inp.value.trim();
  if (!nv || nv === old) { inp.value = old; return; }
  if (list.some((u, k) => k !== i && u === nv)) { bdToast('That unit already exists'); inp.value = old; return; }
  if (i < list.length) list[i] = nv; else list.push(nv);
  acUnitsSave(list);
  const al = acUnitAlias(); delete al[nv]; al[old] = nv;
  try { localStorage.setItem('bd_ac_unit_alias', JSON.stringify(al)); } catch (e) {}
  if (window._acUnitSel === old) window._acUnitSel = nv;
  acUnitPaint();
}
function acUnitAdd() {
  const inp = document.getElementById('acUnitNew'); const v = (inp.value || '').trim(); if (!v) return;
  const list = acUnits();
  if (list.includes(v)) { bdToast('That unit already exists'); return; }
  list.push(v); acUnitsSave(list); window._acUnitSel = v; acUnitPaint(); document.getElementById('acUnitNew')?.focus();
}
function acUnitDel(i) {
  const list = acUnits(); const gone = list[i]; if (gone == null) return;
  list.splice(i, 1); acUnitsSave(list);
  if (window._acUnitSel === gone) window._acUnitSel = list[0] || '';
  acUnitPaint();
}

// ── Date cells: the Stock as at calendar, with its Format switcher ──
let _acCal = null, _acCalOut = null;
function acDateFmt() { try { const f = localStorage.getItem('bd_ac_datefmt'); if (f && PS_DATE_FORMAT_LABELS[f]) return f; } catch (e) {} return 'slash'; }
function acDateOpen(ev, el) {
  ev.stopPropagation(); acDateClose();
  const r = el.getBoundingClientRect(); const iso = el.dataset.iso || '';
  const base = iso ? new Date(iso + 'T00:00:00') : new Date();
  _acCal = { el, year: base.getFullYear(), month: base.getMonth() };
  const panel = document.createElement('div'); panel.id = 'acDatePanel'; panel.className = 'col-menu';
  panel.style.cssText = 'position:fixed;z-index:12001;padding:12px;width:270px;top:' + Math.min(r.bottom + 6, window.innerHeight - 360) + 'px;left:' + Math.max(8, Math.min(r.left, window.innerWidth - 286)) + 'px;';
  panel.addEventListener('click', e => e.stopPropagation());
  panel.innerHTML = acCalHtml(); document.body.appendChild(panel);
  setTimeout(() => { _acCalOut = e => { if (!panel.contains(e.target) && !e.target.closest('.ac-date')) acDateClose(); }; document.addEventListener('click', _acCalOut, true); }, 0);
}
function acDateClose() {
  document.getElementById('acDatePanel')?.remove();
  if (_acCalOut) { document.removeEventListener('click', _acCalOut, true); _acCalOut = null; }
  _acCal = null;
}
function acCalHtml() {
  const { year, month, el } = _acCal; const sel = el.dataset.iso || ''; const fmt = acDateFmt();
  const first = new Date(year, month, 1).getDay(), dim = new Date(year, month + 1, 0).getDate(), dpm = new Date(year, month, 0).getDate();
  let cells = ''; for (let i = 0; i < first; i++) cells += '<div class="ps-cal-day ps-cal-out">' + (dpm - first + i + 1) + '</div>';
  for (let d = 1; d <= dim; d++) { const iso = year + '-' + String(month + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0'); cells += '<div class="ps-cal-day' + (iso === sel ? ' ps-cal-selected' : '') + '" onclick="acDatePick(\'' + iso + '\')">' + d + '</div>'; }
  const tr = (7 - ((first + dim) % 7)) % 7; for (let i = 1; i <= tr; i++) cells += '<div class="ps-cal-day ps-cal-out">' + i + '</div>';
  return '<div style="position:relative;margin-bottom:10px;"><button onclick="acDateToggleFmt(event)" class="ps-cal-format-btn"><span>Format: ' + escH(PS_DATE_FORMAT_LABELS[fmt]) + '</span><span>▾</span></button>'
    + '<div id="acFormatMenu" class="ps-cal-format-menu hidden">' + Object.entries(PS_DATE_FORMAT_LABELS).map(([k, l]) => '<div class="ps-cal-format-opt" onclick="acDateSetFmt(\'' + k + '\')">' + l + '</div>').join('') + '</div></div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;"><button onclick="acCalNav(-1)" class="ps-cal-nav">‹</button><span style="font-size:0.78rem;font-weight:700;color:var(--white);">' + PS_MONTH_FULL[month] + ' ' + year + '</span><button onclick="acCalNav(1)" class="ps-cal-nav">›</button></div>'
    + '<div class="ps-cal-grid ps-cal-dow">' + ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => '<div>' + d + '</div>').join('') + '</div><div class="ps-cal-grid">' + cells + '</div>'
    + '<button onclick="acDatePick(\'\')" class="ps-cal-clear">Clear date</button>';
}
function acCalNav(d) { _acCal.month += d; if (_acCal.month < 0) { _acCal.month = 11; _acCal.year--; } if (_acCal.month > 11) { _acCal.month = 0; _acCal.year++; } document.getElementById('acDatePanel').innerHTML = acCalHtml(); }
function acDateToggleFmt(ev) { ev.stopPropagation(); document.getElementById('acFormatMenu')?.classList.toggle('hidden'); }
function acDateSetFmt(f) {
  try { localStorage.setItem('bd_ac_datefmt', f); } catch (e) {}
  if (document.getElementById('acDatePanel')) document.getElementById('acDatePanel').innerHTML = acCalHtml();
  document.querySelectorAll('.ac-date').forEach(acDatePaint);   // every date cell switches to the new format
}
function acDateInfo(iso, alertKey) {
  const per = AC_ALERTS.find(x => x[0] === alertKey); if (!per || !iso) return null;
  const t0 = new Date(); t0.setHours(0, 0, 0, 0);
  const d = Math.round((new Date(iso + 'T00:00:00') - t0) / 86400000);
  const n = (x, u) => x + ' ' + u + (x === 1 ? '' : 's');
  let text, cls;
  if (d < 0) { text = 'Expired ' + n(-d, 'day') + ' ago'; cls = 'ac-exp-bad'; }
  else if (d === 0) { text = 'Expires today'; cls = 'ac-exp-bad'; }
  else if (d <= 14) { text = 'Expires in ' + n(d, 'day'); cls = d <= per[2] ? 'ac-exp-warn' : 'ac-exp-ok'; }
  else if (d <= 60) { text = 'Expires in ' + n(Math.round(d / 7), 'week'); cls = d <= per[2] ? 'ac-exp-warn' : 'ac-exp-ok'; }
  else { text = 'Expires in ' + n(Math.round(d / 30), 'month'); cls = d <= per[2] ? 'ac-exp-warn' : 'ac-exp-ok'; }
  return { text, cls };
}
function acDatePaint(el) {
  const sp = el.querySelector('.ac-dtxt'); if (!sp) return;
  const iso = el.dataset.iso; if (!iso) { sp.innerHTML = '<span style="color:var(--muted)">Pick date</span>'; return; }
  const f = escH(psFormatQtyDate(iso, acDateFmt())), info = acDateInfo(iso, el.dataset.alert);
  sp.innerHTML = info ? '<div class="ac-exp ' + info.cls + '">' + escH(info.text) + '</div><div class="ac-expd">' + f + '</div>' : f;
}
function acDatePick(iso) {
  if (!_acCal) return; const el = _acCal.el; el.dataset.iso = iso;
  const hid = el.querySelector('input.ac-val'); hid.value = iso; acDatePaint(el); acDateClose();
  hid.dispatchEvent(new Event('input', { bubbles: true }));
}

// Renders one cell's <input>/<select> according to its column's Assign
// Cells type. onChangeExpr is a JS expression string containing the
// literal placeholder VALUE, substituted with the real change handler
// per call site (Sales/Expenses vs Products use different storage).
function renderAssignedCell(meta, value, onChangeExpr, idAttr, cellClass, wrapMode) {
  meta = _acNormalizeMeta(meta);
  cellClass = cellClass || 'staff-cell';
  const v = value || '';
  const idHtml = idAttr ? ` id="${idAttr}"` : '';
  if (meta && meta.type === 'text' && meta.fields && meta.fields.length) return fxCellHtml(meta, v, onChangeExpr, idHtml);
  if (!meta || !meta.type || meta.type === 'text') {
    if (wrapMode) {
      return `<textarea class="${cellClass} ps-cell-wrap"${idHtml} rows="1" oninput="${onChangeExpr.replace('VALUE','this.value')};psAutoGrowCell(this)">${escH(v)}</textarea>`;
    }
    return `<input class="${cellClass}"${idHtml} type="text" value="${escH(v)}" oninput="${onChangeExpr.replace('VALUE','this.value')}"/>`;
  }
  if (meta.type === 'number') {
    // type="text" with the same live comma-formatter used elsewhere —
    // not type="number", which can't display commas at all.
    return `<input class="${cellClass} num"${idHtml} type="text" inputmode="decimal" value="${v?Number(v).toLocaleString('en-NG'):''}" oninput="${onChangeExpr.replace('VALUE','psGenericAmtFormat(this)')}"/>`;
  }
  if (meta.type === 'measurement') {
    // Deliberately NOT comma-formatted — this type supports ranges like "0-5".
    // The unit follows any rename made in the unit list (ton -> tons).
    const unit = acUnitName(meta.unit || '');
    const unitSuffix = ' ' + unit;
    let num = v;
    if (v.endsWith(unitSuffix)) num = v.slice(0, -unitSuffix.length);
    else if (/\s+[^\s\d.,\-]+$/.test(v)) num = v.replace(/\s+[^\s\d.,\-]+$/, '');   // a value saved with an older unit name
    return `<div style="display:flex;align-items:center;gap:4px;"><input class="${cellClass} num" style="flex:1;min-width:0;"${idHtml} type="text" inputmode="decimal" value="${escH(num)}"
      oninput="${onChangeExpr.replace('VALUE', `this.value + ' ${escH(unit.replace(/'/g, "\\'"))}'`)}"/><span style="color:var(--muted);font-size:0.7rem;flex-shrink:0;padding-right:6px;">${escH(unit)}</span></div>`;
  }
  if (meta.type === 'date') {
    const info = acDateInfo(v, meta.alert);
    const shown = !v ? '<span style="color:var(--muted)">Pick date</span>' : (info ? `<div class="ac-exp ${info.cls}">${escH(info.text)}</div><div class="ac-expd">${escH(psFormatQtyDate(v, acDateFmt()))}</div>` : escH(psFormatQtyDate(v, acDateFmt())));
    return `<div class="ac-date" data-iso="${escH(v)}" data-alert="${escH(meta.alert || '')}" onclick="acDateOpen(event,this)"><span class="ac-dtxt">${shown}</span><span style="color:var(--muted);font-size:.7rem">\u25BE</span><input type="hidden" class="ac-val"${idHtml} value="${escH(v)}" oninput="${onChangeExpr.replace('VALUE','this.value')}"/></div>`;
  }
  if (meta.type === 'color') {
    const swatch = v || '#888888';
    return `<div style="display:flex;align-items:center;gap:6px;padding-left:6px;"><input type="color"${idHtml} value="${escH(swatch)}" style="width:26px;height:26px;padding:0;border:1px solid var(--border2);border-radius:5px;background:none;cursor:pointer;"
      oninput="${onChangeExpr.replace('VALUE','this.value')}"/><span style="color:var(--muted);font-size:0.68rem;">${escH(swatch)}</span></div>`;
  }
  if (meta.type === 'dropdown') {
    return `<select class="${cellClass}"${idHtml} onchange="${onChangeExpr.replace('VALUE','this.value')}">
      <option value=""></option>${(meta.options||[]).map(o=>`<option ${v===o?'selected':''}>${escH(o)}</option>`).join('')}</select>`;
  }
  return `<input class="${cellClass}"${idHtml} type="text" value="${escH(v)}" oninput="${onChangeExpr.replace('VALUE','this.value')}"/>`;
}

function openTextPortal(label, initial, cb) {
  closeColMenu();
  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:20px;';
  wrap.innerHTML = `<div class="col-menu" style="padding:14px;min-width:250px;max-width:340px;" onclick="event.stopPropagation()">
    <label class="su-label">${label}</label>
    <input class="bk-login-input" id="tpInput" value="${escH(initial||'')}" style="margin-bottom:10px;"/>
    <button id="tpOk" style="width:100%;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Save</button>
  </div>`;
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  document.body.appendChild(wrap);
  const inp = wrap.querySelector('#tpInput');
  inp.focus(); inp.select();
  const go = ()=>{ const v = inp.value.trim(); closeColMenu(); if (v) cb(v); };
  wrap.querySelector('#tpOk').onclick = go;
  inp.addEventListener('keydown', e=>{ if(e.key==='Enter') go(); });
}
function openOptionsPortal(label, initialArr, cb) {
  closeColMenu();
  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;padding:20px;';
  wrap.innerHTML = `<div class="col-menu" style="padding:14px;min-width:260px;max-width:360px;" onclick="event.stopPropagation()">
    <label class="su-label">${label}</label>
    <div style="font-size:0.64rem;color:var(--muted);margin-bottom:6px;">One option per line (e.g. Paid, Not paid). Leave empty to return to free text.</div>
    <textarea class="bk-login-input" id="opInput" rows="4" style="margin-bottom:10px;resize:vertical;">${escH((initialArr||[]).join('\n'))}</textarea>
    <button id="opOk" style="width:100%;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:9px;border-radius:8px;cursor:pointer;">Save</button>
  </div>`;
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  document.body.appendChild(wrap);
  wrap.querySelector('#opOk').onclick = ()=>{
    const v = wrap.querySelector('#opInput').value.split('\n').map(s=>s.trim()).filter(Boolean);
    closeColMenu(); cb(v);
  };
}

function bdToast(msg, kind){
  const m=document.createElement('div');
  const isErr = kind==='error';
  m.className = 'bd-toast' + (isErr ? ' bd-toast-err' : '');
  m.textContent=msg;
  document.body.appendChild(m);
  setTimeout(()=>{ m.style.transition='opacity 0.25s'; m.style.opacity='0'; setTimeout(()=>m.remove(),250); }, isErr?3200:2000);
}

// ── Universal save feedback: … while saving, ✓ when done ─────
async function bdSaveWrap(btn, fn) {
  if (!btn || btn.disabled) return;
  const original = btn.innerHTML;
  btn.disabled = true;
  btn.classList.add('bd-saving');
  btn.innerHTML = '<span class="bd-save-dots"><span></span><span></span><span></span></span>';
  try {
    await fn();
    btn.classList.remove('bd-saving');
    btn.classList.add('bd-saved');
    btn.innerHTML = '✓';
    setTimeout(()=>{ btn.classList.remove('bd-saved'); btn.innerHTML = original; btn.disabled = false; }, 900);
  } catch(e) {
    btn.classList.remove('bd-saving');
    btn.innerHTML = original;
    btn.disabled = false;
    bdToast('Save failed: '+(e?.message||e||'unknown error'), 'error');
  }
}

function closeColMenu(){ document.getElementById('colMenuPortal')?.remove(); }
function openColMenuPortal(ev, items) {
  ev.stopPropagation();
  closeColMenu();
  const rect = ev.target.getBoundingClientRect();
  const wrap = document.createElement('div');
  wrap.id = 'colMenuPortal';
  wrap.style.cssText = 'position:fixed;inset:0;z-index:12000;';
  const menu = document.createElement('div');
  menu.className = 'col-menu';
  menu.style.cssText = 'position:fixed;z-index:12001;';
  menu.innerHTML = items.map(([label,call])=>`<div class="col-menu-item" onclick="event.stopPropagation();closeColMenu();${call}">${label}</div>`).join('');
  wrap.addEventListener('click', e=>{ if(e.target===wrap) closeColMenu(); });
  wrap.appendChild(menu);
  document.body.appendChild(wrap);
  const vw = document.documentElement.clientWidth || window.innerWidth, vh = window.innerHeight;
  menu.style.boxSizing = 'border-box'; menu.style.width = Math.min(300, vw - 16)+'px';
  menu.style.left = '0px'; menu.style.top = '0px';
  // Measure the real size so long labels never run off the right/bottom edge.
  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let x = Math.max(8, Math.min(rect.right - mw, vw - mw - 12));
  // Always open BENEATH the three dots. If it would run off the bottom,
  // nudge the page up just enough to make room (never flip above).
  let y = rect.bottom + 4;
  if (y + mh > vh - 8) {
    try { window.scrollBy(0, Math.ceil(y + mh - (vh - 8))); } catch(e){}
    const r2 = ev.target.getBoundingClientRect(); y = r2.bottom + 4;
  }
  if (y + mh > vh - 8) {
    // The page could not scroll far enough: open above the button if it fits there, otherwise scroll inside the menu.
    const above = rect.top - mh - 4;
    if (above >= 8) y = above;
    else { y = Math.max(8, Math.min(y, vh - 128)); menu.style.maxHeight = Math.max(120, vh - y - 8)+'px'; menu.style.overflowY = 'auto'; }
  }
  menu.style.left = x+'px'; menu.style.top = y+'px';
}

function sheetHlCol(kind, key) {
  const st = sheetState[kind];
  st.hlCol = (st.hlCol===key) ? null : key;
  st.menuCol = null;
  renderRecordSheet(kind);
}
function sheetColMenu(kind, key) {
  const st = sheetState[kind];
  st.menuCol = (st.menuCol===key) ? null : key;
  renderRecordSheet(kind);
}
function sheetColRename(kind, key) {
  const st = sheetState[kind];
  const c = st.colOrder.find(x=>x.k===key);
  const cur = c ? sheetColLabel(kind,c) : '';
  st.menuCol = null;
  openTextPortal('RENAME HEADER', cur, name=>{
    if (c && c.t==='c') c.label = name;
    else { st.colLabels = st.colLabels||{}; st.colLabels[key] = name; }
    sheetPersistCols(kind);
    renderRecordSheet(kind);
  });
}
function sheetColInsert(kind, key, side) {
  const st = sheetState[kind];
  st.menuCol = null;
  const idx = st.colOrder.findIndex(x=>x.k===key);
  const at = side==='left' ? idx : idx+1;
  st.colOrder.splice(at, 0, {k:'c'+Date.now(), t:'c', label:'New Column'});
  sheetPersistCols(kind);
  renderRecordSheet(kind);
}
async function sheetColDelete(kind, key) {
  const st = sheetState[kind];
  const c = st.colOrder.find(x=>x.k===key);
  st.menuCol = null;
  if (!c || c.t!=='c') { alert('Built-in columns cannot be deleted — use Hide column instead.'); renderRecordSheet(kind); return; }
  if (!(await bdConfirm('Delete column "'+sheetColLabel(kind,c)+'" and its contents?'))) { renderRecordSheet(kind); return; }
  sheetSnapshot(kind);
  st.colOrder = st.colOrder.filter(x=>x.k!==key);
  sheetRows(kind).forEach(r=>{
    if (r._bundle) r.items.forEach(x=>{ if(x.custom) delete x.custom[key]; });
    else if (r.custom) delete r.custom[key];
  });
  sheetPersistCols(kind);
  renderRecordSheet(kind);
}
function sheetColClear(kind, key) {
  const st = sheetState[kind];
  st.menuCol = null;
  if (key==='total') { alert('Total is calculated — clear Unit Price or Quantity instead.'); renderRecordSheet(kind); return; }
  sheetSnapshot(kind);
  const clear = r => {
    if (key==='narration') r.narration='';
    else if (key==='date') r.txn_date='';
    else if (key==='payee' || key==='payer') r[key]='';
    else if (key==='product'){ r.product=''; r.product_id=null; }
    else if (key==='unit_price'){ r.unit_price=0; r.total=0; }
    else if (key==='qty'){ r.qty=1; delete r.qty_raw; r.total=r.unit_price*1; }
    else if (key==='pay_mode') r.pay_mode='cash';
    else if (r.custom) delete r.custom[key];
    r._posted=false;
  };
  sheetRows(kind).forEach(r=>{ if(r._bundle) r.items.forEach(clear); else clear(r); });
  renderRecordSheet(kind);
}
function sheetColHide(kind, key) {
  const st = sheetState[kind];
  st.menuCol = null;
  st.hidden = st.hidden||{};
  st.hidden[key] = true;
  if (st.hlCol===key) st.hlCol=null;
  sheetPersistCols(kind);
  renderRecordSheet(kind);
}
function sheetColUnhide(kind, key) {
  const st = sheetState[kind];
  if (st.hidden) delete st.hidden[key];
  sheetPersistCols(kind);
  renderRecordSheet(kind);
}
function sheetToggleReceipt(kind, on) {
  sheetState[kind].receipt = !!on;
  renderRecordSheet(kind);
}

// ── Receipt ──────────────────────────────────────────────────
function _receiptData(kind, i) {
  const r = sheetRows(kind)[i];
  let items = r._bundle ? r.items : [r];
  // Edited receipt rows (back page) override the item list
  const _ov = window._rcptOverrideRows || (function(){ try { const rec=_rcptStore()[_rcptKey(kind,i)]; return rec&&rec.versions.length ? rec.rows : null; } catch(e){ return null; } })();
  if (_ov && _ov.length) items = _ov.map(x=>({narration:x.narration + (x.s1?' — '+x.s1:'') + (x.s2?' / '+x.s2:''), unit_price:x.unit, qty:x.qty, total:x.total}));
  const subtotal = items.reduce((s,x)=>s+(x.total||0),0);
  const biz = activeBusiness || {};
  const payLabels = {cash:'Cash',transfer:'Bank Transfer',pos:'POS',cheque:'Cheque',credit:'On Credit'};
  return {
    bizName: biz.name || businessDisplayName || 'Business',
    bizAddr: biz.business_address || biz.address || '',
    bizPhone: profileData?.phone || '',
    bizEmail: bkUser?.email || '',
    when: new Date().toLocaleString('en-NG',{dateStyle:'full',timeStyle:'short'}),
    number: 'BD-' + (r._txnId ? String(r._txnId).slice(0,8).toUpperCase() : Date.now().toString(36).toUpperCase()),
    items, subtotal, vat: 0, discount: 0, total: subtotal,
    pay: payLabels[r.pay_mode||'cash'] || 'Cash',
  };
}
// ── Receipt back page: editable spreadsheet + versions ───────
function _rcptKey(kind, i) {
  const r = sheetRows(kind)[i];
  if (!r) return 'r'+i;
  if (r._bundle) return 'g'+(r.items[0]?.txn_group_id || r.items[0]?._gid || r.items[0]?._txnId || i);
  return 't'+(r._txnId || r.txn_group_id || i);
}
function _rcptStore(){ try { return JSON.parse(localStorage.getItem('bd_receipts')||'{}'); } catch(e){ return {}; } }
function _rcptSave(store){ localStorage.setItem('bd_receipts', JSON.stringify(store)); }
const RCPT_COLS_DEFAULT = [
  {k:'sn',label:'S/N'},{k:'narration',label:'Narration'},{k:'unit',label:'Unit Price'},
  {k:'qty',label:'Quantity'},{k:'total',label:'Total'},{k:'s1',label:'Status 1'},
  {k:'s2',label:'Status 2'},{k:'pay',label:'Payment mode'},{k:'del',label:''},{k:'save',label:''}
];
let _rcptCtx = null; // {kind,i,key,rec}

function showReceiptEdit(kind, i) {
  const key = _rcptKey(kind, i);
  const store = _rcptStore();
  if (!store[key]) {
    const d = _receiptData(kind, i);
    store[key] = {
      cols: JSON.parse(JSON.stringify(RCPT_COLS_DEFAULT)),
      meta: {},
      rows: d.items.map((x,n)=>({narration:x.narration||'', unit:x.unit_price||0, qty:x.qty||1, total:x.total||0, s1:'', s2:'', pay:d.pay})),
      versions: []
    };
    if (!store[key].rows.length) store[key].rows=[{narration:'',unit:0,qty:1,total:0,s1:'',s2:'',pay:'Cash'}];
    _rcptSave(store);
  }
  _rcptCtx = { kind, i, key };
  renderReceiptEdit();
}
function renderReceiptEdit(viewVersion) {
  const store = _rcptStore();
  const rec = store[_rcptCtx.key];
  const rows = (viewVersion!=null && rec.versions[viewVersion]) ? rec.versions[viewVersion].rows : rec.rows;
  const readonly = viewVersion!=null;
  const cols = rec.cols.filter(c=>!(rec.hidden||{})[c.k]);
  const overlay = document.getElementById('receiptOverlay');
  if (!overlay) return;
  const th = cols.map((c,ci)=>{
    const structural = c.k==='del'||c.k==='save'||c.k==='sn';
    const tri = structural ? '' : `<span class="col-tri col-tri-show" style="position:static;font-size:0.5rem;margin-left:3px;" onclick="event.stopPropagation();rcptColMenu(event,'${c.k}')">▼</span>`;
    return `<th style="white-space:nowrap;min-width:${c.k==='narration'?150:c.k==='sn'?40:(c.k==='del'||c.k==='save')?34:100}px;">${escH(c.label)}${tri}</th>`;
  }).join('');
  const body = rows.map((r,ri)=>'<tr>'+cols.map(c=>{
    const opts = (rec.meta||{})[c.k];
    const dis = readonly?'disabled':'';
    switch(c.k){
      case 'sn': return `<td style="text-align:center;color:var(--muted);">${ri+1}</td>`;
      case 'total': return `<td style="text-align:right;font-weight:700;" id="rcptTot_${ri}">${staffFmtAmt(r.total)}</td>`;
      case 'unit': case 'qty':
        return `<td><input class="staff-cell num" ${dis} type="text" inputmode="decimal" value="${r[c.k]||''}"
          oninput="rcptCell(${ri},'${c.k}',this.value)"/></td>`;
      case 'pay':
        return `<td><select class="staff-cell" ${dis} onchange="rcptCell(${ri},'pay',this.value)">
          ${['Cash','Bank Transfer','POS','Cheque','On Credit'].map(o=>`<option ${(r.pay||'Cash')===o?'selected':''}>${o}</option>`).join('')}</select></td>`;
      case 'del': return `<td><button class="staff-del-btn" ${dis} onclick="rcptDelRow(${ri})">&times;</button></td>`;
      case 'save': return `<td><button class="staff-save-row-btn" ${dis} onclick="bdSaveWrap(this,()=>rcptSaveRow(${ri}))">&rsaquo;</button></td>`;
      default: {
        if (opts && opts.length) return `<td><select class="staff-cell" ${dis} onchange="rcptCell(${ri},'${c.k}',this.value)">
          <option value=""></option>${opts.map(o=>`<option ${(r[c.k]||'')===o?'selected':''}>${escH(o)}</option>`).join('')}</select></td>`;
        return `<td><input class="staff-cell" ${dis} type="text" value="${escH(r[c.k]||'')}"
          oninput="rcptCell(${ri},'${c.k}',this.value)"/></td>`;
      }
    }
  }).join('')+'</tr>').join('');
  overlay.innerHTML = `
    <div id="receiptCard" style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;max-width:640px;width:100%;max-height:90vh;overflow-y:auto;padding:18px;" onclick="event.stopPropagation()">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
        <div style="font-weight:900;color:var(--gold);">Receipt — Back Page (Edit)</div>
        <select class="bk-login-input" style="width:auto;margin:0;font-size:0.7rem;padding:6px 8px;" onchange="renderReceiptEdit(this.value===''?null:parseInt(this.value))">
          <option value="">Current (editable)</option>
          ${rec.versions.map((v,vi)=>`<option value="${vi}" ${viewVersion===vi?'selected':''}>Version ${vi+1} — ${new Date(v.t).toLocaleString()}</option>`).join('')}
        </select>
      </div>
      <div style="font-size:0.64rem;color:var(--muted);margin:4px 0 10px;">Update items (e.g. 3 shirts deposited → 2 collected). Each › save creates a printable version.</div>
      <div class="bk-sheet-wrap" style="overflow-x:auto;">
        <table class="staff-table staff-table-compact" style="min-width:${cols.length*110}px;">
          <thead><tr>${th}</tr></thead>
          <tbody>${body}</tbody>
        </table>
      </div>
      ${readonly?'':'<button class="staff-add-cust-btn" style="margin-top:10px;" onclick="rcptAddRow()">+ Add Row</button>'}
      <div style="display:flex;gap:8px;margin-top:14px;">
        <button onclick="${readonly?`rcptPrintVersion(${viewVersion})`:'rcptSaveAll()'}" style="flex:1;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:10px;border-radius:8px;cursor:pointer;">${readonly?'🖨 Print this version':'💾 Save version'}</button>
        <button onclick="showReceipt('${_rcptCtx.kind}',${_rcptCtx.i})" style="background:var(--surface2);color:var(--gold);border:1px solid var(--gold);font-weight:800;font-size:0.76rem;padding:10px 14px;border-radius:8px;cursor:pointer;">↩ Front</button>
        <button onclick="document.getElementById('receiptOverlay').remove()" style="background:none;color:var(--muted);border:1px solid var(--border2);font-size:0.76rem;padding:10px 12px;border-radius:8px;cursor:pointer;">Close</button>
      </div>
    </div>`;
}
function rcptCell(ri, k, val) {
  const store = _rcptStore(); const rec = store[_rcptCtx.key]; const r = rec.rows[ri];
  if (k==='unit'||k==='qty') {
    r[k] = parseFloat(String(val).replace(/,/g,''))||0;
    r.total = (r.unit||0)*(r.qty||1);
    const t = document.getElementById('rcptTot_'+ri); if (t) t.textContent = staffFmtAmt(r.total);
  } else r[k] = val;
  _rcptSave(store);
}
function rcptAddRow(){ const s=_rcptStore(); s[_rcptCtx.key].rows.push({narration:'',unit:0,qty:1,total:0,s1:'',s2:'',pay:'Cash'}); _rcptSave(s); renderReceiptEdit(); }
function rcptDelRow(ri){ const s=_rcptStore(); const rec=s[_rcptCtx.key]; rec.rows.splice(ri,1); if(!rec.rows.length)rec.rows.push({narration:'',unit:0,qty:1,total:0,s1:'',s2:'',pay:'Cash'}); _rcptSave(s); renderReceiptEdit(); }
function rcptSaveRow(ri){ rcptSaveAll(); }
function rcptSaveAll() {
  const s = _rcptStore(); const rec = s[_rcptCtx.key];
  rec.versions.push({ t: Date.now(), rows: JSON.parse(JSON.stringify(rec.rows)) });
  _rcptSave(s);
  bdToast('\u2713 Receipt updated — version '+rec.versions.length+' saved');
  renderReceiptEdit();
}
function rcptPrintVersion(vi) {
  const rec = _rcptStore()[_rcptCtx.key];
  const rows = vi!=null && rec.versions[vi] ? rec.versions[vi].rows : rec.rows;
  window._rcptOverrideRows = rows;
  showReceipt(_rcptCtx.kind, _rcptCtx.i);
  setTimeout(()=>{ printReceipt(); window._rcptOverrideRows=null; }, 100);
}
function rcptColMenu(ev, key) {
  openColMenuPortal(ev, [
    ['\u270F\uFE0F Rename Header', "rcptColRename('"+key+"')"],
    ['+ Insert column left', "rcptColInsert('"+key+"','left')"],
    ['+ Insert column right', "rcptColInsert('"+key+"','right')"],
    ['\u2699 Edit cells', "rcptColEditCells('"+key+"')"],
    ['\uD83D\uDDD1 Delete column', "rcptColDelete('"+key+"')"],
    ['\u2715 Clear column', "rcptColClear('"+key+"')"],
    ['\uD83D\uDEAB\uD83D\uDC41 Hide column', "rcptColHide('"+key+"')"],
  ]);
}
function rcptColRename(key){ const s=_rcptStore(); const rec=s[_rcptCtx.key]; const c=rec.cols.find(x=>x.k===key); if(!c)return;
  openTextPortal('RENAME HEADER', c.label, v=>{ c.label=v; _rcptSave(s); renderReceiptEdit(); }); }
function rcptColInsert(key, side){ const s=_rcptStore(); const rec=s[_rcptCtx.key];
  const idx=rec.cols.findIndex(x=>x.k===key); const at=side==='left'?idx:idx+1;
  rec.cols.splice(at,0,{k:'rc'+Date.now(),label:'New Column'}); _rcptSave(s); renderReceiptEdit(); }
function rcptColDelete(key){ if(!String(key).startsWith('rc')&&!['s1','s2'].includes(key)){ alert('This column is part of the receipt structure — hide it instead.'); return; }
  const s=_rcptStore(); const rec=s[_rcptCtx.key]; rec.cols=rec.cols.filter(x=>x.k!==key); _rcptSave(s); renderReceiptEdit(); }
function rcptColClear(key){ const s=_rcptStore(); const rec=s[_rcptCtx.key]; rec.rows.forEach(r=>{ if(key==='unit'||key==='qty'){r[key]=0;r.total=0;} else if(key!=='total') r[key]=''; }); _rcptSave(s); renderReceiptEdit(); }
function rcptColHide(key){ const s=_rcptStore(); const rec=s[_rcptCtx.key]; rec.hidden=rec.hidden||{}; rec.hidden[key]=true; _rcptSave(s); renderReceiptEdit(); }
function rcptColEditCells(key){ const s=_rcptStore(); const rec=s[_rcptCtx.key]; const c=rec.cols.find(x=>x.k===key); if(!c)return;
  rec.meta=rec.meta||{};
  openOptionsPortal('CELL OPTIONS — '+c.label, rec.meta[key]||[], opts=>{
    if(opts.length) rec.meta[key]=opts; else delete rec.meta[key];
    _rcptSave(s); renderReceiptEdit(); }); }

function showReceipt(kind, i) {
  const d = _receiptData(kind, i);
  const sym = staffSym();
  const rowsHtml = d.items.map((x,n)=>`
    <tr><td style="padding:4px 6px;border-bottom:1px solid var(--border);">${n+1}. ${escH(x.narration||'Item')}</td>
    <td style="padding:4px 6px;border-bottom:1px solid var(--border);text-align:center;">${x.qty||1}</td>
    <td style="padding:4px 6px;border-bottom:1px solid var(--border);text-align:right;">${staffFmtAmt(x.unit_price)}</td>
    <td style="padding:4px 6px;border-bottom:1px solid var(--border);text-align:right;font-weight:700;">${staffFmtAmt(x.total)}</td></tr>`).join('');
  const overlay = document.createElement('div');
  overlay.id = 'receiptOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML = `
    <div id="receiptCard" style="background:var(--surface);border:1px solid var(--gold);border-radius:14px;max-width:420px;width:100%;max-height:88vh;overflow-y:auto;padding:20px;">
      <div style="text-align:center;border-bottom:1px dashed var(--border2);padding-bottom:12px;">
        <div style="font-size:1.05rem;font-weight:900;color:var(--gold);">${escH(d.bizName)}</div>
        ${d.bizAddr?`<div style="font-size:0.68rem;color:var(--muted);">${escH(d.bizAddr)}</div>`:''}
        ${d.bizPhone?`<div style="font-size:0.68rem;color:var(--muted);">${escH(d.bizPhone)}</div>`:''}
        <div style="font-size:0.68rem;color:var(--muted);">${escH(d.bizEmail)}</div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:0.68rem;color:var(--off);padding:10px 0 6px;">
        <span>${d.when}</span><span style="font-weight:800;">№ ${d.number}</span>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:0.74rem;color:var(--off);">
        <thead><tr style="color:var(--muted);font-size:0.6rem;text-align:left;">
          <th style="padding:4px 6px;">ITEM</th><th style="padding:4px 6px;text-align:center;">QTY</th>
          <th style="padding:4px 6px;text-align:right;">UNIT</th><th style="padding:4px 6px;text-align:right;">TOTAL</th>
        </tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
      <div style="font-size:0.74rem;color:var(--off);padding-top:10px;">
        <div style="display:flex;justify-content:space-between;"><span>Subtotal</span><span>${staffFmtAmt(d.subtotal)}</span></div>
        <div style="display:flex;justify-content:space-between;color:var(--muted);"><span>VAT</span><span>${staffFmtAmt(d.vat)}</span></div>
        <div style="display:flex;justify-content:space-between;color:var(--muted);"><span>Discount</span><span>${staffFmtAmt(d.discount)}</span></div>
        <div style="display:flex;justify-content:space-between;font-weight:900;color:var(--gold);font-size:0.9rem;border-top:1px dashed var(--border2);margin-top:6px;padding-top:6px;">
          <span>TOTAL PAID</span><span>${staffFmtAmt(d.total)}</span></div>
        <div style="display:flex;justify-content:space-between;margin-top:4px;"><span>Payment method</span><span style="font-weight:700;">${d.pay}</span></div>
      </div>
      <div style="display:flex;gap:8px;margin-top:16px;">
        <button onclick="printReceipt()" style="flex:1;background:var(--gold);color:var(--accent-ink);border:none;font-weight:800;font-size:0.76rem;padding:10px;border-radius:8px;cursor:pointer;">🖨 Print</button>
        <button onclick="emailReceipt('${kind}',${i})" style="flex:1;background:var(--surface2);color:var(--gold);border:1px solid var(--gold);font-weight:800;font-size:0.76rem;padding:10px;border-radius:8px;cursor:pointer;">✉ Email</button>
        <button onclick="showReceiptEdit('${kind}',${i})" style="flex:1;background:var(--surface2);color:var(--gold);border:1px solid var(--gold);font-weight:800;font-size:0.76rem;padding:10px;border-radius:8px;cursor:pointer;">✏ Edit</button>
        <button onclick="document.getElementById('receiptOverlay').remove()" style="background:none;color:var(--muted);border:1px solid var(--border2);font-size:0.76rem;padding:10px 14px;border-radius:8px;cursor:pointer;">Close</button>
      </div>
    </div>`;
  overlay.addEventListener('click', e=>{ if(e.target===overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}
function printReceipt() {
  const card = document.getElementById('receiptCard');
  if (!card) return;
  const w = window.open('','_blank');
  w.document.write('<html><head><title>Receipt</title><style>body{font-family:Arial;color:#000;max-width:380px;margin:20px auto;}table{width:100%;border-collapse:collapse;}td,th{padding:4px 6px;}div,span{color:#000 !important;}</style></head><body>'+card.innerHTML.replace(/<div style="display:flex;gap:8px;margin-top:16px;">[\s\S]*$/,'')+'</body></html>');
  w.document.close();
  setTimeout(()=>w.print(), 300);
}
function emailReceipt(kind, i) {
  const d = _receiptData(kind, i);
  const body = encodeURIComponent(
    d.bizName+'\n'+d.when+'\nReceipt '+d.number+'\n\n'
    + d.items.map((x,n)=>(n+1)+'. '+(x.narration||'Item')+'  x'+(x.qty||1)+'  '+staffFmtAmt(x.total)).join('\n')
    + '\n\nSubtotal: '+staffFmtAmt(d.subtotal)
    + '\nTOTAL PAID: '+staffFmtAmt(d.total)
    + '\nPayment: '+d.pay+'\n\nThank you for your patronage.');
  window.location.href = 'mailto:?subject='+encodeURIComponent('Receipt '+d.number+' — '+d.bizName)+'&body='+body;
}

// ── Selection mode + One-Payment bundling ─────────────────────
function sheetSelButton(kind) {
  const sel = sheetSel[kind];
  if (sel.active) { sheetSelCancel(kind); return; }
  sel.active = true; sel.picked = [];
  renderRecordSheet(kind);
}

function sheetEnterSel(kind, idx) {
  const sel = sheetSel[kind];
  sel.active = true;
  const r = sheetRows(kind)[idx];
  sel.picked = (r && !r._bundle) ? [idx] : [];
  renderRecordSheet(kind);
}
function sheetSelToggle(kind, i) {
  const sel = sheetSel[kind];
  const p = sel.picked.indexOf(i);
  if (p >= 0) sel.picked.splice(p,1); else sel.picked.push(i);
  renderRecordSheet(kind);
}
function sheetSelectAll(kind) {
  const sel = sheetSel[kind];
  const all = [...document.querySelectorAll('#bkContent .op-selcell .op-circle')].map(el=>{
    const m = /sheetSelToggle\('[^']*',(\d+)\)/.exec(el.getAttribute('onclick')||''); return m ? parseInt(m[1]) : -1; }).filter(i=>i>=0);
  const every = all.length && all.every(i => sel.picked.includes(i));
  sel.picked = every ? [] : all;
  renderRecordSheet(kind);
}
async function sheetDeleteSelected(kind) {
  const sel = sheetSel[kind];
  if (!sel.picked.length) return;
  if (!(await bdConfirm('Delete '+sel.picked.length+' selected row(s)?'))) return;
  const rows = sheetRows(kind);
  const idxs = sel.picked.slice().sort((a,b)=>b-a);
  const gone = [];
  idxs.forEach(i => { const r = rows[i]; if (r) { gone.push(r); rows.splice(i,1); } });
  if (rows.length === 0) rows.push(kind==='sales' ? staffEmptySaleRow(1) : staffEmptyExpRow(1));
  sheetSel[kind] = {active:false, picked:[]};
  renderRecordSheet(kind);
  try { if (typeof sheetAutosaveTrigger === 'function') sheetAutosaveTrigger(kind); } catch(e) {}
  // database catches up behind the screen
  const jids = new Set();
  for (const row of gone) {
    if (!(row && row._posted)) continue;
    const ids = [row._txnId].filter(Boolean);
    if (!ids.length) continue;
    try {
      const { data: txns } = await bkDb.from('bk_transactions').select('id,journal_id').in('id', ids);
      (txns||[]).forEach(t => { if (t.journal_id) jids.add(t.journal_id); });
    } catch(e) {}
  }
  for (const jid of jids) { try { await bdCascadeDeleteJournalEntry(jid); } catch(e) {} }
  try { await refreshEquation(); } catch(e) {}
}
function sheetSelCancel(kind) {
  sheetSel[kind] = {active:false, picked:[]};
  renderRecordSheet(kind);
}
function sheetBundleRenamePick(kind) {
  openTextPortal('NARRATION FOR THE GROUPED ROW', sheetSel[kind].pendingLabel||'', v=>{
    sheetSel[kind].pendingLabel = v;
    renderRecordSheet(kind);
  });
}
function sheetBundleRename(kind, i) {
  const b = sheetRows(kind)[i];
  if (!b || !b._bundle) return;
  openTextPortal('RENAME GROUPED ROW', b.label||'', v=>{ b.label=v; renderRecordSheet(kind); });
}

function sheetBundleSelected(kind) {
  const sel = sheetSel[kind];
  if (sel.picked.length < 2) return;
  sheetSnapshot(kind);
  const rows = sheetRows(kind);
  const idxs = sel.picked.slice().sort((a,b)=>a-b);
  const items = idxs.map(i=>rows[i]).filter(r=>r && !r._bundle);
  const bundle = { _bundle:true, items, pay_mode:(items[0]?.pay_mode||'cash'), expanded:false, _posted:false, label: sel.pendingLabel||'' };
  sel.pendingLabel = '';
  for (let k = idxs.length-1; k >= 0; k--) rows.splice(idxs[k], 1);
  rows.splice(idxs[0], 0, bundle);
  sheetSel[kind] = {active:false, picked:[]};
  renderRecordSheet(kind);
}
function sheetToggleBundle(kind, i) {
  const r = sheetRows(kind)[i];
  if (r && r._bundle) { r.expanded = !r.expanded; renderRecordSheet(kind); }
}
function sheetUngroup(kind, i) {
  const rows = sheetRows(kind);
  const r = rows[i];
  if (!r || !r._bundle) return;
  sheetSnapshot(kind);
  rows.splice(i, 1, ...r.items);
  renderRecordSheet(kind);
}
function bundleItemChange(kind, bIdx, j, field, val) {
  const b = sheetRows(kind)[bIdx];
  if (!b || !b._bundle) return;
  const x = b.items[j];
  if (field === 'narration') { x.narration = val; }
  else { x[field] = parseFloat(String(val).replace(/,/g,''))||0; x.total = x.unit_price*(x.qty||1); }
  x._posted = false; b._posted = false;
  const it = document.getElementById('bItemTot_'+kind+'_'+bIdx+'_'+j);
  if (it) it.textContent = staffFmtAmt(x.total);
  const bt = document.getElementById('bundleTotal_'+kind+'_'+bIdx);
  if (bt) bt.textContent = staffFmtAmt(b.items.reduce((s,r)=>s+(r.total||0),0));
  const gt = document.getElementById('sheetGrandTotal_'+kind);
  if (gt) gt.textContent = staffFmtAmt(sheetGrand(sheetRows(kind)));
}
function bundleItemDelete(kind, bIdx, j) {
  const rows = sheetRows(kind);
  const b = rows[bIdx];
  if (!b || !b._bundle) return;
  sheetSnapshot(kind);
  b.items.splice(j,1);
  if (b.items.length <= 1) rows.splice(bIdx, 1, ...b.items);
  renderRecordSheet(kind);
}
async function sheetSaveBundle(kind, i) {
  const b = sheetRows(kind)[i];
  if (!b || !b._bundle || b._posted) return;
  const valid = b.items.filter(x=>x.total>0);
  if (!valid.length) return;
  const btn = document.querySelector('#'+kind+'row_'+i+' .staff-save-row-btn');
  if (btn) { btn.textContent='...'; btn.disabled=true; }
  const gid = (crypto.randomUUID ? crypto.randomUUID() : 'g'+Date.now()+Math.random().toString(16).slice(2));
  const date = new Date().toISOString().slice(0,10);
  if (kind === 'sales') {
    for (const x of valid) {
      const err = bdValidateSaleRow(x);
      if (err) { alert(err); return; }
    }
  }
  try {
    for (const x of valid) {
      x.txn_group_id = gid;
      x.pay_mode = b.pay_mode;
      if (kind === 'sales') {
        if (navigator.onLine) await autoPostSaleRow(x, '', date);
        else { await bdSaveOffline(x, '', date); }
      } else {
        await autoPostExpenseRow(x);
      }
      x._posted = true;
    }
    if (!navigator.onLine && kind==='sales') bdUpdateSyncBadge();
    b._posted = true;
    if (btn) { btn.textContent='\u2713'; btn.style.color='var(--green)'; }
  } catch(e) {
    if (btn) { btn.textContent='!'; btn.style.color='var(--red)'; btn.disabled=false; }
  }
}

function sheetAddRow(kind){
  sheetSnapshot(kind);
  const rows = sheetRows(kind);
  const nr = kind==='sales'?staffEmptySaleRow(rows.length+1):staffEmptyExpRow(rows.length+1);
  const first = rows.find(x=>!x._bundle); if (first && first.txn_date) nr.txn_date = first.txn_date;
  rows.push(nr);
  renderRecordSheet(kind);
}

async function sheetDeleteRow(kind,i){
  const rows = sheetRows(kind);
  const row = rows[i];

  // A saved row carries a link back to its real database record —
  // deleting it here needs to remove that too (journal entry, ledger
  // transactions, and restore any stock it had deducted), not just
  // disappear it from the on-screen list while the underlying data
  // stays behind untouched.
  if (row && row._posted) {
    const txnIds = row._bundle ? (row.items||[]).map(x=>x._txnId).filter(Boolean) : [row._txnId].filter(Boolean);
    if (txnIds.length) {
      try {
        const { data: txns } = await bkDb.from('bk_transactions').select('id,journal_id').in('id', txnIds);
        const journalIds = [...new Set((txns||[]).map(t=>t.journal_id).filter(Boolean))];
        for (const jid of journalIds) await bdCascadeDeleteJournalEntry(jid);
        await refreshEquation();
      } catch(e) {}
    }
  }

  // Undo is purely an in-memory/visual mechanism — it can't reverse
  // the database cascade above, so offering it here would silently
  // bring the row back on screen while its journal entry stays
  // deleted underneath. Only snapshot (and offer undo) for rows that
  // were never posted in the first place, where undo is fully honest.
  if (!(row && row._posted)) sheetSnapshot(kind);
  rows.splice(i,1);
  if (rows.length === 0) rows.push(kind==='sales' ? staffEmptySaleRow(1) : staffEmptyExpRow(1));
  renderRecordSheet(kind);
}

function sheetToggleToolbox(kind){
  sheetToolboxOpen[kind] = !sheetToolboxOpen[kind];
  const tb = document.getElementById('sheetToolbox_'+kind);
  if (tb) tb.classList.toggle('hidden', !sheetToolboxOpen[kind]);
  // The pinned header just got taller/shorter: re-measure so the column headers stay visible.
  requestAnimationFrame(()=>{ try { bdApplyStickyLayout('.staff-table th','.staff-total-row td'); bdSyncStickyClones(); } catch(e){} });
}

function sheetDecimals(kind,delta){
  const st = sheetState[kind];
  st.decimals = Math.max(0, Math.min(4, st.decimals + delta));
  renderRecordSheet(kind);
}
function sheetSetFont(kind,f){ sheetState[kind].font=f; renderRecordSheet(kind); }
function sheetSetWrap(kind,w){ sheetState[kind].wrap=w; renderRecordSheet(kind); }
function sheetToday(kind){
  const t=new Date().toISOString().slice(0,10);
  sheetState[kind].dateFrom=t; sheetState[kind].dateTo=t;
  sheetLoadDateRange(kind);
}

function sheetTogglePanel(kind,panel){
  const el = document.getElementById('sheetPanel_'+kind);
  if (!el) return;
  if (el.dataset.panel===panel && !el.classList.contains('hidden')) { el.classList.add('hidden'); return; }
  el.dataset.panel = panel;
  el.classList.remove('hidden');
  const st = sheetState[kind];
  if (panel==='search') {
    el.innerHTML = `<input class="bk-input" placeholder="Search narration…" value="${escH(st.search)}" style="flex:1;"
      oninput="sheetState['${kind}'].search=this.value" onkeydown="if(event.key==='Enter')renderRecordSheet('${kind}')"/>
      <button class="bk-btn bk-btn-gold" style="font-size:0.74rem;" onclick="renderRecordSheet('${kind}')">Search</button>
      <button class="bk-btn bk-btn-outline" style="font-size:0.74rem;" onclick="sheetState['${kind}'].search='';renderRecordSheet('${kind}')">Clear</button>`;
  } else if (panel==='freeze') {
    el.innerHTML = `<label style="font-size:0.74rem;color:var(--muted);">Freeze up to row:</label>
      <input class="bk-input" type="number" min="0" max="20" value="${st.freezeRow}" style="width:70px;"
        onchange="sheetState['${kind}'].freezeRow=parseInt(this.value)||0;renderRecordSheet('${kind}')"/>`;
  } else if (panel==='date') {
    el.innerHTML = `<label style="font-size:0.72rem;color:var(--muted);">From</label>
      <input class="bk-input" type="date" value="${st.dateFrom}" onchange="sheetState['${kind}'].dateFrom=this.value"/>
      <label style="font-size:0.72rem;color:var(--muted);">To</label>
      <input class="bk-input" type="date" value="${st.dateTo}" onchange="sheetState['${kind}'].dateTo=this.value"/>
      <button class="bk-btn bk-btn-gold" style="font-size:0.74rem;" onclick="sheetLoadDateRange('${kind}')">Load</button>`;
  } else if (panel==='inscol') {
    const positions = ['After S/N','After Narration'].concat(st.customCols.map(c=>'After '+c.name));
    el.innerHTML = `<input id="insColName_${kind}" class="bk-input" placeholder="Column header…" style="flex:1;"/>
      <select id="insColPos_${kind}" class="bk-input">${positions.map((p,i)=>`<option value="${i}">${escH(p)}</option>`).join('')}</select>
      <button class="bk-btn bk-btn-gold" style="font-size:0.74rem;" onclick="sheetInsertColumn('${kind}')">Insert</button>`;
  } else if (panel==='print') {
    el.innerHTML = `<label style="font-size:0.74rem;color:var(--muted);">Orientation:</label>
      <button class="bk-btn bk-btn-outline" style="font-size:0.74rem;" onclick="sheetPrint('${kind}','portrait')">Portrait</button>
      <button class="bk-btn bk-btn-gold" style="font-size:0.74rem;" onclick="sheetPrint('${kind}','landscape')">Landscape</button>`;
  }
}

function sheetInsertColumn(kind){
  const name = document.getElementById('insColName_'+kind)?.value?.trim();
  if (!name) { alert('Enter a column header'); return; }
  const pos = parseInt(document.getElementById('insColPos_'+kind)?.value)||0;
  const st = sheetState[kind];
  // pos 0 = after S/N (custom index 0)... custom cols render between Narration and Unit Price;
  // simplest honoring: pos 0/1 => start, otherwise after that custom col
  const key = 'c'+Date.now();
  const insertAt = Math.max(0, Math.min(st.customCols.length, pos-1));
  st.customCols.splice(pos<=1?0:insertAt, 0, {name, key});
  renderRecordSheet(kind);
}

async function sheetLoadDateRange(kind){
  const st = sheetState[kind];
  const to = st.dateTo || st.dateFrom;
  try {
    const rt = kind==='sales' ? 'income' : 'expenditure';
    let q = bkDb.from('bk_transactions').select('*').match(bizMatch()).eq('record_type',rt);
    if (st.allDates || !st.dateFrom) q = q.order('txn_date',{ascending:false}).order('id');
    else q = q.gte('txn_date',st.dateFrom).lte('txn_date',to).order('txn_date');
    let {data:T} = await q;
    T = (T||[]).filter(t=>t.account_name!=='Cost of Goods Sold' && (kind!=='sales' || salesIncomeShown(t)));
    if (st.allDates || !st.dateFrom) T.reverse();
    const flat = T.map((t,n)=>({
      sn:n+1, txn_date:t.txn_date||'', payee:t.payee||'', payer:t.payer||'', narration:t.narration||'', product:(kind==='sales'?(t.narration||''):''), unit_price:Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0)),
      qty:1, total:Math.abs((parseFloat(t.credit)||0)-(parseFloat(t.debit)||0)),
      pay_mode:t.payment_mode||'cash', _posted:true, _txnId:t.id, _jid:t.journal_id||null, _gid:t.txn_group_id||null,
    }));
    const loaded=[]; const seen={};
    for (const r of flat) {
      if (r._gid) {
        if (seen[r._gid]) { seen[r._gid].items.push(r); continue; }
        const b = { _bundle:true, items:[r], pay_mode:r.pay_mode, expanded:false, _posted:true };
        seen[r._gid]=b; loaded.push(b);
      } else loaded.push(r);
    }
    // rows still waiting to save stay on screen
    sheetRows(kind).forEach(r=>{ if (!r._posted && (r.total>0 || r.narration || r.payee || r.payer || r.product)) loaded.push(r); });
    const nr = kind==='sales' ? staffEmptySaleRow(loaded.length+1) : staffEmptyExpRow(loaded.length+1);
    if (st.dateFrom && !st.allDates) nr.txn_date = st.dateFrom;
    loaded.push(nr);
    loaded.forEach((r,i)=>{ if(!r._bundle) r.sn=i+1; });
    if (kind==='sales') salesRows = loaded; else staffExpRows = loaded;
    renderRecordSheet(kind);
  } catch(e) { renderRecordSheet(kind); }
}

function sheetPrint(kind, orientation){
  bdPrintTable({ table: document.getElementById('sheetTable_'+kind), orientation: orientation || 'portrait',
    title: kind==='sales' ? 'Sales Records' : 'Expenses Records', subtitle: sheetHeaderDate(kind) });
}

// Long-press to select and drag rows
function sheetInitLongPress(kind){
  const tbody = document.querySelector('#sheetTable_'+kind+' tbody');
  if (!tbody) return;
  let timer=null, startY=0, armed=false, dragging=false, dragRow=null;

  const arm = (tr) => {
    armed = true;
    dragRow = tr;
    tr.style.outline = '2px solid var(--gold)';
    const ae = document.activeElement;
    if (ae && (ae.tagName==='INPUT' || ae.tagName==='SELECT')) ae.blur();
    if (navigator.vibrate) navigator.vibrate(30);
  };
  const disarm = () => {
    clearTimeout(timer); timer=null;
    if (dragRow) dragRow.style.outline='';
    armed=false; dragging=false; dragRow=null;
  };

  // ── Touch (mobile): hold anywhere on the row; release = select, drag = move ──
  tbody.addEventListener('touchstart', e=>{
    const tr = e.target.closest('tr'); if (!tr || tr.dataset.idx===undefined) return;
    if (e.target.tagName==='BUTTON' || e.target.classList.contains('op-circle')) return;
    startY = e.touches[0].clientY;
    armed=false; dragging=false; dragRow=tr;
    timer = setTimeout(()=>arm(tr), 450);
  }, {passive:true});

  tbody.addEventListener('touchmove', e=>{
    if (!armed) { if (Math.abs(e.touches[0].clientY-startY)>10) clearTimeout(timer); return; }
    dragging = true;
    e.preventDefault();
    const over = document.elementFromPoint(e.touches[0].clientX, e.touches[0].clientY)?.closest('tr');
    if (over && over!==dragRow && over.dataset.idx!==undefined) {
      const rows = sheetRows(kind);
      const from = parseInt(dragRow.dataset.idx), to = parseInt(over.dataset.idx);
      if (from!==to && !isNaN(from) && !isNaN(to)) {
        sheetSnapshot(kind);
        const [moved] = rows.splice(from,1);
        rows.splice(to,0,moved);
        disarm();
        renderRecordSheet(kind);
      }
    }
  }, {passive:false});

  tbody.addEventListener('touchend', e=>{
    if (armed && !dragging && dragRow) {
      const idx = parseInt(dragRow.dataset.idx);
      e.preventDefault();           // stop the input under the finger from focusing
      disarm();
      if (!isNaN(idx)) sheetEnterSel(kind, idx);
      return;
    }
    disarm();
  }, {passive:false});

  tbody.addEventListener('touchcancel', disarm);

  // ── Desktop: hold the mouse button 450ms on a row = selection mode ──
  tbody.addEventListener('mousedown', e=>{
    if (e.button !== 0) return;
    const tr = e.target.closest('tr'); if (!tr || tr.dataset.idx===undefined) return;
    if (e.target.tagName==='BUTTON' || e.target.classList.contains('op-circle')) return;
    dragRow = tr;
    timer = setTimeout(()=>{
      arm(tr);
      const idx = parseInt(tr.dataset.idx);
      disarm();
      if (!isNaN(idx)) sheetEnterSel(kind, idx);
    }, 450);
  });
  tbody.addEventListener('mouseup', ()=>{ if (!armed) clearTimeout(timer); });
  tbody.addEventListener('mousemove', ()=>{ if (!armed) clearTimeout(timer); });

  // ── Desktop: right-click a row = selection mode ──
  tbody.addEventListener('contextmenu', e=>{
    const tr = e.target.closest('tr');
    if (!tr || tr.dataset.idx===undefined) return;
    e.preventDefault();
    sheetEnterSel(kind, parseInt(tr.dataset.idx));
  });
}




function showOwingPage() {
  staffHideChrome();
  if (owingRows.length === 0) owingRows = [1,2,3].map(n => staffEmptyOwingRow(n));
  renderOwingPage();
}

function renderOwingPage() {
  const rows = owingRows.map((r,i) => `
    <tr>
      <td class="staff-sn">${i+1}</td>
      <td><input class="staff-cell" type="text" value="${escH(r.name)}" placeholder="Name…"
        oninput="owingRows[${i}].name=this.value"/></td>
      <td><input class="staff-cell" type="text" value="${escH(r.narration)}" placeholder="What's owed…"
        oninput="owingRows[${i}].narration=this.value"/></td>
      <td><div class="staff-price-wrap"><span class="staff-curr-prefix">${staffSym()}</span>
        <input class="staff-cell num" type="text" inputmode="decimal"
          value="${r.unit_price>0?r.unit_price.toLocaleString('en-NG'):''}" placeholder="0"
          onclick="staffCursorEnd(this)" onfocus="staffCursorEnd(this)"
          oninput="owingNumChange(${i},'unit_price',this.value)"/></div></td>
      <td><input class="staff-cell num" type="text" inputmode="numeric" value="${r.qty||1}"
        onclick="staffCursorEnd(this)" onfocus="staffCursorEnd(this)"
        oninput="owingNumChange(${i},'qty',this.value)"/></td>
      <td><div class="staff-cell ro" id="owing_total_${i}">${staffFmtAmt(r.total)}</div></td>
      <td><button class="staff-del-btn" onclick="owingRows.splice(${i},1);renderOwingPage()">✕</button></td>
    </tr>`).join('');
  const grandTotal = owingRows.reduce((a,r) => a+(r.total||0), 0);
  document.getElementById('bkContent').innerHTML = `
    <div class="bk-content-header">
      <div class="bk-content-title">OWING</div>
      <button class="bk-btn bk-btn-outline" style="font-size:0.76rem;" onclick="showRecordChoice()">← Back</button>
    </div>
    <div class="bk-sheet-wrap">
      <table class="staff-table staff-table-compact" style="min-width:580px;">
        <thead><tr>
          <th style="width:34px;">S/N</th>
          <th style="width:130px;">Name</th>
          <th style="width:160px;">Narration</th>
          <th style="width:130px;">Unit Price</th>
          <th style="width:80px;">Quantity</th>
          <th style="width:120px;">Total</th>
          <th style="width:34px;"></th>
        </tr></thead>
        <tbody>${rows}</tbody>
        <tfoot><tr class="staff-total-row">
          <td colspan="5" style="padding:7px 5px;">Total Owing</td>
          <td style="text-align:right;padding:7px 5px;">${staffFmtAmt(grandTotal)}</td>
          <td></td>
        </tr></tfoot>
      </table>
    </div>
    <div style="display:flex;gap:10px;margin-top:8px;">
      <button class="staff-add-cust-btn" onclick="owingRows.push(staffEmptyOwingRow(owingRows.length+1));renderOwingPage()">+ Add Row</button>
      <button class="staff-save-static-btn" onclick="saveAllOwing()">Save All</button>
    </div>`;
}

function owingNumChange(i, field, val) {
  owingRows[i][field] = parseFloat(String(val).replace(/,/g,''))||0;
  owingRows[i].total  = owingRows[i].unit_price * (owingRows[i].qty||1);
  const el = document.getElementById('owing_total_'+i);
  if (el) el.textContent = staffFmtAmt(owingRows[i].total);
  const totEl = document.querySelector('#bkContent .staff-total-row td:nth-child(6)');
  if (totEl) totEl.textContent = staffFmtAmt(owingRows.reduce((a,r)=>a+(r.total||0),0));
}


