// ── Generic sales block: S/N, Narration, Unit Price, Qty, Total ─
// Fits in ONE mobile pane — no horizontal swiping needed
function renderCustomerBlock(cust){
  const totalAmt = cust.rows.reduce(function(a,r){ return a+(parseFloat(r.total)||0); },0);
  const cid = cust.id;
  const locked = !!cust.locked;
  const lockAttr = locked ? ' disabled' : '';

  let rowsHtml = '';
  cust.rows.forEach(function(row, ri){
    const upVal  = row.unit_price > 0 ? row.unit_price.toLocaleString('en-NG') : '';
    const totVal = staffFmtAmt(row.total);
    rowsHtml += '<tr id="srow_'+cid+'_'+ri+'">'
      + '<td style="width:34px;text-align:center;color:var(--muted);font-size:0.7rem;padding:6px 4px;">'+(ri+1)+'</td>'
      + '<td><input class="staff-cell" type="text" value="'+escH(row.narration||'')+'" placeholder="What was sold?"'+lockAttr
      + ' oninput="staffSaleChange('+cid+','+ri+',\'narration\',this.value)"/></td>'
      + '<td style="white-space:nowrap;"><div class="staff-price-wrap"><span class="staff-curr-prefix">'+staffSym()+'</span>'
      + '<input class="staff-cell num" type="text" inputmode="decimal" value="'+upVal+'" placeholder="0"'+lockAttr
      + ' onclick="staffCursorEnd(this)" onfocus="staffCursorEnd(this)"'
      + ' oninput="staffNumChange('+cid+','+ri+',\'unit_price\',this.value)"/></div></td>'
      + '<td style="white-space:nowrap;"><input class="staff-cell num" type="text" inputmode="numeric" value="'+(row.qty||1)+'"'+lockAttr
      + ' onclick="staffCursorEnd(this)" onfocus="staffCursorEnd(this)"'
      + ' oninput="staffNumChange('+cid+','+ri+',\'qty\',this.value)"/></td>'
      + '<td style="white-space:nowrap;"><div class="staff-cell ro" id="stotal_'+cid+'_'+ri+'">'+totVal+'</div></td>'
      + '<td><button class="staff-del-btn" onclick="staffDelRow('+cid+','+ri+')"'+lockAttr+'>&#x2715;</button></td>'
      + '<td><button class="staff-save-row-btn" onclick="bdSaveWrap(this,()=>staffSaveRow('+cid+','+ri+'))"'+lockAttr+'>&#8250;</button></td>'
      + '</tr>';
  });

  const table = '<table class="staff-table staff-table-compact" style="min-width:520px;">'
    + '<thead><tr>'
    + '<th style="width:34px;">S/N</th>'
    + '<th style="width:160px;">Narration</th>'
    + '<th style="width:130px;">Unit Price</th>'
    + '<th style="width:60px;">Qty</th>'
    + '<th style="width:120px;">Total</th>'
    + '<th style="width:34px;"></th>'
    + '<th style="width:34px;"></th>'
    + '</tr></thead>'
    + '<tbody>'+rowsHtml+'</tbody>'
    + '<tfoot><tr class="staff-total-row">'
    + '<td colspan="5" style="padding:7px 5px;">Total</td>'
    + '<td style="text-align:right;padding:7px 5px;" id="totAmt_'+cid+'">'+(totalAmt>0?staffFmtAmt(totalAmt):'')+'</td>'
    + '<td></td>'
    + '</tr></tfoot>'
    + '</table>';

  return '<div class="staff-customer-block'+(locked?' staff-locked-block':'')+'" data-custid="'+cid+'">'
    + '<div style="overflow-x:auto;-webkit-overflow-scrolling:touch;">'
    + table
    + '</div>'
    + '<div class="staff-save-static-wrap">'
    + '<button class="staff-save-static-btn" onclick="staffSaveCustomer('+cid+')">&#8250; Save</button>'
    + '<span class="staff-static-total" id="staticTotal_'+cid+'">Total = '+(totalAmt>0?staffFmtAmt(totalAmt):staffSym()+'0')+'</span>'
    + '</div>'
    + '</div>';
}

function staffGetCust(id){return staffCustomers.find(c=>c.id===id);}

// Products: save all unsaved rows
let _psAutoT = null;
function psAutosaveTrigger() {
  try { psPendCommit(); } catch(e) {}
  clearTimeout(_psAutoT);
  const m = document.getElementById('psSaveMsg'); if (m && psRows.some(r=>!r.saved && (r.name||'').trim())) { m.textContent = 'Saving…'; m.className = 'bk-save-msg pending'; }
  _psAutoT = setTimeout(()=>psSaveAll(), 600);
}

let _psSaving = false, _psSaveAgain = false;
async function psSaveAll() {
  if (_psSaving) { _psSaveAgain = true; return; }
  _psSaving = true;
  let anyFailed = false;
  try {
    const todo = [];
    for (let i=0; i<psRows.length; i++) { if (!psRows[i].saved && psRows[i].name.trim()) todo.push(i); }
    for (const i of todo) { try { await psEnsureProductAccount(psRows[i]); } catch(e) {} }   // accounts first, one by one (rows can share one)
    await Promise.all(todo.map(i => psSaveRow(i)));
    todo.forEach(i => { if (psRows[i] && !psRows[i].saved) anyFailed = true; });
  } finally { _psSaving = false; }
  const m = document.getElementById('psSaveMsg');
  if (m) { m.textContent = anyFailed ? '⚠ Not saved' : '✓ Saved'; m.className = 'bk-save-msg ' + (anyFailed ? '' : 'ok'); }
  if (anyFailed) bdToast('⚠ Some changes could not be saved — check your connection and try again', 'error');
  if (_psSaveAgain) { _psSaveAgain = false; psAutosaveTrigger(); }
}
document.addEventListener('visibilitychange', () => { if (document.hidden && typeof psRows !== 'undefined' && document.getElementById('psBody') && psRows.some(r=>!r.saved && (r.name||'').trim())) { clearTimeout(_psAutoT); psSaveAll(); } });

// Suppliers: save all unsaved rows
async function supSaveAll() {
  for (let i=0; i<supplierRows.length; i++) {
    if (!supplierRows[i].saved && supplierRows[i].name.trim()) await supSaveRow(i);
  }
}

// Expenses: save all rows with values to ledger
async function expSaveRow(i){
  const r=staffExpRows[i];
  if(!r||!r.total) return;
  if(r._posted) return; // already posted
  try{
    if (!navigator.onLine) {
      await bdQueueOp('expense', { row: r, businessId: activeBusiness?.id||null });
      bdUpdateSyncBadge();
    } else {
      await autoPostExpenseRow(r);
    }
    staffExpRows[i]._posted = true;
    const btn = document.querySelector('#erow_'+i+' .staff-save-row-btn');
    if(btn){btn.textContent='✓';btn.style.color='var(--green)';btn.disabled=true;}
  } catch(e){}
}

async function saveAllExpenses() {
  const flat=[];
  for (const r of staffExpRows) {
    if (r._bundle && !r._posted) {
      const gid = (crypto.randomUUID ? crypto.randomUUID() : 'g'+Date.now()+Math.random().toString(16).slice(2));
      r.items.forEach(x=>{ if(x.total>0 && !x._posted){ x.txn_group_id=gid; x.pay_mode=r.pay_mode; flat.push(x); } });
      r._posted = true;
    } else if (!r._bundle && r.total>0 && !r._posted) flat.push(r);
  }
  if (!flat.length) { alert('No new expenses to save — all have already been posted.'); return; }
  const offline = !navigator.onLine;
  for (const r of flat) {
    if (offline) await bdQueueOp('expense', { row: r, businessId: activeBusiness?.id||null });
    else await autoPostExpenseRow(r);
    r._posted = true;
  }
  if (offline) bdUpdateSyncBadge();
  alert(offline
    ? '✓ '+flat.length+' expense'+(flat.length>1?'s':'')+' saved offline — will sync when back online'
    : '✓ '+flat.length+' expense'+(flat.length>1?'s':'')+' posted to ledger');
}

