async function loadProfileData() {
  const d = { email: bkUser?.email || '' };
  try {
    const { data:p, error } = await bkDb.from('profiles').select('*').eq('id',bkUser.id).maybeSingle();
    if (error) console.warn('profile load:', error.message);
    if (p) Object.assign(d, p);
  } catch(e) { console.warn('profile load failed', e); }
  return d;
}

