function selectBizIcon(btn, icon) {
  document.querySelectorAll('.biz-icon-pick').forEach(b=>b.style.borderColor='var(--border2)');
  btn.style.borderColor='var(--gold)';
  document.getElementById('newBizIcon').value = icon;
}

async function submitNewBusiness() {
  const name = document.getElementById('newBizName')?.value?.trim();
  if (!name) { alert('Please enter a business name'); return; }
  const industry = document.getElementById('newBizIndustry')?.value || 'General';
  const icon     = document.getElementById('newBizIcon')?.value || '🏢';
  try {
    const {data,error} = await bkDb.from('businesses').insert({
      name, industry, icon,
      owner_user_id:bkUser.id,
      currency:activeCurrency||'NGN',
      is_primary:false, status:'healthy',
    }).select().single();
    if (error) throw error;
    userBusinesses.push(data);
    await bkDb.from('user_businesses').upsert(
      {user_id:bkUser.id,business_id:data.id,role:'owner'},
      {onConflict:'user_id,business_id'}
    );
    document.getElementById('addBizModal')?.remove();
    renderMenuBusinesses();
    await showAllBusinessesDashboard();
  } catch(e) { alert('Error creating business: '+e.message); }
}

async function exportAllBusinesses() {
  try {
    const metrics = await fetchAllBusinessMetrics();
    let csv = 'BUTTERFLY DYNAMIX ACCOUNTING — PORTFOLIO REPORT\n';
    csv += 'Generated,' + new Date().toISOString().slice(0,10) + '\n\n';
    csv += 'BUSINESS SUMMARY\n';
    csv += 'Business,Industry,Revenue,Expenses,Net Profit,Margin %,Status\n';
    metrics.forEach(b=>{
      csv += `"${b.name}","${b.industry||''}",${b.revenue},${b.expenses},${b.profit},${b.margin},"${b.status}"\n`;
    });
    const tRev = metrics.reduce((s,b)=>s+b.revenue,0);
    const tExp = metrics.reduce((s,b)=>s+b.expenses,0);
    csv += `"TOTAL","",${tRev},${tExp},${tRev-tExp},,\n\n`;
    // Transactions
    const {data:T} = await bkDb.from('bk_transactions').select('txn_date,account_name,record_type,narration,debit,credit')
      .match(bizMatch()).order('txn_date');
    if (T && T.length) {
      csv += 'ALL TRANSACTIONS\n';
      csv += 'Date,Account,Type,Narration,Debit,Credit\n';
      T.forEach(t=>{
        csv += `${t.txn_date||''},"${t.account_name||''}","${t.record_type||''}","${(t.narration||'').replace(/"/g,'""')}",${t.debit||0},${t.credit||0}\n`;
      });
    }
    const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'butterfly-dynamix-portfolio-' + new Date().toISOString().slice(0,10) + '.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href), 5000);
  } catch(e) { alert('Export failed: '+(e.message||'')); }
}


const BD_DB_NAME    = 'bd_offline';
const BD_DB_VERSION = 2;
const BD_STORE      = 'pending_sales';
const BD_OPS_STORE  = 'pending_ops';   // generalized: expenses, ledger rows, journal rows

function bdOpenDB() {
  return new Promise(function(resolve, reject) {
    const req = indexedDB.open(BD_DB_NAME, BD_DB_VERSION);
    req.onupgradeneeded = function(e) {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(BD_STORE)) {
        const store = db.createObjectStore(BD_STORE, { keyPath:'id', autoIncrement:true });
        store.createIndex('synced', 'synced', { unique:false });
      }
      if (!db.objectStoreNames.contains(BD_OPS_STORE)) {
        const opsStore = db.createObjectStore(BD_OPS_STORE, { keyPath:'id', autoIncrement:true });
        opsStore.createIndex('synced', 'synced', { unique:false });
      }
    };
    req.onsuccess = function(e) { resolve(e.target.result); };
    req.onerror   = function(e) { reject(e.target.error); };
  });
}

// ── Generalized offline queue: expenses, ledger rows, journal rows ──
async function bdQueueOp(opType, payload) {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_OPS_STORE, 'readwrite');
    const store = tx.objectStore(BD_OPS_STORE);
    store.add({ opType, payload, savedAt:new Date().toISOString(), synced:false, userId:bkUser?.id||null });
    return new Promise(function(resolve, reject) {
      tx.oncomplete = resolve;
      tx.onerror    = function(e) { reject(e.target.error); };
    });
  } catch(e) {}
}
async function bdGetPendingOps() {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_OPS_STORE, 'readonly');
    const index = tx.objectStore(BD_OPS_STORE).index('synced');
    const req   = index.getAll(false);
    return new Promise(function(resolve) {
      req.onsuccess = function(e) { resolve(e.target.result||[]); };
      req.onerror   = function() { resolve([]); };
    });
  } catch(e) { return []; }
}
async function bdMarkOpSynced(id) {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_OPS_STORE, 'readwrite');
    const store = tx.objectStore(BD_OPS_STORE);
    const req   = store.get(id);
    req.onsuccess = function() {
      const rec = req.result;
      if (rec) { rec.synced = true; store.put(rec); }
    };
    return new Promise(function(resolve) { tx.oncomplete = resolve; });
  } catch(e) {}
}
async function bdSyncOfflineOps() {
  if (!bkUser) return;
  const pending = await bdGetPendingOps();
  if (!pending.length) return;
  let synced = 0;
  for (const record of pending) {
    try {
      const p = record.payload;
      if (record.opType === 'expense') {
        await autoPostExpenseRow(p.row, p.businessId);
      } else if (record.opType === 'ledger_row') {
        await bkDb.from('bk_transactions').insert(p.insertPayload);
      } else if (record.opType === 'journal_row') {
        const { data: jnl } = await bkDb.from('bk_journal').insert(p.journalPayload).select().single();
        if (jnl && p.legs && p.legs.length) {
          p.legs.forEach(l => { l.journal_id = jnl.id; });
          await bkDb.from('bk_transactions').insert(p.legs);
        }
      }
      await bdMarkOpSynced(record.id);
      synced++;
    } catch(e) {}
  }
  if (synced > 0) {
    bdUpdateSyncBadge();
    bdToast('\u2713 ' + synced + ' offline entr' + (synced>1?'ies':'y') + ' synced');
    try { await refreshEquation(); } catch(e) {}
  }
}
async function bdGetTotalPendingCount() {
  const [sales, ops] = await Promise.all([bdGetPendingSales(), bdGetPendingOps()]);
  return sales.length + ops.length;
}

async function bdSaveOffline(row, customerName, txnDate) {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_STORE, 'readwrite');
    const store = tx.objectStore(BD_STORE);
    store.add({ row, customerName, txnDate, businessId: activeBusiness?.id||null, savedAt:new Date().toISOString(), synced:false, userId:bkUser?.id||null });
    return new Promise(function(resolve, reject) {
      tx.oncomplete = resolve;
      tx.onerror    = function(e) { reject(e.target.error); };
    });
  } catch(e) {}
}

async function bdGetPendingSales() {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_STORE, 'readonly');
    const index = tx.objectStore(BD_STORE).index('synced');
    const req   = index.getAll(false);
    return new Promise(function(resolve) {
      req.onsuccess = function(e) { resolve(e.target.result||[]); };
      req.onerror   = function()  { resolve([]); };
    });
  } catch(e) { return []; }
}

async function bdMarkSynced(id) {
  try {
    const db    = await bdOpenDB();
    const tx    = db.transaction(BD_STORE, 'readwrite');
    const store = tx.objectStore(BD_STORE);
    const req   = store.get(id);
    req.onsuccess = function(e) {
      const r = e.target.result;
      if (r) { r.synced = true; store.put(r); }
    };
  } catch(e) {}
}

async function bdSyncOfflineSales() {
  if (!bkUser) return;
  const pending = await bdGetPendingSales();
  if (!pending.length) return;
  let synced = 0;
  for (const record of pending) {
    try {
      await autoPostSaleRow(record.row, record.customerName, record.txnDate, record.businessId);
      await bdMarkSynced(record.id);
      synced++;
    } catch(e) {}
  }
  if (synced > 0) {
    bdUpdateSyncBadge();
    const msg = document.createElement('div');
    msg.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#1a2a1a;border:1px solid var(--green);color:#4ade80;padding:10px 20px;border-radius:8px;font-size:0.82rem;font-weight:600;z-index:9999;white-space:nowrap;';
    msg.textContent = '\u2713 ' + synced + ' offline sale' + (synced>1?'s':'') + ' synced to ledger';
    document.body.appendChild(msg);
    setTimeout(function() { msg.remove(); }, 3000);
    refreshEquation();
  }
}

async function bdUpdateSyncBadge() {
  const [pendingSales, pendingOps] = await Promise.all([bdGetPendingSales(), bdGetPendingOps()]);
  const count = pendingSales.length + pendingOps.length;
  let badge   = document.getElementById('bdOfflineBadge');
  if (count === 0) { if (badge) badge.remove(); return; }
  if (!badge) {
    badge = document.createElement('div');
    badge.id = 'bdOfflineBadge';
    const _bGold=getComputedStyle(document.body).getPropertyValue('--gold'),_bInk=getComputedStyle(document.body).getPropertyValue('--accent-ink');
    badge.style.cssText = 'position:fixed;top:12px;right:12px;background:'+_bGold+';color:'+_bInk+';font-size:0.72rem;font-weight:800;padding:5px 12px;border-radius:20px;z-index:9999;cursor:pointer;';
    badge.onclick = function() { bdSyncOfflineSales(); bdSyncOfflineOps(); };
    document.body.appendChild(badge);
  }
  badge.textContent = count + ' offline entr' + (count>1?'ies':'y') + ' \u2014 tap to sync';
}

window.addEventListener('online',  function() { bdSyncOfflineSales(); bdSyncOfflineOps(); });
window.addEventListener('load',     function() {
  setTimeout(bdUpdateSyncBadge, 2000);
  if (navigator.onLine) setTimeout(function(){ bdSyncOfflineSales(); bdSyncOfflineOps(); }, 3000);
});

// Global comma formatter for any number input — call oninput
// Preserves cursor position, strips non-numeric, inserts commas
function fmtInputCommas(el) {
  const raw = el.value.replace(/[^0-9.]/g, '');
  if (!raw) return;
  const dot = raw.indexOf('.');
  const intPart = dot>=0 ? raw.slice(0,dot) : raw;
  const decPart = dot>=0 ? '.'+raw.slice(dot+1).replace(/\./g,'') : '';
  const formatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + decPart;
  const cursor = el.selectionStart;
  const prevLen = el.value.length;
  el.value = formatted;
  const diff = formatted.length - prevLen;
  try { el.setSelectionRange(cursor + diff, cursor + diff); } catch(e) {}
}

// Maps payment method to the cash/bank account name
function staffCashAccount(payMode) {
  const m = (payMode||'').toLowerCase();
  if (m === 'transfer' || m === 'pos' || m === 'bank' || m === 'debitcard' || m === 'creditcard') return 'Cash at Bank';
  return 'Cash in Hand'; // cash, default
}

// Determines the correct income account for a narration/product name.
// Tries to match against products in bk_products, then falls back to rules.
// A product that has its own sub-account (made when "Posts To" was chosen on the Products page)
// records its sales there; otherwise the old rule applies.
async function bdSaleIncomeAccount(row) {
  try {
    if (row.product_id && bkUser) {
      const { data } = await bkDb.from('bk_products').select('income_account, custom').eq('id', row.product_id).single();
      if (data && data.custom && data.custom.__sub) return data.custom.__sub;
      if (data && data.income_account) return data.income_account;
    }
  } catch(e) {}
  return staffIncomeAccount(row.product || row.narration);
}
async function staffIncomeAccount(narration) {
  if (!bkUser || !narration) return 'Sales Revenue';
  try {
    const { data } = await bkDb.from('bk_products')
      .select('product_name, income_account, custom')
      .eq('user_id', bkUser.id)
      .ilike('product_name', '%' + narration.trim() + '%')
      .limit(1);
    if (data && data[0] && data[0].custom && data[0].custom.__sub) return data[0].custom.__sub;
    if (data && data[0] && data[0].income_account) return data[0].income_account;
  } catch(e) {}
  // Rule-based fallback
  const n = narration.toLowerCase();
  if (n.includes('haircut')||n.includes('barb')||n.includes('shave')||n.includes('trim')||n.includes('cut')) return 'Barbing Revenue';
  if (n.includes('laundry')||n.includes('wash')||n.includes('dry')||n.includes('iron')||n.includes('clean')) return 'Service Income';
  if (n.includes('service')||n.includes('consult')||n.includes('repair')||n.includes('fix')) return 'Service Income';
  return 'Sales Revenue';
}

// Auto-post a single sale row to the journal + ledger
// Reduce stock for a sale that is actually linked to a registered
// product. Freehand-typed narration with no product_id is left
// untouched — matching a name by text alone is too unreliable.
// Every sale must be linked to an actual product — without that link
// there's no way to know what to deduct from stock or what it cost,
// so free-text sales (picked from nowhere, no product_id) are rejected
// here rather than silently skipping the stock/COGS side for them.
function bdValidateSaleRow(row) {
  return null; // a product from the list is optional: only linked products touch stock / cost of goods
}
async function bdDeductStockForSale(row) {
  if (!row.product_id) return;
  const qty = parseFloat(row.qty) || 1;
  if (qty <= 0) return;
  try {
    const { data } = await bkDb.from('bk_products').select('qty_in_stock').eq('id', row.product_id).single();
    if (!data) return;
    const newQty = (parseFloat(data.qty_in_stock) || 0) - qty;
    await bkDb.from('bk_products').update({ qty_in_stock: newQty, qty_as_at: today() }).eq('id', row.product_id);
    salesProductCacheBizId = undefined; // stock changed — refresh the picker cache next time it's used
  } catch(e) {}
}
// If the dashboard is the page currently on screen, refresh its
// numbers immediately after something that affects them is posted.
async function bdRefreshDashboardIfVisible() {
  if (currentPage !== 'all-businesses') return;
  // A lightweight refresh: re-fetch and re-render only, without the
  // full-page loading flash or resetting activeBusiness — those are
  // appropriate for a real navigation, not a background live-update.
  try {
    const bizMetrics = await fetchAllBusinessMetrics();
    renderAllBusinessesDashboard(bizMetrics);
  } catch(e) {}
}

// A row that is already in the books is changed in place (never posted twice).
async function bdUpdatePostedEntry(row, date, narration) {
  const amount = parseFloat(row.total) || 0;
  const upd = { txn_date: date, narration: narration, payee: row.payee || null, payer: row.payer || null };
  const { data: legs } = await bkDb.from('bk_transactions').select('id,debit,credit').eq('journal_id', row._jid);
  const canAmt = legs && legs.length === 2;
  const jupd = Object.assign({}, upd);
  if (canAmt) { jupd.debit_amount = amount; jupd.credit_amount = amount; }
  await bkDb.from('bk_journal').update(jupd).eq('id', row._jid);
  if (legs && legs.length) {
    await bkDb.from('bk_transactions').update(Object.assign({ payment_mode: row.pay_mode || 'cash' }, upd)).eq('journal_id', row._jid);
    if (canAmt) for (const l of legs) await bkDb.from('bk_transactions').update((parseFloat(l.debit)||0) > 0 ? { debit: amount } : { credit: amount }).eq('id', l.id);
  }
}
async function autoPostSaleRow(row, customerName, txnDate, forcedBusinessId) {
  if (!bkUser || !row.total || row.total <= 0) return;
  try { bdNoteUnregistered(row); } catch(e) {}
  if (row._jid) {
    if (row._own && (row.product_id || (row._pm && row._pm !== (row.pay_mode||'cash')))) {
      try { await bdCascadeDeleteJournalEntry(row._jid); } catch(e) {}   // restores stock; then post fresh below
      row._jid = null;
    } else {
      await bdUpdatePostedEntry(row, txnDate || row.txn_date || today(), (row.product || row.narration || 'Sale') + (customerName ? ' — ' + customerName : ''));
      bdRefreshDashboardIfVisible();
      return;
    }
  }
  const bizId = forcedBusinessId !== undefined ? forcedBusinessId : (activeBusiness?.id||null);
  const payMode = row.pay_mode || row.payMode || 'cash';
  let cashAcct;
  if (payMode === 'credit')            cashAcct = 'Debtors';
  else if (payMode === 'transfer' || payMode === 'pos' || payMode === 'cheque' || payMode === 'debitcard' || payMode === 'creditcard') cashAcct = 'Cash at Bank';
  else                                  cashAcct = 'Cash in Hand';
  const incomeAcct = await bdSaleIncomeAccount(row);
  const amount     = parseFloat(row.total) || 0;
  const narration  = (row.product || row.narration || 'Sale') + (customerName ? ' — ' + customerName : '');
  const date       = txnDate || new Date().toISOString().slice(0,10);
  // Shared by both journal entries this sale posts (revenue + COGS),
  // so deleting either one later finds and removes both together.
  const saleRefId  = (crypto.randomUUID ? crypto.randomUUID() : 'sale'+Date.now()+Math.random().toString(16).slice(2));

  // 1. Write to bk_journal
  const { data: jnl, error: jErr } = await bkDb.from('bk_journal').insert({
    user_id:              bkUser.id,
    business_id:          bizId,
    txn_date:             date,
    narration:            narration,
    payee:                row.payee || null,
    payer:                row.payer || null,
    debit_account_name:   cashAcct,
    debit_record_type:    'asset',
    credit_account_name:  incomeAcct,
    credit_record_type:   'income',
    debit_amount:         amount,
    credit_amount:        amount,
    product_id:           row.product_id || null,
    qty:                  parseFloat(row.qty) || null,
    sale_ref_id:          saleRefId,
    created_at:           new Date().toISOString(),
  }).select().single();

  if (jErr || !jnl) return;
  row._jid = jnl.id; row._own = true; row._pm = payMode;

  // 2. Find account IDs and calculate new running balances
  const [cashRes, incomeRes] = await Promise.all([
    acctBizFilter(bkDb.from('bk_accounts').select('id,opening_balance')).eq('account_name',cashAcct).maybeSingle(),
    acctBizFilter(bkDb.from('bk_accounts').select('id,opening_balance')).eq('account_name',incomeAcct).maybeSingle(),
  ]);

  // 3. Get last balance for each account to calculate running balance
  const getLastBal = async (acctName) => {
    const { data } = await bkDb.from('bk_transactions')
      .select('balance').match(bizMatch()).eq('account_name',acctName)
      .order('created_at',{ascending:false}).limit(1);
    return parseFloat(data?.[0]?.balance) || 0;
  };

  const cashLastBal   = await getLastBal(cashAcct);
  const incomeLastBal = await getLastBal(incomeAcct);

  // 4. Post to bk_transactions (both sides of the entry)
  const txns = [];
  if (cashRes?.data) {
    txns.push({
      user_id:      bkUser.id,
      journal_id:   jnl.id,
      record_type:  'asset',
      account_name: cashAcct,
      txn_date:     date,
      narration:    narration,
      payee:        row.payee || null,
      payer:        row.payer || null,
      debit:        amount,
      credit:       0,
      balance:      cashLastBal + amount, // assets increase with debit
      created_at:   new Date().toISOString(),
    });
  }
  if (incomeRes?.data) {
    txns.push({
      user_id:      bkUser.id,
      journal_id:   jnl.id,
      record_type:  'income',
      account_name: incomeAcct,
      txn_date:     date,
      narration:    narration,
      payee:        row.payee || null,
      payer:        row.payer || null,
      debit:        0,
      credit:       amount,
      balance:      incomeLastBal + amount, // income increases with credit
      created_at:   new Date().toISOString(),
    });
  }
  txns.forEach(t=>{ if(bizId) t.business_id=bizId; if(row.txn_group_id) t.txn_group_id=row.txn_group_id; t.payment_mode=payMode; });
  if (txns.length) await bkDb.from('bk_transactions').insert(txns);

  await postCogsForSale(row, bizId, date, saleRefId);
  await bdDeductStockForSale(row);
  bdRefreshDashboardIfVisible();
}

// Debit Cost of Goods Sold — Credit Inventory / Stock, at the
// product's cost price (not selling price). This is the piece that
// was missing alongside the existing quantity deduction: without it,
// a sale recorded revenue but never reduced the inventory asset's
// book value or recorded the actual cost of what was sold, so gross
// profit and the balance sheet were both wrong. Silently does nothing
// for a row with no linked product, or a product with no cost price
// set — there's nothing meaningful to post in that case.
async function postCogsForSale(row, bizId, date, saleRefId) {
  if (!row.product_id) return;
  const qty = parseFloat(row.qty) || 0;
  if (qty <= 0) return;
  try {
    const { data: product } = await bkDb.from('bk_products').select('cost_price, custom').eq('id', row.product_id).single();
    const invName = (product && product.custom && product.custom.__invsub && (accounts.asset || []).some(a => a.account_name === product.custom.__invsub)) ? product.custom.__invsub : 'Inventory / Stock';
    const costPrice = parseFloat(product?.cost_price) || 0;
    if (costPrice <= 0) return; // no cost recorded for this product — nothing to post
    const amount = costPrice * qty;
    const narration = 'Cost of goods sold' + (row.narration ? ' — ' + row.narration : '');

    const { data: jnl, error: jErr } = await bkDb.from('bk_journal').insert({
      user_id: bkUser.id, business_id: bizId, txn_date: date, narration: narration,
      debit_account_name: 'Cost of Goods Sold', debit_record_type: 'expenditure',
      credit_account_name: invName, credit_record_type: 'asset',
      debit_amount: amount, credit_amount: amount,
      product_id: row.product_id, qty: qty, sale_ref_id: saleRefId,
      created_at: new Date().toISOString(),
    }).select().single();
    if (jErr || !jnl) return;

    const [cogsRes, invRes] = await Promise.all([
      acctBizFilter(bkDb.from('bk_accounts').select('id')).eq('account_name', 'Cost of Goods Sold').maybeSingle(),
      acctBizFilter(bkDb.from('bk_accounts').select('id')).eq('account_name', invName).maybeSingle(),
    ]);
    const getLastBal = async (acctName) => {
      const { data } = await bkDb.from('bk_transactions').select('balance').match(bizMatch())
        .eq('account_name', acctName).order('created_at', { ascending: false }).limit(1);
      return parseFloat(data?.[0]?.balance) || 0;
    };
    const [cogsLastBal, invLastBal] = await Promise.all([getLastBal('Cost of Goods Sold'), getLastBal(invName)]);

    const txns = [];
    if (cogsRes?.data) txns.push({
      user_id: bkUser.id, journal_id: jnl.id, record_type: 'expenditure', account_name: 'Cost of Goods Sold',
      txn_date: date, narration, debit: amount, credit: 0,
      balance: cogsLastBal + amount, created_at: new Date().toISOString(),
    });
    if (invRes?.data) txns.push({
      user_id: bkUser.id, journal_id: jnl.id, record_type: 'asset', account_name: invName,
      txn_date: date, narration, debit: 0, credit: amount,
      balance: invLastBal - amount, created_at: new Date().toISOString(),
    });
    txns.forEach(t => { if (bizId) t.business_id = bizId; if (row.txn_group_id) t.txn_group_id = row.txn_group_id; });
    if (txns.length) await bkDb.from('bk_transactions').insert(txns);
  } catch (e) {}
}

// Save a customer block AND auto-post all rows to the accounting ledger
async function staffSaveCustomer(custId) {
  const cust = staffGetCust(custId);
  if (!cust) return;
  if (cust._posting) return; // prevent double-post
  cust._posting = true;

  // Find the Save button and show saving state
  let saveBtn = null;
  document.querySelectorAll('.staff-save-static-btn').forEach(function(b){
    if (b.getAttribute('onclick') === 'staffSaveCustomer('+custId+')') saveBtn = b;
  });
  if (saveBtn) { saveBtn.textContent = 'Posting…'; saveBtn.disabled = true; }

  const date = new Date().toISOString().slice(0,10);
  const rows  = (cust.rows || []).filter(function(r){ return r.total > 0; });
  for (const row of rows) {
    const err = bdValidateSaleRow(row);
    if (err) { alert(err); cust._posting = false; if (saveBtn) { saveBtn.textContent = 'Save'; saveBtn.disabled = false; } return; }
  }

  try {
    const isOnline = navigator.onLine;
    if (isOnline) {
      // Online — post directly to Supabase
      for (const row of rows) {
        await autoPostSaleRow(row, cust.name, date);
      }
    } else {
      // Offline — save to IndexedDB queue
      for (const row of rows) {
        await bdSaveOffline(row, cust.name, date);
      }
      bdUpdateSyncBadge();
    }
    // Mark saved
    cust.posted = true;
    if (saveBtn) {
      saveBtn.textContent = isOnline ? '✓ Posted' : '✓ Saved offline';
      saveBtn.style.background = 'var(--green)';
      saveBtn.disabled = false;
      setTimeout(function(){
        saveBtn.textContent = '› Save';
        saveBtn.style.background = '';
        cust._posting = false;
      }, 2500);
    }
    // Refresh equation bar if visible
    if (document.getElementById('bkMainChrome')?.style.display !== 'none') {
      refreshEquation();
    }
  } catch(e) {
    cust._posting = false;
    if (saveBtn) {
      saveBtn.textContent = '⚠ Error — retry';
      saveBtn.style.background = 'var(--red)';
      saveBtn.disabled = false;
    }
  }
}

