// ── SWIPE: mobile/tablet pane navigation ──────────────────────
// Remembers which pane each customer's swipe view was on, across re-renders
let staffActivePaneByCust = {};

function initStaffSwipe(){
  document.querySelectorAll('.staff-swipe-wrap').forEach(function(wrap){
    const track  = wrap.querySelector('.staff-swipe-track');
    const dots   = wrap.querySelectorAll('.staff-swipe-dot');
    const custId = wrap.dataset.custid;
    const paneCount = parseInt(wrap.dataset.panecount) || 1;
    const paneUnit = 100 / paneCount; // % of track width per pane
    let startX = 0, isDragging = false;
    let currentPane = Math.min(staffActivePaneByCust[custId] || 0, paneCount - 1);

    function goToPane(idx, animate){
      currentPane = Math.max(0, Math.min(paneCount - 1, idx));
      staffActivePaneByCust[custId] = currentPane; // remember for next re-render
      track.style.transition = animate ? 'transform 0.25s ease' : 'none';
      track.style.transform = 'translateX(-' + (currentPane*paneUnit) + '%)';
      dots.forEach(function(d,i){ d.classList.toggle('active', i===currentPane); });
    }
    dots.forEach(function(d,i){ d.addEventListener('click', function(){ goToPane(i, true); }); });

    track.addEventListener('touchstart', function(e){
      startX = e.touches[0].clientX; isDragging = true;
      track.style.transition = 'none';
    }, {passive:true});

    track.addEventListener('touchmove', function(e){
      if (!isDragging) return;
      const dx = e.touches[0].clientX - startX;
      const pct = (dx / wrap.offsetWidth) * paneUnit;
      track.style.transform = 'translateX(calc(-' + (currentPane*paneUnit) + '% + ' + pct + '%))';
    }, {passive:true});

    track.addEventListener('touchend', function(e){
      isDragging = false;
      const dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 50) {
        if (dx < 0) goToPane(currentPane+1, true); else goToPane(currentPane-1, true);
      } else {
        goToPane(currentPane, true);
      }
    });

    // Restore to whatever pane this customer was on — no animation, instant
    goToPane(currentPane, false);
  });
}

