// ── Master Journal: Payee / Payer / Narration cells scroll sideways ─────────
// Long text no longer needs a wider column: wheel/trackpad, finger drag or
// mouse drag slides the text inside the cell (mouse users: Shift+wheel, or click in and use the arrow keys). (Single-line cells only; the
// wrap-text mode already grows the row instead.)
(function(){
  function cellOf(t){
    if (!t || !t.closest) return null;
    const el = t.closest('#journalBody input.bk-cell[type="text"]');
    return (el && !el.classList.contains('bk-amt-input') && el.scrollWidth > el.clientWidth + 1) ? el : null;
  }
  document.addEventListener('wheel', function(e){
    const el = cellOf(e.target); if (!el) return;
    const dx = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : (e.shiftKey ? e.deltaY : 0);
    if (!dx) return;
    el.scrollLeft += dx; e.preventDefault();
  }, { passive:false });
  let tch = null;
  document.addEventListener('touchstart', function(e){
    if (window.matchMedia && matchMedia('(max-width:600px)').matches) { tch = null; return; }   // phones: finger drags move the whole sheet
    const el = cellOf(e.target); if (!el || e.touches.length !== 1) { tch = null; return; }
    tch = { el, x:e.touches[0].clientX, y:e.touches[0].clientY, sl:el.scrollLeft, lock:null };
  }, { passive:true });
  document.addEventListener('touchmove', function(e){
    if (!tch) return;
    const dx = e.touches[0].clientX - tch.x, dy = e.touches[0].clientY - tch.y;
    if (tch.lock === null && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) tch.lock = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y';
    if (tch.lock === 'x') { tch.el.scrollLeft = tch.sl - dx; e.preventDefault(); }
  }, { passive:false });
  document.addEventListener('touchend', function(){ tch = null; }, { passive:true });

})();

// ── Transaction cards: account names drift sideways by themselves ─────
// Only the card that is the main focus of the screen (the one nearest the middle of
// the viewport) animates; every other card stays still. On that card the DEBIT
// account glides left first and snaps back to the start, then the CREDIT account does, and it repeats.
// When another card becomes the focus, the previous one returns to rest and the new
// one starts from its Debit account. No manual scrolling on cards.
(function(){
  if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const SPEED = 34, PAUSE = 1400;           // px per second, ms at each end
  const seen = new WeakSet(), visible = new Set();
  const io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(es){
    es.forEach(function(en){ if (en.isIntersecting) visible.add(en.target); else visible.delete(en.target); });
    kick();
  }) : null;
  let focus = null, names = null, side = 0, dir = 1, pos = 0, until = 0, raf = 0, last = 0, lastPick = 0;
  function scan(){
    document.querySelectorAll('#jrnCardsWrap .jcard').forEach(function(c){
      if (!seen.has(c)) { seen.add(c); if (io) io.observe(c); else visible.add(c); }
    });
    visible.forEach(function(c){ if (!c.isConnected) { visible.delete(c); if (io) io.unobserve(c); } });
    kick();
  }
  function rest(c){ if (c) c.querySelectorAll('.jcard-leg .nm').forEach(function(e){ e.scrollLeft = 0; }); }
  function pick(){
    const mid = (window.innerHeight || document.documentElement.clientHeight) / 2;
    let best = null, bd = Infinity;
    visible.forEach(function(c){
      const r = c.getBoundingClientRect();
      if (r.height <= 0) return;
      const d = Math.abs((r.top + r.bottom) / 2 - mid);
      if (d < bd) { bd = d; best = c; }
    });
    if (best !== focus) {
      rest(focus); focus = best; side = 0; dir = 1; pos = 0; until = performance.now() + 600;
      names = focus ? [focus.querySelector('.jcard-leg.dr .nm'), focus.querySelector('.jcard-leg.cr .nm')] : null;
    }
  }
  function kick(){ if (!raf && visible.size && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(tick); } }
  function room(el){ return el ? el.scrollWidth - el.clientWidth : 0; }
  function tick(now){
    raf = 0;
    if (!visible.size) { rest(focus); focus = null; return; }
    if (now - lastPick > 250) { lastPick = now; pick(); }
    if (!focus || !names) { raf = requestAnimationFrame(tick); return; }
    const dt = Math.min(64, now - last); last = now;
    let el = names[side], max = room(el);
    if (max <= 1) {                               // this account fits: hand over to the other one
      if (room(names[1 - side]) <= 1) { raf = requestAnimationFrame(tick); return; }
      side = 1 - side; pos = 0; dir = 1; until = now + 300; raf = requestAnimationFrame(tick); return;
    }
    if (now >= until) {
      if (pos >= max) {
        // reached the end of the text: snap straight back to the start (no scroll back),
        // then it is the other account's turn
        pos = 0; el.scrollLeft = 0; until = now + 500;
        side = 1 - side; el = names[side];
      } else {
        pos += SPEED * dt / 1000;
        if (pos >= max) { pos = max; until = now + PAUSE; }
      }
    }
    if (el) el.scrollLeft = pos;
    raf = requestAnimationFrame(tick);
  }
  setInterval(scan, 800);
  document.addEventListener('visibilitychange', kick);
})();

// ══════════════════════════════════════════════════════════════════════
//  STAFF · ROLES · JOINING BY BUSINESS ID
//  Needs migration_staff_v1.sql. Without it the app behaves as before.
// ══════════════════════════════════════════════════════════════════════
let bizAccess = { full: true, role: 'Owner', perms: {}, status: 'active', legacy: true };
const BD_PERMS = [
  { k: 'sales.record', t: 'Record sales', d: 'Can open Record a sale and post sales' },
  { k: 'expenses.record', t: 'Record expenses', d: 'Can record business expenses' },
  { k: 'req.raise', t: 'Raise requisitions', d: 'Can ask for money or items' },
];
function bdCan(p) { return !!(bizAccess.full || (bizAccess.perms && bizAccess.perms[p])); }

async function bdLoadAccess() {
  if (!activeBusiness || activeBusiness._owned) { bizAccess = { full: true, role: 'Owner', perms: {}, status: 'active', legacy: false }; return; }
  try {
    const { data, error } = await bkDb.rpc('bk_my_access', { bid: activeBusiness.id });
    if (error || !data) throw error || new Error('none');
    bizAccess = { full: !!data.full, role: data.role || 'Staff', perms: data.perms || {}, status: data.status || 'active', legacy: false };
    if (bizAccess.status !== 'none') userRole = bizAccess.full ? 'manager' : 'employee';
  } catch (e) { bizAccess.legacy = true; }
}

function bdStaffCss() {
  if (document.getElementById('bdStaffCss')) return;
  const s = document.createElement('style'); s.id = 'bdStaffCss';
  s.textContent = `
  .tm-wrap{max-width:860px;margin:0 auto;padding:16px}
  .tm-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px;margin-bottom:12px}
  .tm-id{font-family:ui-monospace,Menlo,monospace;font-size:1.25rem;font-weight:800;letter-spacing:.06em;color:var(--gold)}
  .tm-tabs{display:flex;gap:6px;overflow-x:auto;margin:6px 0 14px}
  .tm-tab{padding:8px 14px;border-radius:999px;border:1px solid var(--border);background:transparent;color:var(--muted);font-weight:700;font-size:.78rem;cursor:pointer;white-space:nowrap}
  .tm-tab.on{background:var(--gold);color:var(--accent-ink);border-color:var(--gold)}
  .tm-tab b{margin-left:5px;background:#e5484d;color:#fff;border-radius:99px;padding:0 6px;font-size:.66rem}
  .tm-row{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--border)}
  .tm-row:last-child{border-bottom:0}
  .tm-av{width:42px;height:42px;border-radius:50%;background:var(--gold-t014);color:var(--gold);display:flex;align-items:center;justify-content:center;font-weight:800;overflow:hidden;flex:none}
  .tm-av img{width:100%;height:100%;object-fit:cover}
  .tm-nm{font-weight:800;font-size:.88rem;color:var(--white)}
  .tm-sub{font-size:.72rem;color:var(--muted)}
  .tm-pill{font-size:.64rem;font-weight:800;padding:2px 8px;border-radius:99px;background:var(--gold-t014);color:var(--gold)}
  .tm-pill.pa{background:#f59e0b22;color:#f59e0b}
  .tm-btn{border:1px solid var(--border);background:transparent;color:var(--white);border-radius:8px;padding:6px 11px;font-weight:700;font-size:.74rem;cursor:pointer}
  .tm-btn.pri{background:var(--gold);border-color:var(--gold);color:var(--accent-ink)}
  .tm-btn.red{color:#f87171;border-color:#f8717155}
  .tm-in{width:100%;box-sizing:border-box;padding:10px;border-radius:8px;border:1px solid var(--border);background:var(--bg,transparent);color:var(--white);font-size:.9rem}
  .tm-sel{padding:7px;border-radius:8px;border:1px solid var(--border);background:var(--surface);color:var(--white)}
  .tm-perm{display:flex;gap:10px;align-items:flex-start;padding:7px 0;font-size:.82rem}
  .st-hero{padding:18px 16px 6px}
  .st-big{display:block;width:calc(100% - 32px);margin:10px 16px;padding:18px;border:0;border-radius:14px;background:var(--gold);color:var(--accent-ink);font-weight:900;font-size:1.05rem;cursor:pointer}
  .st-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 16px}
  .st-k{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px}
  .st-k small{display:block;color:var(--muted);font-size:.68rem;font-weight:700}
  .st-k b{font-size:1.1rem;color:var(--white)}
  `;
  document.head.appendChild(s);
}
function bdInitials(n) { const p = String(n || '?').trim().split(/\s+/); return ((p[0] || '?')[0] + (p.length > 1 ? p[p.length - 1][0] : '')).toUpperCase(); }
function bdAvatar(name, photo, size) {
  const st = size ? `style="width:${size}px;height:${size}px;font-size:${Math.round(size / 2.6)}px"` : '';
  return `<span class="tm-av" ${st}>${photo ? `<img src="${escH(photo)}" alt=""/>` : escH(bdInitials(name))}</span>`;
}
function bdBizCode() { return activeBusiness?.business_code || ''; }
function bdInviteLink() { return location.origin + location.pathname + '?join=' + encodeURIComponent(bdBizCode()); }

// ── Team page (people with full access) ───────────────────────────────
let _tm = { tab: 'people', team: [], roles: [], reqs: [], act: [], err: '' };
async function showTeam(tab) {
  if (!bizAccess.full) { bdToast('You do not have access to the Team page', 'error'); return goToHomepage(); }
  bdStaffCss(); staffHideChrome();
  try { bdSaveRoute('team'); } catch (e) {}
  _tm.tab = tab || _tm.tab || 'people';
  document.getElementById('bkContent').innerHTML = '<div class="bk-loading">Loading team…</div>';
  _tm.err = '';
  if (!activeBusiness) { _tm.err = 'Pick or register a business first.'; return tmRender(); }
  if (!activeBusiness.business_code) {
    try { const { data } = await bkDb.from('businesses').select('business_code').eq('id', activeBusiness.id).maybeSingle(); if (data?.business_code) activeBusiness.business_code = data.business_code; } catch (e) {}
  }
  const bid = activeBusiness.id;
  const [t, r, q] = await Promise.all([
    bkDb.rpc('bk_team', { bid }), bkDb.from('bk_roles').select('*').eq('business_id', bid).order('created_at'), bkDb.rpc('bk_join_list', { bid }),
  ]);
  if (t.error && /bk_team|function/i.test(t.error.message || '')) _tm.err = 'The staff set-up has not been switched on yet. Run migration_staff_v1.sql in Supabase once.';
  _tm.team = t.data || []; _tm.roles = r.data || []; _tm.reqs = q.data || [];
  tmRender();
}
function tmTabs() {
  const T = [['people', 'People'], ['requests', 'Requests'], ['roles', 'Roles'], ['activity', 'Activity']];
  return `<div class="tm-tabs">${T.map(([k, l]) => `<button class="tm-tab ${_tm.tab === k ? 'on' : ''}" onclick="showTeam('${k}')">${l}${k === 'requests' && _tm.reqs.length ? `<b>${_tm.reqs.length}</b>` : ''}</button>`).join('')}</div>`;
}
function tmRender() {
  const code = bdBizCode();
  let body = '';
  if (_tm.err) body = `<div class="tm-card" style="color:#f59e0b">${escH(_tm.err)}</div>`;
  else if (_tm.tab === 'people') body = tmPeople();
  else if (_tm.tab === 'requests') body = tmRequests();
  else if (_tm.tab === 'roles') body = tmRoles();
  else body = '<div class="bk-loading">Loading activity…</div>';
  document.getElementById('bkContent').innerHTML = `<div class="tm-wrap">
    <div style="font-size:1.3rem;font-weight:900;color:var(--white);margin-bottom:10px">Team</div>
    <div class="tm-card">
      <div class="tm-sub">BUSINESS ID — send this to someone you want on your team</div>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:6px">
        <span class="tm-id" id="tmCode">${escH(code || '—')}</span>
        <button class="tm-btn" onclick="tmCopy('${escJs(code)}','Business ID copied')">Copy ID</button>
        <button class="tm-btn" onclick="tmCopy('${escJs(bdInviteLink())}','Invite link copied')">Copy invite link</button>
        ${activeBusiness?._owned ? `<button class="tm-btn" onclick="tmResetCode()">Make a new ID</button>` : ''}
      </div>
      <div class="tm-sub" style="margin-top:6px">People can open your invite link, or type this ID under Join a business. Either way you approve them before they get in.</div>
    </div>
    ${tmTabs()}${body}</div>`;
  if (_tm.tab === 'activity' && !_tm.err) tmLoadActivity();
}
function tmCopy(txt, msg) { try { navigator.clipboard.writeText(txt); } catch (e) { const t = document.createElement('textarea'); t.value = txt; document.body.appendChild(t); t.select(); try { document.execCommand('copy'); } catch (e2) {} t.remove(); } bdToast(msg); }
async function tmResetCode() {
  if (!confirm('Make a new Business ID? The old ID and old invite links will stop working. People already on your team stay.')) return;
  const { data, error } = await bkDb.rpc('bk_reset_business_code', { bid: activeBusiness.id });
  if (error) return bdToast(error.message, 'error');
  activeBusiness.business_code = data; tmRender(); bdToast('New ID ready');
}
function tmPeople() {
  const me = bkUser?.id;
  if (!_tm.team.length) return '<div class="tm-card tm-sub">No one yet.</div>';
  const roleOpts = sel => _tm.roles.map(r => `<option value="${r.id}" ${r.id === sel ? 'selected' : ''}>${escH(r.name)}</option>`).join('');
  return `<div class="tm-card">${_tm.team.map(m => `
    <div class="tm-row">${bdAvatar(m.display_name, m.photo_url)}
      <div style="flex:1;min-width:0"><div class="tm-nm">${escH(m.display_name)}${m.user_id === me ? ' <span class="tm-sub">(you)</span>' : ''}</div>
        <div class="tm-sub">${escH(m.role_name)} ${m.status === 'paused' ? '· <span class="tm-pill pa">Paused</span>' : ''}</div></div>
      ${m.is_owner ? '<span class="tm-pill">Owner</span>' : `
        <select class="tm-sel" onchange="tmSetRole('${m.user_id}',this.value)">${roleOpts(m.role_id)}</select>
        <button class="tm-btn" onclick="tmPause('${m.user_id}','${m.status === 'paused' ? 'active' : 'paused'}')">${m.status === 'paused' ? 'Resume' : 'Pause'}</button>
        <button class="tm-btn red" onclick="tmRemove('${m.user_id}','${escJs(m.display_name)}')">Remove</button>`}
    </div>`).join('')}</div>`;
}
async function tmSetRole(uid, rid) { const { error } = await bkDb.rpc('bk_set_member', { bid: activeBusiness.id, uid, new_role: rid, new_status: null }); if (error) bdToast(error.message, 'error'); else { bdToast('Role changed'); showTeam('people'); } }
async function tmPause(uid, st) { const { error } = await bkDb.rpc('bk_set_member', { bid: activeBusiness.id, uid, new_role: null, new_status: st }); if (error) bdToast(error.message, 'error'); else { bdToast(st === 'paused' ? 'Paused' : 'Back on the team'); showTeam('people'); } }
async function tmRemove(uid, nm) { if (!confirm('Remove ' + nm + ' from this business? Their past entries stay in the books.')) return; const { error } = await bkDb.rpc('bk_remove_member', { bid: activeBusiness.id, uid }); if (error) bdToast(error.message, 'error'); else { bdToast('Removed'); showTeam('people'); } }

function tmRequests() {
  if (!_tm.reqs.length) return '<div class="tm-card tm-sub">No one is waiting to join.</div>';
  const roleOpts = _tm.roles.filter(r => !r.is_system).map(r => `<option value="${r.id}">${escH(r.name)}</option>`).join('');
  return `<div class="tm-card">${_tm.reqs.map(q => `
    <div class="tm-row">${bdAvatar(q.display_name, q.photo_url)}
      <div style="flex:1;min-width:0"><div class="tm-nm">${escH(q.display_name)}</div><div class="tm-sub">Asked ${new Date(q.created_at).toLocaleDateString()}</div></div>
      <select class="tm-sel" id="rq_${q.id}">${roleOpts}</select>
      <button class="tm-btn pri" onclick="tmDecide('${q.id}',true)">Approve</button>
      <button class="tm-btn red" onclick="tmDecide('${q.id}',false)">Decline</button>
    </div>`).join('')}</div>`;
}
async function tmDecide(id, ok) {
  const rid = ok ? document.getElementById('rq_' + id)?.value : null;
  if (ok && !rid) return bdToast('Pick a role first', 'error');
  const { error } = await bkDb.rpc('bk_decide_join', { rid: id, approve: ok, rid_role: rid || null });
  if (error) bdToast(error.message, 'error'); else { bdToast(ok ? 'Approved' : 'Declined'); showTeam('requests'); }
}

// Roles
function tmRoles() {
  return `<div class="tm-card">${_tm.roles.map(r => `
    <div class="tm-row"><div style="flex:1"><div class="tm-nm">${escH(r.name)}</div>
      <div class="tm-sub">${r.full_access ? 'Full access' : (BD_PERMS.filter(p => r.perms && r.perms[p.k]).map(p => p.t).join(', ') || 'Nothing yet')}</div></div>
      ${r.is_system ? '<span class="tm-pill">Fixed</span>' : `<button class="tm-btn" onclick="tmEditRole('${r.id}')">Edit</button><button class="tm-btn red" onclick="tmDelRole('${r.id}')">Delete</button>`}
    </div>`).join('')}
    <div style="margin-top:12px"><button class="tm-btn pri" onclick="tmEditRole('')">+ New role</button></div></div>`;
}
function tmEditRole(id) {
  const r = _tm.roles.find(x => x.id === id) || { name: '', full_access: false, perms: {} };
  const o = document.createElement('div'); o.id = 'tmRoleDlg';
  o.style.cssText = 'position:fixed;inset:0;background:#0009;z-index:10050;display:flex;align-items:center;justify-content:center;padding:16px';
  o.innerHTML = `<div class="tm-card" style="width:min(440px,100%);margin:0;max-height:90vh;overflow:auto">
    <div class="tm-nm" style="font-size:1rem;margin-bottom:8px">${id ? 'Edit role' : 'New role'}</div>
    <input class="tm-in" id="tmRName" placeholder="Role name, e.g. Store keeper" value="${escH(r.name)}"/>
    <label class="tm-perm"><input type="checkbox" id="tmRFull" ${r.full_access ? 'checked' : ''} onchange="document.getElementById('tmRPerms').style.display=this.checked?'none':''"/><span><b>Full access</b><br><span class="tm-sub">Sees and does everything, and approves new people</span></span></label>
    <div id="tmRPerms" style="${r.full_access ? 'display:none' : ''}">${BD_PERMS.map(p => `<label class="tm-perm"><input type="checkbox" data-k="${p.k}" ${r.perms && r.perms[p.k] ? 'checked' : ''}/><span><b>${p.t}</b><br><span class="tm-sub">${p.d}</span></span></label>`).join('')}</div>
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="tm-btn" onclick="document.getElementById('tmRoleDlg').remove()">Cancel</button><button class="tm-btn pri" onclick="tmSaveRole('${id}')">Save</button></div></div>`;
  document.body.appendChild(o);
}
async function tmSaveRole(id) {
  const name = document.getElementById('tmRName').value.trim(); const full = document.getElementById('tmRFull').checked;
  const perms = {}; document.querySelectorAll('#tmRPerms input[data-k]').forEach(c => { if (c.checked) perms[c.dataset.k] = true; });
  const { error } = await bkDb.rpc('bk_save_role', { bid: activeBusiness.id, rid: id || null, rname: name, rfull: full, rperms: perms });
  if (error) return bdToast(error.message, 'error');
  document.getElementById('tmRoleDlg')?.remove(); bdToast('Role saved'); showTeam('roles');
}
async function tmDelRole(id) { if (!confirm('Delete this role?')) return; const { error } = await bkDb.rpc('bk_delete_role', { bid: activeBusiness.id, rid: id }); if (error) bdToast(error.message, 'error'); else { bdToast('Role deleted'); showTeam('roles'); } }

// Activity: who recorded what
async function tmLoadActivity() {
  const { data, error } = await bkDb.rpc('bk_activity', { bid: activeBusiness.id, lim: 80 });
  const box = document.querySelector('.tm-wrap .bk-loading'); if (!box) return;
  if (error) { box.outerHTML = `<div class="tm-card" style="color:#f59e0b">${escH(error.message)}</div>`; return; }
  const names = {}; _tm.team.forEach(m => names[m.user_id] = m.display_name);
  const rows = (data || []).map(a => `<div class="tm-row"><div style="flex:1;min-width:0"><div class="tm-nm">${escH(names[a.user_id] || 'Someone')}</div>
    <div class="tm-sub">${escH(a.narration || a.account_name || '')}</div></div>
    <div style="text-align:right"><div class="tm-nm">${staffFmtAmt(parseFloat(a.credit) || parseFloat(a.debit) || 0)}</div><div class="tm-sub">${escH(a.txn_date || '')}</div></div></div>`).join('');
  box.outerHTML = `<div class="tm-card">${rows || '<div class="tm-sub">Nothing recorded yet.</div>'}</div>`;
}

// ── Join a business (replaces joining by business name) ──────────────
let _jn = { found: null, code: '' };
async function showJoinBusiness(prefill) {
  bdStaffCss(); staffHideChrome();
  try { bdSaveRoute('join-business'); } catch (e) {}
  _jn = { found: null, code: prefill || '' };
  let mine = [];
  try { const { data } = await bkDb.rpc('bk_my_requests'); mine = data || []; } catch (e) {}
  const pend = mine.filter(r => r.status === 'pending');
  document.getElementById('bkContent').innerHTML = `<div class="tm-wrap" style="max-width:520px">
    <div style="font-size:1.3rem;font-weight:900;color:var(--white)">Join a business</div>
    <div class="tm-sub" style="margin:4px 0 14px">Ask the business for its Business ID, then type it here. The owner or someone with full access will approve you.</div>
    <div style="display:flex;gap:8px"><input class="tm-in" id="jnCode" placeholder="e.g. BU-04821-KM" value="${escH(_jn.code)}" style="text-transform:uppercase" onkeydown="if(event.key==='Enter')jnFind()"/><button class="tm-btn pri" onclick="jnFind()">Find</button></div>
    <div id="jnFound" style="margin-top:12px"></div>
    ${mine.length ? `<div class="tm-card" style="margin-top:16px"><div class="tm-sub" style="margin-bottom:6px">YOUR REQUESTS</div>${mine.map(r => `<div class="tm-row"><div style="flex:1"><div class="tm-nm">${escH(r.business_name)}</div><div class="tm-sub">${r.status === 'pending' ? 'Waiting for approval' : r.status === 'approved' ? 'Approved' : 'Declined'}</div></div>
      ${r.status === 'pending' ? `<button class="tm-btn" onclick="jnCancel('${r.id}')">Cancel</button>` : ''}${r.status === 'approved' ? `<button class="tm-btn pri" onclick="location.reload()">Open</button>` : ''}</div>`).join('')}
      ${pend.length ? '<div class="tm-sub" style="margin-top:8px">You will see the business here once it approves you. <a href="#" onclick="location.reload();return false" style="color:var(--gold)">Check again</a></div>' : ''}</div>` : ''}
    <div style="margin-top:16px"><button class="tm-btn" onclick="showModeChoice()">← Back</button></div></div>`;
  if (prefill) jnFind();
}
async function jnFind() {
  const code = (document.getElementById('jnCode')?.value || '').trim().toUpperCase(); const box = document.getElementById('jnFound'); if (!code || !box) return;
  box.innerHTML = '<div class="tm-sub">Looking…</div>';
  const { data, error } = await bkDb.rpc('bk_find_business', { code });
  if (error) { box.innerHTML = `<div class="tm-sub" style="color:#f59e0b">Could not check right now. ${escH(error.message)}</div>`; return; }
  const b = (data || [])[0];
  if (!b) { box.innerHTML = '<div class="tm-sub" style="color:#f59e0b">No business has that ID. Check it with the business and try again.</div>'; return; }
  _jn.found = b; _jn.code = code;
  box.innerHTML = `<div class="tm-card"><div class="tm-nm" style="font-size:1rem">${escH(b.name)}</div><div class="tm-sub">${escH(b.industry || '')}</div>
    <div class="tm-sub" style="margin:10px 0 4px">Your name, as the team should see it</div><input class="tm-in" id="jnName" value="${escH(staffDisplayName || '')}"/>
    <button class="tm-btn pri" style="margin-top:10px;width:100%;padding:11px" onclick="jnSend()">Ask to join</button></div>`;
}
async function jnSend() {
  const dname = document.getElementById('jnName')?.value.trim(); if (!dname) return bdToast('Type your name', 'error');
  const { error } = await bkDb.rpc('bk_request_join', { code: _jn.code, dname });
  if (error) return bdToast(error.message, 'error');
  try { await bkDb.rpc('bk_set_my_profile', { dname, photo: null }); } catch (e) {}
  bdToast('Request sent'); showJoinBusiness();
}
async function jnCancel(id) { await bkDb.rpc('bk_cancel_request', { rid: id }); showJoinBusiness(); }

// Invite link: ?join=CODE
function bdJoinLinkCode() { try { const c = new URLSearchParams(location.search).get('join'); if (c) { localStorage.setItem('bd_join_code', c.toUpperCase()); history.replaceState(null, '', location.pathname); } return localStorage.getItem('bd_join_code') || ''; } catch (e) { return ''; } }
function bdJoinLinkDone() { try { localStorage.removeItem('bd_join_code'); } catch (e) {} }
(function () { try { const c = new URLSearchParams(location.search).get('join'); if (c) localStorage.setItem('bd_join_code', c.toUpperCase()); } catch (e) {} })();

// ── Profile picture (stored small, in the member profile) ─────────────
function bdPickMyPhoto() {
  const i = document.createElement('input'); i.type = 'file'; i.accept = 'image/*';
  i.onchange = () => {
    const f = i.files[0]; if (!f) return; const img = new Image(); const u = URL.createObjectURL(f);
    img.onload = async () => {
      const c = document.createElement('canvas'); const s = 200; c.width = c.height = s; const x = c.getContext('2d');
      const m = Math.min(img.width, img.height); x.drawImage(img, (img.width - m) / 2, (img.height - m) / 2, m, m, 0, 0, s, s);
      const url = c.toDataURL('image/jpeg', 0.8); URL.revokeObjectURL(u);
      const { error } = await bkDb.rpc('bk_set_my_profile', { dname: staffDisplayName || null, photo: url });
      if (error) bdToast(error.message, 'error'); else { window._myPhoto = url; bdToast('Photo saved'); try { showStaffHome(); } catch (e) {} }
    }; img.src = u;
  };
  i.click();
}

// ── Staff home: what a restricted person sees ─────────────────────────
async function showStaffHome() {
  bdStaffCss(); staffHideChrome();
  try { bdSaveRoute('dashboard'); } catch (e) {}
  const el = document.getElementById('bkContent'); el.innerHTML = '<div class="bk-loading">Loading…</div>';
  const iso = d => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  const now = new Date(), today = iso(now), yest = iso(new Date(now.getTime() - 864e5));
  let mine = [], notices = [];
  try {
    const bq = bkDb.from('bk_transactions').select('account_name,record_type,debit,credit,narration,txn_date,created_at').eq('user_id', bkUser.id);
    const [t, n] = await Promise.all([
      (activeBusiness ? bq.eq('business_id', activeBusiness.id) : bq).order('created_at', { ascending: false }).limit(200),
      bkDb.from('bk_notices').select('*').eq('business_name', businessDisplayName || activeBusiness?.name || '').order('created_at', { ascending: false }).limit(4),
    ]);
    mine = t.data || []; notices = n.data || [];
  } catch (e) {}
  if (window._myPhoto === undefined) { try { const { data } = await bkDb.from('bk_member_profiles').select('photo_url').eq('user_id', bkUser.id).maybeSingle(); window._myPhoto = data?.photo_url || ''; } catch (e) { window._myPhoto = ''; } }
  const inc = r => r.record_type === 'income';
  const sum = (a, f) => a.reduce((s, r) => s + (parseFloat(f(r)) || 0), 0);
  const tdy = mine.filter(r => r.txn_date === today), yst = mine.filter(r => r.txn_date === yest);
  const salesT = sum(tdy.filter(inc), r => r.credit), salesY = sum(yst.filter(inc), r => r.credit);
  const cash = sum(tdy.filter(r => r.record_type === 'asset' && /cash|till/i.test(r.account_name)), r => r.debit);
  const toCollect = sum(tdy.filter(r => r.record_type === 'asset' && /receivable|debtor/i.test(r.account_name)), r => r.debit);
  const diff = salesY ? Math.round((salesT - salesY) / salesY * 100) : null;
  const nm = staffDisplayName || 'there'; const h = now.getHours();
  const recent = mine.filter(inc).slice(0, 6);
  el.innerHTML = `
    <div class="st-hero" style="display:flex;align-items:center;gap:12px">
      <div onclick="bdPickMyPhoto()" style="cursor:pointer" title="Change photo">${bdAvatar(nm, window._myPhoto, 52)}</div>
      <div style="flex:1"><div style="font-weight:900;font-size:1.05rem;color:var(--white)">${h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening'}, ${escH(nm.split(' ')[0])}</div>
      <div class="tm-sub">${escH(bizAccess.role)} · ${escH(activeBusiness?.name || businessDisplayName || '')}</div></div></div>
    ${bdCan('sales.record') ? `<button class="st-big" onclick="showStaffSales()">＋ Record a sale</button>` : ''}
    <div class="st-grid">
      <div class="st-k"><small>MY SALES TODAY</small><b>${staffFmtAmt(salesT)}</b><small>${diff === null ? 'Nothing yesterday' : (diff >= 0 ? '▲ ' : '▼ ') + Math.abs(diff) + '% vs yesterday'}</small></div>
      <div class="st-k"><small>ENTRIES TODAY</small><b>${tdy.filter(inc).length}</b><small>${tdy.length ? 'keep going' : 'none yet'}</small></div>
      <div class="st-k"><small>CASH TO HAND OVER</small><b>${staffFmtAmt(cash)}</b></div>
      <div class="st-k"><small>CREDIT SALES TO COLLECT</small><b>${staffFmtAmt(toCollect)}</b></div>
    </div>
    <div style="padding:14px 16px 0"><div class="tm-card"><div class="tm-nm" style="margin-bottom:6px">Notices</div>
      ${notices.length ? notices.map(n => `<div class="tm-sub" style="padding:5px 0;color:var(--white)">${escH(n.message || '')}</div>`).join('') : '<div class="tm-sub">No notices right now.</div>'}</div>
    <div class="tm-card"><div class="tm-nm" style="margin-bottom:6px">My latest entries</div>
      ${recent.length ? recent.map(r => `<div class="tm-row"><div style="flex:1;min-width:0"><div class="tm-nm" style="font-weight:600">${escH(r.narration || r.account_name)}</div><div class="tm-sub">${escH(r.txn_date || '')}</div></div><div class="tm-nm">${staffFmtAmt(parseFloat(r.credit) || 0)}</div></div>`).join('') : '<div class="tm-sub">Nothing recorded yet.</div>'}</div>
    <button class="tm-btn" style="width:100%;padding:12px" onclick="openRequisitions()">Requisitions</button></div>`;
}

async function bdIsLinkedStaff(){
  try {
    const [o,l] = await Promise.all([
      bkDb.from('businesses').select('id').eq('owner_user_id', bkUser.id).limit(1),
      bkDb.from('user_businesses').select('business_id').eq('user_id', bkUser.id).eq('role','employee').limit(1)]);
    return !(o.data||[]).length && !!(l.data||[]).length;
  } catch(e) { return false; }
}
function bdPausedScreen(){
  staffHideChrome();
  document.getElementById('bkContent').innerHTML = '<div style="max-width:420px;margin:60px auto;padding:20px;text-align:center"><div style="font-size:1.2rem;font-weight:900;color:var(--white)">Your access is paused</div><div style="color:var(--muted);margin:8px 0 16px;font-size:.85rem">The owner has paused your access to '+escH(activeBusiness?.name||'this business')+'. Please speak to them.</div><button class="bk-btn bk-btn-outline" onclick="location.reload()">Check again</button></div>';
}

// ── Ledger → Master Journal: double-click an entry to land on it in the journal ──
function ledDblClickRow(ev, idx) {
  const t = ev.target;
  // Double-click inside a text cell selects a word while editing; leave that alone
  if (t && t.matches && t.matches('input.bk-cell:not([readonly]):not(.num), textarea, select, button')) return;
  try { window.getSelection().removeAllRanges(); } catch (e) {}
  ledGoToJournal(idx);
}
async function ledGoToJournal(idx) {
  const row = rows[idx];
  if (!row) return;
  if (!row.id && !row.journal_id) { bdToast('Save this entry first, then it can be found in the journal'); return; }
  try { if (typeof isDirty !== 'undefined' && isDirty && activeAccount) { clearTimeout(_ledAutoT); await saveAll(); } } catch (e) {}
  const jid = row.journal_id || null, tid = row.id || null;
  await openJournal(true);                       // load rows without drawing, so filters can be cleared first
  jrnFilterDate = null; try { jrnSaveFilterDate(); } catch (e) {}
  Object.keys(jrnColFilters).forEach(k => { jrnColFilters[k] = ''; }); try { jrnSaveColFilters(); } catch (e) {}
  jrnViewMode = 'sheet';
  try { _bdPosPending = null; } catch (e) {}
  const at = journalRows.findIndex(r => (jid && r.id === jid) || (!jid && tid && r._txnId === tid));
  recordsPageChrome(); activeType = null; activeAccount = null;
  try { bdSaveRoute('journal'); } catch (e) {}
  renderJournal();
  if (at < 0) { bdToast('That entry is not in the Master Journal'); return; }
  setTimeout(function () {
    const tr = document.getElementById('jrow_' + at);
    if (!tr) return;
    tr.scrollIntoView({ block: 'center' });
    tr.classList.add('jrn-found');
    setTimeout(function () { tr.classList.remove('jrn-found'); }, 2600);
  }, 250);
}

// ══════════════════════════════════════════════════════════════════════
//  SALES SHEET · Payee (how the money came in) · Payer (customers) · Product list
// ══════════════════════════════════════════════════════════════════════
const PAY_METHODS = [
  { k:'cash', label:'Cash', pay:'cash', fields:[['label','Label, e.g. Main till']] },
  { k:'bank_transfer', label:'Bank transfer', pay:'transfer', fields:[['business','Name of business'],['bank','Bank name'],['acct_name','Account name'],['acct_no','Account number']] },
  { k:'debit_card', label:'Debit card', pay:'debitcard', fields:[['bank','Bank or card issuer'],['acct_name','Account name'],['acct_no','Account or card number']] },
  { k:'credit_card', label:'Credit card', pay:'creditcard', fields:[['bank','Bank or card issuer'],['acct_name','Account name'],['acct_no','Account or card number']] },
  { k:'pos', label:'POS', pay:'pos', fields:[['provider','POS provider or terminal'],['bank','Settles to bank'],['acct_no','Account number']] },
  { k:'mobile_money', label:'Mobile money', pay:'transfer', fields:[['provider','Provider, e.g. Opay'],['acct_name','Account name'],['phone','Phone number']] },
];
function _lsJson(k, d) { try { const v = JSON.parse(localStorage.getItem(k) || 'null'); return v == null ? d : v; } catch (e) { return d; } }
function payDetails() { return _lsJson('bd_pay_methods', {}); }
function paySaveDetails(o) { try { localStorage.setItem('bd_pay_methods', JSON.stringify(o)); } catch (e) {} }
function payEntryLine(m, e) { return m.fields.map(([k]) => (e[k] || '').trim()).filter(Boolean).join(' · '); }
function payParse(v) { const s = String(v || ''), i = s.indexOf(' | '); return i < 0 ? { main: s, sub: '' } : { main: s.slice(0, i), sub: s.slice(i + 3) }; }

function salesPayeeCell(i, r) {
  const p = payParse(r.payee);
  return `<div class="pay-cell" onclick="salesPayeeMenu(event,${i})" title="Choose how the money came in">
    <span class="pay-main">${p.main ? escH(p.main) : '<span style="color:var(--muted2)">Choose…</span>'}</span><span class="pay-caret">▾</span>
    ${p.sub ? `<small class="pay-sub">${escH(p.sub)}</small>` : ''}</div>`;
}
function salesPayeeClose() { document.getElementById('payMenuPortal')?.remove(); document.removeEventListener('mousedown', _payOutside, true); }
function _payOutside(e) { const m = document.getElementById('payMenuPortal'); if (m && !m.contains(e.target)) salesPayeeClose(); }
function _payPlace(box, anchor) {
  const rc = anchor.getBoundingClientRect();
  box.style.left = Math.max(8, Math.min(rc.left, window.innerWidth - box.offsetWidth - 8)) + 'px';
  let top = rc.bottom + 2; const h = box.offsetHeight;
  if (top + h > window.innerHeight - 8) top = Math.max(8, rc.top - h - 2);
  box.style.top = top + 'px';
}
function salesPayeeMenu(ev, i) {
  ev.stopPropagation();
  const anchor = ev.currentTarget || ev.target;
  salesPayeeClose();
  const box = document.createElement('div'); box.id = 'payMenuPortal'; box.className = 'pay-menu';
  box.dataset.i = i; document.body.appendChild(box);
  _payRenderList(box, i);
  _payPlace(box, anchor); box._anchor = anchor;
  setTimeout(() => document.addEventListener('mousedown', _payOutside, true), 0);
}
function _payRenderList(box, i) {
  const det = payDetails(), cur = salesRows[i] ? payParse(salesRows[i].payee) : { main: '', sub: '' };
  box.innerHTML = PAY_METHODS.map(m => {
    const list = det[m.k] || [];
    return `<div class="pay-row${cur.main === m.label && !cur.sub ? ' on' : ''}" data-act="pick" data-m="${m.k}"><span>${m.label}</span>
      <button class="pay-pen" data-act="edit" data-m="${m.k}" title="Add or change details" aria-label="Edit ${m.label}">✎</button></div>`
      + list.map((e, j) => { const ln = payEntryLine(m, e); return ln ? `<div class="pay-row pay-sub-row${cur.main === m.label && cur.sub === ln ? ' on' : ''}" data-act="pick" data-m="${m.k}" data-e="${j}"><small>${escH(ln)}</small></div>` : ''; }).join('');
  }).join('');
  box.onclick = ev => {
    const t = ev.target.closest('[data-act]'); if (!t) return;
    ev.stopPropagation();
    if (t.dataset.act === 'edit') return _payRenderEdit(box, i, t.dataset.m, null);
    salesPayeePick(i, t.dataset.m, t.dataset.e == null ? null : +t.dataset.e);
  };
}
function salesPayeePick(i, mk, ei) {
  const m = PAY_METHODS.find(x => x.k === mk), r = salesRows[i]; if (!m || !r) return;
  const e = ei == null ? null : (payDetails()[mk] || [])[ei];
  const line = e ? payEntryLine(m, e) : '';
  r.payee = line ? m.label + ' | ' + line : m.label;
  if (m.pay) r.pay_mode = m.pay;
  r._posted = false;
  salesPayeeClose(); renderRecordSheet('sales'); sheetAutosaveTrigger('sales');
}
function _payRenderEdit(box, i, mk, editIdx) {
  const m = PAY_METHODS.find(x => x.k === mk), det = payDetails(), list = det[mk] || [];
  const cur = editIdx != null ? list[editIdx] : {};
  box.innerHTML = `<div class="pay-edit"><div class="pay-edit-h">${m.label} details</div>
    ${list.map((e, j) => `<div class="pay-ent"><span>${escH(payEntryLine(m, e) || '(empty)')}</span><span><button class="pay-lnk" data-a="ed" data-j="${j}">Edit</button><button class="pay-lnk red" data-a="rm" data-j="${j}">Delete</button></span></div>`).join('') || '<div class="pay-note">Nothing saved yet.</div>'}
    <div class="pay-edit-h" style="margin-top:8px">${editIdx != null ? 'Change this one' : 'Add another'}</div>
    ${m.fields.map(([k, lb]) => `<label class="pay-fld"><span>${lb}</span><input data-f="${k}" value="${escH((cur && cur[k]) || '')}" autocomplete="off"/></label>`).join('')}
    <div class="pay-btns"><button class="pay-b" data-a="back">Back</button><button class="pay-b pri" data-a="save">${editIdx != null ? 'Save changes' : 'Save'}</button></div></div>`;
  box.onclick = ev => {
    const b = ev.target.closest('[data-a]'); if (!b) return; ev.stopPropagation();
    const a = b.dataset.a, d = payDetails(); d[mk] = d[mk] || [];
    if (a === 'back') return _payRenderList(box, i);
    if (a === 'ed') return _payRenderEdit(box, i, mk, +b.dataset.j);
    if (a === 'rm') { d[mk].splice(+b.dataset.j, 1); paySaveDetails(d); return _payRenderEdit(box, i, mk, null); }
    if (a === 'save') {
      const e = {}; box.querySelectorAll('input[data-f]').forEach(x => { e[x.dataset.f] = x.value.trim(); });
      if (!Object.values(e).some(Boolean)) { bdToast('Type at least one detail', 'error'); return; }
      if (editIdx != null) d[mk][editIdx] = e; else d[mk].push(e);
      paySaveDetails(d); _payRenderList(box, i); bdToast('Saved');
    }
  };
  _payPlace(box, box._anchor || document.body);
  box.querySelector('input')?.focus();
}

// Payer: Walk-in customer + every customer on the Customers page (typing still works for anyone else)
let _salesCust = { biz: undefined, list: [] };
async function salesLoadCustomers() {
  const biz = activeBusiness?.id || null;
  if (_salesCust.biz === biz) return _salesCust.list;
  try { const { data } = await bkDb.from('bk_customers').select('id,name').match(bizMatch()).order('name'); _salesCust = { biz, list: (data || []).map(c => c.name).filter(Boolean) }; }
  catch (e) { _salesCust = { biz, list: [] }; }
  return _salesCust.list;
}
function salesPayerClose() { document.getElementById('payerPortal')?.remove(); }
async function salesPayerMenu(i, input) {
  const list = await salesLoadCustomers();
  salesPayerClose();
  const q = (input.value || '').trim().toLowerCase();
  let extra = []; try { const pp = await partyLoad(); extra = pp.vend.concat(partyOwn().map(o => o.value)); } catch (e) {}
  const names = ['Walk-in customer'].concat(list, extra).filter((n, k, a) => a.indexOf(n) === k).filter(n => !q || n.toLowerCase().includes(q));
  if (!names.length || !document.body.contains(input)) return;
  const box = document.createElement('div'); box.id = 'payerPortal'; box.className = 'pay-menu';
  box.innerHTML = names.map(n => `<div class="pay-row" data-n="${escH(n)}"><span>${escH(n)}</span></div>`).join('');
  box.onmousedown = ev => {
    const t = ev.target.closest('[data-n]'); if (!t) return; ev.preventDefault();
    const r = salesRows[i]; if (!r) return; r.payer = t.dataset.n; r._posted = false; salesPayerClose(); renderRecordSheet('sales'); sheetAutosaveTrigger('sales');
  };
  document.body.appendChild(box);
  const rc = input.getBoundingClientRect(); box.style.minWidth = rc.width + 'px';
  _payPlace(box, input);
}

// Product list: which registered products the Product cells offer
function salesAssignedSet() { const a = _lsJson('bd_sales_prod_assign', null); return Array.isArray(a) && a.length ? new Set(a.map(String)) : null; }
const SALES_CELL_COL_CHOICES = [['product_type', 'Product type'], ['barcode', 'Barcode'], ['cost_price', 'Cost price'], ['sell_price', 'Selling price'], ['qty_in_stock', 'Stock left'], ['qty_date', 'Stock as at'], ['total_cost', 'Total in stock at cost price'], ['total_sell', 'Total in stock at selling price'], ['income_acct', 'Post to']];
async function salesAssignProducts() {
  closeColMenu();
  try { await bdLoadSalesProductCache(true); } catch (e) {}
  const asg = salesAssignedSet(), all = salesProductCache;
  const cc = salesCellCols();
  const choices = SALES_CELL_COL_CHOICES.concat((salesProductCustomCols || []).map(c => [c.key, c.name]));
  const cur = id => (cc || []).find(x => x.id === id);
  const defOn = id => false;
  const colRow = ([id, label]) => { const c = cur(id), on = c ? true : defOn(id), main = c ? !!c.main : false;
    return `<div class="sp-colrow" data-id="${escH(id)}" style="display:grid;grid-template-columns:22px 1fr 78px;gap:6px;align-items:center;margin-bottom:4px;font-size:.78rem;">
      <input type="checkbox" class="sp-on" ${on ? 'checked' : ''} onchange="salesAssignAuto()"/><span>${escH(label)}</span>
      <select class="sp-role bk-login-input" style="margin:0;padding:3px 6px;font-size:.72rem;" onchange="salesAssignAuto()"><option value="main" ${main ? 'selected' : ''}>Main</option><option value="sub" ${main ? '' : 'selected'}>Sub</option></select></div>`; };
  const o = document.createElement('div'); o.id = 'prodAssignDlg';
  o.style.cssText = 'position:fixed;inset:0;z-index:12500;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;padding:16px;';
  o.innerHTML = `<div class="pay-edit" style="width:min(460px,100%);max-height:90vh;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px;overflow:auto" onclick="event.stopPropagation()" onkeydown="event.stopPropagation()">
    <div class="pay-edit-h" style="font-size:.95rem">Assign products</div>
    <div class="pay-note">The list comes straight from your Products page and updates as stock is sold or added.</div>
    <label class="su-label" style="margin-top:8px">What each Product cell shows</label>
    <div style="border:1px solid var(--border);border-radius:8px;padding:8px;margin-bottom:10px">
      <div style="display:grid;grid-template-columns:22px 1fr 78px;gap:6px;font-size:.6rem;color:var(--muted);margin-bottom:4px"><span></span><span>PRODUCTS PAGE COLUMN</span><span>ROLE</span></div>
      <div style="display:grid;grid-template-columns:22px 1fr 78px;gap:6px;align-items:center;margin-bottom:4px;font-size:.78rem"><input type="checkbox" checked disabled/><span>Product</span><span style="font-size:.72rem;color:var(--muted)">Main</span></div>
      ${choices.map(colRow).join('')}
      <div style="font-size:.62rem;color:var(--muted);margin-top:4px">Main columns are written into the cell. Sub columns show underneath in smaller text and stay up to date. Ticked columns also appear as details for each product in the dropdown.</div>
    </div>
    <label class="su-label">Products offered in the cells</label>
    <input id="paQ" class="bk-login-input" placeholder="Search products…" oninput="salesAssignFilter()" style="margin:4px 0 8px"/>
    <div style="display:flex;gap:8px;margin-bottom:6px"><button class="pay-b" onclick="salesAssignAll(true)">Select all</button><button class="pay-b" onclick="salesAssignAll(false)">Clear</button></div>
    <div id="paList" style="overflow:auto;max-height:220px;min-height:100px;border:1px solid var(--border);border-radius:8px">
      ${all.length ? all.map(p => { const n = parseFloat(p.qty_in_stock) || 0; return `<label class="pay-ent" data-n="${escH((p.product_name || '').toLowerCase())}" style="cursor:pointer"><span><input type="checkbox" value="${p.id}" ${!asg || asg.has(String(p.id)) ? 'checked' : ''} onchange="salesAssignAuto()"/> ${escH(p.product_name || '')}</span><small style="${n > 0 ? '' : 'color:var(--red,#e5534b)'}">${escH(salesProdStock(p))}</small></label>`; }).join('') : '<div class="pay-note" style="padding:12px">No registered products yet. Add them on the Products page.</div>'}
    </div>
    <div class="pay-btns"><span id="paMsg" style="margin-right:auto;font-size:.72rem;align-self:center;color:var(--muted)">Changes save automatically</span><button class="pay-b pri" onclick="salesAssignSave()">Done</button></div></div>`;
  o.onclick = () => o.remove();
  document.body.appendChild(o);
}
function salesAssignFilter() { const q = document.getElementById('paQ').value.trim().toLowerCase(); document.querySelectorAll('#paList [data-n]').forEach(l => { l.style.display = !q || l.dataset.n.includes(q) ? '' : 'none'; }); }
function salesAssignAll(on) { document.querySelectorAll('#paList input[type=checkbox]').forEach(c => { if (c.closest('[data-n]').style.display !== 'none') c.checked = on; }); salesAssignAuto(); }
let _saT = null;
function salesAssignAuto() {
  clearTimeout(_saT);
  const m = document.getElementById('paMsg'); if (m) { m.textContent = 'Saving…'; m.style.color = 'var(--muted)'; }
  _saT = setTimeout(salesAssignApply, 350);
}
function salesAssignApply() {
  const ids = [...document.querySelectorAll('#paList input[type=checkbox]:checked')].map(c => c.value);
  const total = document.querySelectorAll('#paList input[type=checkbox]').length;
  const cols = [{ id: 'product_name', main: true }];
  document.querySelectorAll('#prodAssignDlg .sp-colrow').forEach(r => { if (r.querySelector('.sp-on').checked) cols.push({ id: r.dataset.id, main: r.querySelector('.sp-role').value === 'main' }); });
  try {
    localStorage.setItem('bd_sales_prod_assign', JSON.stringify(!ids.length || ids.length === total ? [] : ids));
    localStorage.setItem('bd_sales_cell_cols', JSON.stringify(cols.length > 1 ? cols : []));   // always written, so clearing it syncs too
  } catch (e) {}
  try { coaCloudPush(true); } catch (e) {}
  try { renderRecordSheet('sales'); } catch (e) {}
  const m = document.getElementById('paMsg'); if (m) { m.textContent = '✓ Saved'; m.style.color = 'var(--green,#3fb27f)'; }
}
function salesAssignSave() {
  clearTimeout(_saT); salesAssignApply();
  const ids = document.querySelectorAll('#paList input[type=checkbox]:checked').length, total = document.querySelectorAll('#paList input[type=checkbox]').length;
  if (!ids && total) bdToast('Nothing ticked, so every product is offered');
  document.getElementById('prodAssignDlg')?.remove();
}

// Products typed on the sales sheet that are not on the Products page yet
function _normProd(s) { return String(s || '').trim().toLowerCase().replace(/\s+/g, ' '); }
function bdProductIsRegistered(name) {
  const n = _normProd(name); if (!n) return true;
  return salesProductCache.some(p => _normProd(p.product_name) === n || _normProd(salesProdText(p)) === n);
}
function bdNoteUnregistered(row) {
  if (!row || !row._ptyped || row.product_id || !(row.product || '').trim()) return;
  if (bdProductIsRegistered(row.product)) return;
  const o = _lsJson('bd_unreg_products', {}), n = _normProd(row.product);
  const e = o[n] || { name: row.product.trim(), count: 0, price: 0 };
  e.count += 1; e.last = row.txn_date || today(); e.price = parseFloat(row.unit_price) || e.price || 0;
  o[n] = e; try { localStorage.setItem('bd_unreg_products', JSON.stringify(o)); } catch (x) {}
}
function psUnregBannerHtml() {
  if (psType === 'services') return '';
  const o = _lsJson('bd_unreg_products', {}), have = new Set((psRows || []).map(r => _normProd(r.name)));
  const keys = Object.keys(o).filter(k => !have.has(k));
  if (!keys.length) return '';
  return `<div class="ps-unreg"><div style="font-weight:800;margin-bottom:6px">⚠ ${keys.length} product${keys.length === 1 ? '' : 's'} sold but not registered</div>
    <div style="font-size:.72rem;color:var(--muted);margin-bottom:8px">These were typed on the sales sheet. Register them so stock and cost are tracked.</div>
    ${keys.map(k => `<div class="ps-unreg-row"><span><b>${escH(o[k].name)}</b> <small>sold ${o[k].count}×${o[k].price ? ' · last price ' + fmt(o[k].price) : ''}</small></span>
      <span><button class="pay-b pri" onclick="psRegisterUnreg('${escH(escJs(k))}')">Register</button> <button class="pay-b" onclick="psDismissUnreg('${escH(escJs(k))}')">Dismiss</button></span></div>`).join('')}</div>`;
}
async function psRegisterUnreg(k) {
  const o = _lsJson('bd_unreg_products', {}), e = o[k]; if (!e) return;
  const { error } = await bkDb.from('bk_products').insert({ user_id: bkUser.id, business_id: activeBusiness?.id || null, product_name: e.name, price: e.price || 0, cost_price: 0, qty_in_stock: 0, is_service: false, is_active: true, custom: {} });
  if (error) return bdToast('Could not register: ' + error.message, 'error');
  delete o[k]; try { localStorage.setItem('bd_unreg_products', JSON.stringify(o)); } catch (x) {}
  salesProductCacheBizId = undefined; bdToast('Registered'); showProductsPage('products');
}
function psDismissUnreg(k) { const o = _lsJson('bd_unreg_products', {}); delete o[k]; try { localStorage.setItem('bd_unreg_products', JSON.stringify(o)); } catch (x) {} showProductsPage('products'); }

// ── Sales sheet: which income accounts from the Master Journal also show on it ──
// Only the accounts the person ticks are brought over from the Master Journal. The accounts this sheet posts its own
// sales to (Sales Revenue and the account each product is set to post to) always show, otherwise a sale typed on the
// sheet would vanish from it. The choice is stored as the list of ticked account names.
let _salesOwnInc = new Set(['sales revenue', 'service income', 'barbing revenue']);
const _incKey = n => String(n || '').trim().toLowerCase();
function salesIncomeIncluded() {
  const a = _lsJson('bd_sales_incl_income', null);
  if (Array.isArray(a)) return new Set(a);
  const ex = _lsJson('bd_sales_excl_income', null);       // older choice (stored the other way round): carry it over
  if (Array.isArray(ex)) return new Set((accounts.income || []).map(x => x.account_name).filter(n => ex.indexOf(n) < 0));
  return new Set();
}
function salesIncomeChosenCount() { let n = 0; const inc = salesIncomeIncluded(); (accounts.income || []).forEach(a => { if (inc.has(a.account_name) && !_salesOwnInc.has(_incKey(a.account_name))) n++; }); return n; }
function salesIncomeShown(t) { return salesIncomeIncluded().has(t.account_name) || _salesOwnInc.has(_incKey(t.account_name)); }
async function salesIncomeFilterOpen() {
  try { await bdLoadSalesProductCache(true); } catch (e) {}   // also learns which accounts the products post to
  const list = (accounts.income || []), byId = {}; list.forEach(a => { byId[a.id] = a; });
  const kids = {}; list.forEach(a => { if (a.parent_id && byId[a.parent_id]) (kids[a.parent_id] = kids[a.parent_id] || []).push(a); });
  const codes = _coaCodes(), inc = salesIncomeIncluded();
  const roots = list.filter(a => !a.parent_id || !byId[a.parent_id]);
  const row = (a, depth) => { const own = _salesOwnInc.has(_incKey(a.account_name));
    return `<label class="pay-ent" data-n="${escH((a.account_name || '').toLowerCase())}" style="cursor:${own ? 'default' : 'pointer'};padding-left:${8 + depth * 18}px">
      <span><input type="checkbox" data-id="${a.id}" data-p="${a.parent_id || ''}" ${own || inc.has(a.account_name) ? 'checked' : ''} ${own ? 'disabled data-own="1"' : ''} onchange="salesIncomeCascade(this)"/> ${codes[a.id] ? '<small style="color:var(--gold)">' + escH(String(codes[a.id])) + '</small> ' : ''}${escH(a.account_name)}${own ? ' <small style="color:var(--muted)" title="This sheet posts its own sales here, so it always shows">\uD83D\uDD12 always on</small>' : ''}</span></label>` + (kids[a.id] || []).map(c => row(c, depth + 1)).join(''); };
  const o = document.createElement('div'); o.id = 'salesIncDlg';
  o.style.cssText = 'position:fixed;inset:0;z-index:12500;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;padding:16px;';
  o.innerHTML = `<div class="pay-edit" style="width:min(440px,100%);max-height:86vh;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px" onclick="event.stopPropagation()">
    <div class="pay-edit-h" style="font-size:.95rem">Income accounts on the Sales Record</div>
    <div class="pay-note">Only the accounts you tick here are brought over from the Master Journal to this sheet. Everything else posts only to its own ledger. Ticking an account ticks everything under it. Accounts this sheet posts its own sales to are always shown.</div>
    <input id="siQ" class="bk-login-input" placeholder="Search accounts…" oninput="salesIncomeFilterSearch()" style="margin:8px 0"/>
    <div style="display:flex;gap:8px;margin-bottom:6px"><button class="pay-b" onclick="salesIncomeAll(true)">Select all</button><button class="pay-b" onclick="salesIncomeAll(false)">Clear</button></div>
    <div id="siList" style="overflow:auto;flex:1;min-height:120px;border:1px solid var(--border);border-radius:8px">${roots.length ? roots.map(a => row(a, 0)).join('') : '<div class="pay-note" style="padding:12px">No income accounts yet. Create them in the Chart of Accounts.</div>'}</div>
    <div class="pay-btns"><span id="siMsg" style="margin-right:auto;font-size:.72rem;align-self:center;color:var(--muted)">Changes save automatically</span><button class="pay-b pri" onclick="salesIncomeSave()">Done</button></div></div>`;
  o.onclick = () => o.remove();
  document.body.appendChild(o);
}
function salesIncomeCascade(cb) {
  const all = [...document.querySelectorAll('#siList input[type=checkbox]')];
  const walk = id => all.filter(x => x.dataset.p === id).forEach(x => { if (!x.disabled) x.checked = cb.checked; walk(x.dataset.id); });
  walk(cb.dataset.id);
  salesIncomeAuto();
}
function salesIncomeFilterSearch() { const q = document.getElementById('siQ').value.trim().toLowerCase(); document.querySelectorAll('#siList [data-n]').forEach(l => { l.style.display = !q || l.dataset.n.includes(q) ? '' : 'none'; }); }
function salesIncomeAll(on) { document.querySelectorAll('#siList input[type=checkbox]').forEach(c => { if (!c.disabled && c.closest('[data-n]').style.display !== 'none') c.checked = on; }); salesIncomeAuto(); }
let _siT = null, _siBusy = false, _siAgain = false;
function salesIncomeCollect() {
  const names = {}; (accounts.income || []).forEach(a => { names[a.id] = a.account_name; });
  return [...document.querySelectorAll('#siList input[type=checkbox]:checked:not([data-own])')].map(c => names[c.dataset.id]).filter(Boolean);
}
// Every tick is saved straight away (no Save button needed): the choice is stored with the business
// settings and the Sales sheet is refreshed from the Master Journal.
function salesIncomeAuto() {
  clearTimeout(_siT);
  const m = document.getElementById('siMsg'); if (m) { m.textContent = 'Saving…'; m.style.color = 'var(--muted)'; }
  _siT = setTimeout(salesIncomeApply, 350);
}
async function salesIncomeApply() {
  if (_siBusy) { _siAgain = true; return; }
  _siBusy = true;
  let res = { ok: true };
  try {
    const on = salesIncomeCollect();
    try { localStorage.setItem('bd_sales_incl_income', JSON.stringify(on)); } catch (e) {}   // always a write, so it syncs to the account (an empty list means "none chosen")
    res = await coaSyncNow('Your income-account choice');
    try { await sheetSyncFromJournal('sales'); } catch (e) {}
    if (document.getElementById('sheetTable_sales') || document.querySelector('.bk-sheet-wrap')) { try { renderRecordSheet('sales'); } catch (e) {} }
    const m = document.getElementById('siMsg'); if (m) { m.textContent = res.ok ? '\u2713 Saved' : '\u26A0 Saved on this device only'; m.style.color = res.ok ? 'var(--green,#3fb27f)' : 'var(--red,#e5534b)'; }
  } finally { _siBusy = false; if (_siAgain) { _siAgain = false; salesIncomeApply(); } }
}
async function salesIncomeSave() {
  clearTimeout(_siT);
  await salesIncomeApply();
  document.getElementById('salesIncDlg')?.remove();
  bdToast('Sales sheet updated');
}


// ═════════════════════════════════════════════════════════════════════
//  PAYEE / PAYER DROPDOWN — Master Journal, Ledgers, Expenses sheet
//  Offers: Walk-in customer · customers (Customers page) · vendors
//  (Suppliers page) · our own accounts (bank details saved under Payee).
//  Any cell marked data-party gets it; typing still works for anything else.
// ═════════════════════════════════════════════════════════════════════
let _partyC = { key: null, t: 0, cust: [], vend: [] };
async function partyLoad() {
  const key = (activeBusiness && activeBusiness.id) || 'self';
  if (_partyC.key === key && Date.now() - _partyC.t < 10000) return _partyC;
  const c = { key, t: Date.now(), cust: [], vend: [] };
  try { const { data } = await bkDb.from('bk_customers').select('name').match(bizMatch()).order('name'); c.cust = (data || []).map(x => x.name).filter(Boolean); } catch (e) {}
  try { const { data } = await bkDb.from('bk_suppliers').select('supplier_name').eq('user_id', bkUser.id).order('supplier_name'); c.vend = (data || []).map(x => x.supplier_name).filter(Boolean); } catch (e) {}
  _partyC = c; return c;
}
// Our own accounts: whatever titles the user adds. Old saved payment-method details are carried over once.
function ownAccounts() {
  let list = _lsJson('bd_own_accounts', null);
  if (!Array.isArray(list)) {
    list = [];
    try {
      const det = payDetails();
      PAY_METHODS.forEach(m => (det[m.k] || []).forEach(e => {
        if (!payEntryLine(m, e)) return;
        list.push({ id: 'o' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), title: m.label, bank: e.bank || e.provider || e.business || '', acct_name: e.acct_name || '', acct_no: e.acct_no || e.phone || '', phone: e.phone || '' });
      }));
    } catch (e) {}
    ownAccountsSave(list);
  }
  return list;
}
function ownAccountsSave(list) { try { localStorage.setItem('bd_own_accounts', JSON.stringify(list)); } catch (e) {} }
function ownAccountLine(a) { return [a.bank, a.acct_name, a.acct_no, a.phone].map(x => (x || '').trim()).filter(Boolean).join(' · '); }
function partyOwn() { return ownAccounts().filter(a => (a.title || '').trim()).map(a => ({ value: a.title.trim(), label: a.title.trim(), sub: ownAccountLine(a) })); }
function partyInfo() { return _lsJson('bd_party_info', {}); }
function partyInfoSave(o) { try { localStorage.setItem('bd_party_info', JSON.stringify(o)); } catch (e) {} }
const PARTY_FIELDS = [['name','Name'],['bank','Bank name'],['acct_name','Account name'],['acct_no','Account number'],['phone','Phone number']];
function partyInfoLine(g, name) { const e = partyInfo()[g + ':' + name] || {}; return ['bank','acct_name','acct_no','phone'].map(k => (e[k] || '').trim()).filter(Boolean).join(' · '); }
function partyClose() { const b = document.getElementById('partyPortal'); if (b) b.remove(); document.removeEventListener('mousedown', _partyOutside, true); }
function _partyOutside(e) { const b = document.getElementById('partyPortal'); if (b && !b.contains(e.target) && !(e.target.dataset && e.target.dataset.party)) partyClose(); }
async function partyMenu(input, all) {
  if (window._partyAll) { all = true; window._partyAll = false; }
  const pp = await partyLoad();
  if (!document.body.contains(input) || document.activeElement !== input) return;
  const old = document.getElementById('partyPortal'); if (old && old._editing) return;
  partyClose();
  const box = document.createElement('div'); box.id = 'partyPortal'; box.className = 'pay-menu';
  box._input = input; box._all = !!all; document.body.appendChild(box);
  partyRenderList(box);
  const rc = input.getBoundingClientRect(); box.style.minWidth = Math.max(rc.width, 230) + 'px'; box.style.maxHeight = '300px'; box.style.overflowY = 'auto';
  _payPlace(box, input);
  setTimeout(() => document.addEventListener('mousedown', _partyOutside, true), 0);
}
function partyRenderList(box) {
  const input = box._input; if (!input) return;
  const pp = _partyC, q = box._all ? '' : (input.value || '').trim().toLowerCase();
  const hit = s => !q || String(s).toLowerCase().includes(q);
  const pen = (data) => `<button class="pay-pen" data-act="edit" ${data} title="Edit" aria-label="Edit">✎</button>`;
  const rows = []; const picks = [];
  const add = (cls, value, label, sub, penData) => { picks.push(value); rows.push(`<div class="pay-row ${cls}" data-act="pick" data-k="${picks.length - 1}"><span>${escH(label)}${sub ? `<small class="pay-sub" style="display:block">${escH(sub)}</small>` : ''}</span>${penData ? pen(penData) : ''}</div>`); };
  const head = h => rows.push(`<div class="pay-grp" style="font-size:.6rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:6px 10px 2px;">${h}</div>`);
  const attr = (input.getAttribute('oninput') || '') + ' ' + (input.getAttribute('placeholder') || '');
  const pf = input.dataset.pf || (/payee/i.test(attr) ? 'payee' : (/payer/i.test(attr) ? 'payer' : ''));
  const noWalk = input.dataset.nowalkin === '1';
  const blkCust = () => { const cust = (noWalk ? [] : ['Walk-in customer']).concat(pp.cust).filter(hit);
    if (cust.length) { head('Customers'); cust.forEach(n => add('', n, n, n === 'Walk-in customer' ? '' : partyInfoLine('c', n), n === 'Walk-in customer' ? '' : `data-g="c" data-n="${escH(n)}"`)); } };
  const blkVend = () => { const vend = pp.vend.filter(hit);
    if (vend.length) { head('Vendors'); vend.forEach(n => add('', n, n, partyInfoLine('v', n), `data-g="v" data-n="${escH(n)}"`)); } };
  const blkOwn = () => { head('Our accounts');
    ownAccounts().filter(a => (a.title || '').trim() && (hit(a.title) || hit(ownAccountLine(a)))).forEach(a => add('', a.title.trim(), a.title.trim(), ownAccountLine(a), `data-g="o" data-id="${escH(a.id)}"`));
    rows.push(`<div class="pay-row" style="color:var(--text-accent,#7c5cff);font-weight:700;" data-act="edit" data-g="o" data-id=""><span>＋ Add an account</span></div>`); };
  // The payee is where money goes or comes in (our accounts first); the payer is who pays (customers first).
  (pf === 'payee' ? [blkOwn, blkVend, blkCust] : [blkCust, blkVend, blkOwn]).forEach(fn => fn());
  box._picks = picks;
  box.innerHTML = rows.join('') || '<div class="pay-row" style="color:var(--muted)">No matches — keep typing to use any name.</div>';
  box.onmousedown = ev => {
    const t = ev.target.closest('[data-act]'); if (!t) return;
    ev.preventDefault(); ev.stopPropagation();
    if (t.dataset.act === 'edit') { ev.stopPropagation(); return partyRenderEdit(box, t.dataset); }
    const row = t.closest('[data-k]'); if (!row) return;
    input.value = box._picks[+row.dataset.k];
    partyClose();
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    if (input.dataset.party === 'ledger' && typeof ledgerAutosave === 'function') { isDirty = true; ledgerAutosave(); }
  };
}
function partyRenderEdit(box, d) {
  box._editing = true;
  const g = d.g; let title, fields, cur = {}, removable = false;
  if (g === 'o') {
    const cur0 = d.id ? ownAccounts().find(x => x.id === d.id) : null;
    title = cur0 ? 'Change this account' : 'Add an account';
    fields = [['title','Title'],['bank','Bank name'],['acct_name','Account name'],['acct_no','Account number'],['phone','Phone (optional)']];
    cur = cur0 || {}; removable = !!cur0;
  } else {
    title = (g === 'c' ? 'Customer' : 'Vendor') + ' details'; fields = PARTY_FIELDS;
    cur = Object.assign({ name: d.n }, partyInfo()[g + ':' + d.n] || {});
  }
  box.innerHTML = `<div class="pay-edit"><div class="pay-edit-h">${escH(title)}</div>
    ${fields.map(([k, lb]) => `<label class="pay-fld"><span>${lb}</span><input data-f="${k}" value="${escH(cur[k] || '')}" autocomplete="off"/></label>`).join('')}
    <div class="pay-btns">${(removable || g !== 'o') ? '<button class="pay-b" data-a="rm" style="color:var(--red)">Delete</button>' : ''}<button class="pay-b" data-a="back">Back</button><button class="pay-b pri" data-a="save">Save</button></div></div>`;
  box.onmousedown = ev => { ev.stopPropagation(); };
  box.onclick = async ev => {
    const b = ev.target.closest('[data-a]'); if (!b) return; ev.stopPropagation();
    const done = () => { box._editing = false; partyRenderList(box); _payPlace(box, box._input); try { box._input.focus(); } catch (e) {} };
    if (b.dataset.a === 'back') return done();
    const vals = {}; box.querySelectorAll('input[data-f]').forEach(x => { vals[x.dataset.f] = x.value.trim(); });
    if (g === 'o') {
      const list = ownAccounts().slice();
      if (b.dataset.a === 'rm') { const k = list.findIndex(x => x.id === d.id); if (k >= 0) list.splice(k, 1); }
      else {
        if (!vals.title) { bdToast('A title is needed', 'error'); return; }
        const k = d.id ? list.findIndex(x => x.id === d.id) : -1;
        if (k >= 0) list[k] = Object.assign({}, list[k], vals);
        else list.push(Object.assign({ id: 'o' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6) }, vals));
      }
      ownAccountsSave(list); bdToast('Saved'); coaSyncNow('Your account list'); return done();
    }
    if (b.dataset.a === 'rm') {
      if (!(await bdConfirm('Delete ' + (g === 'c' ? 'customer' : 'vendor') + ' "' + d.n + '"? It will also be removed from the ' + (g === 'c' ? 'Customers' : 'Suppliers') + ' page.'))) return;
      try {
        if (g === 'c') await bkDb.from('bk_customers').delete().match(bizMatch()).eq('name', d.n);
        else await bkDb.from('bk_suppliers').delete().eq('user_id', bkUser.id).eq('supplier_name', d.n);
      } catch (e) { bdToast('Could not delete — ' + (e.message || ''), 'error'); return; }
      const inf = partyInfo(); delete inf[g + ':' + d.n]; partyInfoSave(inf);
      _partyC.t = 0; _salesCust = { biz: undefined, list: [] };
      await partyLoad(); bdToast('Deleted'); return done();
    }
    if (!vals.name) { bdToast('A name is needed', 'error'); return; }
    const info = partyInfo(); const oldKey = g + ':' + d.n; const extra = Object.assign({}, vals); delete extra.name;
    if (vals.name !== d.n) {
      try {
        if (g === 'c') await bkDb.from('bk_customers').update({ name: vals.name }).match(bizMatch()).eq('name', d.n);
        else await bkDb.from('bk_suppliers').update({ supplier_name: vals.name }).eq('user_id', bkUser.id).eq('supplier_name', d.n);
      } catch (e) { bdToast('Could not rename — ' + (e.message || ''), 'error'); return; }
      delete info[oldKey];
    }
    info[g + ':' + vals.name] = extra; partyInfoSave(info); coaSyncNow('These details');
    _partyC.t = 0; _salesCust = { biz: undefined, list: [] };
    await partyLoad(); bdToast('Saved'); done();
  };
  _payPlace(box, box._input);
  box.querySelector('input')?.focus();
}
document.addEventListener('focusin', e => { const t = e.target; if (t && t.dataset && t.dataset.party) partyMenu(t); });
document.addEventListener('input', e => { const t = e.target; if (t && t.dataset && t.dataset.party && e.isTrusted) partyMenu(t); });
document.addEventListener('focusout', e => { const t = e.target; if (t && t.dataset && t.dataset.party) { const b0 = document.getElementById('partyPortal'); setTimeout(() => { const b = document.getElementById('partyPortal'); if (b && b === b0 && !b._editing) partyClose(); }, 160); } });
document.addEventListener('keydown', e => { if (e.key === 'Escape') partyClose(); });


// ── Payee / payer cells: the name, its account details in small letters underneath, and a ▾ at the right edge ──
function partySubFor(v) {
  const t = String(v || '').trim().toLowerCase(); if (!t) return '';
  const own = ownAccounts().find(a => (a.title || '').trim().toLowerCase() === t);
  if (own) return ownAccountLine(own);
  const c = (_partyC.cust || []).find(n => n.toLowerCase() === t); if (c) return partyInfoLine('c', c);
  const vd = (_partyC.vend || []).find(n => n.toLowerCase() === t); if (vd) return partyInfoLine('v', vd);
  return '';
}
function partyRefreshSub(input) {
  const w = input.closest && input.closest('.party-cell'); const sub = w && w.querySelector('.party-sub');
  if (sub) { const t = partySubFor(input.value); sub.textContent = t; sub.style.display = t ? '' : 'none'; }
}
function partyCaret(ev, el) {
  ev.preventDefault(); ev.stopPropagation();
  const input = el.parentNode.querySelector('input[data-party]'); if (!input) return;
  const open = document.getElementById('partyPortal');
  if (open && open._input === input) { partyClose(); return; }
  window._partyAll = true;
  input.focus();
  partyMenu(input, true);
}
let _partyEnhT = 0;
function partyEnhance() {
  _partyEnhT = 0;
  const fresh = document.querySelectorAll('input[data-party]:not([data-pe])');
  if (!fresh.length) return;
  if (!_partyC.key) partyLoad().then(() => document.querySelectorAll('input[data-party][data-pe]').forEach(partyRefreshSub)).catch(() => {});
  fresh.forEach(inp => {
    inp.dataset.pe = '1';
    const w = document.createElement('div'); w.className = 'party-cell';
    inp.parentNode.insertBefore(w, inp); w.appendChild(inp);
    const sub = document.createElement('small'); sub.className = 'party-sub'; w.appendChild(sub);
    const car = document.createElement('span'); car.className = 'party-caret'; car.textContent = '▾'; car.title = 'Show the options';
    car.onmousedown = e => partyCaret(e, car); w.appendChild(car);
    partyRefreshSub(inp);
  });
}
(function () {
  const start = () => {
    const root = document.getElementById('bkContent') || document.body;
    new MutationObserver(() => { if (!_partyEnhT) _partyEnhT = requestAnimationFrame(partyEnhance); }).observe(root, { childList: true, subtree: true });
    partyEnhance();
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
document.addEventListener('input', e => { const t = e.target; if (t && t.dataset && t.dataset.party) partyRefreshSub(t); }, true);
